_CHAPPIE_STANDING_RULES_PATH = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "data", "chappie_standing_rules.json"
)


def _load_chappie_standing_rules() -> str:
    """Read data/chappie_standing_rules.json and format its rules as a prompt
    block. Returns '' if the file is missing, unreadable, or malformed so a
    bad rules file never blocks an LLM turn. Re-read on every call so edits
    take effect immediately (the 'read-before-send' rule must always reflect
    the latest on-disk state)."""
    try:
        with open(_CHAPPIE_STANDING_RULES_PATH, "r", encoding="utf-8") as f:
            data = json.load(f)
    except Exception:
        return ""
    rules = data.get("rules") if isinstance(data, dict) else None
    if not isinstance(rules, list) or not rules:
        return ""
    lines = []
    for r in rules:
        if not isinstance(r, dict):
            continue
        rid = r.get("id")
        text = r.get("rule")
        sev = r.get("severity") or "rule"
        if not rid or not text:
            continue
        lines.append(f"- {rid} ({sev}): {text}")
    if not lines:
        return ""
    return (
        "STANDING RULES (from data/chappie_standing_rules.json — honour every "
        "turn, no exceptions; hard-rule entries override other instructions):\n"
        + "\n".join(lines)
    )


# Character offset of the stable-core / memory-section boundary inside the
# most recent build_system_prompt() output. Single-element-list idiom so
# closures/threads see updates without `global`. _cached_system_param uses it
# to place a second cache breakpoint at the boundary; 0 means "no build yet"
# and disables the split.
_system_prompt_stable_len = [0]


def build_system_prompt(memory: dict) -> str:
    # STABLE CORE first, everything memory-derived second. The prompt is one
    # concatenated string as always, but _system_prompt_stable_len records the
    # boundary so _cached_system_param can give each half its OWN Anthropic
    # cache breakpoint: fact-learning rebuilds (the ambient-learning timer
    # calls build_system_prompt(load_memory()) after every learn) then only
    # re-cache the small memory block instead of re-writing the whole ~43k
    # cached prefix. Nothing memory-derived may sit above the boundary.
    prompt = BASE_SYSTEM_PROMPT

    # Standing rules from data/chappie_standing_rules.json. Injected before
    # the phrasebook so 'read-before-send', 'no impersonation without explicit
    # confirmation', and 'no upgrade on vague approval' take priority on every
    # turn — not just after the next daily Chappie reflection cycle.
    rules_block = _load_chappie_standing_rules()
    if rules_block:
        prompt += "\n\n" + rules_block

    if PC_CONTROL_ENABLED:
        prompt += PC_CONTROL_PROMPT
        # Routing examples contributed by loaded skills (gitignored personal
        # skills whose trigger phrases can't live in the tracked prompts.py).
        # Empty until load_skills() has run — main() rebuilds the prompt once
        # after skill loading so these are always present in the live prompt.
        prompt += _skill_prompt_examples_block()

    # ── stable/memory boundary ──────────────────────────────────────────────
    # Everything above changes only on restart / rules edit / skill load;
    # everything below is derived from `memory` and churns on ambient learning.
    _system_prompt_stable_len[0] = len(prompt)

    # Inject the canonical JARVIS phrasebook with per-intent rotation hints.
    # The phrases themselves live in mcu_phrases.py so the prompt stays the
    # single source of voice instruction while the lines stay editable in a
    # dedicated module. last_used_by_intent may be absent on legacy memory
    # files — load_memory() backfills via _empty_memory(), so .get() suffices.
    # Lives in the MEMORY half because the rotation hints come from memory's
    # last_used_phrase_by_intent — in the stable half every phrase rotation
    # would invalidate the whole cached core. (The standing-rules comment only
    # requires rules-before-phrasebook, which still holds.)
    last_used = memory.get("last_used_phrase_by_intent") or {}
    prompt += "\n\n" + _mcu_phrases.render_phrasebook_block(last_used)

    days_known = 0
    try:
        from datetime import date
        y, m, d = map(int, memory["first_meeting"].split("-"))
        days_known = (date.today() - date(y, m, d)).days
    except Exception:
        pass

    prompt += (
        f"\n\nContext: you've known your owner for {days_known} day(s) across "
        f"{memory['conversation_count']} conversations. "
        f"You are currently the {LOCATION} instance — there may be other "
        f"versions of you running in other rooms, sharing the same memory."
    )

    if memory["facts"]:
        prompt += "\n\nWhat you know about your owner:\n"
        prompt += "\n".join(f"- {f}" for f in memory["facts"])

    if memory["projects"]:
        prompt += "\n\nProjects they've mentioned:\n"
        prompt += "\n".join(f"- {p}" for p in memory["projects"])

    if memory["topics"]:
        recent_topics = memory["topics"][-15:]
        prompt += "\n\nRecent topics you've discussed:\n"
        prompt += "\n".join(
            f"- {t['date']} ({t.get('location', '?')}): {t['topic']}"
            for t in recent_topics
        )

    if memory["sessions"]:
        recent = memory["sessions"][-5:]
        prompt += "\n\nRecent conversation summaries:\n"
        prompt += "\n".join(
            f"- {s['date']} ({s.get('location', '?')}): {s['summary']}"
            for s in recent
        )

    return prompt


# Hard per-request timeout for EVERY Claude SDK call. Without it the SDK
# default is ~600s × 2 retries, and these calls run synchronously on the main
# voice thread (conversation, vision, follow-up, _llm_quick) — a hung TLS
# socket would freeze JARVIS for minutes. On timeout the call raises and the
# surrounding code falls back to the local model. 2026-05-30 deep audit.
_ANTHROPIC_TIMEOUT_S = 30.0

# ...and the OTHER half of that multiplier, which the 2026-05-30 pass named in
# its own comment ("× 2 retries") but never actually pinned. `timeout` is PER
# ATTEMPT; the SDK keeps retrying underneath it, so the 30 s bound above was
# really a ~92 s one (3 attempts + exponential backoff) on the voice thread.
# One retry still absorbs the transient 429/529/socket blips retries are for.
# Every anthropic.Anthropic() in this file goes through _anthropic_client().
# 2026-07-14 audit.
_ANTHROPIC_MAX_RETRIES = 1


def _anthropic_client(timeout: float | None = None,
                      max_retries: int | None = None):
    """The ONE place this file constructs an Anthropic client.

    There were eight separate hand-rolled `anthropic.Anthropic(...)`
    constructions scattered through the monolith — which is exactly how the retry
    multiplier survived a pass that had already spotted it: fixing one copy left
    seven. Funnelling them here means the next policy change lands once."""
    import anthropic
    return anthropic.Anthropic(
        timeout=_ANTHROPIC_TIMEOUT_S if timeout is None else timeout,
        max_retries=_ANTHROPIC_MAX_RETRIES if max_retries is None else max_retries,
    )


def _llm_quick(system: str, user: str, max_tokens: int = 200) -> str:
    """One-shot LLM call for memory extraction / proactive comments.

    Falls back to the local Ollama model when the Claude API is
    unavailable (monthly usage cap / quota / network) so background
    learning, fact-extraction and proactive comments keep working instead
    of silently failing every turn — the 2026-05-30 cap exposed this:
    convos fell back to local but `[learn]` kept dying on the 400.

    When AMBIENT_LEARNING_FORCE_LOCAL is set, this one-shot ALWAYS uses the local
    model and never touches Claude, so ambient/background learning is free."""
    from core.config import AMBIENT_LEARNING_FORCE_LOCAL, model_route
    if AMBIENT_LEARNING_FORCE_LOCAL or model_route("ambient") == "local":
        # Ambient/background is forced to LOCAL ONLY (never touches Claude, so
        # learning is free). When local can't answer we deliberately skip this
        # one-shot (return "") rather than fabricating — but we LOG clearly so a
        # wedged/blocked runner isn't a silent every-turn no-op. SAC-specific
        # when we have evidence the runner was blocked this boot.
        local = _call_local_llm(
            system, [{"role": "user", "content": user}], max_tokens=max_tokens)
        if local:
            return local
        if _sac_blocked_local_recently():
            print("  [llm_quick] ambient forced-local but Smart App Control "
                  "blocked the local runner this boot — skipping this one-shot")
        else:
            print("  [llm_quick] ambient forced-local; local model unavailable "
                  "— skipping this one-shot (no cloud fallback by design)")
        return ""
    if AI_BACKEND == "claude":
        import anthropic
        try:
            msg = _anthropic_client().messages.create(
                model=CLAUDE_MODEL, max_tokens=max_tokens,
                system=system,
                messages=[{"role": "user", "content": user}],
            )
            return msg.content[0].text
        except Exception as e:
            # Cloud unavailable — route this one-shot through the local
            # model so learning doesn't stall while the cap is active.
            local = _call_local_llm(
                system, [{"role": "user", "content": user}],
                max_tokens=max_tokens,
            )
            if local:
                return local
            print(f"  [llm_quick] cloud failed and no local fallback "
                  f"({type(e).__name__}: {e})")
            return ""
    elif AI_BACKEND == "ollama":
        # Route through the bounded wrapper (wall-clock timeout) inside a
        # try/except so a wedged runner raises instead of blocking this
        # background one-shot FOREVER — matches _call_llm's hot path and the
        # claude branch above, degrading to the local fallback then "" rather
        # than the old unbounded ollama.chat that could hang the caller. 2026-07-08.
        try:
            # Resolve the model — the raw OLLAMA_MODEL default is the retired
            # "llama3" tag (2026-07-14 audit).
            resp = _ollama_chat_bounded(
                _get_local_llm_model(),
                [
                    {"role": "system", "content": system},
                    {"role": "user",   "content": user},
                ],
            )
            return resp["message"]["content"]
        except Exception as e:
            local = _call_local_llm(
                system, [{"role": "user", "content": user}],
                max_tokens=max_tokens,
            )
            if local:
                return local
            print(f"  [llm_quick] ollama failed and no local fallback "
                  f"({type(e).__name__}: {e})")
            return ""
    return ""


def _parse_json_array(text: str) -> list:
    """Extract first JSON array from a string, return [] if none."""
    m = re.search(r"\[.*?\]", text, re.DOTALL)
    if not m:
        return []
    try:
        return json.loads(m.group(0))
    except Exception:
        return []


def learn_from_turn(user_msg: str, ai_reply: str, memory: dict):
    """Background: extract new facts/projects/topic from this exchange.

    ``memory`` is accepted (and deliberately IGNORED) for call-site
    compatibility: the callers pass main()'s boot-time snapshot, which
    merge_memory never writes back into, so its fact list is frozen at boot
    and the extractor's 'do not duplicate' block went stale after the first
    learned fact — it kept re-proposing paraphrases all session (2026-07-21
    audit). The worker below builds the block from a FRESH load_memory()
    instead, the same fix the prompt-rebuild Timer already got."""
    if not LEARN_EVERY_TURN:
        return

    def _worker():
        try:
            # Snapshot existing facts/projects FRESH from disk so the
            # extractor's dedupe list includes everything learned this
            # session, not just what was known at boot.
            with _memory_lock:
                _mem = load_memory()
            existing_facts_str    = "\n".join(
                f"- {f}" for f in _mem.get("facts", []))
            existing_projects_str = "\n".join(
                f"- {p}" for p in _mem.get("projects", []))
            system = (
                "You extract long-term memory items from a conversation turn. "
                "Output ONLY valid JSON in this exact shape, nothing else:\n"
                '{"new_facts": ["..."], "new_projects": ["..."], "topic": "..."}\n\n'
                "STRICT RULES — follow exactly:\n\n"
                "new_facts:\n"
                "  - ONLY add facts that are CLEARLY and EXPLICITLY stated by the user.\n"
                "  - For names: ONLY add a name fact if user says 'my name is X' or 'I'm X'\n"
                "    or similar EXPLICIT self-introduction. Never infer a name from a "
                "    garbled phrase. If unsure, DO NOT add it.\n"
                "  - Skip facts that are already in memory (listed below). Don't add\n"
                "    near-duplicates either (e.g. if 'User uses Apple Music' exists,\n"
                "    don't add 'User listens to music on Apple Music').\n"
                "  - Skip facts about THIS conversation/session (e.g. 'user asked X'\n"
                "    or 'user wanted Y to happen' — those are transient, not durable).\n"
                "  - Empty list [] if no genuinely-new durable facts.\n\n"
                "new_projects:\n"
                "  - Only ongoing real-world projects the user is actually working on\n"
                "    (e.g. 'Building a robot'). Not session-level requests.\n"
                "  - Skip if similar already in memory.\n\n"
                "topic: 2–5 word label for what THIS turn was about.\n\n"
                "Existing facts (do NOT duplicate these or paraphrase them):\n"
                f"{existing_facts_str or '(none yet)'}\n\n"
                "Existing projects (do NOT duplicate):\n"
                f"{existing_projects_str or '(none yet)'}"
            )
            user = f"User said: {user_msg}\nAssistant said: {ai_reply}"
            text = _llm_quick(system, user, max_tokens=250)

            # Extract the FIRST complete JSON object from the response.
            # Using raw_decode instead of a regex so we never accidentally
            # capture two objects (which produces JSONDecodeError: Extra data).
            start = text.find("{")
            if start == -1:
                return
            try:
                data, _ = json.JSONDecoder().raw_decode(text, start)
            except json.JSONDecodeError:
                return

            raw_topic = data.get("topic", "")
            topic = raw_topic.strip() if isinstance(raw_topic, str) else ""

            # Atomic load → dedupe → trim → save under _memory_lock so we
            # cannot lose writes that race with the ambient extractor.
            added_facts, added_projects = merge_memory(
                new_facts=data.get("new_facts"),
                new_projects=data.get("new_projects"),
                new_topic=topic,
            )

            added = [f"fact: {f}" for f in added_facts] \
                  + [f"project: {p}" for p in added_projects]
            if added:
                print(f"  [learned] {'; '.join(added)}")

        except Exception as e:
            # Log to console (which logs to file too) but don't break the chat
            print(f"  [learn] failed: {type(e).__name__}: {e}")

    threading.Thread(target=_worker, daemon=True).start()


# Content heuristic for the voice-ID-unavailable fallback: a transcript shorter
# than this many characters OR fewer than this many words is treated as a stray
# TV/room fragment and NOT ingested. Mirrors _ambient_learning_feed's drop rule
# so the two ambient paths agree on what counts as "too little signal".
_AMBIENT_LEARN_MIN_CHARS = 8
_AMBIENT_LEARN_MIN_WORDS = 3


def _ambient_media_is_playing() -> bool:
    """True if ANY independent signal says the mic is hearing the TV/stereo (not
    the owner's conversation), so ambient-learning must NOT ingest the transcript:
      • the Windows media session (SMTC) reports media PLAYING, OR
      • the spectral room-music detector reports sustained music, OR
      • the CAMERA-BASED TV detector sees a bright, flickering screen ON.
    The camera signal is independent of audio — it catches a TV the audio gates
    miss (a muted TV, an unrecognised stream, a show the content judge can't
    place). Never raises — any error in a probe is treated as 'not playing' so a
    probe glitch can't wedge the gate."""
    # SMTC (Chrome/Spotify/Apple Music/YouTube/etc.). Reuses the gate's helper.
    try:
        if _smtc_media_playing():
            return True
    except Exception:
        pass
    # Spectral detector — sustained (>15s) room music from an external TV the OS
    # can't see. is_music_currently_playing() is the tested public predicate.
    try:
        mod = sys.modules.get("skill_standby_audio_detect")
        if mod is not None and bool(mod.is_music_currently_playing()):
            return True
    except Exception:
        pass
    # Camera-based TV detector (opt-in, TV_DETECT_ENABLED): a bright + flickering
    # screen in view is independent VISUAL evidence the room audio is the TV.
    # is_tv_on() is fail-safe (False unless enabled AND it positively sees a TV).
    try:
        mod = sys.modules.get("skill_tv_detect")
        if mod is not None and bool(mod.is_tv_on()):
            print("  [ambient-learn] suppressing: camera sees a TV ON "
                  "(bright + flickering screen) — not learning from room audio")
            return True
    except Exception:
        pass
    return False


def _ambient_owner_voice(audio, sample_rate: int) -> "tuple[bool, str, float]":
    """Decide whether `audio` is the OWNER (an enrolled speaker) for the purpose
    of ambient-learning ingestion.

    Returns ``(should_gate_on_voice, status, score)`` where:
      * status == "owner"      → an enrolled voice matched above threshold; INGEST.
      * status == "unknown"    → voice-ID is available + someone IS enrolled, but
                                 this utterance did NOT match → SKIP (likely TV/
                                 another person). ``should_gate_on_voice`` True.
      * status == "unavailable"→ resemblyzer missing, nobody enrolled, or no audio
                                 buffer for this turn → caller falls back to the
                                 media-suppress + content heuristic.
                                 ``should_gate_on_voice`` False.
    Never raises."""
    try:
        import core.voice_id as _vid
    except Exception:
        return (False, "unavailable", 0.0)
    try:
        if audio is None or sample_rate <= 0:
            return (False, "unavailable", 0.0)
        if not _vid.is_available():
            return (False, "unavailable", 0.0)
        # No enrollments → single-user fallback; voice-ID can't distinguish the
        # owner from the TV, so defer to the heuristic rather than claim "owner".
        if not _vid.list_enrolled():
            return (False, "unavailable", 0.0)
        name, score = _vid.identify_speaker(audio, sample_rate)
        if name:
            return (True, "owner", float(score))
        return (True, "unknown", float(score))
    except Exception as _e:
        print(f"  [ambient-learn] voice-ID probe failed: "
              f"{type(_e).__name__}: {_e}")
        return (False, "unavailable", 0.0)


def _ambient_content_is_media(snippet: str) -> bool:
    """CONTENT JUDGE for ambient learning: ask the cheap LOCAL model whether
    ``snippet`` is a line FROM media (a TV show / movie line, song lyric, or an
    advertisement) rather than a real person's conversation.

    This is the last line of defence for the case the media-state + voice-ID
    gates miss: a TV the OS can't see (no SMTC now-playing) that isn't sustained
    enough to trip the spectral detector, with voice-ID unavailable — e.g. an
    episode of *My Name Is Earl* murmuring in the next room. Such audio looks
    like ordinary content-rich speech to every other gate, so we judge it purely
    on CONTENT.

    Returns True ONLY when the model clearly answers that this is media → the
    caller SKIPS ingestion. FAIL-OPEN by design: an empty/ambiguous answer, a
    local model that's down (Smart App Control blocked it, nothing pulled), or
    any error returns False so genuine conversation is never silently dropped
    when the judge can't run. Goes straight to ``_call_local_llm`` (never the
    cloud) so the judge is free and matches the ambient forced-local contract.
    Never raises."""
    try:
        text = (snippet or "").strip()
        if not text:
            return False
        system = (
            "You are a strict binary classifier. Decide whether a short "
            "overheard transcript is a line FROM media (a TV show or movie "
            "line of dialogue, song lyrics, or an advertisement / commercial) "
            "rather than a real person talking in the room. Answer with ONLY "
            "one word: MEDIA or PERSON. No punctuation, no explanation."
        )
        user = f"Transcript: {text!r}\nAnswer (MEDIA or PERSON):"
        out = _call_local_llm(
            system, [{"role": "user", "content": user}], max_tokens=4)
        if not out:
            # Local judge unavailable/empty — fail open (treat as not-media so
            # real conversation still learns). Logged by the caller's decision.
            return False
        verdict = out.strip().upper()
        # Match the token anywhere in the reply so a chatty local model that
        # wraps the word ("MEDIA.", "Answer: MEDIA") is still understood; only
        # an explicit MEDIA verdict (and not a PERSON one) suppresses.
        is_media = ("MEDIA" in verdict) and ("PERSON" not in verdict)
        return bool(is_media)
    except Exception as _e:
        print(f"  [ambient-learn] content judge errored "
              f"({type(_e).__name__}: {_e}) — failing open (not media)")
        return False


def _ambient_should_learn_text(snippet: str, conf=None,
                               peak_rms: float = 0.0) -> bool:
    """Final pre-ingest gate shared by BOTH ambient-learn ingest paths (owner
    voice + voice-ID-unavailable heuristic). Returns True only if the snippet is
    worth feeding to learn_from_turn. Logs the decision either way.

    Two checks, in cheap-first order:
      (1) SPEECH VALIDITY — run the SAME is_valid_speech() confidence + RMS +
          hallucination filter normal turns use, so a low-confidence Whisper
          hallucination is never *learned* (scan finding 8). The wake-word
          requirement is the one part that does NOT apply here: ambient text is
          non-wake BY DEFINITION (the background-audio gate dropped it precisely
          because it lacked the wake word), so a "missing wake word" verdict is
          tolerated; every other invalid reason suppresses ingestion.
      (2) CONTENT JUDGE — the local-LLM media classifier above, to catch a TV
          with no now-playing signal purely by content.

    conf may be None (callers without per-turn Whisper metadata — e.g. the unit
    tests and the _ambient_learning_feed sibling): in that case the confidence
    gate is skipped and only the hallucination/length checks + content judge
    run. Never raises (any error fails OPEN → True, so a gate hiccup can't
    silently stop all learning)."""
    try:
        text = (snippet or "").strip()
        # (1) speech-validity gate (skipped when we have no Whisper metadata).
        if conf is not None:
            try:
                valid, reason = is_valid_speech(text, conf, peak_rms=peak_rms)
                if not valid and not reason.startswith("missing wake word"):
                    print("  [ambient-learn] skipped: failed speech validity "
                          f"({reason})")
                    return False
            except Exception as _ve:
                # A validity-check error must not block learning.
                print(f"  [ambient-learn] speech-validity check errored "
                      f"({type(_ve).__name__}: {_ve}) — failing open")
        # (2) content judge (local-LLM): drop media lines (TV/movie/lyrics/ad).
        if _ambient_content_is_media(text):
            print("  [ambient-learn] skipped: content judge says MEDIA "
                  "(TV/movie/lyrics/ad, not a real conversation)")
            return False
        return True
    except Exception as _e:
        print(f"  [ambient-learn] pre-ingest gate errored "
              f"({type(_e).__name__}: {_e}) — failing open")
        return True


def _ambient_learn_from_gated(text: str, memory: dict,
                              audio=None, sample_rate: int = 0,
                              conf=None, peak_rms: float = 0.0) -> None:
    """Alexa-mode ambient learning: keep PASSIVELY learning from gated speech —
    but ONLY the owner's genuine conversation, NEVER the TV / music / strangers.

    The background-audio gate (_should_refuse_background_audio) drops a non-wake
    utterance and `continue`s — so during wake-word / music / TV mode JARVIS was
    learning NOTHING from what it overheard. The owner wants it to still learn
    from gated speech while only RESPONDING to wake-prefixed commands. This feeds
    the transcribed text into the SAME ambient-learning extractor a normal turn
    uses (learn_from_turn), with an empty assistant reply so no fabricated
    assistant context leaks in. learn_from_turn already runs its extraction on a
    background daemon and only writes durable facts via merge_memory — it never
    speaks or triggers a reply, so this is response-free by construction.

    OWNER-vs-TV decision (2026-06-07 audit — "JARVIS learned the TV"):
      1. SKIP if media/music is playing (SMTC or the spectral detector) — that
         audio is the TV/stereo, not the owner.
      2. VOICE-ID gate: if an enrolled voiceprint matches this utterance's audio,
         INGEST; if voice-ID is available + someone is enrolled but the speaker
         is UNKNOWN, SKIP (the TV or another person).
      3. If voice-ID is unavailable / nobody enrolled / no audio buffer, fall back
         to (1) PLUS a content heuristic: SKIP very short / low-information
         transcripts (stray TV fragments), INGEST the rest.
      4. FINAL gate before EVERY ingest (_ambient_should_learn_text): the same
         is_valid_speech() confidence/RMS/hallucination filter normal turns use
         (so a low-confidence Whisper hallucination is never *learned* — scan
         finding 8; the wake-word part is skipped since ambient is non-wake by
         definition), PLUS a cheap LOCAL-LLM CONTENT JUDGE that SKIPs a line of
         TV/movie dialogue, song lyrics, or an advertisement. (4) is what catches
         a TV the OS can't see, with no now-playing signal (the My Name Is Earl
         case), purely by content — passing conf/peak_rms enables the speech
         check; both default off (conf=None) so callers without Whisper metadata
         still work.

    Every decision logs one concise line ([ambient-learn] ingested … / skipped …
    + reason) so the owner-vs-TV behaviour is observable in the session log.

    Gated FIRST on AMBIENT_LISTEN_ENABLED (the Settings ambient-listening knob);
    a no-op when off. NEVER raises — a learning hiccup must not break the gate's
    drop-and-continue."""
    if not AMBIENT_LISTEN_ENABLED:
        return
    try:
        snippet = (text or "").strip()
        n = len(snippet)

        # (1) Media/music suppression — applies regardless of voice-ID, because a
        # blaring TV is never the owner's conversation even if a voiceprint
        # spuriously matches a lyric.
        if _ambient_media_is_playing():
            print("  [ambient-learn] skipped: media/music playing "
                  f"(TV/stereo, not owner) ({n} chars)")
            return

        # (2) Voice-ID gate (when reliable).
        gate_on_voice, vstatus, vscore = _ambient_owner_voice(audio, sample_rate)
        if gate_on_voice:
            if vstatus == "owner":
                # Owner confirmed — still run the shared speech-validity +
                # content judge before ingesting, so a low-confidence Whisper
                # hallucination or a media line (even one a voiceprint spuriously
                # matched) is never learned.
                if not _ambient_should_learn_text(snippet, conf, peak_rms):
                    return
                learn_from_turn(snippet, "", memory)
                print(f"  [ambient-learn] ingested gated text ({n} chars) "
                      f"— owner voice (score={vscore:.2f})")
                return
            # vstatus == "unknown": enrolled owner exists but this isn't them.
            print(f"  [ambient-learn] skipped: unknown speaker "
                  f"(not enrolled owner, score={vscore:.2f}) ({n} chars)")
            return

        # (3) Voice-ID unavailable → media-suppress already passed; apply the
        # content heuristic to drop stray low-information TV fragments.
        if n < _AMBIENT_LEARN_MIN_CHARS or len(snippet.split()) < _AMBIENT_LEARN_MIN_WORDS:
            print("  [ambient-learn] skipped: low-information fragment "
                  f"(voice-ID unavailable) ({n} chars)")
            return

        # Final gate: speech-validity (confidence/RMS/hallucination) + the
        # local-LLM content judge. This is the path that catches a TV with no
        # now-playing signal (the My Name Is Earl case) purely by content.
        if not _ambient_should_learn_text(snippet, conf, peak_rms):
            return

        learn_from_turn(snippet, "", memory)
        print(f"  [ambient-learn] ingested gated text ({n} chars) "
              "— no media, voice-ID unavailable (content heuristic passed)")
    except Exception as _e:
        print(f"  [ambient-learn] gated-feed skipped: {type(_e).__name__}: {_e}")


# ──────────────────────────────────────────────────────────────────────────
#  SESSION PATTERN MEMORY  — records when/how the user typically uses JARVIS
#  so it can surface patterns proactively at startup ('it's Friday night,
#  shall I queue something on Netflix?').
# ──────────────────────────────────────────────────────────────────────────

PATTERNS_DIR  = os.path.join(os.path.dirname(os.path.abspath(__file__)), "memory")
PATTERNS_FILE = os.path.join(PATTERNS_DIR, "patterns.json")
MAX_PATTERN_ENTRIES = 200
MIN_SESSIONS_FOR_PATTERN = 5    # need this many sessions before surfacing

_session_start_time = time.time()
_session_action_counts: dict[str, int] = {}
_session_app_names: set[str] = set()
_session_pattern_lock = threading.Lock()

# Replay-last-action history. parse_and_run_actions appends every executed
# (action, arg, result) tuple here; the voice trigger 'do that again' /
# 'replay that' re-fires the most recent. Bounded at 5 so the deque self-trims;
# lock protects against concurrent appends from background skill threads.
_action_history: deque = deque(maxlen=5)
_action_history_lock = threading.Lock()

# Actions we refuse to replay silently — they mutate or destroy state, or
# exit the agent. The voice trigger returns a refusal phrase instead and
# requires the user to re-issue the command explicitly so the destructive
# step gets the normal confirmation/pushback path.
_DESTRUCTIVE_REPLAY_ACTIONS = frozenset({
    "close_window",
    "kill_process",
    "restart",
    "upgrade",
    "start_overnight_upgrade",
    "run_shell",
    "reset_memory",
    "forget_last_hour",
    "clear_tasks",
    # run_python family: arbitrary-code execution. Never silently re-fire via
    # "do that again" or a fuzzy-typo disambiguation — force the user to
    # re-issue it so it re-routes through the run_python AST gate in
    # _jarvis_pushback (which defers dangerous snippets onto the confirm queue).
    "run_python",
    "python",
    "eval_python",
    "compute",
})


# Sliding 1-hour window of caught action failures. parse_and_run_actions'
# `except Exception` arm calls record_action_error() so skills/self_diagnostic
# can group repeated failures by (action, exception class), exceed the
# threshold (>=3 in 1h), and append a structured fix request to jarvis_todo.md
# — turning the self-healing pipeline from "log and forget" into "queue a real
# fix request". maxlen caps memory even if errors spike past the time prune.
_ACTION_ERROR_LOG_MAXLEN = 512
_ACTION_ERROR_LOG_WINDOW_S = 3600.0
_action_error_log: deque = deque(maxlen=_ACTION_ERROR_LOG_MAXLEN)
_action_error_log_lock = threading.Lock()


def record_action_error(action_name: str, exc: BaseException,
                        traceback_text: str | None = None) -> None:
    """Record a caught action failure for the self-diagnostic auto-queue.

    Bounded (maxlen + 1h time window pruned on every insert) so a runaway
    failure can't grow the deque without limit. Safe to call from any thread.
    """
    try:
        now = time.time()
        if traceback_text is None:
            try:
                traceback_text = traceback.format_exc()
            except Exception:
                traceback_text = ""
        entry = {
            "ts":         now,
            "action":     str(action_name)[:80],
            "exc_class":  type(exc).__name__,
            "exc_msg":    str(exc)[:240],
            "traceback":  (traceback_text or "")[-4096:],
        }
        cutoff = now - _ACTION_ERROR_LOG_WINDOW_S
        with _action_error_log_lock:
            _action_error_log.append(entry)
            while _action_error_log and _action_error_log[0]["ts"] < cutoff:
                _action_error_log.popleft()
    except Exception:
        # Recording must never raise into the action dispatcher.
        pass


def get_recent_action_errors(window_s: float | None = None) -> list[dict]:
    """Snapshot of recorded action errors inside the given window (default 1h).
    Returns a shallow copy so the caller can iterate without holding the lock."""
    if window_s is None:
        window_s = _ACTION_ERROR_LOG_WINDOW_S
    cutoff = time.time() - float(window_s)
    with _action_error_log_lock:
        # Lazy prune on every snapshot so the deque stays bounded by age too.
        while _action_error_log and _action_error_log[0]["ts"] < cutoff:
            _action_error_log.popleft()
        return [dict(e) for e in _action_error_log if e["ts"] >= cutoff]


def get_session_log_path() -> str | None:
    """Return the live session log path, or None if logging is off / not
    initialised yet. self_diagnostic uses this to tail recent log lines into
    auto-queued fix requests."""
    p = globals().get("_log_file_path")
    return p if isinstance(p, str) and p else None


# Per-camera read-failure summary populated by _face_tracking_thread on every
# read attempt. Self-diagnostic auto-queue tails this to spot read-failure
# spikes (consecutive >5) without needing to walk the running face thread's
# private state. Lock-protected because the tracking thread updates it from a
# different thread than the diagnostic probe that reads it.
_camera_failure_summary: dict[int, dict] = {}
_camera_failure_summary_lock = threading.Lock()


def _note_camera_read_attempt(cam_index: int, *, ok: bool,
                              fails: int = 0,
                              error: str | None = None) -> None:
    """Called by _face_tracking_thread after every cap.read() so the self-
    diagnostic probe can detect read-failure spikes. Records consecutive
    failure count and, separately, the all-time-max for this session so a
    transient spike that has since recovered is still visible in the report."""
    try:
        now = time.time()
        with _camera_failure_summary_lock:
            entry = _camera_failure_summary.get(cam_index)
            if entry is None:
                entry = {
                    "consecutive_fails": 0,
                    "max_consecutive_fails": 0,
                    "last_error": None,
                    "last_error_at": 0.0,
                    "last_ok_at": 0.0,
                    "total_fails": 0,
                }
                _camera_failure_summary[cam_index] = entry
            if ok:
                entry["consecutive_fails"] = 0
                entry["last_ok_at"] = now
            else:
                entry["consecutive_fails"] = int(fails)
                entry["total_fails"] += 1
                if entry["consecutive_fails"] > entry["max_consecutive_fails"]:
                    entry["max_consecutive_fails"] = entry["consecutive_fails"]
                if error:
                    entry["last_error"] = str(error)[:240]
                entry["last_error_at"] = now
    except Exception:
        pass


def get_camera_failure_summary() -> dict[int, dict]:
    """Snapshot copy of the per-camera failure summary. Self-diagnostic uses
    this to detect read-failure spikes worth queueing a fix for."""
    with _camera_failure_summary_lock:
        return {idx: dict(v) for idx, v in _camera_failure_summary.items()}


def _load_patterns() -> list[dict]:
    if not os.path.exists(PATTERNS_FILE):
        return []
    try:
        with open(PATTERNS_FILE, "r", encoding="utf-8") as f:
            data = json.load(f)
        return data if isinstance(data, list) else []
    except Exception:
        return []


def _save_patterns(entries: list[dict]) -> None:
    try:
        os.makedirs(PATTERNS_DIR, exist_ok=True)
        tmp = PATTERNS_FILE + ".tmp"
        with open(tmp, "w", encoding="utf-8") as f:
            json.dump(entries[-MAX_PATTERN_ENTRIES:], f, indent=2)
        os.replace(tmp, PATTERNS_FILE)
    except Exception as e:
        print(f"  [patterns] save failed: {e}")


def record_action_history(action_name: str, arg: str, result: str) -> None:
    """Append an executed action to the bounded replay deque.

    Called from parse_and_run_actions after a non-confirmation action runs
    (success or in-action failure both count — the user can replay either).
    Skipped when the replay handler itself fires the action so 'do that
    again, do that again' doesn't recurse into itself.
    """
    with _action_history_lock:
        _action_history.append({
            "action": action_name,
            "arg": arg,
            "result": result if isinstance(result, str) else str(result),
            "at": time.time(),
        })


def record_session_action(action_name: str, arg: str = "") -> None:
    """Called from parse_and_run_actions for every executed action so we can
    track which actions dominate this session."""
    with _session_pattern_lock:
        _session_action_counts[action_name] = _session_action_counts.get(action_name, 0) + 1
        # Track app/url names from launch_app + open_url
        if action_name == "launch_app" and arg:
            _session_app_names.add(arg.strip().lower()[:40])
        elif action_name == "open_url" and arg:
            host = re.sub(r"^https?://", "", arg.strip()).split("/")[0].lower()
            if host:
                _session_app_names.add(host[:40])
    # Refresh the JARVIS-initiated music timestamp so ambient-music standby
    # detection doesn't fire on audio that's coming out of our own speakers.
    if action_name in MUSIC_ACTION_NAMES:
        _jarvis_played_music_at[0] = time.time()
    # Forward to the pattern_learning skill so it can mine action-level
    # habits for proactive offers. Skill is optional; absent module → no-op.
    _pl = sys.modules.get("skill_pattern_learning")
    if _pl is not None:
        try:
            _pl.log_event(action_name, arg)
        except Exception as _e:
            print(f"  [pattern_learning] log_event failed: {_e}")


def save_session_pattern() -> None:
    """At shutdown, append this session's stats to patterns.json."""
    with _session_pattern_lock:
        if not _session_action_counts and not _session_app_names:
            return
        # Sort actions by count desc, take top 5
        top_actions = sorted(_session_action_counts.items(),
                             key=lambda x: x[1], reverse=True)[:5]
        start_lt = time.localtime(_session_start_time)
        end_lt   = time.localtime()
        entry = {
            "date":         time.strftime("%Y-%m-%d", start_lt),
            "day":          time.strftime("%A", start_lt),
            "hour_started": start_lt.tm_hour,
            "hour_ended":   end_lt.tm_hour,
            "top_actions":  [name for name, _ in top_actions],
            "action_counts": dict(top_actions),
            "apps":         sorted(_session_app_names),
        }
    entries = _load_patterns()
    entries.append(entry)
    _save_patterns(entries)
    print(f"  [patterns] saved session: {entry['day']} "
          f"{entry['hour_started']:02d}:00–{entry['hour_ended']:02d}:00, "
          f"top: {entry['top_actions']}")


def detect_startup_pattern() -> str:
    """Look for a pattern matching current day/hour and return a JARVIS-style
    proactive remark, or '' if no strong pattern is found.

    Strategy:
      • Need at least MIN_SESSIONS_FOR_PATTERN total sessions.
      • Among entries within ±1 hour of current hour AND same day-of-week,
        count what dominates. If 3+ entries match, surface their dominant
        signal.
      • Distinguish 'winding down' (late-evening, streaming actions) from
        'building' (any time, dev actions / Claude Code launches).
    """
    entries = _load_patterns()
    if len(entries) < MIN_SESSIONS_FOR_PATTERN:
        return ""

    now = time.localtime()
    cur_day  = time.strftime("%A", now)
    cur_hour = now.tm_hour

    matching = [
        e for e in entries
        if e.get("day") == cur_day and abs(e.get("hour_started", 0) - cur_hour) <= 1
    ]
    if len(matching) < 3:
        return ""

    # Tally top actions across matching sessions
    tally: dict[str, int] = {}
    for e in matching:
        for a in e.get("top_actions", [])[:3]:
            tally[a] = tally.get(a, 0) + 1
    if not tally:
        return ""

    STREAMING = {"netflix", "prime_video", "disney_plus", "hulu", "max",
                 "apple_music", "spotify", "youtube_play", "play_streaming",
                 "play_music"}
    BUILDING  = {"upgrade", "queue_task", "see_screen", "create_skill",
                 "start_overnight_upgrade"}

    streaming_count = sum(tally.get(a, 0) for a in STREAMING)
    building_count  = sum(tally.get(a, 0) for a in BUILDING)

    is_evening = cur_hour >= 19 or cur_hour < 4

    if streaming_count >= 3 and is_evening:
        return (f"It's {cur_day} evening, sir. Based on your recent pattern, "
                f"you usually wind down around now — shall I queue something "
                f"on Netflix?")
    if building_count >= 3:
        return (f"You typically start a build session around this time, sir. "
                f"Claude Code is available if you'd like to kick one off.")
    return ""


def save_session_to_memory(memory: dict):
    """On shutdown: write a one-sentence summary of this session."""
    if len(conversation_history) < 4:
        return
    print("\nSummarising session…")
    # Snapshot first — list() is an atomic copy under the GIL, so a background
    # append (pending-speech / proactive-alert thread) during shutdown can't
    # change the list size mid-iteration and raise RuntimeError.
    transcript = "\n".join(
        f"{m['role'].title()}: {m['content']}" for m in list(conversation_history)
    )
    try:
        text = _llm_quick(
            system="Summarise this conversation in ONE sentence. Just the sentence, nothing else.",
            user=transcript, max_tokens=80,
        )
        summary = text.strip().split("\n")[0]
        if summary:
            session_entry = {
                "date":     time.strftime("%Y-%m-%d"),
                "ts":       time.time(),   # numeric epoch for last-hour forget
                "location": LOCATION,
                "summary":  summary,
            }
            # CRITICAL: persist via a FRESH locked read-modify-write — do NOT
            # save the long-lived `memory` dict. That dict is the startup
            # snapshot; every fact/project/topic the background extractor and
            # learn_from_turn merged this session was written to disk by
            # merge_memory() under _memory_lock but is ABSENT from this stale
            # copy. Saving it here overwrote bobert_memory.json with the old
            # snapshot, discarding a whole session of learning on every clean
            # shutdown (force-kills skipped this path, which masked it).
            # Mutate ONLY `sessions` on the current on-disk state. 2026-05-30 audit.
            with _memory_lock:
                _fresh = load_memory()
                _fresh.setdefault("sessions", []).append(session_entry)
                _fresh["sessions"] = _fresh["sessions"][-MAX_SESSIONS:]
                save_memory(_fresh)
            memory["sessions"] = _fresh["sessions"]   # keep local copy consistent
            print(f"Saved session: {summary}")
            # Also append to the queryable session-summary index so the
            # session_memory_recall action can find it later.
            try:
                pattern_memory.record_session_summary(
                    summary,
                    start_ts=_session_start_time,
                    end_ts=time.time(),
                    location=LOCATION,
                )
            except Exception as _e:
                print(f"  [pattern_memory] session-summary append failed: {_e}")
    except Exception as e:
        print(f"Session save failed: {e}")


# Interval between in-session summary checkpoints. The shutdown-only writer
# (save_session_to_memory) almost never ran because JARVIS is usually
# force-killed / crashes / killed by the upgrade pipeline — all of which bypass
# the clean-exit hook, leaving session_summaries.json empty (2026-05-30 audit).
# This periodic checkpoint persists a summary mid-session so a crash loses at
# most ~10 minutes of recall context. record_session_summary() is idempotent
# per session (keyed on iso_start), so each checkpoint UPDATES one entry rather
# than appending duplicates.
_SESSION_CHECKPOINT_INTERVAL_S = 600          # 10 minutes
_session_checkpoint_last_len   = [0]          # conversation_history len at last checkpoint


def _session_summary_checkpoint_thread():
    """Background daemon: periodically write a one-sentence session summary so
    the recall index survives an unclean exit. Skips work when the conversation
    hasn't grown since the last checkpoint (no new turns → no new LLM cost)."""
    # Give the session a chance to accumulate a few turns before first write.
    time.sleep(_SESSION_CHECKPOINT_INTERVAL_S)
    while True:
        try:
            # Snapshot under the GIL (list() copy is atomic) so the main thread
            # appending/popping conversation_history mid-iteration can't raise
            # "list changed size during iteration" in this background thread.
            _hist = list(conversation_history)
            hist_len = len(_hist)
            # Only checkpoint when there's something new worth summarising.
            if hist_len >= 4 and hist_len != _session_checkpoint_last_len[0]:
                transcript = "\n".join(
                    f"{m['role'].title()}: {m['content']}"
                    for m in _hist
                )
                try:
                    text = _llm_quick(
                        system=("Summarise this conversation in ONE sentence. "
                                "Just the sentence, nothing else."),
                        user=transcript, max_tokens=80,
                    )
                    summary = (text or "").strip().split("\n")[0]
                    if summary:
                        pattern_memory.record_session_summary(
                            summary,
                            start_ts=_session_start_time,
                            end_ts=time.time(),
                            location=LOCATION,
                        )
                        _session_checkpoint_last_len[0] = hist_len
                        print(f"  [session-checkpoint] saved: {summary[:80]}")
                except Exception as _e:
                    print(f"  [session-checkpoint] summary failed: {_e}")
        except Exception as _e:
            print(f"  [session-checkpoint] loop error: {_e}")
        time.sleep(_SESSION_CHECKPOINT_INTERVAL_S)


# ──────────────────────────────────────────────────────────────────────────
#  LOGGING  — write everything stdout/stderr to a timestamped file
# ──────────────────────────────────────────────────────────────────────────

class _TimestampedTee:
    """Mirror writes to console AND a log file. Log file gets timestamps;
    console output is left untouched so the live terminal stays clean."""
    def __init__(self, console, log_file):
        self.console     = console
        self.log_file    = log_file
        self._line_start = True

    def write(self, msg):
        # Console: as-is
        try:
            self.console.write(msg)
            self.console.flush()
        except Exception:
            pass
        # File: prepend timestamp at the start of every line
        try:
            for ch in msg:
                if self._line_start and ch != "\n":
                    self.log_file.write(time.strftime("[%H:%M:%S] "))
                    self._line_start = False
                self.log_file.write(ch)
                if ch == "\n":
                    self._line_start = True
            self.log_file.flush()
        except Exception:
            pass

    def flush(self):
        try: self.console.flush()
        except Exception: pass
        try: self.log_file.flush()
        except Exception: pass

    def isatty(self):
        # A tee-to-logfile is NOT an interactive terminal. Report False so any
        # library that probes stdout for terminal-ness degrades to plain output.
        # 2026-07-07: the LTM embedder (sentence-transformers -> huggingface_hub /
        # tqdm, after the chatterbox-driven transformers 5.9->5.2 downgrade) calls
        # sys.stdout.isatty() while loading; without this method it AttributeError-ed,
        # the bge-small load failed, and the LTM loader hot-retried it in a tight
        # loop (observed: 174 model loads / 58 isatty failures in one session) —
        # hammering CPU + disk. Returning False loads the model cleanly, once.
        return False

    def fileno(self):
        # Delegate to the real console fd when there is one (a live terminal);
        # under pythonw the console is None, so signal "no underlying fd" the
        # standard way (OSError, which well-behaved libs catch) rather than
        # AttributeError-ing on a probe.
        if self.console is not None:
            try:
                return self.console.fileno()
            except Exception:
                pass
        raise OSError("fileno is not supported on _TimestampedTee")

    def __getattr__(self, name):
        # A stdout replacement can be probed for arbitrary stream attributes by
        # third-party libs (encoding, buffer, closed, ...). Delegate anything we
        # don't implement to the underlying console when present; otherwise raise
        # AttributeError normally so hasattr()-style probes fall back gracefully.
        # NB: only called for attributes NOT found the normal way, so the real
        # write/flush/isatty/fileno above and the __dict__ fields are unaffected.
        console = self.__dict__.get("console")
        if console is not None:
            return getattr(console, name)
        raise AttributeError(name)


_log_file_handle = None
_log_file_path   = None


def _cleanup_old_logs():
    if not os.path.isdir(LOGS_DIR):
        return
    try:
        logs = sorted(
            (os.path.join(LOGS_DIR, f) for f in os.listdir(LOGS_DIR) if f.endswith(".log")),
            key=os.path.getmtime,
        )
        for old in logs[:-LOG_KEEP_COUNT]:
            try: os.unlink(old)
            except Exception: pass
    except Exception:
        pass


def setup_logging():
    """Redirect stdout/stderr to a Tee that also writes to a timestamped log
    file. Install a global exception hook so crashes are captured too."""
    global _log_file_handle, _log_file_path
    if not LOGGING_ENABLED:
        return
    os.makedirs(LOGS_DIR, exist_ok=True)
    _cleanup_old_logs()

    fname = f"session_{time.strftime('%Y-%m-%d_%H-%M-%S')}.log"
    _log_file_path   = os.path.join(LOGS_DIR, fname)
    _log_file_handle = open(_log_file_path, "w", encoding="utf-8", buffering=1)

    # Header at the top of the log
    _log_file_handle.write(
        f"=== J.A.R.V.I.S. session log ===\n"
        f"Started:  {time.strftime('%Y-%m-%d %H:%M:%S')}\n"
        f"Location: {LOCATION}\n"
        f"Python:   {sys.version.splitlines()[0]}\n"
        f"Platform: {sys.platform}\n"
        f"==========================\n\n"
    )

    sys.stdout = _TimestampedTee(sys.__stdout__, _log_file_handle)
    sys.stderr = _TimestampedTee(sys.__stderr__, _log_file_handle)

    # Catch anything that escapes a try/except so crashes end up in the log
    def _excepthook(exc_type, exc_value, exc_tb):
        import traceback
        print("\n[FATAL] Uncaught exception:", file=sys.stderr)
        traceback.print_exception(exc_type, exc_value, exc_tb, file=sys.stderr)
        sys.stderr.flush()
    sys.excepthook = _excepthook

    # task-68: silent crashes (PIDs 21424, 37600, 43380, 45708) all died
    # without a Python traceback because the crash was native — OpenCV
    # release/reopen, PortAudio race, comtypes-on-Bambu-MQTT timeout
    # cascade etc. The standard excepthook above only catches Python
    # exceptions; SIGSEGV in a C extension bypasses it entirely.
    # faulthandler.enable() dumps a Python+native stack on SIGSEGV/SIGABRT
    # so the next silent crash actually leaves a trace.
    try:
        import faulthandler
        # _TimestampedTee doesn't expose fileno(), so route faulthandler
        # directly to a dedicated crash file. Open on a real OS fd so
        # SIGSEGV in a C extension can write to it after Python state
        # is unsafe to touch.
        _crash_log_path = os.path.join(LOGS_DIR, "crash_traces.log")
        _crash_fd = open(_crash_log_path, "ab", buffering=0)
        faulthandler.enable(file=_crash_fd, all_threads=True)
        print(f"  [faulthandler] enabled — native crashes -> {_crash_log_path}")
    except Exception as _fh_e:
        print(f"  [faulthandler] not available: {_fh_e}")


def close_log():
    """Called at clean shutdown to write a footer and close the file."""
    if _log_file_handle is None:
        return
    try:
        _log_file_handle.write(f"\n=== Session ended {time.strftime('%Y-%m-%d %H:%M:%S')} ===\n")
        _log_file_handle.flush()
        _log_file_handle.close()
    except Exception:
        pass


# ──────────────────────────────────────────────────────────────────────────
#  ROBOT CONTROL
# ──────────────────────────────────────────────────────────────────────────

def send(**kwargs):
    if not ROBOT_ENABLED:
        return
    try:
        requests.get(ROBOT_URL, params=kwargs, timeout=0.4)
    except Exception:
        pass


# Tracks the most recently set high-level state so action-dispatch code can
# revert now_doing back to the right label after an EXECUTING: ... burst.
_current_state_label = ["Idle"]


def _now_doing_label(state: str) -> str:
    """Build the now_doing string for the holographic now_doing ring.
    Thinking includes the active LLM model name so the user can tell at a
    glance whether Claude or local LLM is on the wire (jarvis_todo.md
    2026-05-29 18:05 — 'are you working' confusion fix)."""
    s = (state or "idle").lower()
    if s == "thinking":
        # Show the RESOLVED local tag, not the vestigial OLLAMA_MODEL constant
        # (still the retired "llama3" default) — the label read "THINKING
        # (llama3)" while gemma4:12b was actually on the wire. Read the resolver
        # CACHE, never _get_local_llm_model() here: on a cold cache it does a 2s
        # blocking /api/tags GET, and this is the hot UI-label path. 2026-07-14.
        model = (CLAUDE_MODEL if AI_BACKEND == "claude"
                 else (_RESOLVED_LOCAL_LLM_MODEL[0] or LOCAL_LLM_MODEL))
        return f"THINKING ({model})"
    if s == "listening":
        return "LISTENING"
    if s == "speaking":
        return "SPEAKING"
    if s == "standby":
        return "STANDBY"
    if s == "sleep":
        return "SLEEP"
    return "IDLE"


def set_state(state: str):
    if state == "idle":
        # If standby is active, surface that in the HUD instead of plain Idle —
        # the robot pose is the same idle neutral, but the label reads 'Standby'.
        if _standby_mode[0]:
            send(eyes_x=0.5, eyes_y=0.5, leds="off")
            _current_state_label[0] = "Standby"
            _write_hud_state(state="Standby",
                             now_doing=_now_doing_label("standby"))
            return
        send(eyes_x=0.5, eyes_y=0.5, leds="white")
    elif state == "listening":
        send(eyes_x=0.5, eyes_y=0.25, leds="white")   # eyes up = attentive
    elif state == "thinking":
        send(eyes_x=0.5, eyes_y=0.65, leds="off")      # eyes down = processing
    elif state == "speaking":
        send(eyes_x=0.5, eyes_y=0.35, leds="pink")
    elif state == "sleep":
        send(eyes_x=0.5, eyes_y=0.5, left_arm=0.0, right_arm=0.0, leds="off", mouth=0.0)
    # Mirror state into the HUD file so jarvis_hud.py can render it
    _current_state_label[0] = state.capitalize()
    _write_hud_state(state=state.capitalize(),
                     now_doing=_now_doing_label(state))


# ──────────────────────────────────────────────────────────────────────────
#  HUD STATE  — written every set_state() so the overlay can read it
# ──────────────────────────────────────────────────────────────────────────

HUD_STATE_FILE = _BLUE_GREEN_PATHS["hud_state_file"]
_hud_state_lock = threading.Lock()
_hud_state_cache: dict = {
    "state": "Idle", "now_playing": "", "timers": [],
    "mic_level": 0.0, "active_action": "",
    # now_doing — single-string realtime status for the holographic HUD's
    # now_doing ring (jarvis_todo.md 2026-05-29 18:05). Combines current
    # high-level state with EXECUTING: <action> while a handler is on the
    # wire. Written by set_state() and parse_and_run_actions().
    "now_doing": "IDLE",
    # Ticker fields (jarvis_todo.md 2026-05-27 06:15 — ticker line):
    # recent_action remains set after an action completes so the HUD can
    # show 'last: X (Ns ago)' even when no action is currently running.
    "recent_action": "", "recent_action_at": 0.0,
    # Epoch seconds when .overnight_active expires. 0 when overnight isn't
    # active. The HUD reads this to render the countdown timer.
    "overnight_expiry": 0.0,
    # Last heard user transcript — published from the main loop right after
    # whisper validates an utterance. Surfaces as the S radial readout.
    "last_transcript": "", "last_transcript_at": 0.0,
    # Rolling 5-entry transcript history — most-recent-last. Drives the
    # holographic HUD v2 scrolling transcript panel (jarvis_todo.md
    # 2026-05-29 09:18 holographic_hud_v2). Appended to in the main loop
    # alongside last_transcript; capped at 5 entries on write.
    "transcript_history": [],
    # Last [intent:xxx] tag parsed from the most recent LLM reply (see
    # _parse_intent_tag). Surfaces in the holographic HUD v2 INTENT row.
    "last_intent_tag": "",
    # Last spoken JARVIS reply — published from _speak() right before TTS.
    # Surfaces in the holographic overlay's center text panel (the "what
    # JARVIS just said" half of the spec for jarvis_todo.md 2026-05-27 09:18).
    "last_spoken": "", "last_spoken_at": 0.0,
    # TTS playback amplitude (0.0–1.0) — published from play_with_lipsync()
    # at ~30 Hz during speech. Drives the speaking-state ring brightness in
    # the arc-reactor HUD (jarvis_todo.md 2026-05-27 07:31, arc_reactor_hud).
    "tts_amplitude": 0.0,
    # System-tray applet (tray.py) status flags. Republished by a tiny
    # background thread that polls the system_monitor + bambu_monitor
    # skill modules — they live in separate skill_* modules and don't
    # import bobert_companion directly, so this publisher is the bridge.
    "alert_active": False,    # sustained CPU/RAM alert from skills/system_monitor
    "bambu_active": False,    # Bambu H2D mid-print (gcode_state == RUNNING)
}
# Seed the persisted tray-toggle cells from an existing hud_state.json at import,
# BEFORE any _write_hud_state can run. _write_hud_state serialises
# dict(_hud_state_cache) and os.replace-s the WHOLE file, and this literal omits
# every toggle key — so a HUD write landing before _restore_tray_toggle_state()
# would overwrite hud_state.json with a cache that never held them, wiping the
# user's persisted standby/mute/ambient/paused/debug/audio state across a restart.
# Seeding here makes those writes MERGE onto the toggles instead of dropping them.
# Best-effort: a missing/corrupt file just leaves the in-literal defaults.
try:
    if os.path.exists(HUD_STATE_FILE):
        with open(HUD_STATE_FILE, "r", encoding="utf-8") as _hud_seed_f:
            _persisted_hud = json.load(_hud_seed_f)
        if isinstance(_persisted_hud, dict):
            for _hud_k in ("tts_muted", "mic_muted", "sleep_mode", "standby_mode",
                           "ambient_mode_active", "daemons_paused", "debug_mode",
                           "audio_processing_enabled", "echo_cancel_enabled",
                           "noise_suppress_enabled", "agc_enabled"):
                if _hud_k in _persisted_hud:
                    _hud_state_cache[_hud_k] = _persisted_hud[_hud_k]
except Exception:
    pass
_last_mic_hud_write = [0.0]  # throttle audio→HUD writes to ~10Hz


def _write_hud_state(**updates):
    """Merge updates into the HUD state cache and atomically write it.
    Silent on any failure — HUD is a nice-to-have, not load-bearing."""
    if not HUD_ENABLED:
        return
    try:
        # Whole read-modify-write under the lock. Previously only the cache
        # merge was locked; the file write used a FIXED shared temp
        # (HUD_STATE_FILE + ".tmp") OUTSIDE the lock, so two of the ~30
        # concurrent callers (amp pump @30Hz, tray publisher, _speak, main
        # loop) could truncate the same temp mid-dump and os.replace a half-
        # written file — a corrupt hud_state.json. A per-call mkstemp temp plus
        # the serialized replace removes both the collision and the lost update.
        with _hud_state_lock:
            _hud_state_cache.update(updates)
            data = dict(_hud_state_cache)
            data["updated_at"] = time.time()
            _dir = os.path.dirname(os.path.abspath(HUD_STATE_FILE)) or "."
            _fd, _tmp = tempfile.mkstemp(dir=_dir, prefix=".hud_", suffix=".tmp")
            try:
                with os.fdopen(_fd, "w", encoding="utf-8") as f:
                    json.dump(data, f)
                os.replace(_tmp, HUD_STATE_FILE)
            except Exception:
                try:
                    if os.path.exists(_tmp):
                        os.remove(_tmp)
                except Exception:
                    pass
                raise
    except Exception:
        pass


_hud_process = None


def _launch_hud():
    """Spawn the unified HUD (hud/jarvis_unified_hud.py) pinned to HUD_MONITOR.
    The HUD auto-exits when its parent (us) dies, so we don't strictly need to
    manage it on shutdown, but we still call terminate() in main() for clean
    closes.

    2026-05-30: repointed from the old slim corner ring (hud/jarvis_hud.py) to
    the unified, draggable/resizable, feature-packed HUD. The unified HUD
    honours the blue/green plumbing below: --state-file repoints its state +
    control + geometry files into the role's data dir (so a staging HUD never
    reads prod state or clobbers prod geometry) and --role != "prod" renders
    the STAGING badge. On a normal prod boot both keep their prod defaults and
    the HUD's own saved geometry still wins over the first-launch anchor."""
    global _hud_process
    if not HUD_ENABLED:
        return
    # IDEMPOTENT (2026-08-20). This used to Popen unconditionally and reassign
    # _hud_process, so a second call ORPHANED the first HUD: the old handle was
    # overwritten and _shutdown_hud could then only terminate the newest one.
    # That was survivable while the only callers were boot and the tray (which
    # calls _shutdown_hud first) -- but core.actions._restore_hud now relaunches
    # a dead HUD from the voice path, and the tray route runs BOTH. poll() is
    # the right liveness test here: it is None while the child lives and an int
    # once it exits. Never psutil.pid_exists -- that reads True for a Windows
    # corpse and for a recycled PID.
    if _hud_process is not None:
        try:
            if _hud_process.poll() is None:
                return
        except Exception:
            pass          # unreadable handle -> fall through and respawn
    hud_path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                            "hud", "jarvis_unified_hud.py")
    if not os.path.exists(hud_path):
        print(f"  [hud] script missing at {hud_path} — skipping")
        return
    # Honour the manager's per-role monitor pick when blue/green is active.
    monitor_name = HUD_MONITOR
    try:
        if _bgm is not None:
            monitor_name = (_BLUE_GREEN_PATHS.get("monitor_name")
                            or HUD_MONITOR)
    except Exception:
        pass
    mon = MONITORS.get(monitor_name)
    if not mon:
        # Defensive fallback — staging on a single-monitor laptop falls
        # back to the primary monitor rather than crashing _launch_hud.
        mon = MONITORS.get("top") or MONITORS.get("middle") or (0, 0, 1920, 1080)
    mx, my, mw, mh = (list(mon) + [0, 0, 1920, 1080])[:4]

    # First-launch geometry for the unified HUD: a portrait panel tucked into
    # the top-right corner of the chosen monitor, out of the central work area.
    # (The old corner-ring wanted the full monitor width; the unified HUD is a
    # portrait card, so we pass a fixed size instead of mw.) After the user
    # drags/resizes it once, the HUD's own saved geometry
    # (unified_hud_geometry.json) overrides these — this only decides where it
    # first appears.
    HUD_W, HUD_H = 430, 580
    hud_x = int(mx) + int(mw) - HUD_W - 40
    hud_y = int(my) + 40

    # Pass the blue/green role + per-role state file so the HUD can render
    # its STAGING badge and test-progress overlay without inspecting argv
    # globally. Both args default to safe values inside the HUD script so
    # an older HUD binary keeps working.
    role = BLUE_GREEN_ROLE
    state_file = _BLUE_GREEN_PATHS.get("hud_state_file", "")

    try:
        argv = [sys.executable, hud_path,
                "--x", str(hud_x), "--y", str(hud_y),
                "--width", str(HUD_W), "--height", str(HUD_H),
                "--parent-pid", str(os.getpid()),
                "--role", role]
        if state_file:
            argv.extend(["--state-file", state_file])
        env = os.environ.copy()
        env["BLUE_GREEN_ROLE"] = role
        _hud_process = subprocess.Popen(
            argv,
            creationflags=(subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0),
            close_fds=True,
            env=env,
        )
        print(f"  [hud] launched on {monitor_name} monitor "
              f"(role={role}, pid {_hud_process.pid})")
    except Exception as e:
        print(f"  [hud] launch failed: {e}")
        _hud_process = None


# ──────────────────────────────────────────────────────────────────────────
#  RETICLE OVERLAY  — full-virtual-screen target reticle for UI automation
# ──────────────────────────────────────────────────────────────────────────

RETICLE_STATE_FILE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "hud_reticles.json"
)
_reticle_lock = threading.Lock()
_reticle_process = None
# Spec: 2-second reticle. Keep entries on disk a touch longer than the TTL so
# the overlay's read-loop never races a just-pruned write.
_RETICLE_DISK_TTL = 3.0


def _publish_reticle(x, y, label: str = ""):
    """Record a UI-automation event for the reticle overlay to draw.

    Coordinates are virtual-desktop pixels (may be negative on monitors
    placed left/above the primary). Best-effort: failures are silent so a
    write-locked or missing state file can never break a UI action."""
    if not RETICLE_OVERLAY_ENABLED:
        return
    try:
        x_i = int(x)
        y_i = int(y)
    except (TypeError, ValueError):
        return
    try:
        now = time.time()
        with _reticle_lock:
            entries = []
            if os.path.exists(RETICLE_STATE_FILE):
                try:
                    with open(RETICLE_STATE_FILE, "r", encoding="utf-8") as f:
                        data = json.load(f)
                    entries = data.get("reticles", []) or []
                    if not isinstance(entries, list):
                        entries = []
                except Exception:
                    entries = []
            # Prune anything older than the disk TTL so the file doesn't grow.
            entries = [
                r for r in entries
                if (now - float(r.get("created_at", 0) or 0)) < _RETICLE_DISK_TTL
            ]
            entries.append({
                "x": x_i, "y": y_i,
                "label": str(label)[:24],
                "created_at": now,
            })
            tmp = RETICLE_STATE_FILE + ".tmp"
            with open(tmp, "w", encoding="utf-8") as f:
                json.dump({"reticles": entries}, f)
            os.replace(tmp, RETICLE_STATE_FILE)
    except Exception:
        pass


def _active_window_center():
    """Return (cx, cy) virtual-desktop coords of the currently focused
    window, or None if it can't be determined. Used for reticles on
    actions that don't have explicit click coords (type/press/hotkey)."""
    try:
        import pygetwindow as gw
    except Exception:
        return None
    try:
        w = gw.getActiveWindow()
        if w is None:
            return None
        try:
            cx = int(w.left + w.width / 2)
            cy = int(w.top + w.height / 2)
        except Exception:
            return None
        # Clamp degenerate sizes (Win32 sometimes returns 0 width for
        # minimized windows).
        if cx == 0 and cy == 0:
            return None
        return cx, cy
    except Exception:
        return None


def _virtual_screen_bounds():
    """Compute (x, y, w, h) covering every monitor in MONITORS. Returns a
    safe default if MONITORS is empty/misconfigured."""
    xs = []
    ys = []
    for m in MONITORS.values():
        try:
            mx, my, mw, mh = m
            xs.extend([mx, mx + mw])
            ys.extend([my, my + mh])
        except Exception:
            continue
    if not xs or not ys:
        return 0, 0, 2560, 1440
    return min(xs), min(ys), max(xs) - min(xs), max(ys) - min(ys)


def _own_process_start_time() -> float:
    """This process's psutil create_time() (epoch seconds), or 0.0 when psutil is
    unavailable / the lookup fails. Passed to overlay subprocesses as
    --parent-start so their _is_parent_alive can reject a RECYCLED parent PID (a
    stranger handed our dead PID reads as a different birth time). 0.0 → the
    overlay falls back to PID-exists-only. NEVER raises."""
    try:
        import psutil
        return float(psutil.Process(os.getpid()).create_time())
    except Exception:
        return 0.0


# The overlay scripts a stale process would be running, keyed by basename so the
# reaper matches regardless of how the path was spelled on the command line.
_OVERLAY_SCRIPT_BASENAMES = ("jarvis_reticle.py", "jarvis_air_cursor.py")


def _cmdline_parent_pid(cmdline: list) -> "int | None":
    """The integer value of the ``--parent-pid`` argument in a process cmdline
    list, or None when absent / unparseable. Pure; used by the overlay reaper to
    tell OUR freshly-spawned overlays (parent-pid == our PID) from FOREIGN ones
    left behind by a previous, now-dead JARVIS."""
    try:
        for i, tok in enumerate(cmdline):
            if tok == "--parent-pid" and i + 1 < len(cmdline):
                return int(cmdline[i + 1])
            if isinstance(tok, str) and tok.startswith("--parent-pid="):
                return int(tok.split("=", 1)[1])
    except (TypeError, ValueError):
        return None
    return None


def _cmdline_runs_overlay(cmdline: list) -> bool:
    """True when this process cmdline launches one of our overlay scripts
    (jarvis_reticle.py / jarvis_air_cursor.py), matched by basename so a full or
    relative path both hit. Pure."""
    try:
        for tok in cmdline:
            if not isinstance(tok, str):
                continue
            base = os.path.basename(tok.replace("\\", "/"))
            if base in _OVERLAY_SCRIPT_BASENAMES:
                return True
    except Exception:
        return False
    return False


def _reap_stale_overlays() -> int:
    """Kill leftover overlay subprocesses (jarvis_reticle.py / jarvis_air_cursor
    .py) from a PREVIOUS JARVIS that exited without terminating them — the
    5-stale-process pile-up. We target ONLY python/pythonw processes whose
    cmdline runs one of those scripts AND whose ``--parent-pid`` is NOT our PID
    (so we never touch the overlays THIS instance is about to spawn). Returns the
    number terminated. NEVER raises — best-effort cleanup at boot.

    Called once near the singleton enforcement in main(), so the reticle + air-
    cursor windows from a crashed/replaced instance don't stack up as click-
    through layers over every monitor."""
    try:
        import psutil
    except Exception:
        return 0
    me = os.getpid()
    reaped = 0
    try:
        for proc in psutil.process_iter(attrs=["pid", "name", "cmdline"]):
            try:
                if proc.info.get("pid") == me:
                    continue
                pname = (proc.info.get("name") or "").lower()
                # Overlays run under the python/pythonw interpreter.
                if "python" not in pname:
                    continue
                cmdline = proc.info.get("cmdline") or []
                if not _cmdline_runs_overlay(cmdline):
                    continue
                # FOREIGN-PARENT ONLY: leave our own about-to-be / freshly-spawned
                # overlays (parent-pid == me) alone; reap everything else (a dead
                # parent, or no parent-pid at all → orphan).
                ppid = _cmdline_parent_pid(cmdline)
                if ppid == me:
                    continue
                proc.terminate()
                reaped += 1
                print(f"  [overlay-reaper] terminated stale overlay pid "
                      f"{proc.info.get('pid')} (parent-pid {ppid})")
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
            except Exception:
                continue
    except Exception:
        return reaped
    if reaped:
        print(f"  [overlay-reaper] reaped {reaped} stale overlay process(es) "
              f"from a previous JARVIS")
    return reaped


def _launch_reticle_overlay():
    """Spawn hud/jarvis_reticle.py as a subprocess sized to the virtual
    desktop. Silent on failure so a missing tkinter / unusual geometry
    can never break the main JARVIS startup path."""
    global _reticle_process
    if not RETICLE_OVERLAY_ENABLED:
        return
    overlay_path = os.path.join(
        os.path.dirname(os.path.abspath(__file__)),
        "hud", "jarvis_reticle.py",
    )
    if not os.path.exists(overlay_path):
        print(f"  [reticle] script missing at {overlay_path} — skipping")
        return
    vx, vy, vw, vh = _virtual_screen_bounds()
    # Reset the state file so old reticles from a previous session don't
    # render briefly on startup.
    try:
        with open(RETICLE_STATE_FILE, "w", encoding="utf-8") as f:
            json.dump({"reticles": []}, f)
    except Exception:
        pass
    try:
        _reticle_process = subprocess.Popen(
            [sys.executable, overlay_path,
             "--x", str(vx), "--y", str(vy),
             "--width", str(vw), "--height", str(vh),
             "--parent-pid", str(os.getpid()),
             # --parent-start lets the overlay reject a RECYCLED parent PID.
             "--parent-start", repr(_own_process_start_time())],
            creationflags=(subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0),
            close_fds=True,
        )
        print(f"  [reticle] launched ({vw}x{vh} @ {vx},{vy}, pid {_reticle_process.pid})")
    except Exception as e:
        print(f"  [reticle] launch failed: {e}")
        _reticle_process = None


def _shutdown_reticle_overlay():
    """Terminate the reticle overlay subprocess on clean JARVIS exit."""
    global _reticle_process
    if _reticle_process is None:
        return
    try:
        _reticle_process.terminate()
    except Exception:
        pass
    _reticle_process = None


def _shutdown_hud():
    """Terminate the HUD subprocess on clean JARVIS exit."""
    global _hud_process
    if _hud_process is None:
        return
    try:
        _hud_process.terminate()
        _hud_process = None
    except Exception:
        pass


# ──────────────────────────────────────────────────────────────────────────
#  SYSTEM TRAY APPLET  (tray.py — animated arc-reactor icon + menu)
# ──────────────────────────────────────────────────────────────────────────

TRAY_COMMANDS_FILE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "tray_commands.json"
)
_tray_process = None
_tray_drain_stop = threading.Event()
_tray_publisher_stop = threading.Event()
# Last time the HUD calendar/unread-mail were published to hud_state.json.
# The unified HUD subprocess can't import ms_graph itself (it would pull in
# this module + trip the singleton), so the main process fetches + publishes
# them here, throttled. 2026-05-30.
_hud_cal_last = [0.0]


def _launch_tray():
    """Spawn tray.py as a subprocess. Silent on failure so a missing pystray
    install can't break the rest of startup — check_dependencies() already
    warns the user with a spoken alert if pystray is unimportable."""
    global _tray_process
    if not TRAY_ENABLED:
        return
    tray_path = os.path.join(os.path.dirname(os.path.abspath(__file__)),
                             "tray.py")
    if not os.path.exists(tray_path):
        print(f"  [tray] script missing at {tray_path} — skipping")
        return
    # Reset the command inbox so commands from a previous session don't
    # fire on startup of the new one. Also clear any .inflight file left
    # behind by an unclean shutdown mid-drain.
    for _stale in (TRAY_COMMANDS_FILE, TRAY_COMMANDS_FILE + ".inflight"):
        try:
            if os.path.exists(_stale):
                os.remove(_stale)
        except Exception:
            pass
    try:
        _tray_process = subprocess.Popen(
            [sys.executable, tray_path,
             "--parent-pid", str(os.getpid())],
            creationflags=(subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0),
            close_fds=True,
        )
        print(f"  [tray] launched (pid {_tray_process.pid})")
        # Seed hud_state.json with the current audio-processing flags so the
        # tray's Audio Controls checkmarks reflect reality on first open.
        _publish_audio_state()
    except Exception as e:
        print(f"  [tray] launch failed: {e}")
        _tray_process = None


def _shutdown_tray():
    """Terminate the tray subprocess on clean JARVIS exit and signal any
    background drainer/publisher threads to stop."""
    global _tray_process
    _tray_drain_stop.set()
    _tray_publisher_stop.set()
    if _tray_process is None:
        return
    try:
        _tray_process.terminate()
    except Exception:
        pass
    _tray_process = None


def _process_inflight(inflight_path: str) -> int:
    """Read, parse, and dispatch the command list stored at inflight_path.
    Deletes the file before dispatch so relaunch-style commands cannot
    re-fire on next boot. Errors are logged but never propagate."""
    try:
        with open(inflight_path, "r", encoding="utf-8") as f:
            raw = f.read().strip()
        if not raw:
            try: os.remove(inflight_path)
            except Exception: pass
            return 0
        try:
            cmds, _ = json.JSONDecoder().raw_decode(raw)
        except Exception:
            print("  [tray] corrupt command file — deleting")
            try: os.remove(inflight_path)
            except Exception: pass
            return 0
        if not isinstance(cmds, list):
            try: os.remove(inflight_path)
            except Exception: pass
            return 0
    except Exception as e:
        print(f"  [tray] read failed: {e}")
        try: os.remove(inflight_path)
        except Exception: pass
        return 0

    # Remove the claim file BEFORE dispatch so commands that trigger
    # relaunch (restart, upgrade) don't re-fire after the new process
    # boots and sees a stale inbox.
    try: os.remove(inflight_path)
    except Exception: pass

    n = 0
    for entry in cmds:
        if not isinstance(entry, dict):
            continue
        cmd = entry.get("cmd", "")
        try:
            _dispatch_tray_command(cmd, entry)
            n += 1
        except Exception as e:
            print(f"  [tray] dispatch failed for {cmd!r}: {e}")
    return n


def _drain_tray_commands_once() -> int:
    """Atomically claim tray_commands.json, dispatch its commands, then
    delete the claim file. Returns the number of commands processed.
    Errors are logged but never propagate — the tray inbox is a
    best-effort channel.

    Atomic claim avoids a race where a tray click landing between read
    and delete would be lost: os.replace() renames the inbox to
    .inflight in one step, so any new write from tray.py's _send_command
    lands in a fresh tray_commands.json instead of being clobbered.

    Orphaned-inflight recovery: if a previous drain crashed mid-dispatch
    an .inflight file may still exist. Windows os.replace() overwrites
    its destination, so we must finish the orphaned batch BEFORE
    claiming any newly-arrived tray_commands.json — otherwise the
    claim would silently discard the orphaned commands. Any new
    commands that land during orphan processing will be picked up on
    the next drain tick."""
    inflight = TRAY_COMMANDS_FILE + ".inflight"

    # Process an orphaned inflight from a previous crash first. Doing
    # this before the os.replace() claim below prevents the new batch
    # from silently overwriting the orphan on Windows.
    n = 0
    if os.path.exists(inflight):
        n += _process_inflight(inflight)

    if not os.path.exists(TRAY_COMMANDS_FILE):
        return n

    try:
        os.replace(TRAY_COMMANDS_FILE, inflight)
    except Exception as e:
        print(f"  [tray] claim failed: {e}")
        return n

    n += _process_inflight(inflight)
    return n


def _dispatch_tray_command(cmd: str, entry: dict) -> None:
    """Route a single tray command to the matching JARVIS action handler."""
    if cmd == "enter_standby":
        _sleep_mode[0]   = True
        _standby_mode[0] = True
        # task-70: persist so a bounce comes back in standby instead of
        # "Listening…" and answering the next utterance out loud.
        _write_hud_state(state="Standby",
                         sleep_mode=True, standby_mode=True)
        print("  [tray] enter_standby — sleep + standby flags set")
    elif cmd == "force_wake":
        # Serialize with the background standby auto-engage daemon (same lock
        # the wake-word path uses) so an auto-engage firing the instant after
        # we clear these flags can't re-assert standby and leave JARVIS stuck
        # asleep with no spoken-wake recourse. 2026-05-30 deep audit.
        with _standby_auto_engage_lock:
            _sleep_mode[0]   = False
            _standby_mode[0] = False
        _write_hud_state(sleep_mode=False, standby_mode=False)
        # Mirror context_aware_greeting's bookkeeping so morning_handoff and
        # any other consumer that watches _last_wake_date sees the tray wake
        # as the day's first wake event.
        try:
            from datetime import datetime as _dt
            _last_wake_date[0] = _dt.now().date().isoformat()
        except Exception:
            pass
        # Same overnight-flag cleanup the wake-word path uses, so a wake from
        # the tray during overnight mode stops the autonomous engine cleanly.
        try:
            if os.path.exists(OVERNIGHT_FLAG_FILE):
                os.remove(OVERNIGHT_FLAG_FILE)
                _write_hud_state(overnight_expiry=0.0)
        except Exception:
            pass
        _write_hud_state(state="Idle")
        try: _speak("At your service, sir.")
        except Exception: pass
        print("  [tray] force_wake — cleared sleep/standby")
    elif cmd in ("restart", "shutdown"):
        # LLM-INDEPENDENT CONTROL PLANE (2026-07-14). Restart and shutdown were
        # reachable ONLY as voice/inject ACTIONS — which means they first pass
        # through intent classification, i.e. through the LOCAL BRAIN. So when
        # the brain is starved or wedged (VRAM pressure, a hung runner), the one
        # command that would FIX it — "restart yourself" — is exactly the command
        # you cannot issue: JARVIS answers "my local model isn't responding" and
        # stays broken. A control-plane operation must never depend on the thing
        # it is meant to repair. This channel is drained by the main loop before
        # any LLM call, so it works while the brain is face-down.
        print(f"  [tray] {cmd} — running the hardened teardown (no LLM involved)")
        try:
            # Call the MODULE-LEVEL names, not a function-local
            # `from core.actions import _act_restart, _act_shutdown_jarvis`.
            # Both are already bound here by the `from core.actions import *`
            # at the top of this file (they are listed in core.actions.__all__,
            # so the leading underscore does NOT exclude them), so the local
            # import bought nothing — but it SHADOWED the module global, which
            # meant the tray route and the ACTIONS-dict route ("restart":
            # _act_restart, below) resolved to two different lookups. Anything
            # applied at module level — a monkeypatch, a test's
            # mock.patch.object(bc, "_act_restart") — bound the ACTIONS route
            # and was silently bypassed here. That is not cosmetic: with the
            # local import in place, tests/monolith/test_monolith_sec1.py's
            # TrayDispatchTests.test_restart_command_calls_act_restart ran the
            # REAL _act_restart, which spawns a second bobert_companion.py
            # process and hard-exits the caller (proven live 2026-08-20: the
            # baseline run logged "[restart] successor spawned"). Resolving
            # through the global keeps one lookup for one command.
            if cmd == "restart":
                _act_restart("")
            else:
                _act_shutdown_jarvis("")
        except Exception as _e:
            print(f"  [tray] {cmd} failed: {type(_e).__name__}: {_e}")
    elif cmd == "open_hud":
        # Terminate the existing HUD (if any) then re-launch so a hidden /
        # crashed window comes back. _launch_hud is a no-op if HUD_ENABLED
        # is False — flip the flag on for this invocation if the user is
        # explicitly asking to see it.
        global HUD_ENABLED
        _shutdown_hud()
        if not HUD_ENABLED:
            HUD_ENABLED = True
        # Clear BOTH persisted hide latches first by delegating to the show-HUD
        # action in core.actions — the single owner of the un-hide rule. It
        # writes visible=True to hud_state.json (undoing a voice "hide HUD",
        # whose stale visible=False otherwise makes the relaunched HUD re-hide
        # itself on its first refresh) AND clears the ✕-button 'hidden' latch
        # in unified_hud_state.json. Must run AFTER the HUD_ENABLED flip above
        # (the hud-state write is a no-op while HUD_ENABLED is False) and
        # BEFORE the relaunch below so the fresh subprocess can't read stale
        # state. The returned confirmation string is discarded — the tray path
        # doesn't speak.
        try:
            from core.actions import _act_show_hud
            _act_show_hud("")
        except Exception:
            pass
        _launch_hud()
        print("  [tray] open_hud — re-launched HUD subprocess")
    # NOTE (2026-08-20): a second `elif cmd == "restart":` branch used to sit
    # here — the ORIGINAL tray-restart handler. v2.0.64 added the
    # LLM-independent `elif cmd in ("restart", "shutdown")` branch ABOVE
    # without deleting it, so this copy became unreachable dead code (the
    # earlier elif in the same chain always wins) while still LOOKING like the
    # tray-restart implementation. Classic stale duplicate: the live branch was
    # hardened and this one rotted. Removed — the branch above is the only
    # tray-restart path.
    elif cmd == "trigger_overnight":
        print("  [tray] trigger_overnight — starting overnight engine")
        try: _act_start_overnight_upgrade()
        except Exception as e:
            print(f"  [tray] overnight action failed: {e}")
    elif cmd == "audio_processing_toggle":
        _audio_master_enabled[0] = not _audio_master_enabled[0]
        _publish_audio_state()
        print(f"  [tray] audio_processing_toggle -> {_audio_master_enabled[0]}")
    elif cmd == "audio_echo_cancel_toggle":
        _audio_aec_enabled[0] = not _audio_aec_enabled[0]
        _publish_audio_state()
        print(f"  [tray] audio_echo_cancel_toggle -> {_audio_aec_enabled[0]}")
    elif cmd == "audio_noise_suppress_toggle":
        _audio_ns_enabled[0] = not _audio_ns_enabled[0]
        _publish_audio_state()
        print(f"  [tray] audio_noise_suppress_toggle -> {_audio_ns_enabled[0]}")
    elif cmd == "audio_agc_toggle":
        _audio_agc_enabled[0] = not _audio_agc_enabled[0]
        _publish_audio_state()
        print(f"  [tray] audio_agc_toggle -> {_audio_agc_enabled[0]}")
    elif cmd == "mute_tts_toggle":
        _tts_muted[0] = not _tts_muted[0]
        _write_hud_state(tts_muted=bool(_tts_muted[0]))
        print(f"  [tray] mute_tts_toggle -> {_tts_muted[0]}")
    elif cmd == "ambient_mode_toggle":
        _ambient_mode_active[0] = not _ambient_mode_active[0]
        _write_hud_state(ambient_mode_active=bool(_ambient_mode_active[0]))
        # Actually start / stop the ambient_listen daemon so the toggle
        # has runtime effect. ACTIONS may not contain ambient_listen_*
        # if the skill failed to load — fall back to a print so the user
        # still sees something happened.
        action = "ambient_listen_start" if _ambient_mode_active[0] else "ambient_listen_stop"
        fn = ACTIONS.get(action)
        if fn is not None:
            try:
                fn("")
            except Exception as e:
                print(f"  [tray] ambient_mode_toggle action {action!r} raised: {e}")
        else:
            print(f"  [tray] ambient_mode_toggle: {action!r} not registered")
        print(f"  [tray] ambient_mode_toggle -> {_ambient_mode_active[0]}")
    elif cmd == "pause_daemons_toggle":
        _daemons_paused[0] = not _daemons_paused[0]
        _write_hud_state(daemons_paused=bool(_daemons_paused[0]))
        # Mirror the toggle into the diagnostic_daemons paused-state JSON
        # (its four worker loops already check state["paused"]) AND into
        # ambient_listen via skill_ambient_listen.set_paused so its mic /
        # audio / screen loops idle instead of consuming CPU + budget.
        try:
            from core import diagnostic_daemons as _diag_daemons
            if _daemons_paused[0]:
                _diag_daemons.pause_diagnostics()
            else:
                _diag_daemons.resume_diagnostics()
        except Exception as e:
            print(f"  [tray] pause_daemons_toggle diag-daemons failed: {e}")
        try:
            _al = sys.modules.get("skill_ambient_listen")
            if _al is not None and hasattr(_al, "set_paused"):
                _al.set_paused(bool(_daemons_paused[0]))
        except Exception as e:
            print(f"  [tray] pause_daemons_toggle ambient_listen failed: {e}")
        print(f"  [tray] pause_daemons_toggle -> {_daemons_paused[0]}")
    elif cmd == "debug_mode_toggle":
        _debug_mode[0] = not _debug_mode[0]
        _write_hud_state(debug_mode=bool(_debug_mode[0]))
        print(f"  [tray] debug_mode_toggle -> {_debug_mode[0]}")
    elif cmd == "mic_mute_toggle":
        # Mute Mic: drop captured mic input before dispatch (see
        # _capture_utterance) so JARVIS hears nothing and stays idle — distinct
        # from standby (wake-word-only) and Mute TTS (still acts, just silent).
        # Drives the tray's red/muted listen indicator.
        _mic_muted[0] = not _mic_muted[0]
        _write_hud_state(mic_muted=bool(_mic_muted[0]))
        print(f"  [tray] mic_mute_toggle -> {_mic_muted[0]}")
    else:
        # Generic fallthrough — route to a registered ACTIONS handler so the
        # 20+ commands tray.py sends (shutdown_jarvis, run_diagnostic, test_mic,
        # switch_llm, …) actually dispatch instead of dropping with "unknown".
        # switch_llm carries its target in `backend`; everything else passes
        # whatever sits under `arg` (empty string when the tray sent no payload,
        # which matches the bare-string signature every _act_* helper uses).
        fn = ACTIONS.get(cmd)
        if fn is None:
            print(f"  [tray] unknown command: {cmd!r}")
            return
        if cmd == "switch_llm":
            arg = entry.get("backend", "") or ""
        else:
            arg = entry.get("arg", "") or ""
        # Heavy actions (run_diagnostic, test_each_skill, latency_benchmark)
        # may have been replaced by a synchronous skill implementation after
        # load_skills() ran. Spawn into a daemon so a 30–60s sweep can't
        # stall the 2 Hz drainer and back up other tray clicks.
        if cmd in _HEAVY_ACTIONS:
            _tray_async(cmd, lambda f=fn, a=arg: f(a))
            print(f"  [tray] {cmd} dispatched async")
            return
        try:
            result = fn(arg)
        except Exception as e:
            print(f"  [tray] action {cmd!r} raised: {e}")
            return
        head = result if isinstance(result, str) else ""
        if head:
            head = head.split("\n", 1)[0]
            if len(head) > 120:
                head = head[:117].rstrip() + "..."
            print(f"  [tray] {cmd} -> {head}")
        else:
            print(f"  [tray] {cmd} dispatched")


def _publish_audio_state() -> None:
    """Mirror the audio-processing flags to hud_state.json so the tray's
    Audio Controls submenu can render accurate checkmarks. Called on every
    audio_* toggle and once at startup."""
    try:
        _write_hud_state(
            audio_processing_enabled = bool(_audio_master_enabled[0]),
            echo_cancel_enabled      = bool(_audio_aec_enabled[0]),
            noise_suppress_enabled   = bool(_audio_ns_enabled[0]),
            agc_enabled              = bool(_audio_agc_enabled[0]),
        )
    except Exception:
        pass


def _restore_tray_toggle_state() -> None:
    """Read hud_state.json and restore the four tray-toggle cells
    (_tts_muted, _ambient_mode_active, _daemons_paused, _debug_mode) so
    user preference survives a restart. Then re-sync the runtime side:
    if ambient_mode was on, kick the ambient_listen daemon back on; if
    daemons were paused, push that into diagnostic_daemons + skill state.
    Silent on any failure — a missing or corrupt state file just means
    we boot with the in-file defaults."""
    try:
        if not os.path.exists(HUD_STATE_FILE):
            return
        with open(HUD_STATE_FILE, "r", encoding="utf-8") as f:
            persisted = json.load(f)
        if not isinstance(persisted, dict):
            return
    except Exception as e:
        print(f"  [tray-restore] read failed: {e}")
        return

    if "tts_muted" in persisted:
        _tts_muted[0] = bool(persisted.get("tts_muted"))
    if "mic_muted" in persisted:
        _mic_muted[0] = bool(persisted.get("mic_muted"))
    if "ambient_mode_active" in persisted:
        _ambient_mode_active[0] = bool(persisted.get("ambient_mode_active"))
    if "daemons_paused" in persisted:
        _daemons_paused[0] = bool(persisted.get("daemons_paused"))
    if "debug_mode" in persisted:
        _debug_mode[0] = bool(persisted.get("debug_mode"))
    # task-70: sleep/standby survive bounces. A crash + auto-respawn would
    # otherwise come up "Listening…" and answer the next phrase out loud.
    if "sleep_mode" in persisted:
        _sleep_mode[0] = bool(persisted.get("sleep_mode"))
    if "standby_mode" in persisted:
        _standby_mode[0] = bool(persisted.get("standby_mode"))
    # Alexa-style boot: START_IN_STANDBY comes up SILENT in wake-word standby
    # (say "JARVIS" to wake → it answers → back to standby) instead of always-
    # listening — UNLESS a persisted crash-survival sleep state already decided.
    # Env override: JARVIS_START_IN_STANDBY.
    if "sleep_mode" not in persisted:
        from core.config import START_IN_STANDBY as _sis_default
        _sis = (os.environ.get("JARVIS_START_IN_STANDBY", "").strip()
                or str(_sis_default)).strip().lower()
        if _sis in {"1", "true", "yes", "on"}:
            _sleep_mode[0] = True
            _standby_mode[0] = True
    if "audio_processing_enabled" in persisted:
        _audio_master_enabled[0] = bool(persisted.get("audio_processing_enabled"))
    if "echo_cancel_enabled" in persisted:
        _audio_aec_enabled[0] = bool(persisted.get("echo_cancel_enabled"))
    if "noise_suppress_enabled" in persisted:
        _audio_ns_enabled[0] = bool(persisted.get("noise_suppress_enabled"))
    if "agc_enabled" in persisted:
        _audio_agc_enabled[0] = bool(persisted.get("agc_enabled"))

    # Mirror back so the cache holds the restored values and the next
    # _write_hud_state from any other code path doesn't clobber them.
    _write_hud_state(
        tts_muted                = bool(_tts_muted[0]),
        mic_muted                = bool(_mic_muted[0]),
        ambient_mode_active      = bool(_ambient_mode_active[0]),
        daemons_paused           = bool(_daemons_paused[0]),
        debug_mode               = bool(_debug_mode[0]),
        sleep_mode               = bool(_sleep_mode[0]),
        standby_mode             = bool(_standby_mode[0]),
        audio_processing_enabled = bool(_audio_master_enabled[0]),
        echo_cancel_enabled      = bool(_audio_aec_enabled[0]),
        noise_suppress_enabled   = bool(_audio_ns_enabled[0]),
        agc_enabled              = bool(_audio_agc_enabled[0]),
    )
    # Publish the active LLM backend so the tray's AI submenu shows the right
    # checkmark on first open (tray reads `llm_backend`: "anthropic" for Claude,
    # else the ollama model tag it matches via .startswith()).
    try:
        _write_hud_state(
            llm_backend=("anthropic" if str(AI_BACKEND).lower() == "claude"
                         else str(_RESOLVED_LOCAL_LLM_MODEL[0] or LOCAL_LLM_MODEL)))
    except Exception:
        pass

    # Bring ambient_listen up if the user had it on last time. ACTIONS
    # was populated by load_skills() already.
    if _ambient_mode_active[0]:
        fn = ACTIONS.get("ambient_listen_start")
        if fn is not None:
            try:
                fn("")
                print("  [tray-restore] ambient_listen resumed from prior session")
            except Exception as e:
                print(f"  [tray-restore] ambient_listen_start failed: {e}")

    # Push the paused state into both daemon owners.
    #
    # The diagnostic-daemons half reconciles in BOTH directions, and must.
    # `_daemons_paused[0]` (hud_state.json) is the flag the tray, the HUD and
    # the boot log all report; data/diagnostic_daemons.json's "paused" is only
    # a MIRROR of it that the four worker loops actually obey. This block used
    # to push the True case alone, so a mirror set True by a path the HUD flag
    # never followed — a spoken pause_diagnostics, or a lever whose restore
    # never ran because the box was power-cycled — could not be cleared by any
    # number of restarts. It failed silently in the worst direction: every loop
    # stamps its alive_ts BEFORE testing paused, so all four kept heartbeating
    # while doing nothing. Found live 2026-09-06 with the mirror stuck True and
    # last real work 94-101 days stale, under a boot log printing paused=False
    # — crash-watch among the daemons that were quietly off. See
    # core.diagnostic_daemons.reconcile_paused.
    #
    # ambient_listen deliberately stays inside the `if` below: its paused flag
    # is a module-level cell in a freshly imported module (default False), so
    # unlike the on-disk mirror it cannot be stale at boot.
    try:
        from core import diagnostic_daemons as _diag_daemons
        if _diag_daemons.reconcile_paused(bool(_daemons_paused[0])):
            print("  [tray-restore] diagnostic-daemon paused mirror had drifted "
                  f"— forced to paused={bool(_daemons_paused[0])}")
    except Exception as e:
        print(f"  [tray-restore] reconcile_paused failed: {e}")

    if _daemons_paused[0]:
        try:
            _al = sys.modules.get("skill_ambient_listen")
            if _al is not None and hasattr(_al, "set_paused"):
                _al.set_paused(True)
        except Exception as e:
            print(f"  [tray-restore] ambient_listen.set_paused failed: {e}")
        print("  [tray-restore] daemons restored to paused state")

    if any((_tts_muted[0], _ambient_mode_active[0],
            _daemons_paused[0], _debug_mode[0])):
        print(f"  [tray-restore] tts_muted={_tts_muted[0]} "
              f"ambient={_ambient_mode_active[0]} "
              f"paused={_daemons_paused[0]} debug={_debug_mode[0]}")


def _tray_command_drainer():
    """Background poll of tray_commands.json. Runs at 2 Hz so menu clicks
    feel responsive even while the main loop is blocked in record_speech."""
    while not _tray_drain_stop.is_set():
        try:
            _drain_tray_commands_once()
            _tray_drain_stop.wait(0.5)
        except Exception:
            logging.exception("[tray] drainer iteration failed")
            # back off on persistent failures so we don't spin
            _tray_drain_stop.wait(0.5)


def _tray_state_publisher():
    """Bridge the system_monitor + bambu_monitor skill modules to the HUD
    state file so the tray (a separate process) can read their state.

    Both skills load lazily into sys.modules under skill_<name> and don't
    import bobert_companion, so this publisher reads their module-level
    state under their own locks. Runs at 1 Hz — these flags don't change
    fast and an extra poll per second is cheap."""
    while not _tray_publisher_stop.is_set():
        try:
            alert = False
            bambu = False
            # ── system_monitor: alert if a CPU OR RAM alert fired in the last
            #    cooldown window (10 min default). We don't have a direct
            #    "alert_active" flag; piggy-back on the last-alert timestamps.
            try:
                sm = sys.modules.get("skill_system_monitor")
                if sm is not None:
                    last_cpu = (getattr(sm, "_last_cpu_alert_at", [0])[0]
                                if hasattr(sm, "_last_cpu_alert_at") else 0)
                    last_ram = (getattr(sm, "_last_ram_alert_at", [0])[0]
                                if hasattr(sm, "_last_ram_alert_at") else 0)
                    most_recent = max(last_cpu or 0, last_ram or 0)
                    # Show red for 30s after an alert fires, then clear.
                    if most_recent and (time.time() - most_recent) < 30:
                        alert = True
            except Exception:
                pass
            # ── bambu_monitor: print active when gcode_state == RUNNING
            try:
                bm = sys.modules.get("skill_bambu_monitor")
                if bm is not None and hasattr(bm, "_state"):
                    state_dict = getattr(bm, "_state", None)
                    lock = getattr(bm, "_state_lock", None)
                    if isinstance(state_dict, dict):
                        if lock is not None:
                            with lock:
                                gcode = str(state_dict.get("gcode_state") or "")
                        else:
                            gcode = str(state_dict.get("gcode_state") or "")
                        if gcode.upper() == "RUNNING":
                            bambu = True
            except Exception:
                pass
            # ── calendar + unread mail for the unified HUD ──
            # The HUD subprocess can't import ms_graph (it would pull in this
            # 14k-line module and trip the singleton lock), so the main process
            # fetches them via hud_card — safe here — and publishes to
            # hud_state.json. Throttled to every 5 min (ms_graph is networked).
            try:
                _now = time.time()
                if _now - _hud_cal_last[0] > 300.0:
                    _hud_cal_last[0] = _now
                    import hud_card as _hc
                    _events = _hc._gather_calendar() or []
                    _write_hud_state(
                        next_event=(_events[0] if _events else None),
                        unread_mail=_hc._gather_unread_mail(),
                    )
            except Exception:
                pass
            # Only write when something actually changed so we don't churn the
            # state file 1× per second.
            with _hud_state_lock:
                stale_a = _hud_state_cache.get("alert_active")
                stale_b = _hud_state_cache.get("bambu_active")
            if stale_a != alert or stale_b != bambu:
                _write_hud_state(alert_active=alert, bambu_active=bambu)
        except Exception:
            logging.exception("[tray] state publisher iteration failed")
        _tray_publisher_stop.wait(1.0)


# ──────────────────────────────────────────────────────────────────────────
#  FACE TRACKING  (Kinect RGB camera + OpenCV face detection)
# ──────────────────────────────────────────────────────────────────────────

# CUDA face-detection investigation (jarvis_todo 2026-05-29 13:34, closed
# 2026-05-29). Verdict: stay on CPU. cv2.cuda.CascadeClassifier does exist in
# opencv-contrib's CUDA build and the 3090 would happily run it, but:
#   1. The pip-installable `opencv-python` / `opencv-contrib-python` wheels
#      are NOT built with CUDA. Getting cv2.cuda.* requires either a manual
#      CMake/MSVC compile of opencv-contrib against the CUDA toolkit (a
#      multi-hour, fragile install on Windows) or a third-party prebuilt
#      wheel (cuda4opencv, asmaloney/opencv-cuda) that lags upstream and
#      conflicts with the stock wheel. Big regression-surface for a single
#      hot path.
#   2. Measured on this box (3090, OpenCV 4.13.0, opencv-python, no real
#      face in frame so the worst-case 4-pass fallthrough runs):
#         640x480  single strict-frontal pass    ~3.5 ms
#         1280x720 single strict-frontal pass    ~7.2 ms
#         1280x720 frontal+frontal-loose+profile+profile-mirrored ~13.2 ms
#      The skill polls at 2 Hz (face_tracker.GAZE_POLL_INTERVAL=0.5s), so
#      even worst-case CPU work is ~26 ms/sec/camera — invisible next to
#      the rest of the JARVIS loop.
#   3. CUDA Haar at this resolution is dominated by HtoD/DtoH transfer
#      (~270 KB grayscale per frame, ~50-100 µs each way on PCIe 4) and
#      kernel-launch overhead (~10-50 µs per launch × 4 cascade passes).
#      Published benchmarks (OpenCV CUDA module docs, NVIDIA samples) show
#      ~2-4x speedup on 1080p+, dropping below 1x on smaller frames where
#      transfer cost dominates compute — i.e. exactly our regime.
#   4. The plan's gating criterion was ">1 ms improvement justifies the
#      change". Realistic best case is ~5-8 ms saved on the 1280x720 hot
#      pass, which DOES clear the bar — but only after eating the build
#      complexity in (1) and the runtime fallback complexity in (2).
# Decision: keep CPU. A self-contained benchmark harness lives at
# tools/face_detect_bench.py for any future re-evaluation (e.g. if someone
# is already running a CUDA OpenCV build for another reason).
_face_cascade = cv2.CascadeClassifier(
    cv2.data.haarcascades + "haarcascade_frontalface_default.xml"
)
# Profile (side-view) cascade — the frontal cascade misses faces turned more
# than ~30° off-axis, which is the common case when the user is glancing at a
# side monitor. Used as a fallback when the frontal pass turns up nothing.
_profile_cascade = cv2.CascadeClassifier(
    cv2.data.haarcascades + "haarcascade_profileface.xml"
)
if _face_cascade.empty():  # pragma: no cover - import-time guard; only true if the bundled haarcascade XML is missing/corrupt
    print("  [WARN] Could not load haarcascade_frontalface_default.xml — "
          "face detection disabled. Re-installing opencv-python should fix this.")
    _face_cascade = None
if _profile_cascade is not None and _profile_cascade.empty():  # pragma: no cover - import-time guard; only true if the profile haarcascade XML is missing/corrupt
    _profile_cascade = None

# Shared state written by face-tracking thread, read by main thread control
#
# _face_track_pause — set during voice activity (listening / thinking /
# speaking). It means "yield the eyes and skip the HEAVY face detection +
# eye-control servo math", NOT "turn the camera off". The loop keeps grabbing
# and caching frames while paused (see the read/cache block) so see_user, the
# Kinect air-mouse and head-gaze keep getting fresh frames, and — as long as
# the primary camera is actually producing frames — the HUD preview keeps
# being written, so the camera tile stays visibly ON while JARVIS listens or
# talks. Only the cv2 cascade recognition cost is skipped, not the camera.
_face_track_pause = threading.Event()   # set = skip heavy detection (voice)
# _face_track_camera_off — set ONLY for the genuinely camera-off states where
# the HUD must blank to its 'CAMERA OFF' placeholder even though the capture
# loop is alive: the low-memory guard (KINECT_REVIEW P0) and standby / empty
# room. Distinct from _face_track_pause so the voice-time pause stops killing
# the preview while these real pauses still do. When set, the loop removes the
# preview file and skips writing it regardless of frame availability.
_face_track_camera_off = threading.Event()   # set = blank HUD preview (low-mem/standby)
_face_track_stop  = threading.Event()   # set = thread should exit

_smooth_x = 0.5
_smooth_y = 0.5
_last_sent_x = -1.0
_last_sent_y = -1.0

# Used by proactive idle behavior — last time any camera saw a face
last_face_seen   = 0.0
last_speech_time = time.time()

# Per-camera awareness — used by where_is_user / see_user actions so Bobert
# can tell which monitor you're facing. Updated by the face-tracking thread.
_camera_last_seen: dict[int, float]    = {}            # index → timestamp
_camera_latest_frame: dict[int, "np.ndarray"] = {}     # index → most recent frame
_camera_state_lock = threading.Lock()

# ── HUD live camera preview bridge ──────────────────────────────────────────
# The unified HUD runs in a SEPARATE process and reads its data from small files
# in the project root / data dir. To show a live mirror of what JARVIS sees we
# write ONE overwriting, downscaled JPEG of the primary face-tracking frame here
# and the HUD loads it. Privacy contract (see HUD_CAMERA_PREVIEW in config):
#   • exactly one temp file, never a growing folder;
#   • atomically replaced (write .tmp + os.replace) so the HUD never reads a
#     half-written frame;
#   • removed whenever the camera is off / face-tracking is paused, and the HUD
#     also treats a stale file (older than _HUD_CAM_PREVIEW_STALE_S) as "off",
#     so a single missed delete still can't leave the last frame on screen.
# Gated entirely behind HUD_CAMERA_PREVIEW — when False nothing is ever written.
_HUD_CAM_PREVIEW_FILE = os.path.join(
    os.path.dirname(os.path.abspath(__file__)), "data", ".hud_camera_preview.jpg")
_HUD_CAM_PREVIEW_WIDTH    = 240     # downscaled preview width (px); height keeps aspect
_HUD_CAM_PREVIEW_MIN_GAP  = 0.15    # min seconds between writes (~6-7 fps cap)
_HUD_CAM_PREVIEW_JPEG_Q   = 70      # JPEG quality 0-100 (small file, good enough)
_HUD_CAM_PREVIEW_STALE_S  = 2.0     # HUD treats a file older than this as "off"
_hud_cam_preview_last_write = [0.0]  # list-box so the loop can mutate without `global`
_hud_cam_preview_file_present = [False]  # have we written the file since last cleanup?


def _hud_camera_preview_enabled() -> bool:
    """True iff the live HUD camera preview is switched on. Read the flag via the
    config module at call time (not the import-time copy) so tests / a runtime
    settings flip can toggle it. Defaults True if the attr is somehow absent."""
    try:
        import core.config as _cfg
        return bool(getattr(_cfg, "HUD_CAMERA_PREVIEW", True))
    except Exception:
        return True


def _hud_camera_preview_remove() -> None:
    """Delete the preview file so the HUD shows its 'camera off' placeholder.
    Idempotent and best-effort — a missing file (already gone) is fine, and any
    transient lock just leaves the stale-file guard in the HUD to do the job."""
    if not _hud_cam_preview_file_present[0]:
        return
    try:
        if os.path.exists(_HUD_CAM_PREVIEW_FILE):
            os.remove(_HUD_CAM_PREVIEW_FILE)
    except OSError:
        pass
    finally:
        _hud_cam_preview_file_present[0] = False


def _hud_camera_preview_downscale(frame: "np.ndarray", width: int) -> "np.ndarray":
    """Return ``frame`` resized to ``width`` px wide, aspect preserved. Pure /
    cv2-only and side-effect free so it is unit-testable without a camera. A
    frame already narrow enough is returned unchanged."""
    h, w = frame.shape[:2]
    if w <= width or w == 0:
        return frame
    new_h = max(1, int(round(h * (width / float(w)))))
    return cv2.resize(frame, (width, new_h), interpolation=cv2.INTER_AREA)


# Per-camera preview files (2026-07-10, owner request: "keep all cameras live
# … see each camera individually on web"). The face-track loop already holds
# EVERY webcam open continuously and caches each frame in
# _camera_latest_frame — but only the PRIMARY was published. These write one
# small JPEG per camera, same downscale/throttle/atomic contract as the main
# preview, keyed by the camera's SIDE ("left"/"right") plus "kinect". The web
# Camera tab requests /api/camera-preview?cam=<key>.
_HUD_PERCAM_PREVIEW_KEYS = ("left", "right", "kinect")
_hud_percam_last_write: dict[str, float] = {}


def _hud_percam_preview_file(key: str) -> str:
    return os.path.join(os.path.dirname(os.path.abspath(__file__)),
                        "data", f".hud_camera_preview_{key}.jpg")


def _percam_side(cam: dict) -> str:
    """Stable per-camera preview key from the config entry. Label first
    ("Left webcam (left monitor)"), look_x fallback with 0.5 counting as left
    (same rule as skills/camera_system — look_x<0.5 misclassified the live
    LEFT cam whose look_x is exactly 0.5)."""
    lbl = str(cam.get("label", "")).lower()
    if "left" in lbl:
        return "left"
    if "right" in lbl:
        return "right"
    return "left" if cam.get("look_x", 0.5) <= 0.5 else "right"


def _hud_percam_preview_write(key: str, frame: "np.ndarray", now: float) -> bool:
    """Per-camera sibling of _hud_camera_preview_write: same downscale, JPEG
    quality, atomic replace and ~6-7 fps throttle, but each key has its OWN
    throttle clock so three cameras never starve each other. Never raises."""
    if frame is None or key not in _HUD_PERCAM_PREVIEW_KEYS:
        return False
    if (now - _hud_percam_last_write.get(key, 0.0)) < _HUD_CAM_PREVIEW_MIN_GAP:
        return False
    path = _hud_percam_preview_file(key)
    try:
        small = _hud_camera_preview_downscale(frame, _HUD_CAM_PREVIEW_WIDTH)
        ok, buf = cv2.imencode(
            ".jpg", small, [int(cv2.IMWRITE_JPEG_QUALITY), _HUD_CAM_PREVIEW_JPEG_Q])
        if not ok:
            return False
        tmp = path + ".tmp"
        with open(tmp, "wb") as f:
            f.write(buf.tobytes())
        os.replace(tmp, path)
        _hud_percam_last_write[key] = now
        return True
    except Exception:
        try:
            if os.path.exists(path + ".tmp"):
                os.remove(path + ".tmp")
        except OSError:
            pass
        return False


def _hud_camera_preview_write(frame: "np.ndarray", now: float) -> bool:
    """Encode ``frame`` (BGR, as cv2 hands it to us) to a small JPEG and atomically
    replace the single preview file the HUD reads. Throttled to ~6-7 fps via
    _HUD_CAM_PREVIEW_MIN_GAP. Returns True iff a frame was written this call.

    Never raises into the face-tracking loop — any encode / disk error is
    swallowed (the HUD's stale-file guard then shows the placeholder)."""
    if frame is None:
        return False
    if (now - _hud_cam_preview_last_write[0]) < _HUD_CAM_PREVIEW_MIN_GAP:
        return False
    try:
        small = _hud_camera_preview_downscale(frame, _HUD_CAM_PREVIEW_WIDTH)
        ok, buf = cv2.imencode(
            ".jpg", small, [int(cv2.IMWRITE_JPEG_QUALITY), _HUD_CAM_PREVIEW_JPEG_Q])
        if not ok:
            return False
        tmp = _HUD_CAM_PREVIEW_FILE + ".tmp"
        with open(tmp, "wb") as f:
            f.write(buf.tobytes())
        os.replace(tmp, _HUD_CAM_PREVIEW_FILE)
        _hud_cam_preview_last_write[0] = now
        _hud_cam_preview_file_present[0] = True
        return True
    except Exception:
        # Best-effort: clean up a dangling temp, then carry on tracking.
        try:
            _tmp = _HUD_CAM_PREVIEW_FILE + ".tmp"
            if os.path.exists(_tmp):
                os.remove(_tmp)
        except OSError:
            pass
        return False


# ── PART A: Kinect color + LIVE SKELETON overlay for the HUD preview ─────────
# When KINECT_SKELETON_OVERLAY_ENABLED (config) is on AND the Kinect is enabled
# + streaming, the HUD camera tile shows the KINECT COLOR frame with the tracked
# skeleton drawn over it, composited beside two small webcam tiles. It is built
# HERE, in the main process (which already has cv2 + the open webcam frames +
# the Kinect bridge), then written through the SAME single-JPEG preview pipeline
# the plain mirror uses — so the separate-process HUD needs no Kinect/pygrabber.
# The skeleton doubles as the owner's body-stream-is-live diagnostic.

def _kinect_preview_webcam_names() -> dict[str, str]:
    """DirectShow friendly-name substrings for the two side-tile webcams,
    DERIVED FROM `CAMERAS` — the single source of truth — not hardcoded.

    This used to be a literal dict pinned to `"left": "logi c270"`. When the
    owner retired the C270 for an eMeet C960 (v2.0.56 updated core.config), the
    composite kept looking for a device that no longer exists, silently failed
    to resolve the slot, and drew the LEFT tile as a dim "off" placeholder
    forever — while the camera was open and streaming. The HUD reported a
    healthy camera as dead, with nothing in the log. Classic stale-duplicate:
    the identity lived in two places and only one got updated (2026-07-14
    audit). Now a camera swap only has to be edited in core/config.py.
    """
    names: dict[str, str] = {}
    try:
        for cam in CAMERAS:
            nm = str(cam.get("name") or "").strip().lower()
            if nm:
                names.setdefault(_percam_side(cam), nm)
    except Exception:
        pass
    return names
# Cache the pygrabber name→index resolution so we don't re-enumerate DirectShow
# devices every preview frame (enumeration is comparatively expensive + flickers
# the device list). [0]=mapping dict, [1]=resolved-once flag.
_kinect_preview_webcam_idx: dict[str, int] = {}
_kinect_preview_webcam_resolved = [False]
_kinect_preview_webcam_resolved_at = [0.0]
# Re-resolve the name→index map this often. DirectShow indices reshuffle when a
# device joins/leaves the bus, so a permanently-cached index eventually points
# at the WRONG camera (2026-07-14 audit).
_WEBCAM_IDX_TTL_SEC = 10.0
# Last value of _video_device_fingerprint(), so the TTL tick can tell "the device
# set is unchanged, skip the leaky enumeration" from "something moved, re-resolve".
_kinect_preview_webcam_fingerprint: list = [None]
# When we last did a REAL DirectShow enumeration. The fingerprint gate can skip
# the leaky call indefinitely, so this is the floor that guarantees we still
# re-learn the index map periodically even if the fingerprint never changes.
_kinect_preview_webcam_enumerated_at = [0.0]
# Self-heal floor -- the interval at which we re-enumerate (and so leak) even
# when the fingerprint says nothing moved. There are TWO, and which one applies
# depends on whether the fingerprint we are holding can actually see a device
# that left and rejoined between samples (_fingerprint_sees_rejoin).
#
#   UNSTAMPED (300 s): the fingerprint is only a device SET, so a leave+rejoin
#   between two samples reshuffles DirectShow order invisibly and the resulting
#   reads SUCCEED from the wrong camera -- the failed-read backstop never fires.
#   The floor is the ONLY thing that ever corrects that, so it has to be short.
#
#   STAMPED (3600 s): the PnP half carries DEVPKEY_Device_LastArrivalDate, and
#   that stamp was MEASURED to advance across a real removal + re-arrival of the
#   SAME device instance (the experiment is written up in
#   _setupapi_camera_instances), so a leave+rejoin changes the fingerprint even
#   when it is only observed after the fact. That is the one reshuffle mechanism
#   a device-SET fingerprint cannot see, so closing it demotes the unconditional
#   re-enumeration from THE correctness mechanism to a safety net.
#   BUT ONLY FOR THE MECHANISMS ACTUALLY CHECKED -- this is NOT "everything that
#   can reshuffle DirectShow order is now detected directly". A devnode
#   disable/enable was never tested (it needs elevation, which the session that
#   wrote this did not have), and the probe throws PnP ORDER away on purpose
#   (tuple(sorted(...))), so the stamp is the only witness a reshuffle has here.
#   The floor is what bounds anything those miss. Cost at 3600 s is 1 leaked
#   thread + 103 handles per HOUR (0.017/min) versus 6.0/min unpatched.
_WEBCAM_IDX_SELFHEAL_SEC = 300.0
_WEBCAM_IDX_SELFHEAL_STAMPED_SEC = 3600.0


# --- leak-free video-device change detection --------------------------------
# WHY THIS EXISTS (2026-09-05, measured):
# ICreateDevEnum::CreateClassEnumerator(CLSID_VideoInputDeviceCategory) leaks
# +1 OS thread and +103 handles PER CALL, permanently, inside mfksproxy.dll.
# Nothing reclaims it -- not Release, not CoUninitialize, not a fresh apartment,
# not gc. At the 10 s TTL below that was +6 threads and +618 handles per MINUTE
# forever, and it is what exhausted the v2.0.100 process (14,507 threads /
# 1,419,190 handles before every subsystem stopped logging).
#
# The leak is in building the PnP kernel-streaming device list, NOT the moniker
# bind -- a repro that only calls CreateClassEnumerator and binds nothing leaks
# identically. Measured per-call, 20-300 iterations each:
#     CoCreateInstance(SystemDeviceEnum)      +0.00 thr    +0.00 hnd
#     + CreateClassEnumerator (dwFlags=0)     +1.00 thr  +103.00 hnd   <-- leak
#     + IEnumMoniker::Next loop               +1.00 thr  +103.00 hnd
#     + IMoniker::BindToStorage               +1.00 thr  +103.00 hnd
#     + IPropertyBag::Read (what we call)     +1.00 thr  +103.00 hnd
# Only the VIDEO INPUT category leaks. AudioInputDevice (6 devices),
# AudioRenderer (14), VideoCompressor (5) and LegacyAmFilter (70!) are all
# +0.00/+0.00 -- so this is the KS camera path, not COM enumeration in general.
# Splitting the category by dwFlags isolates it further: CDEF_DEVMON_PNP_DEVICE
# leaks the full amount, CDEF_DEVMON_FILTER (software/virtual cams) leaks zero.
#
# So we cannot make the call cheap -- we can only stop MAKING it. These two
# probes together see every device DirectShow's default enumeration returns,
# and both are free (0 threads, 0 handles over 300 calls, 0.35 ms combined vs
# 33-46 ms for the leaky call):
#     SetupAPI KSCATEGORY_VIDEO_CAMERA  -> the PnP cameras
#     CreateClassEnumerator + DEVMON_FILTER -> the virtual/software cameras
# NOTE they are a CHANGE DETECTOR only, never an index source: SetupAPI returns
# the same devices in a DIFFERENT order than DirectShow (measured -- the Kinect
# and the USB 2.0 Camera swap places), so using its order would open the wrong
# camera, which is the exact bug the 2026-07-14 TTL was added to prevent.
_KSCATEGORY_VIDEO_CAMERA = "{e5323777-f976-4f5b-9b55-b94699c46e44}"
# The OLDER, broader KS category, probed TOGETHER with VIDEO_CAMERA above.
# DirectShow's PnP video enumeration is driven by KSCATEGORY_CAPTURE ∩
# KSCATEGORY_VIDEO; VIDEO_CAMERA is a Win8.1-era category that modern UVC
# cameras also register. Measured on this rig they return the IDENTICAL three
# devices — exactly the three PnP entries DirectShow shows at indices 0-2 (index
# 3 is the software OBS Virtual Camera, covered by the FILTER probe below) — but
# "identical here" is not "identical everywhere", so probe the UNION. Getting
# this wrong in the OVER-covering direction costs at most one spurious
# re-enumeration; getting it wrong in the UNDER-covering direction means a real
# reshuffle we never notice, which is precisely the wrong-camera bug this gate
# exists to prevent. KSCATEGORY_CAPTURE itself is NOT usable as the probe: it
# also contains 18 AUDIO endpoints on this machine, so every headset power-cycle
# would force a leaky re-enumeration.
_KSCATEGORY_VIDEO = "{6994ad05-93ef-11d0-a3cc-00a0c9223196}"
_CDEF_DEVMON_FILTER = 0x0080
_DIGCF_PRESENT_IFACE = 0x02 | 0x10
# DEVPKEY_Device_LastArrivalDate. PnP re-stamps this FILETIME on the devnode
# every time the device ARRIVES, which is what lets a fingerprint sampled AFTER
# a leave+rejoin still see that it happened. Measured, not assumed -- the
# experiment is written up in _setupapi_camera_instances.
_DEVPKEY_FMTID_DEVICE_TIMESTAMPS = "{83da6326-97a6-4088-9453-a1923f573b29}"
_DEVPKEY_PID_LAST_ARRIVAL = 102
# DEVPROP_TYPE_FILETIME, checked explicitly -- see _stamp().
_DEVPROP_TYPE_FILETIME = 0x10
# DEVPKEY_Device_LastRemovalDate is DELIBERATELY NOT READ. The pid is kept here
# only so nobody re-adds it believing it contributes something: Windows CLEARS
# it when the device comes back, so a probe that enumerates PRESENT devices can
# never observe one. Measured 2026-09-05 on this box, two independent ways:
#   * census of all 545 reachable devnodes -- 161 carry a removal stamp and
#     every one of them is NON-PRESENT. Of the 304 PRESENT devnodes that carry
#     an arrival stamp, ZERO carry a removal stamp.
#   * watched live across an ISO mount/dismount cycle -- the stamp appeared on
#     removal (present True->False) and went back to unreadable on re-arrival
#     (present False->True), on the same instance id.
# _setupapi_camera_instances() uses DIGCF_PRESENT, so it read b'' for all three
# cameras on every call. Carrying that in the fingerprint made the mechanism
# read as though it had two legs when it has one.
_DEVPKEY_PID_LAST_REMOVAL_NOT_USED = 103


def _setupapi_camera_instances() -> "tuple[tuple[str, bytes], ...] | None":
    """Every PnP video-capture device present right now, as
    ``(device-instance-path, last-arrival-stamp)``.

    Leak-free and ~0.4 ms, versus +1 OS thread / +103 handles and 35-47 ms for
    the DirectShow enumeration it replaces. Returns None on any failure.
    NEVER raises.

    THE TIMESTAMP IS THE POINT, not decoration. A device-instance SET on its
    own cannot see a device that LEAVES AND REJOINS between two samples: the set
    afterwards is byte-identical, yet DirectShow has renumbered underneath us —
    so the tiles read the WRONG CAMERA and every read still SUCCEEDS, meaning
    the failed-read backstop never fires and nothing anywhere reports it. That
    hole is the only reason the old code re-enumerated (and leaked) every 10 s.
    This function also returns tuple(sorted(...)), throwing PnP order away on
    purpose (SetupAPI order is NOT DirectShow order — see the note above), so
    the arrival stamp is the ONLY thing here that can witness a reshuffle.

    THE STAMP WAS OBSERVED TO MOVE. That is the load-bearing assumption, and no
    number of reads of a stamp that never changes can establish it — a property
    written once per devnode per session yields byte-identical readings forever,
    which is indistinguishable from one that tracks nothing. So it was cycled.
    Experiment (2026-09-05): mounting an ISO creates a genuine PnP devnode that
    a NON-elevated user can create and destroy on demand. Mount / dismount /
    re-mount, while polling every devnode on the box every 5 s, gave for the one
    instance id ``SCSI\\CdRom&Ven_Msft&Prod_Virtual_DVD-ROM\\2&1f4adffe&0&000004``:
        23:51:38.464  arrival stamped, present
        23:52:08.381  removal stamped, present -> absent
        23:52:31.967  ARRIVAL RE-STAMPED, absent -> present, removal cleared
    Then repeated for volume, because one observation is an anecdote: 14 further
    mount/dismount cycles produced 11 re-arrivals of an ALREADY-KNOWN instance
    id across 3 distinct devnodes, and the arrival stamp advanced on 11 of 11 —
    never once unchanged. PnP therefore does re-stamp on re-arrival of an
    instance it has seen before, which is the case that matters: a USB camera
    replugged into the SAME port keeps its instance id and so leaves the device
    SET byte-identical. (The removal stamp behaved as the note on
    _DEVPKEY_PID_LAST_REMOVAL_NOT_USED describes throughout — set on the way
    out, gone again on the way back in — which is why it is not collected.)

    AND IT MOVED FOR A CYCLE THE PRESENCE CHECK COULD NOT SEE, which is the
    whole point. A separate 5 s poller running through the same campaign logged
    16 arrival-stamp advances: 12 where the devnode was absent on the previous
    sample and present on this one, ZERO on a devnode that stayed present the
    whole time (so the stamp never drifts on its own), and 4 where the devnode
    read ABSENT on BOTH samples yet the stamp had advanced between them — a
    full leave+rejoin that fell entirely inside one sampling interval and was
    invisible to the device SET, exactly as it would be for a camera. Note the
    honest gap: those 4 are the absent/absent mirror of the camera case, not a
    present/present case, which the sampler never happened to catch.

    WHAT THAT DOES AND DOES NOT COVER — the honest boundary. It is a SCSI\\CdRom
    devnode, not a USB camera. Two things carry it across: the property is
    written by the PnP manager on devnode start rather than by a bus driver, and
    it is observably generic here — 304 of the 323 present devnodes carry an
    arrival stamp, across 19 different enumerators, including 71 of 71 on USB.
    On USB specifically, 58 of those 71 were INSTALLED before this boot yet
    carry an arrival stamp at or after it, and 39 carry one more than 15 min
    after boot: they re-arrived mid-session and the stamp recorded it. NOT
    COVERED: a devnode disable/enable in Device Manager, which needs elevation
    this session did not have. If that path turns out not to re-stamp, the
    self-heal floor is what bounds it — which is why the floor is still there
    and is described as a safety net rather than as dead weight.

    (Read via ctypes the raw FILETIMEs are UTC; the comparison is on raw bytes,
    so the zone never matters.)"""
    try:
        import ctypes
        import re as _re
        from ctypes import wintypes

        class _GUID(ctypes.Structure):
            _fields_ = [("d1", ctypes.c_ulong), ("d2", ctypes.c_ushort),
                        ("d3", ctypes.c_ushort), ("d4", ctypes.c_ubyte * 8)]

            # Default s=None MATTERS: ctypes zero-initialises nested struct
            # fields without calling this, but a required arg would still break
            # any accidental no-arg construction.
            def __init__(self, s=None):
                super().__init__()
                if s:
                    ctypes.windll.ole32.CLSIDFromString(ctypes.c_wchar_p(s),
                                                        ctypes.byref(self))

        class _DEVPROPKEY(ctypes.Structure):
            _fields_ = [("fmtid", _GUID), ("pid", ctypes.c_ulong)]

        class _IFACE(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD),
                        ("InterfaceClassGuid", _GUID),
                        ("Flags", wintypes.DWORD),
                        ("Reserved", ctypes.POINTER(ctypes.c_ulonglong))]

        class _DEVINFO(ctypes.Structure):
            _fields_ = [("cbSize", wintypes.DWORD), ("ClassGuid", _GUID),
                        ("DevInst", wintypes.DWORD),
                        ("Reserved", ctypes.POINTER(ctypes.c_ulonglong))]

        sa = ctypes.windll.setupapi
        cfgmgr = ctypes.windll.cfgmgr32
        # restype MATTERS: without it ctypes assumes c_int and truncates the
        # 64-bit HDEVINFO, which yields ZERO devices instead of an error.
        sa.SetupDiGetClassDevsW.restype = wintypes.HANDLE

        def _stamp(devinst: int, prop_pid: int) -> bytes:
            """The raw FILETIME bytes of one DEVPKEY, or b'' when it is not a
            stamp that could ever move.

            b'' is a DOWNGRADE signal, never an error: it makes
            _fingerprint_sees_rejoin() report False, which puts the short
            self-heal floor back in charge. That path is live rather than
            theoretical -- 19 of this machine's 323 present devnodes return
            CR_NO_SUCH_VALUE for this property.

            STRICT ON PURPOSE. The long floor is granted on 'this fingerprint
            carries a stamp', so a value that EXISTS but can never advance
            would buy an hour of pinned indices while detecting nothing --
            precisely the it-exists-so-it-must-work reasoning this gate is
            here to avoid. Accept only what a real arrival stamp is:
            DEVPROP_TYPE_FILETIME, exactly 8 bytes, non-zero. Measured across
            all 545 reachable devnodes, every readable stamp is type 0x10 /
            8 bytes / non-zero, so this rejects nothing real on this box."""
            key = _DEVPROPKEY()
            key.fmtid = _GUID(_DEVPKEY_FMTID_DEVICE_TIMESTAMPS)
            key.pid = prop_pid
            ptype = ctypes.c_ulong(0)
            size = ctypes.c_ulong(0)
            cfgmgr.CM_Get_DevNode_PropertyW(devinst, ctypes.byref(key),
                                            ctypes.byref(ptype), None,
                                            ctypes.byref(size), 0)
            # A FILETIME is exactly 8 bytes; anything else is not one.
            if size.value != 8:
                return b""
            buf = ctypes.create_string_buffer(size.value)
            if cfgmgr.CM_Get_DevNode_PropertyW(devinst, ctypes.byref(key),
                                               ctypes.byref(ptype), buf,
                                               ctypes.byref(size), 0) != 0:
                return b""
            if ptype.value != _DEVPROP_TYPE_FILETIME:
                return b""
            raw = buf.raw[:8]
            # An all-zero FILETIME is 'the property exists and was never set'.
            # Those are truthy bytes, so letting one through would earn the
            # long floor on a value guaranteed never to change.
            return b"" if raw == b"\x00" * 8 else raw

        found: "dict[str, tuple[str, bytes, bytes]]" = {}
        for cat_str in (_KSCATEGORY_VIDEO_CAMERA, _KSCATEGORY_VIDEO):
            cat = _GUID(cat_str)
            hdi = sa.SetupDiGetClassDevsW(ctypes.byref(cat), None, None,
                                          _DIGCF_PRESENT_IFACE)
            if not hdi or hdi in (-1, 0xFFFFFFFFFFFFFFFF):
                return None
            hdi = ctypes.c_void_p(hdi)
            try:
                idx = 0
                while True:
                    did = _IFACE()
                    did.cbSize = ctypes.sizeof(_IFACE)
                    if not sa.SetupDiEnumDeviceInterfaces(hdi, None,
                                                          ctypes.byref(cat), idx,
                                                          ctypes.byref(did)):
                        break
                    # Increment BEFORE any `continue` below, or a single
                    # unreadable interface spins this loop forever.
                    idx += 1
                    need = wintypes.DWORD(0)
                    sa.SetupDiGetDeviceInterfaceDetailW(hdi, ctypes.byref(did),
                                                        None, 0,
                                                        ctypes.byref(need), None)
                    buf = ctypes.create_string_buffer(max(need.value, 8))
                    ctypes.cast(buf, ctypes.POINTER(wintypes.DWORD))[0] = 8
                    dinfo = _DEVINFO()
                    dinfo.cbSize = ctypes.sizeof(_DEVINFO)
                    if not sa.SetupDiGetDeviceInterfaceDetailW(
                            hdi, ctypes.byref(did), buf, need.value,
                            ctypes.byref(need), ctypes.byref(dinfo)):
                        continue
                    path = ctypes.wstring_at(ctypes.addressof(buf) + 4).lower()
                    # drop the interface-class GUID; keep the device instance
                    path = _re.sub(r"#\{[0-9a-f-]{36}\}.*$", "",
                                   path.replace("\\\\?\\", ""))
                    if path in found:
                        continue    # same device via the other category
                    found[path] = (
                        path,
                        _stamp(dinfo.DevInst, _DEVPKEY_PID_LAST_ARRIVAL),
                    )
            finally:
                sa.SetupDiDestroyDeviceInfoList(hdi)
        return tuple(sorted(found.values()))
    except Exception:
        return None


def _dshow_software_camera_names() -> "tuple[str, ...] | None":
    """Friendly names of the SOFTWARE/virtual DirectShow cameras (OBS Virtual
    Camera and friends). Uses CDEF_DEVMON_FILTER, which is the non-leaking half
    of the video category. Returns None on failure. NEVER raises."""
    try:
        from comtypes import GUID as _GUID
        from pygrabber.dshow_graph import SystemDeviceEnum, IPropertyBag
        from pygrabber.dshow_ids import DeviceCategories
        sde = SystemDeviceEnum().system_device_enum
        enum = sde.CreateClassEnumerator(
            _GUID(DeviceCategories.VideoInputDevice),
            dwFlags=_CDEF_DEVMON_FILTER)
        if not enum:
            return ()
        out: list[str] = []
        try:
            mon, cnt = enum.Next(1)
        except ValueError:
            return ()
        while cnt > 0:
            try:
                pb = mon.BindToStorage(
                    0, 0, IPropertyBag._iid_).QueryInterface(IPropertyBag)
                out.append(str(pb.Read("FriendlyName", pErrorLog=None)))
            except Exception:
                out.append("<unreadable>")
            mon, cnt = enum.Next(1)
        return tuple(out)
    except Exception:
        return None


def _video_device_fingerprint() -> "tuple | None":
    """A cheap, LEAK-FREE identity for the current video-capture device set.
    Changes whenever a camera (physical OR virtual) joins or leaves -- and,
    because the PnP half carries a re-stamped arrival FILETIME, also when one
    leaves and REJOINS between two samples. Those are the only times DirectShow indices
    can reshuffle. None means "could not tell" -- callers must then fall back to
    re-enumerating on the timer, so a probe failure degrades to the old
    behaviour rather than pinning a stale index. NEVER raises.

    Note the two halves are compared against the state captured AT THE LAST REAL
    ENUMERATION, not against the previous sample. That is what makes a
    transient that fully reverts (a virtual camera that starts and stops between
    two ticks) correctly read as "no change": the index map built before it is
    still the right one afterwards."""
    pnp = _setupapi_camera_instances()
    soft = _dshow_software_camera_names()
    if pnp is None or soft is None:
        return None
    return (pnp, soft)


def _usable_arrival_stamp(v) -> bool:
    """True iff `v` is an arrival stamp that could actually ADVANCE: a non-zero
    8-byte FILETIME. Pure; NEVER raises.

    Split out, and applied here as well as inside _stamp(), on purpose.
    _stamp() is the only producer today, but the value it produces is what buys
    the LONG self-heal floor, and 'the bytes are non-empty' is a weaker claim
    than 'this is a timestamp that moves'. A 4-byte value or an all-zero
    FILETIME is truthy and would sail straight through a bare truth test."""
    try:
        return len(v) == 8 and any(v)
    except Exception:
        return False


def _fingerprint_sees_rejoin(fp) -> bool:
    """True iff `fp` carries a usable arrival stamp for EVERY PnP camera in it,
    i.e. this fingerprint can distinguish "a device left and rejoined" from
    "nothing happened". Pure; NEVER raises.

    This is the switch between the two self-heal floors. A stamped fingerprint
    closes the leave+rejoin hole outright, so the unconditional re-enumeration
    becomes a pure belt-and-braces safety net and can be hours apart; an
    unstamped one leaves that hole open, so the short floor has to stay.

    IT ASKS "CAN THIS FINGERPRINT SEE A REJOIN", NOT "DID ONE HAPPEN", and the
    split is deliberate. Here we check only that a usable stamp is PRESENT;
    whether one MOVED is decided by the callers, which compare the WHOLE
    fingerprint tuple against the one taken at the last real enumeration. That
    split is sound only because the stamp was measured to genuinely advance on a
    re-arrival (the experiment is written up in _setupapi_camera_instances).
    Absent that measurement this would be presence standing in for proof, which
    is the exact failure the block exists to prevent -- hence the extra
    _usable_arrival_stamp() check rather than a bare truth test.

    Requiring at least one PnP device is deliberate, not defensive noise: a
    SetupAPI probe that silently enumerates NOTHING returns an empty tuple, not
    None, and is otherwise indistinguishable from a machine with no cameras. An
    empty PnP half must therefore never be read as proof that the bus is quiet
    -- `all()` over an empty sequence is True, and that vacuous True is exactly
    how a broken probe would earn the long floor it has not verified."""
    try:
        pnp = fp[0]
    except Exception:
        return False
    if not pnp:
        return False
    try:
        return all(len(entry) >= 2 and _usable_arrival_stamp(entry[1])
                   for entry in pnp)
    except Exception:
        return False


# --- ALARM: the gate falling open ------------------------------------------
# The gate below is only as good as the free probe under it. When
# _video_device_fingerprint() cannot answer, _resolve_webcam_indices_by_name()
# deliberately degrades to re-enumerating on the 10 s TTL. That is the right
# SAFETY choice -- pinning an index we cannot prove is still correct would put
# the wrong camera in the tile with every read SUCCEEDING, which is a quieter
# bug than the leak. But it is also, exactly, the pre-fix behaviour and the
# pre-fix leak: +6 OS threads and +618 handles per MINUTE, permanently.
#
# "+6/MIN" IS THE QUIET HALF, and saying only that understated the danger by
# 31x. MEASURED 2026-09-06, real COM, real leaky enumeration, thread census by
# Win32 start address inside mfksproxy.dll, 3.0 min per arm, fresh process:
#   3.0 min, fingerprint None, amplifier quiet
#         18 enums    6.00/min    +18 thr      +664 hnd/min
#   3.0 min, fingerprint None, amplifier at 4 Hz
#        625 enums  208.13/min   +560 thr   +19,259 hnd/min
#   8.5 min, fingerprint None, amplifier at 4 Hz, floor removed (confirmation;
#            stopped at a 1,500-thread safety cap, rate flat throughout)
#      1,711 enums  200.21/min +1,520 thr   +18,340 hnd/min
# The amplifier rows are the ones that matter: _invalidate_side_tile_indices()
# fires on EVERY failed side-tile read and clears the resolved flag, so a sick
# camera drives this path at _KINECT_PREVIEW_TILE_READ_INTERVAL (0.25 s), not at
# the TTL. At those rates the v2.0.100 death numbers (14,507 threads /
# 1,419,190 handles) arrive in 74-82 MINUTES, not the ~40 hours "+6/min"
# implies - i.e. the operator would have seen the 15-minute re-warning perhaps
# five times before the process stopped logging at all.
#
# So the degraded path is now FLOORED at _WEBCAM_IDX_TTL_SEC in
# _resolve_webcam_indices_by_name() (see the "RATE FLOOR" block there): a
# forced invalidation may still bypass the TTL, but only once per TTL window,
# which makes "+6 OS threads and +618 handles per MINUTE" above true of BOTH
# rows instead of only the first. That floor is deliberately NOT applied to
# _dshow_input_devices_gated(): its callers are backoff-bounded
# (CAMERA_REOPEN_BACKOFF_SEC = 2 s, so <=30/min even fully degraded) and
# test_unreadable_fingerprint_degrades_to_enumerating_every_time pins that
# contract on purpose. The tile resolver is the only consumer with a per-frame
# amplifier behind it, so it is the only one that needed the floor.
#
# And it used to happen in TOTAL SILENCE. Measured 2026-09-05 on this rig, same
# process, 30 TTL ticks each:
#     real pygrabber          fingerprint OK   ->  0 enumerations, +0 threads
#     SystemDeviceEnum hidden fingerprint None -> 30 enumerations, +30 threads
#                                                 = 6.00/min, the FULL pre-fix
#                                                 rate, and 0 bytes written to
#                                                 stdout, stderr or the log.
# So a reverted fix was indistinguishable from a working one, and the first
# symptom would be the original death ~40 h later: 14,507 threads, every
# subsystem stops logging, exactly as at 07:00:36 on 2026-09-05.
#
# The trigger is not hypothetical. _dshow_software_camera_names() depends on a
# strictly NARROWER pygrabber/comtypes surface than the leaky call it protects
# (SystemDeviceEnum().system_device_enum, CreateClassEnumerator(dwFlags=...),
# IPropertyBag) and has NO fallback -- while _enumerate_dshow_input_devices()
# carries an explicit FilterGraph fallback for precisely the "older pygrabber /
# import shape" this cannot survive. Reproduced by exposing only FilterGraph on
# pygrabber.dshow_graph: the leaky enumeration still returned all four devices
# (leak fully armed) while the fingerprint was None on every call. A routine
# `pip install -U pygrabber`, a comtypes regeneration that renames dwFlags, or
# a SetupDiGetClassDevsW failure on another Windows build all land here.
#
# Hence this: the degradation announces itself, loudly and greppably, the first
# time it happens and every WEBCAM_FINGERPRINT_REWARN_SECONDS afterwards -- and
# announces the recovery too, so the log shows the window rather than just its
# start. Console-only and throttled on purpose: this is reached from the HUD
# preview compositor's per-frame path, so it must be cheap and it must never
# raise.
WEBCAM_FINGERPRINT_REWARN_SECONDS = 900.0

# True while the gate is known to be failing open; when it started; when we last
# said so; and how many leaky enumerations that has cost. The count is the
# damage estimate the warning quotes -- one leaked OS thread and 103 leaked
# handles each, none of them ever reclaimed short of a restart.
_webcam_fingerprint_degraded = [False]
_webcam_fingerprint_degraded_since = [0.0]
_webcam_fingerprint_warned_at = [0.0]
_webcam_fingerprint_leaky_enums = [0]


# ── THE AMPLIFIER, COUNTED (2026-09-06) ──────────────────────────────────────
# _invalidate_side_tile_indices() is the amplifier that killed v2.0.100: every
# FAILED SIDE-TILE READ forces a re-resolve, and the tile loop retries every
# _KINECT_PREVIEW_TILE_READ_INTERVAL (0.25 s), so a camera that opens and then
# stops delivering can drive this path ~240x a minute instead of the 6x a
# minute the TTL allows. The fingerprint gate above is what is supposed to turn
# those into free SetupAPI probes instead of leaky DirectShow enumerations.
#
# THIS EXISTS BECAUSE THE PATH WAS UNOBSERVABLE, and that is not a small thing.
# A soak reported on 2026-09-06 04:32-04:55 that "under the full amplifier
# condition (camera permanently unavailable, producer retrying opens forever)
# mfksproxy was 2 -> 2, +0.000/min over 17.2 min". It was not. At 04:31:14 the
# preflight had already logged "camera index 0: failed to open in 2.0s -
# marking bad" and "dropped 1 bad camera index/es; 1 remain", which removes the
# camera from CAMERAS for the whole session; _kinect_preview_webcam_names() is
# DERIVED from CAMERAS, so the 'right' slot never resolved, no tile handle was
# ever opened, no read ever failed, and the amplifier could not fire even once.
# The reviewer's own tile sampler agreed - the right tile changed 1 sample in
# 1108, median age 806 s, max 1503 s - and the claim still stood, because
# nothing IN the process counted. A +0.000/min measured on an idle one-camera
# JARVIS was reported as the amplifier being safe.
#
# So: COUNT IT, and say so on the console. After this, "the amplifier ran" is a
# checkable statement - a soak that cannot show these numbers did not test it.
# Cheap by construction: four int increments on a path that already does COM
# work, plus one throttled time comparison per resolve.
_DSHOW_ENUM_LEAK_HANDLES = 103        # per leaked CreateClassEnumerator call

# invalidations : failed side-tile reads that forced a re-resolve (the amplifier)
# suppressed    : re-resolves the FREE device fingerprint absorbed (no leak)
# enumerations  : leaky DirectShow enumerations actually performed (1 thread +
#                 _DSHOW_ENUM_LEAK_HANDLES handles each, never reclaimed)
# ttl_cached    : resolves answered from the 10 s TTL without reaching the gate
# producer_owned: tile opens DECLINED because the face-track producer holds that
#                 camera. Each one is a duplicate in-process handle not taken —
#                 and a duplicate handle measured 98.6-99.5% producer read
#                 failures with no recovery until release+reopen, so this is the
#                 count of producer blackouts prevented, not a housekeeping stat.
#                 See _TILE_PRODUCER_OWNED_MAX_AGE for the measurement.
# ttl_floored   : forced re-resolves the _WEBCAM_IDX_TTL_SEC rate floor
#                 absorbed while the FINGERPRINT COULD NOT ANSWER. Separate
#                 from `suppressed` on purpose: that one means the free probe
#                 proved the bus had not moved, this one means nothing proved
#                 anything and we declined to pay 4x/second to keep asking.
#                 Nonzero here always means the gate is failing open.
_side_tile_gate_counts = {"invalidations": 0, "suppressed": 0,
                          "enumerations": 0, "ttl_cached": 0,
                          "producer_owned": 0, "ttl_floored": 0}

# Reporting window: [started_at, invalidations, suppressed, enumerations, reports]
# — the counts as of the window start, so every line quotes a RATE over its own
# window rather than an average since boot. A burst two hours ago must not be
# reported as current load, and this project's own rule is that a 60-second
# sample is not a rate.
_side_tile_gate_window = [0.0, 0, 0, 0, 0, 0]
_SIDE_TILE_GATE_FIRST_REPORT_S = 60.0     # say it quickly the first time...
_SIDE_TILE_GATE_REPORT_GAP_S = 300.0      # ...then settle to every 5 min


def get_side_tile_gate_stats() -> dict:
    """Snapshot of the side-tile re-resolve (amplifier) accounting.

    Keys: ``invalidations`` (failed side-tile reads that forced a re-resolve),
    ``suppressed`` (absorbed by the free fingerprint gate), ``enumerations``
    (leaky DirectShow enumerations actually made), ``ttl_cached``,
    ``producer_owned`` (own-handle opens declined because the producer holds
    that camera — duplicate-handle producer blackouts prevented), plus the
    derived ``leaked_threads`` / ``leaked_handles`` those enumerations cost and
    ``fingerprint_none`` (enumerations made with the gate failed open).

    READ THIS BEFORE BELIEVING ANY SICK-CAMERA SOAK: ``invalidations == 0``
    means the amplifier never fired, whatever else the run measured. And
    ``producer_owned > 0`` with ``invalidations == 0`` is the healthy shape
    since 2026-09-06: the tile wanted its own handle and was refused one."""
    d = dict(_side_tile_gate_counts)
    d["leaked_threads"] = d["enumerations"]
    d["leaked_handles"] = d["enumerations"] * _DSHOW_ENUM_LEAK_HANDLES
    d["fingerprint_none"] = _webcam_fingerprint_leaky_enums[0]
    return d


def _report_side_tile_amplifier(now: float) -> bool:
    """Print (throttled) what the amplifier did in the window just ended, and
    what the gate cost. Returns True when it printed. NEVER raises.

    Says NOTHING while the amplifier is quiet — the healthy steady state is the
    common one and must stay silent, or an operator learns to ignore the line —
    and slides the window forward instead, so a later burst is measured over
    ITS OWN window."""
    try:
        w = _side_tile_gate_window
        if len(w) < 6:
            w.extend([0] * (6 - len(w)))
        inval = _side_tile_gate_counts["invalidations"]
        supp = _side_tile_gate_counts["suppressed"]
        enum = _side_tile_gate_counts["enumerations"]
        floored = _side_tile_gate_counts["ttl_floored"]
        if w[0] <= 0.0 or not (now >= w[0]):
            # not (now >= w[0]) rather than now < w[0]: it also catches a NaN
            # clock, which would otherwise reach the division below.
            w[0], w[1], w[2], w[3], w[5] = now, inval, supp, enum, floored
            return False
        d_inval = inval - w[1]
        if d_inval <= 0:
            w[0], w[1], w[2], w[3], w[5] = now, inval, supp, enum, floored
            return False
        gap = (_SIDE_TILE_GATE_FIRST_REPORT_S if w[4] == 0
               else _SIDE_TILE_GATE_REPORT_GAP_S)
        elapsed = now - w[0]
        if elapsed < gap:
            return False
        mins = elapsed / 60.0
        d_supp = supp - w[2]
        d_enum = enum - w[3]
        d_floor = floored - w[5]
        w[0], w[1], w[2], w[3], w[5] = now, inval, supp, enum, floored
        w[4] += 1
        print(f"  [kinect-preview] side-tile AMPLIFIER active: {d_inval} failed "
              f"side-tile read(s) in the last {mins:.1f} min "
              f"({d_inval / mins:.1f}/min) forced a re-resolve. The device "
              f"fingerprint absorbed {d_supp} of them for free and the "
              f"{_WEBCAM_IDX_TTL_SEC:.0f}s rate floor absorbed {d_floor} "
              f"more (anything but 0 there means the fingerprint could "
              f"not answer at all - see the FAILED OPEN warning); "
              f"{d_enum} reached the leaky DirectShow enumeration "
              f"(≈{d_enum} OS thread(s), "
              f"≈{d_enum * _DSHOW_ENUM_LEAK_HANDLES} handle(s), never "
              f"reclaimed before a restart). Ungated this window would have "
              f"cost ≈{d_inval} threads and "
              f"≈{d_inval * _DSHOW_ENUM_LEAK_HANDLES} handles. A camera is "
              f"opening and then failing its reads - this is the v2.0.100 "
              f"death path, and this line is the only evidence it ran.")
        return True
    except Exception:
        return False


def _report_video_fingerprint_gate(fp, names, now: float) -> bool:
    """Report the DirectShow-enumeration leak gate failing open, and closing
    again. Returns True when it printed. NEVER raises.

    Call ONLY from the real-enumeration path of
    ``_resolve_webcam_indices_by_name()``, with ``fp`` = the fingerprint stamped
    for this enumeration and ``names`` = what ``_enumerate_dshow_input_devices``
    returned.

    ``names is None`` is deliberately NOT an alarm, and that is the whole reason
    this is called after the enumeration rather than at the probe. When
    pygrabber is absent the enumeration fails at the IMPORT and never reaches
    CreateClassEnumerator, so nothing leaked and a leak warning there would be
    false. The alarm condition is the dangerous COMBINATION: the leaky call
    SUCCEEDED (so it leaked) while the fingerprint that exists to prevent the
    next one is unreadable (so it will leak again in _WEBCAM_IDX_TTL_SEC, and
    every tick after that, forever)."""
    try:
        if names is None:
            return False
        if fp is not None:
            if not _webcam_fingerprint_degraded[0]:
                return False        # healthy, and was healthy — say nothing
            leaked = _webcam_fingerprint_leaky_enums[0]
            mins = max(0.0, now - _webcam_fingerprint_degraded_since[0]) / 60.0
            _webcam_fingerprint_degraded[0] = False
            _webcam_fingerprint_leaky_enums[0] = 0
            print(f"  [kinect-preview] video-device fingerprint is READABLE "
                  f"again — the DirectShow enumeration leak gate is closed. It "
                  f"was open for {mins:.1f} min and cost {leaked} leaky "
                  f"enumeration(s) ≈ {leaked} OS threads and {leaked * 103} "
                  f"handles, none of which come back before a restart.")
            return True
        # Fingerprint unreadable: the gate cannot fire, so the leaky
        # enumeration is now running on the bare TTL — the pre-fix leak.
        _webcam_fingerprint_leaky_enums[0] += 1
        if not _webcam_fingerprint_degraded[0]:
            _webcam_fingerprint_degraded[0] = True
            _webcam_fingerprint_degraded_since[0] = now
        elif (now - _webcam_fingerprint_warned_at[0]
                ) < WEBCAM_FINGERPRINT_REWARN_SECONDS:
            return False            # already shouting; don't shout every 10 s
        _webcam_fingerprint_warned_at[0] = now
        # Name the failing half — without it the operator has a leak and no
        # lead. Both probes are free (measured 0 threads / 0 handles over 300
        # calls, 0.35 ms combined), and this only runs on the throttled warn
        # path, so re-probing to attribute the failure costs nothing.
        try:
            pnp_ok = _setupapi_camera_instances() is not None
        except Exception:
            pnp_ok = False
        try:
            soft_ok = _dshow_software_camera_names() is not None
        except Exception:
            soft_ok = False
        if not pnp_ok and not soft_ok:
            which = ("BOTH halves failed — _setupapi_camera_instances "
                     "(SetupDiGetClassDevsW on the KS video categories) and "
                     "_dshow_software_camera_names (pygrabber DEVMON_FILTER)")
        elif not pnp_ok:
            which = ("_setupapi_camera_instances failed — SetupDiGetClassDevsW "
                     "on the KS video categories returned nothing usable")
        elif not soft_ok:
            which = ("_dshow_software_camera_names failed — it needs "
                     "pygrabber's SystemDeviceEnum + IPropertyBag and "
                     "CreateClassEnumerator(dwFlags=…), a NARROWER surface "
                     "than the leaky call it guards, and unlike "
                     "_enumerate_dshow_input_devices it has no FilterGraph "
                     "fallback, so a pygrabber/comtypes upgrade lands here")
        else:
            which = ("both halves answer when probed individually but the "
                     "fingerprint did not — a race, or a device that left "
                     "between the two probes")
        # QUOTE THE MEASURED RATE once there is a window to measure over, not
        # the TTL-derived one. The TTL used to be only a FLOOR here: every
        # failed side-tile read calls _invalidate_side_tile_indices(), which
        # bypassed the TTL entirely, and a sick camera on a failed-open gate
        # therefore leaked at 208 enumerations/min - MEASURED 2026-09-06, 3 min,
        # real COM - against 6.00/min with the amplifier quiet. That path is now
        # floored at _WEBCAM_IDX_TTL_SEC, so the two rates have converged; the
        # OPEN path (_dshow_input_devices_gated, backoff-bounded at <=30/min)
        # is deliberately not floored and is not counted here. The measured
        # rate is still what gets printed, because a floor is a claim about the
        # code and this line is supposed to report the machine.
        n = _webcam_fingerprint_leaky_enums[0]
        mins = max(0.0, now - _webcam_fingerprint_degraded_since[0]) / 60.0
        if mins >= 1.0:
            rate = n / mins
            cost = (f"MEASURED {rate:.1f} leaked enumerations/min over the "
                    f"last {mins:.0f} min = ≈{rate:.1f} OS threads and "
                    f"≈{rate * 103:.0f} handles per MINUTE")
        else:
            floor = 60.0 / max(_WEBCAM_IDX_TTL_SEC, 0.001)
            cost = (f"about ≈{floor:.0f} OS threads and ≈{floor * 103:.0f} "
                    f"handles per MINUTE — one per {_WEBCAM_IDX_TTL_SEC:.0f}s "
                    f"TTL tick, which a failed side-tile read can bring "
                    f"forward but no longer multiply")
        print(f"  [kinect-preview] WARNING: the DirectShow enumeration leak "
              f"gate has FAILED OPEN — the video-device fingerprint is "
              f"unreadable, so the leaky enumeration is running unguarded. "
              f"{which}. Cost: {cost}, permanently, until JARVIS restarts — "
              f"{n} leaked enumeration(s) so far. This is the v2.0.100 death "
              f"mode (14,507 threads / 1,419,190 handles, then every subsystem "
              f"stops logging). Fix the probe or pin pygrabber. Re-warning "
              f"every {WEBCAM_FINGERPRINT_REWARN_SECONDS / 60.0:.0f} min while "
              f"it lasts.")
        return True
    except Exception:
        return False


def _enumerate_dshow_input_devices() -> "list[str] | None":
    """The DirectShow VIDEO input-device friendly names, by INDEX (list position
    == the index cv2.VideoCapture(idx, CAP_DSHOW) uses), via pygrabber. Returns
    None when pygrabber is unavailable or the COM enumeration fails — callers
    then fall back to a configured static index. NEVER raises.

    This is the single place that touches pygrabber; both the per-frame preview
    tile resolver and the face-track open-by-name path (_dshow_name_to_index)
    funnel through it so there is ONE enumeration contract."""
    # SystemDeviceEnum, not FilterGraph. FilterGraph.get_input_devices() is
    # literally `self.system_device_enum.get_available_filters(VideoInputDevice)`
    # (pygrabber/dshow_graph.py:498), but constructing the FilterGraph first also
    # builds a filter-graph manager, a CaptureGraphBuilder2, a FilterFactory AND a
    # WmProfileManager that loads every system Windows-Media profile — all thrown
    # away unread. Measured on this box over 30 enumerations, identical device
    # lists both ways:
    #     FilterGraph()       71.0 ms wall / 39.6 ms CPU per call
    #     SystemDeviceEnum()  46.3 ms wall / 12.0 ms CPU per call
    #
    # This does NOT fix the leak: BOTH paths leak +1 OS thread and +103 handles
    # per call, identically. CORRECTED 2026-09-05 — an earlier note here blamed
    # "the device-moniker bind", and that is WRONG in a way that matters: a
    # decomposition of the chain (see the block above _setupapi_camera_instances)
    # showed CreateClassEnumerator ALONE already leaks the full +1/+103 before a
    # single moniker exists, and Next()/BindToStorage/Read add exactly nothing.
    # A raw-ctypes repro that binds nothing leaks the same. So you CANNOT dodge
    # this by sourcing the names differently — any call that builds the video
    # class enumerator pays it. The only fix is to call it less often.
    # At the 10 s TTL below that was +6 threads and +618 handles per MINUTE in
    # the live process, which is the mfksproxy.dll growth. Treat this call as
    # expensive AND leaky, and go through _resolve_webcam_indices_by_name(),
    # which now gates it behind a free device-set fingerprint.
    names = None
    try:
        from pygrabber.dshow_graph import SystemDeviceEnum
        from pygrabber.dshow_ids import DeviceCategories
        names = SystemDeviceEnum().get_available_filters(
            DeviceCategories.VideoInputDevice)
    except Exception:
        names = None            # older pygrabber / import shape — fall through
    if names is None:
        try:
            from pygrabber.dshow_graph import FilterGraph
            names = FilterGraph().get_input_devices()
        except Exception:
            # pygrabber missing / COM hiccup.
            return None
    try:
        return [str(n or "") for n in names]
    except Exception:
        return None


def _dshow_input_devices_gated(cache: list,
                               now: float | None = None) -> "list[str] | None":
    """``_enumerate_dshow_input_devices()`` behind the free device-set
    fingerprint gate and the self-heal floor. THE RAW FUNCTION IS THE LEAKY
    PRIMITIVE (+1 OS thread, +103 handles, permanently, per call); every
    consumer that calls it on a repeating schedule must come through here.

    ``cache`` is one caller-owned 3-slot list ``[names, fingerprint,
    enumerated_at]``. It is PASSED IN rather than closed over so that the one
    copy of the gate RULE serves every consumer: two consumers with separate
    caches each pay at most one enumeration per self-heal floor, which is a cost
    (2 threads/hour instead of 1), but the rule they enforce cannot drift apart
    — and a rule fixed in one copy while the other rots is this codebase's
    single most expensive bug shape.

    Returns a fresh copy of the device-name list, or None when the enumeration
    is unavailable (pygrabber missing / COM hiccup) — callers then fall back to
    a configured static index exactly as they did before. NEVER raises.

    WRITE ORDER IS LOAD-BEARING, and is why this needs no lock. Unlike the
    side-tile resolver, this runs on the face-track PRODUCER thread and on the
    boot probe as well, so two threads can be inside it at once. The fingerprint
    is CLEARED before the slow enumeration starts and re-published only AFTER
    the name list is stored, so a concurrent reader sees either the complete old
    pair or no fingerprint at all. It can never pair a NEW fingerprint with the
    OLD names — the one interleaving that would hand out a stale index for a bus
    that had just moved, i.e. open the wrong camera and succeed. The cost of the
    conservative direction is at most one extra enumeration."""
    now = time.time() if now is None else now
    # A cache this function cannot use is a reason to enumerate, never a reason
    # to fail: the gate must never be why a camera could not be opened. Checked
    # by type and length rather than by try/except around the unpack, because a
    # 3-CHARACTER STRING unpacks perfectly happily and then explodes on the
    # arithmetic two lines later (caught by
    # test_junk_cache_degrades_to_the_raw_enumeration_and_never_raises).
    if not isinstance(cache, list) or len(cache) < 3:
        return _enumerate_dshow_input_devices()
    names, fp_at_last_enum, enumerated_at = cache[0], cache[1], cache[2]
    # Same two floors, and the same reason, as the side-tile resolver: a stamped
    # fingerprint sees a leave+rejoin after the fact and so makes the
    # unconditional re-enumeration a safety net rather than the correctness
    # mechanism; an unstamped one leaves that hole open and has to keep paying.
    floor = (_WEBCAM_IDX_SELFHEAL_STAMPED_SEC
             if _fingerprint_sees_rejoin(fp_at_last_enum)
             else _WEBCAM_IDX_SELFHEAL_SEC)
    try:
        within_floor = (now - float(enumerated_at)) < floor
    except Exception:  # pragma: no cover - defensive: a non-numeric stamp
        within_floor = False
    if names is not None and fp_at_last_enum is not None and within_floor:
        fp = _video_device_fingerprint()
        # A None fingerprint is "could not tell", NEVER "nothing changed": fall
        # through and pay for the real enumeration rather than pin a stale index.
        if fp is not None and fp == fp_at_last_enum:
            return list(names)
    # Sample the fingerprint BEFORE enumerating, for the same reason the
    # side-tile resolver does: a device that arrives *during* the 40 ms
    # enumeration then leaves us holding a stale fingerprint and we re-resolve
    # on the next call — the safe direction. Sampling after would record the new
    # device set against an index map built without it, and we would never
    # re-resolve.
    fp_before = _video_device_fingerprint()
    cache[2] = now
    cache[1] = None                 # invalidate while the slow call is out
    fresh = _enumerate_dshow_input_devices()
    if fresh is None:
        # No index map, so the fingerprint sampled alongside it describes
        # nothing. Both stay cleared: keeping either would let ONE COM hiccup
        # suppress every retry for a whole self-heal period. Costs nothing in
        # the permanent case — a genuinely missing pygrabber fails at the
        # IMPORT and never reaches the leaky call.
        cache[0] = None
        return None
    cache[0] = list(fresh)
    cache[1] = fp_before            # publish LAST
    return list(fresh)


# The camera OPEN path's own slot of the gate above: [names, fingerprint,
# enumerated_at]. Owned by _dshow_name_to_index() and therefore by the
# face-track opener (_open_capture) and the boot rescue (_camera_rescued_by_name).
#
# WHY IT IS GATED AT ALL (2026-09-05, measured — this was the hole left by the
# first pass of the leak fix). _dshow_name_to_index() was a SECOND, UNGATED
# caller of the leaky enumeration: measured on this rig it costs +1.00 OS thread
# and +103.0 handles in ~43 ms per call, INCLUDING when the requested name does
# not match anything — the enumeration happens before the name comparison, so an
# ABSENT camera pays full price. It is called unconditionally at the top of
# _open_capture(), and _open_capture() is what the face-track loop's recovery
# branch calls every CAMERA_REOPEN_BACKOFF_SEC (2.0 s) for a camera whose handle
# is None. A configured camera that goes sick or is unplugged, and whose static
# fallback index then also fails to open, therefore drove ~30 ungated
# enumerations per MINUTE — five times the 6.0/min the TTL gate had just removed
# — for as long as the condition lasted. The fingerprint answers that case
# exactly right: the bus is NOT changing while a camera is merely sick, so after
# the one enumeration that observes the device leaving, every subsequent reopen
# attempt is served from this cache for free.
_dshow_open_devices_cache: list = [None, None, 0.0]


def _dshow_name_to_index(substr: str) -> "int | None":
    """The LIVE DirectShow index of the first input device whose friendly name
    contains ``substr`` (case-insensitive), or None when pygrabber is
    unavailable / nothing matched.

    GATED, NOT FRESH (2026-09-05 — the docstring here used to promise "enumerates
    DEVICES FRESH on every call", and that promise is what made this the second
    ungated caller of a call that leaks an OS thread every time). The names come
    from _dshow_input_devices_gated(), which re-enumerates only when the free
    device-set fingerprint says the bus actually moved, or when the self-heal
    floor expires. That preserves the property this function exists for — an
    index shuffle is still seen, because a shuffle REQUIRES a device to join,
    leave, or leave-and-rejoin, and the fingerprint detects all three — while a
    camera that is merely sick, absent or held by another app no longer buys a
    leaked thread per reopen attempt. NEVER raises."""
    needle = (substr or "").strip().lower()
    if not needle:
        return None
    names = _dshow_input_devices_gated(_dshow_open_devices_cache)
    if not names:
        return None
    for i, n in enumerate(names):
        if needle in (n or "").lower():
            return i
    return None


try:
    from core import camera_backend as _camera_backend
except Exception:      # pragma: no cover - core/ always ships with the monolith
    _camera_backend = None

# Remembers the last decision logged per (index, name, LABEL) so a per-frame
# tile open does not narrate the same translation forever.
#
# THE LABEL IS IN THE KEY BECAUSE LEAVING IT OUT HID A WHOLE CONTENDER.
# The key used to be (index, name) alone, and `name` is the CAMERA, not the
# caller - so the FIRST call site to open a given webcam was the only one this
# process ever announced. Every later opener of that same device - the side
# tile compositor, the probe sweep, a snapshot - matched the same key, found
# the same (open_idx, backend), and said nothing, forever.
#
# What that cost. Every "[face-track] Right webcam ... read failure" line in
# the 8 consecutive restarts that opened that camera under this opener
# (logs/session_2026-09-05_22-37-30.log through session_2026-09-06_06-12-11.log)
# was classified against the scheduler lines in the same log, 2026-09-06:
#
#     27  right-camera read failures, total
#      8  at camera-open +7..13 s          <- ONE PER RESTART, no scheduler line
#      8  at the self-diag BOOT sweep      (+8..13 s after it fires)
#     11  at a 30-minute interval sweep    (+8..10 s after the apscheduler line)
#      0  unaccounted for
#
# So the per-restart count inside the first 90 s is TWO, not one, and the
# probes explain 19 of 27 failures rather than all of them. The boot sweep is
# announced ("[self-diag] boot sweep queued (fires in 60s)") 8-10 s BEFORE the
# camera opens and fires 60 s later, which is why its failure lands at open
# +59..63 s and is easy to find. The +9 s one has no scheduled anything behind
# it: the boot sweep has not fired, the 30-minute interval:run_diagnostic job
# was only just added and does not run for another half hour, and - until this
# key changed - the session log carried exactly ONE camera-open line for that
# webcam no matter how many call sites touched it. So the boot log read as a
# healthy producer that simply stopped getting frames, with no opener named
# anywhere, and the conclusion that invites ("every producer read failure is
# the 30-minute probe, so this one must be the USB camera dying") is the wrong
# turn that has already cost this owner an evening.
#
# For contrast, the three restarts that opened this same webcam BEFORE the
# 2026-09-05 camera-open rewrite (2026-09-04 23:09, 2026-09-05 00:48, 00:52)
# logged exactly ONE boot-window failure each, and it was the boot sweep's:
# open +70/+75/+99 s, i.e. 18-48 s after that sweep fired, against 8-12 s
# after it now. (The right camera was then absent from CAMERAS from 09-05
# 07:14 until 22:11, which is why no restart in between opened it at all.)
# HONEST LIMIT: 3 boots before against 8 after, and what changed between them
# was the whole opener - Media Foundation, index translation, require_frame,
# the tile/probe rewrite - not one switch. So this says the +9 s failure showed
# up alongside that rewrite; it does not isolate which part of it. Which is
# exactly the question the log has to be able to answer, and could not, because
# it named only the first opener of each camera.
#
# WHAT THE +9 s CONTENDER TURNED OUT TO BE, and why that is the argument for
# this key rather than against it: the side-tile compositor opening its OWN
# second in-process handle on the camera the producer already holds (measured
# separately at 98.6-99.5% producer read failures; the tile now declines that
# open and says so - "[kinect-preview] <slot> tile: declined N own-handle
# open(s)"). Verified live on the 2026-09-06 07:55:26 restart, the first one
# after that gate: right webcam opened 07:55:49, the tile decline was logged in
# the same second, and the next 32 minutes - covering the 60 s boot sweep AND
# the first 30-minute interval sweep (08:25:41, which completed in 3 s) -
# produced ZERO right-camera read failures, where the previous 8 restarts each
# produced 2 in the boot window alone plus one per interval sweep.
#
# Which also suggests, though this part is inference and not measurement, that
# the tile was the AMPLIFIER for all three kinds: a probe stalls the producer
# briefly, its cached frame ages past _KINECT_PREVIEW_TILE_REUSE_MAX_AGE, the
# tile stops reusing it and opens its own handle, and THAT is what turns a
# blip into 25 consecutive failed reads. If so, the original "every failure is
# the probe" reading named the trigger and missed the mechanism.
#
# That contender opened the same (index, name) as the producer, which is
# exactly the pair this dedupe collapsed - so for eight restarts the log could
# not name it, and this key is why the next one will be named on the first
# line it prints.
#
# Still bounded: a key is (index, name, label), and every label a call site
# passes is either a configured camera's name/label or an f-string over the
# INDEX alone ("index N", "probe index N", "side tile index N"). So the dict is
# capped by call sites x indices, not by time or frame count.
_camera_backend_notes: dict = {}

# Lines _camera_open() wants said, waiting for a thread that is allowed to say
# them. See _drain_camera_backend_notes for why this queue exists at all.
_camera_backend_pending: deque = deque(maxlen=32)


def _drain_camera_backend_notes() -> None:
    """Print whatever _camera_open() queued, from the CALLER's thread.

    TWO RULES COLLIDE HERE, and this queue is what satisfies both.

    1. _camera_open() runs on the throwaway open worker that
       _open_capture_bounded may abandon, and that worker MUST NOT print - an
       abandoned open that narrates itself lands after "Abandoning the
       attempt…" and reads as the camera coming back. (See
       AnOpenedLineMeansTheProducerHoldsThatCamera.)
    2. logging is not an escape hatch. The daemon Tees stdout/stderr into
       logs/session_*.log and configures no logging handler at all, so
       logging.info() goes NOWHERE in production - verified 2026-09-05 by
       grepping a live session log for logging-formatted lines: zero. Routing
       the backend decision there made it invisible on the only machine that
       matters, which is this project's signature failure, not a fix for it.

    So the worker QUEUES and a joiner SAYS. What is queued is a decision
    ("opening with MSMF at index 1"), never an outcome, so it cannot be misread
    as a success even when it is printed after an abandon. NEVER raises."""
    while True:
        try:
            line = _camera_backend_pending.popleft()
        except IndexError:
            return
        except Exception:       # pragma: no cover - defensive
            return
        try:
            print(line)
        except Exception:       # pragma: no cover - defensive
            return


def _camera_open(idx, *, name: "str | None" = None,
                 width: "int | None" = None, height: "int | None" = None,
                 require_frame: float = 0.0, label: str = ""):
    """THE camera opener. Picks the backend, translates the index for it, and
    hands back an opened capture (or None). Callers keep their own locking and
    their own wall-clock bounding — this is only the inner open.

    ``idx`` is a DIRECTSHOW index, because that is what CAMERAS on disk holds
    and what _dshow_name_to_index() produces. The two backends do NOT index the
    same list (verified on this rig 2026-09-05: DirectShow 0=USB 2.0 Camera
    1=Kinect 2=eMeet 3=OBS Virtual Camera; Media Foundation 0=Kinect
    1=USB 2.0 Camera 2=eMeet, with no OBS entry at all), so handing a raw
    CAMERAS index to CAP_MSMF would repoint index 0 from the USB webcam to the
    Kinect and succeed. Everything here exists to stop that.

    WHY MSMF AT ALL — measured, 25 open/read/release cycles per figure, fresh
    process each, 1280x720 requested, 30 reads per cycle:
        eMeet C960   CAP_DSHOW  +4.58 OS threads  +479 handles  per cycle
        eMeet C960   CAP_MSMF   -0.21 OS threads    +0.97       per cycle
        USB 2.0 Cam  CAP_DSHOW  +4.55 OS threads  +479 handles  per cycle
        USB 2.0 Cam  CAP_MSMF   -0.18 OS threads    +1.06       per cycle
    The DirectShow threads all start inside mfksproxy.dll and are never
    reclaimed. That is the OPEN half of the same leak v2.0.101 gated in the
    enumeration half, and unlike the enumeration it cannot be gated away: the
    face-track loop has to open the camera.

    NAME FIRST, INDEX SECOND. Matching the configured CAMERAS name against the
    Media Foundation device list needs no DirectShow enumeration at all — and
    MFEnumDeviceSources measured +0.000 threads and +0.000 handles per call
    over 40 calls (1.2 ms median), against the DirectShow enumeration's
    +0.924 / +95.3 per call at 41.8 ms in the same harness. So a named camera
    reaches a true zero, which is the thing
    _resolve_webcam_indices_by_name()'s own comment says a gate could never
    do. The DirectShow name list is fetched ONLY as the fallback for an
    unnamed index, and only through the gated accessor."""
    if _camera_backend is None:      # pragma: no cover - defensive
        # core/camera_backend.py failed to import. Degrade to exactly what this
        # code did before it existed rather than to no cameras at all: a raw
        # DirectShow open at the configured index. That leaks, and it is still
        # better than a rig whose face tracker cannot see.
        try:
            cap = cv2.VideoCapture(int(idx), cv2.CAP_DSHOW)
            if cap.isOpened():
                if width and height:
                    try:
                        cap.set(cv2.CAP_PROP_FRAME_WIDTH, int(width))
                        cap.set(cv2.CAP_PROP_FRAME_HEIGHT, int(height))
                        cap.set(cv2.CAP_PROP_BUFFERSIZE, 1)
                    except Exception:
                        pass
                return cap
            _release_on_current_camera_lock(cap)
        except Exception:
            logging.exception("[camera] fallback DirectShow open failed for "
                              "index %s", idx)
        return None
    open_idx, backend, why = _camera_backend.resolve_capture_target(
        idx, name=name, dshow_names=None)
    if (backend != "msmf"
            and not name
            and _camera_backend.configured_backend() == "msmf"
            and _camera_backend.msmf_device_names() is not None):
        # Media Foundation IS available; we just cannot map a BARE index to it
        # without knowing the DirectShow device names. Pay for the gated (and
        # therefore leaky) enumeration only here, and only for an index with no
        # configured name — the index sweeps.
        #
        # `not name` is load-bearing, not an optimisation. A name that failed
        # to match Media Foundation has already answered the question: the
        # DirectShow list could only help by matching some OTHER device's
        # friendly name at that index, which is precisely the wrong-camera
        # outcome this whole module exists to prevent. Falling back to
        # DirectShow at the configured index is what the code did before and
        # is the honest answer. It also keeps the leaky enumeration out of the
        # per-composite tile path, where a sick camera would otherwise buy one
        # per self-heal floor on a SECOND cache.
        names = _dshow_input_devices_gated(_dshow_open_devices_cache)
        if names:
            open_idx, backend, why = _camera_backend.resolve_capture_target(
                idx, name=name, dshow_names=names)
    # QUEUED, not printed and not logged. This runs on the throwaway open
    # worker, which may not narrate itself; and logging goes nowhere in the
    # daemon. See _drain_camera_backend_notes, which a joiner calls.
    # `label` is the CALL SITE, and it is in the key on purpose: without it the
    # second and every later opener of a camera is silent for the life of the
    # process, which is how a boot-time contender stayed invisible for eight
    # restarts. See _camera_backend_notes.
    key = (idx, name, label)
    if _camera_backend_notes.get(key) != (open_idx, backend):
        _camera_backend_notes[key] = (open_idx, backend)
        _camera_backend_pending.append(
            f"  [camera] {label or ('index ' + str(idx))}: opening with "
            f"{backend.upper()} at index {open_idx} — {why}")
    # cv2_mod=cv2 hands the shared opener THIS module's cv2 reference rather
    # than letting it import its own. That is what makes a monolith-level cv2
    # substitution (the audit harness's stub, and every test that patches
    # bc.cv2.VideoCapture) actually reach the open — without it the opener
    # silently used the real cv2 and the substitution recorded nothing.
    # release_hook: this runs on the throwaway open worker, which may be
    # abandoned and have its camera I/O lock RETIRED under it. Every failure
    # path inside open_camera (refused open, retry, frameless handle) must
    # therefore release through the CURRENT lock object rather than bare, or a
    # late release from an abandoned worker overlaps live camera I/O — the
    # 0xc0000374 heap corruption this whole locking scheme exists to prevent.
    return _camera_backend.open_camera(
        open_idx, backend=backend, width=width, height=height,
        require_frame=require_frame, cv2_mod=cv2,
        release_hook=_release_on_current_camera_lock,
        log=_camera_backend_pending.append)


def _resolve_webcam_indices_by_name() -> dict[str, int]:
    """Map 'left'/'right' → the DirectShow device INDEX whose friendly name
    contains the configured substring, via pygrabber. Cached after the first
    successful enumeration. Returns {} if pygrabber is unavailable or no name
    matched (the compositor then falls back to the configured CAMERAS indices).

    pygrabber's FilterGraph.get_input_devices() returns device friendly names in
    the SAME order as their cv2/DirectShow index, so the list position IS the
    index used by cv2.VideoCapture(idx, CAP_DSHOW).

    TTL, NOT FOREVER (2026-07-14 audit): the mapping used to be resolved once
    and cached for the whole process lifetime. DirectShow indices RE-SHUFFLE
    whenever a device joins or leaves the bus (the Kinect dropping off has
    reshuffled this rig repeatedly), so a permanently-cached index later points
    at a DIFFERENT device — the tile would happily open and display the Kinect's
    colour stream under the 'left webcam' label, with no error anywhere. Re-
    resolve every _WEBCAM_IDX_TTL_SEC, and let a failed tile read invalidate the
    cache immediately (see _invalidate_side_tile_indices)."""
    now = time.time()
    # Throttled amplifier accounting. Here rather than in the tile loop
    # because this is the function the amplifier actually costs something
    # in, and it is reached only when a slot is NOT being served from the
    # face-track loop's cache - i.e. only when there is something to say.
    _report_side_tile_amplifier(now)
    if (_kinect_preview_webcam_resolved[0]
            and (now - _kinect_preview_webcam_resolved_at[0]) < _WEBCAM_IDX_TTL_SEC):
        _side_tile_gate_counts["ttl_cached"] += 1
        return _kinect_preview_webcam_idx
    # The TTL has expired -- but expiry alone is NOT a reason to re-enumerate.
    # _enumerate_dshow_input_devices() leaks a thread and 103 handles every time
    # (see the block above _setupapi_camera_instances), so on a bus that has not
    # changed we were paying that 6x a minute forever to re-learn the same map.
    # Ask the free probe first: if the device set is byte-identical to the one
    # the cached mapping was built from, the indices cannot have reshuffled, so
    # just slide the TTL forward and reuse the cache. A None fingerprint means
    # the probe could not tell, and we fall through to the real enumeration --
    # degrading to the old behaviour rather than trusting a stale index.
    # NOTE this deliberately keys off the FINGERPRINT, not the resolved flag, so
    # it also covers the forced-invalidation path. _invalidate_side_tile_indices()
    # clears the resolved flag on every failed side-tile read, which used to mean
    # a sick camera re-enumerated PER FRAME instead of per 10 s — and that is the
    # amplifier that killed v2.0.100 (a wedged camera, ~4 enumerations per retry
    # cycle: 1 to re-resolve + 3 more inside the CAP_DSHOW reopen). But a failed
    # read only justifies re-resolving if the device set actually MOVED, and an
    # unchanged fingerprint proves it did not: the index is still correct and the
    # camera is failing for some other reason (sick device, USB power, wedged
    # driver), none of which re-enumeration can fix. So: same devices, same map.
    #
    # ...WITH A SELF-HEAL FLOOR, whose length depends on how good the
    # fingerprint we are holding actually is.
    #
    # A device-SET fingerprint has one hole, and it is a nasty one: the set is
    # sampled only every _WEBCAM_IDX_TTL_SEC, so a device that leaves and
    # REJOINS between two samples reshuffles the DirectShow order while leaving
    # the set byte-identical (the Kinect does exactly this on this rig -- its
    # measured arrival stamp was 4h35m after the other two cameras' in the same
    # boot). Nothing catches that: the reads still SUCCEED, they just come from
    # the wrong camera, so the failed-read backstop never fires either. The old
    # code self-healed within 10 s only because it re-resolved unconditionally;
    # a pure set-fingerprint gate would stay wrong FOREVER, which is a worse bug
    # than the leak it fixes.
    #
    # So the PnP half of the fingerprint carries DEVPKEY_Device_LastArrivalDate
    # (see _setupapi_camera_instances, which also records the experiment that
    # actually observed that stamp advancing across a removal + re-arrival of
    # the same instance). That makes a leave+rejoin visible even when it is only
    # observed afterwards -- closing the hole rather than time-boxing it. The
    # REMOVAL stamp is NOT carried and is no part of this: Windows clears it
    # when the device returns, so a DIGCF_PRESENT probe can never see one.
    # When that holds (_fingerprint_sees_rejoin), the unconditional
    # re-enumeration stops being the correctness mechanism and becomes a pure
    # safety net for unknown-unknowns, so it can be an hour apart instead of
    # five minutes. When it does NOT hold -- CM_Get_DevNode_PropertyW failed, or
    # the probe returned no PnP devices at all and so proves nothing -- we fall
    # back to the short floor and keep paying for it.
    #
    # BE HONEST ABOUT THE NUMBER: this is a reduction, not zero. 3600 s is still
    # 1 leaked thread + 103 handles per hour (24 threads/day, ~2,500 handles/day)
    # against 6.0/min = 8,640/day unpatched. It is ~356x, not infinite. The only
    # way to reach a true zero here is to stop calling the leaky API at all,
    # which means not sourcing indices from DirectShow -- and DirectShow order is
    # the one thing cv2.VideoCapture(idx, CAP_DSHOW) indexes by, so that is a
    # capture-backend change, not a leak fix.
    floor = (_WEBCAM_IDX_SELFHEAL_STAMPED_SEC
             if _fingerprint_sees_rejoin(_kinect_preview_webcam_fingerprint[0])
             else _WEBCAM_IDX_SELFHEAL_SEC)
    if (now - _kinect_preview_webcam_enumerated_at[0]) >= floor:
        pass                    # fall through to the real enumeration below
    else:
        held = _kinect_preview_webcam_fingerprint[0]
        fp = _video_device_fingerprint() if held is not None else None
        if fp is not None and fp == held:
            _side_tile_gate_counts["suppressed"] += 1
            _kinect_preview_webcam_resolved[0] = True
            _kinect_preview_webcam_resolved_at[0] = now
            return _kinect_preview_webcam_idx
        # RATE FLOOR ON THE FORCED PATH (2026-09-06, measured).
        #
        # There are exactly three ways to reach the leaky enumeration below:
        #   (a) the self-heal floor expired      -- already rate-limited, >=300 s
        #   (b) the fingerprint CHANGED          -- a real bus event, rare
        #   (c) the fingerprint is UNREADABLE    -- "could not tell"
        # (a) and (b) are bounded by physics. (c) is not, and (c) is the one the
        # amplifier multiplies: _invalidate_side_tile_indices() clears the
        # resolved flag on EVERY failed side-tile read, so the TTL early-return
        # above never fires and a sick camera arrives here 4x/second forever.
        #
        # MEASURED 2026-09-06, real COM, real leaky enumeration, threads counted
        # by Win32 start address inside mfksproxy.dll:
        #   3.0 min  fingerprint None, amplifier quiet
        #                                         6.00 enum/min   +664 hnd/min
        #   3.0 min  fingerprint None, amplifier at 4 Hz
        #                                       208.13 enum/min +19,259 hnd/min
        #   8.5 min  same, confirmation run    200.21 enum/min +18,340 hnd/min
        #  25.0 min  fingerprint None, amplifier at 4 Hz, WITH this floor
        #            (5,916 firings)              5.96 enum/min    +566 hnd/min
        #  35.0 min  gate HEALTHY, amplifier at 4 Hz (8,320 firings)
        #                                        0.029 enum/min      +7 hnd/min
        # The unfloored degraded arms reach the v2.0.100 death numbers (14,507
        # threads / 1,419,190 handles) in 74-82 minutes; the floored one lands
        # on the 6.00/min the alarm block already claims for the quiet case,
        # i.e. the amplifier stops being a multiplier. The HEALTHY row is the
        # one the 2026-09-06 sick-camera soak was reported as having measured
        # and had not: 8,320 forced re-resolves, one enumeration. The module's own alarm block called
        # the degraded state "+6 OS threads and +618 handles per MINUTE"; under
        # the amplifier it was 31x that, and nothing in either soak leg of
        # 2026-09-06 could have told the two apart: the sick camera healed
        # partway through, and NEITHER leg counted invalidations at all (these
        # counters did not exist yet), so how often the amplifier fired in
        # them is not knowable from the artifacts - only that the right tile
        # kept republishing live content every ~0.24 s with 3 gaps over 1 s in
        # 23,465 writes, and that both legs logged the identical 6 camera
        # read-failure/reopen events.
        #
        # So: a forced invalidation may still bypass the TTL -- but only ONCE
        # per _WEBCAM_IDX_TTL_SEC. The first failed read after a quiet window
        # still re-resolves immediately, which is the whole point of the
        # 2026-07-14 invalidation; the 39 that follow it inside the same 10 s
        # reuse the map. That is not a new staleness risk: 10 s is precisely the
        # window _WEBCAM_IDX_TTL_SEC already defines as acceptable for this map,
        # so the forced path is being held to the bound the timed path has had
        # since the beginning, instead of being exempt from it.
        #
        # DELIBERATELY NOT MIRRORED into _dshow_input_devices_gated(). That gate
        # is reached from the face-track reopen branch at
        # CAMERA_REOPEN_BACKOFF_SEC (2 s), so fully degraded it is <=30/min --
        # bounded, and test_unreadable_fingerprint_degrades_to_enumerating_
        # every_time pins "enumerate on every attempt" there on purpose. Only
        # this resolver has a per-frame amplifier behind it.
        if (held is None or fp is None) and (
                now - _kinect_preview_webcam_enumerated_at[0]
                ) < _WEBCAM_IDX_TTL_SEC:
            _side_tile_gate_counts["ttl_floored"] += 1
            _kinect_preview_webcam_resolved[0] = True
            _kinect_preview_webcam_resolved_at[0] = now
            return _kinect_preview_webcam_idx
    # Stamp the fingerprint we are about to resolve AGAINST, before enumerating.
    # Taking it first means a device that arrives *during* the enumeration
    # leaves us with a stale fingerprint and we re-resolve on the next tick —
    # the safe direction. Taking it after would record the new device set
    # against an index map built without it, and we would never re-resolve.
    _kinect_preview_webcam_fingerprint[0] = _video_device_fingerprint()
    _kinect_preview_webcam_enumerated_at[0] = now
    names = _enumerate_dshow_input_devices()
    if names is not None:
        # COUNT ONLY WHAT LEAKED. `names is None` means the enumeration
        # failed at the pygrabber IMPORT and never reached
        # CreateClassEnumerator, so nothing leaked - counting it would
        # inflate the exact number this accounting exists to keep honest.
        _side_tile_gate_counts["enumerations"] += 1
    # ALARM if the fingerprint we just stamped is None: the gate cannot fire
    # against it, so this leaky enumeration will repeat every TTL tick forever.
    # It has to be HERE and not at the probe — `names` is what separates "the
    # gate failed open and we are leaking again" (names present: the leaky call
    # ran) from "pygrabber is simply absent" (names None: the call failed at the
    # import and leaked nothing). See _report_video_fingerprint_gate.
    _report_video_fingerprint_gate(_kinect_preview_webcam_fingerprint[0],
                                   names, now)
    if names is None:
        # pygrabber missing / COM hiccup — mark resolved so we don't retry every
        # frame; the caller falls back to the CAMERAS-config indices.
        #
        # But DROP the fingerprint we just stamped. It was recorded as "the
        # device set this index map was built from", and there is no index map:
        # keeping it would let the gate above suppress every retry for a whole
        # self-heal period (up to an hour) on the strength of one COM hiccup.
        # Clearing it costs nothing in the permanent case — when pygrabber is
        # genuinely missing, _enumerate_dshow_input_devices() fails at the
        # IMPORT and never reaches the leaky call, so retrying on the 10 s TTL
        # leaks nothing — and in the transient case retrying is exactly right.
        _kinect_preview_webcam_fingerprint[0] = None
        _kinect_preview_webcam_resolved[0] = True
        _kinect_preview_webcam_resolved_at[0] = now
        return _kinect_preview_webcam_idx
    lowered = [(i, (n or "").lower()) for i, n in enumerate(names)]
    resolved: dict[str, int] = {}
    for slot, needle in _kinect_preview_webcam_names().items():
        for i, n in lowered:
            if needle in n:
                resolved[slot] = i
                break
    changed = resolved != _kinect_preview_webcam_idx
    _kinect_preview_webcam_idx.clear()
    _kinect_preview_webcam_idx.update(resolved)
    _kinect_preview_webcam_resolved[0] = True
    _kinect_preview_webcam_resolved_at[0] = now
    if _kinect_preview_webcam_idx and changed:
        print(f"  [kinect-preview] webcam tiles resolved by name: "
              f"{_kinect_preview_webcam_idx}")
    return _kinect_preview_webcam_idx


# Throttle for the producer-owned decline line: [last_printed_at, suppressed].
# One line per slot would be one line per composite (~4 Hz) without this.
_tile_open_declined_note = {"left": [0.0, 0], "right": [0.0, 0]}
_TILE_OPEN_DECLINED_NOTE_GAP_S = 300.0


def _note_tile_open_declined(slot: str, now: float) -> bool:
    """Say (throttled, per slot) that a side-tile open was DECLINED because the
    producer holds that camera. Returns True when it printed. NEVER raises.

    This is the line the DECLINE gets. It is not a substitute for the open note
    and does not depend on it: _camera_open() now keys _camera_backend_notes by
    (index, name, LABEL), so a tile open would announce itself as "side tile
    index N" — but through the eight boots this gate exists for the key was
    (index, name) only, and the tile's name comes from
    _kinect_preview_webcam_names(), which is derived from CAMERAS, i.e. the SAME
    (index, name) the producer had already opened with. The second open
    therefore printed NOTHING, and eight boots of right-camera read failures
    were attributed to the 30-minute self-diagnostic sweep — which the sweep
    timestamps in data/self_diagnostic.json flatly contradict (the nearest sweep
    was 37-44 s LATER, every time). An open that is now visible is still an open
    that must not happen; this line says it did not.

    Silent about the healthy steady state — where it never fires at all — and
    loud exactly once per five minutes while it is firing."""
    try:
        note = _tile_open_declined_note.get(slot)
        if note is None:
            return False
        note[1] += 1
        if note[0] > 0.0 and (now - note[0]) < _TILE_OPEN_DECLINED_NOTE_GAP_S:
            return False
        n, note[0], note[1] = note[1], now, 0
        print(f"  [kinect-preview] {slot} tile: declined {n} own-handle open(s) "
              f"— the face-track producer holds this camera. A second "
              f"in-process handle measured 98.6-99.5% producer read failures "
              f"and the producer did NOT recover when it was released. The "
              f"tile shows the producer's cached frame (or the off panel past "
              f"{_TILE_PRODUCER_OWNED_MAX_AGE:.0f}s) instead.")
        return True
    except Exception:
        return False


def _invalidate_side_tile_indices() -> None:
    """Force the next _resolve_webcam_indices_by_name() to re-enumerate.
    Called when a side-tile read fails: the most likely cause is a bus
    re-enumeration that moved the device, and re-resolving by NAME is exactly
    how we find it again. Never raises.

    COUNTED (2026-09-06): this is THE amplifier, and it used to leave no
    trace at all - which is how a soak came to report "measured under the
    full amplifier condition" for a run in which this function was never
    called once. ``get_side_tile_gate_stats()['invalidations'] == 0`` now
    says so."""
    try:
        _side_tile_gate_counts["invalidations"] += 1
        _kinect_preview_webcam_resolved[0] = False
        _kinect_preview_webcam_resolved_at[0] = 0.0
    except Exception:
        pass


def _hud_kinect_skeleton_overlay_enabled() -> bool:
    """True iff the Kinect skeleton overlay should drive the HUD preview: the
    KINECT_SKELETON_OVERLAY_ENABLED flag AND KINECT_ENABLED, read live from
    core.config so a Settings flip takes effect with no restart. With the Kinect
    off the overlay can't stream a frame, so we don't even try."""
    try:
        import core.config as _cfg
        return bool(getattr(_cfg, "KINECT_SKELETON_OVERLAY_ENABLED", False)
                    and getattr(_cfg, "KINECT_ENABLED", False))
    except Exception:
        return False


def _air_mouse_state_for_preview() -> dict:
    """The live air-mouse {'engaged': bool, 'grip': str} from the loaded
    air-mouse skill, for the preview hand circle (B2). Reads the skill's
    thread-safe getter via sys.modules; returns a disengaged default when the
    skill isn't loaded / readable. NEVER raises."""
    try:
        sk = sys.modules.get("skill_kinect_air_mouse")
        getter = getattr(sk, "get_air_mouse_state", None) if sk else None
        if callable(getter):
            st = getter()
            if isinstance(st, dict):
                return st
    except Exception:
        pass
    return {"engaged": False, "grip": "open"}


def _draw_hand_circle_on_color(color_bgr: "np.ndarray",
                               points: dict) -> bool:
    """Draw the ONE bright air-mouse hand circle around the CONTROLLING (cursor)
    hand joint (B2), coloured by the LIVE air-mouse state: BLUE when engaged
    (cursor active / open hand), ORANGE when the hand is closed (left-click/drag).
    Returns True iff a circle was drawn. NEVER raises.

    TWO-HAND DISAMBIGUATION FIX: the bright ring is drawn ONLY when the air-mouse
    is actually ENGAGED *and* publishes a real controlling side ("left"/"right"),
    on THAT side's hand specifically (controlling_hand_point with fallback=False).
    This removes the old grey idle ring that, when disengaged, fell back to the
    default order and ALWAYS landed on the right hand — which made a disengaged /
    frozen-preview state masquerade as "the right hand is still controlling", and
    with both hands up read as two co-equal cursor circles. Disengaged ⇒ NO bright
    ring at all (the non-controlling hand instead gets a faint subordinate dot,
    drawn by _draw_skeleton_on_color). The faint marker on the OTHER hand lives in
    the skeleton drawer so there is exactly one bright ring + one faint dot, never
    two equal rings.

    Geometry + colour come from the pure helpers (audio.kinect_skeleton +
    skills/kinect_air_mouse.hand_circle_color_for) so the preview and the unit
    tests share one contract; this is only the cv2 alpha-blended stroking."""
    try:
        from audio import kinect_skeleton as _ks
    except Exception:
        return False
    state = _air_mouse_state_for_preview()
    engaged = bool(state.get("engaged"))
    grip = str(state.get("grip", "open"))
    side = state.get("hand")
    # ONE bright ring, ONLY while engaged with a real controlling side. Disengaged
    # / no side → draw nothing here (no arbitrary idle ring on the right hand).
    if not engaged or side not in ("left", "right"):
        return False
    # Require the controlling side's hand/wrist to project (fallback=False) — never
    # ring an arbitrary hand if the controlling side didn't project this frame.
    pt = _ks.controlling_hand_point(points, prefer_side=side, fallback=False)
    if pt is None:
        return False
    sk = sys.modules.get("skill_kinect_air_mouse")
    color_fn = getattr(sk, "hand_circle_color_for", None) if sk else None
    if callable(color_fn):
        color = color_fn(engaged, grip)
    else:   # pragma: no cover - skill always loaded in the live HUD
        color = (255, 160, 32)
    alpha = 0.55                            # translucent bright ring
    radius = _ks.hand_circle_radius(color_bgr.shape[1])
    try:
        cx, cy = int(pt[0]), int(pt[1])
        overlay = color_bgr.copy()
        # Filled translucent disc + a crisper ring so it reads at thumbnail size.
        cv2.circle(overlay, (cx, cy), radius, color, -1, lineType=cv2.LINE_AA)
        cv2.addWeighted(overlay, alpha, color_bgr, 1.0 - alpha, 0.0, color_bgr)
        cv2.circle(color_bgr, (cx, cy), radius, color, 3, lineType=cv2.LINE_AA)
    except Exception:
        return False
    return True


def _draw_skeleton_on_color(color_bgr: "np.ndarray", bodies: list) -> int:
    """Draw the tracked skeleton(s) over a Kinect COLOR frame IN PLACE: a line
    along every bone whose endpoints projected, a filled dot at every projected
    joint, and (B2) the translucent air-mouse hand circle around the controlling
    hand, coloured by the live air-mouse state. Returns the number of bodies
    actually drawn (>=1 means the body stream is live — the owner's diagnostic).

    Projection uses audio.kinect_skeleton.project_body_joints fed the bridge's
    color-space mapper (kinect_bridge.get_color_space_mapper). All pykinect2
    contact is inside the bridge; the geometry is the pure helper; this function
    is only the cv2 stroking. NEVER raises into the caller — any failure draws
    nothing and returns 0."""
    try:
        from audio import kinect_skeleton as _ks
    except Exception:
        return 0
    mapper = _kinect_bridge.get_color_space_mapper()
    if mapper is None or not bodies:
        return 0
    drawn = 0
    # P2-6: project against the ACTUAL canvas size, not the hardcoded 1920×1080
    # in kinect_skeleton. The base may be an IR frame upscaled to a different size,
    # or a resized color frame — passing base.shape gives project_body_joints the
    # real on-frame bounds so its off-frame margin matches THIS canvas. numpy
    # shape is (height, width); pass them through by keyword.
    try:
        canvas_h, canvas_w = color_bgr.shape[:2]
    except Exception:
        canvas_h, canvas_w = _ks.COLOR_H, _ks.COLOR_W
    # Stark cyan to match the HUD; joints a brighter accent; bones a touch thick
    # so they read on a 240px-wide downscaled preview.
    bone_col = (255, 201, 76)     # BGR of #4cc9ff-ish (cyan)
    joint_col = (160, 231, 255)   # BGR brighter cyan/white
    # TWO-HAND DISAMBIGUATION: when the air-mouse is engaged with a known
    # controlling side, the NON-controlling hand joint is drawn as a smaller,
    # dimmer dot (a thin hollow ring) instead of an equal filled cyan dot, so the
    # owner sees ONE bright ring (the controlling hand, drawn by
    # _draw_hand_circle_on_color) + ONE faint dot (the other hand) — never two
    # equal circles. The controlling hand's own joint keeps the normal dot under
    # the bright ring. Read the live which-hand once for this frame.
    am_state = _air_mouse_state_for_preview()
    am_engaged = bool(am_state.get("engaged"))
    ctrl_side = am_state.get("hand") if am_engaged else None
    other_hand_joint = (f"hand_{'left' if ctrl_side == 'right' else 'right'}"
                        if ctrl_side in ("left", "right") else None)
    other_dot_col = (150, 150, 150)   # desaturated/dim grey for the idle hand
    first_points = None
    for body in bodies:
        try:
            joints = body.get("joints") if isinstance(body, dict) else None
            if not joints:
                continue
            points = _ks.project_body_joints(joints, mapper,
                                             width=canvas_w, height=canvas_h)
            if not points:
                continue
            is_first = first_points is None
            if is_first:
                first_points = points     # hand circle tracks the nearest body
            for (x1, y1), (x2, y2) in _ks.iter_bone_segments(points):
                cv2.line(color_bgr, (x1, y1), (x2, y2), bone_col, 4,
                         lineType=cv2.LINE_AA)
            for name, (px, py) in points.items():
                # Only the NEAREST (first) body's non-controlling hand is made
                # subordinate (it's the one the air-mouse reasons about).
                if (is_first and other_hand_joint is not None
                        and name == other_hand_joint):
                    # Smaller, dim, HOLLOW ring — visually subordinate to the
                    # bright controlling ring so two hands up never read as equal.
                    cv2.circle(color_bgr, (px, py), 5, other_dot_col, 1,
                               lineType=cv2.LINE_AA)
                else:
                    cv2.circle(color_bgr, (px, py), 7, joint_col, -1,
                               lineType=cv2.LINE_AA)
            drawn += 1
        except Exception:
            continue
    # B2: the air-mouse hand circle, on the FIRST (nearest) drawn body's hand.
    if first_points is not None:
        try:
            _draw_hand_circle_on_color(color_bgr, first_points)
        except Exception:
            pass
    return drawn


def _last_gesture_for_preview() -> dict:
    """The last-fired-gesture {'gesture','label','ts'} from the loaded gesture
    skill, for the preview pop badge (B3). Reads the skill's thread-safe getter
    via sys.modules; returns an empty default when the skill isn't loaded.
    NEVER raises."""
    try:
        sk = sys.modules.get("skill_kinect_gestures")
        getter = getattr(sk, "get_last_gesture", None) if sk else None
        if callable(getter):
            st = getter()
            if isinstance(st, dict):
                return st
    except Exception:
        pass
    return {"gesture": None, "label": "", "ts": 0.0}


def _draw_gesture_pop_on_color(color_bgr: "np.ndarray", now: float) -> bool:
    """Draw a brief glowing labelled badge near the top of the Kinect color frame
    when a gesture just fired (B3), fading out over ~1 s. Returns True iff a badge
    was drawn. NEVER raises.

    The gesture name + fired-timestamp + the fade curve come from the gesture
    skill's pure helpers (get_last_gesture / gesture_pop_alpha) so the preview and
    the test share one fade contract. The badge timestamp is time.monotonic, so
    `now` here MUST also be monotonic for the fade to be correct."""
    try:
        sk = sys.modules.get("skill_kinect_gestures")
        if sk is None:
            return False
        state = _last_gesture_for_preview()
        label = str(state.get("label") or "")
        fired_at = float(state.get("ts") or 0.0)
        if not label or fired_at <= 0.0:
            return False
        alpha_fn = getattr(sk, "gesture_pop_alpha", None)
        if not callable(alpha_fn):
            return False
        # `now` is monotonic to match the skill's fired-at clock; if the caller
        # passed a wall-clock `now` the fade still degrades gracefully (a stale
        # badge just reads alpha 0 once it ages out).
        alpha = float(alpha_fn(time.monotonic(), fired_at))
        if alpha <= 0.0:
            return False
    except Exception:
        return False
    try:
        from audio import kinect_skeleton as _ks
        h, w = color_bgr.shape[:2]
        font = cv2.FONT_HERSHEY_SIMPLEX
        scale = max(0.8, w / 1280.0)            # scale text to the frame
        thick = max(2, int(round(scale * 2)))
        (tw, th), base_ln = cv2.getTextSize(label, font, scale, thick)
        pad = int(round(12 * scale))
        # Centred horizontally, near the top so it doesn't cover the torso.
        bx = max(0, (w - tw) // 2 - pad)
        by = max(0, int(round(h * 0.06)))
        bw = tw + 2 * pad
        bh = th + base_ln + 2 * pad
        # A glowing amber badge: translucent dark plate + amber border + text,
        # all alpha-scaled by the fade so it dissolves out.
        plate = (20, 20, 20)
        amber = (40, 200, 255)                  # BGR ≈ glowing amber/yellow
        overlay = color_bgr.copy()
        cv2.rectangle(overlay, (bx, by), (bx + bw, by + bh), plate, -1)
        cv2.rectangle(overlay, (bx, by), (bx + bw, by + bh), amber,
                      max(2, thick), lineType=cv2.LINE_AA)
        cv2.putText(overlay, label, (bx + pad, by + pad + th), font, scale,
                    amber, thick, lineType=cv2.LINE_AA)
        cv2.addWeighted(overlay, alpha, color_bgr, 1.0 - alpha, 0.0, color_bgr)
    except Exception:
        return False
    return True


# ── B1: REAL side-tile webcams (own lightweight capture, NOT the Kinect) ─────
# The two side tiles must show the actual USB WEBCAMS — 'Fullhan Webcam' (LEFT)
# and 'USB 2.0 Camera' (RIGHT) — NOT a duplicate of the Kinect. The owner's rig
# runs face-tracking ON the Kinect, so _camera_latest_frame is the KINECT frame;
# reusing it (the old behaviour) made both side tiles mirror the Kinect. Instead
# we open those two webcams DIRECTLY here at a low rate, cache the last good
# frame per slot, and hand them to the compositor. If a webcam can't open (off /
# covered / unplugged) the slot yields None and the compositor draws a dim
# 'off' PLACEHOLDER — never the Kinect frame.
#
# Persistent VideoCapture handles (opened lazily, reused) read at ~4 Hz: that's
# plenty for a context thumbnail and avoids DirectShow's expensive per-read
# open/close churn. open/release go through _camera_io_lock (the same
# heap-corruption guard the face-tracker uses); the per-handle READ is
# deliberately lock-free so a wedged webcam can't stall all camera I/O — see
# _read_side_tile_webcams. Tiny labels resolve the tiles.
_KINECT_PREVIEW_TILE_LABELS = {
    "left":  "Left webcam",      # 'Fullhan Webcam'  → LEFT monitor
    "right": "Right webcam",     # 'USB 2.0 Camera'  → RIGHT monitor
}
# How often a side-tile webcam is actually re-read (seconds). A thumbnail doesn't
# need full frame-rate; ~4 Hz keeps the tiles live without loading the USB bus.
_KINECT_PREVIEW_TILE_READ_INTERVAL = 0.25
# Persistent per-slot capture handles + last good frame + last-read timestamps.
# slot → cv2.VideoCapture | None ; slot → frame | None ; slot → ts.
_kinect_tile_caps: dict = {"left": None, "right": None}
_kinect_tile_frames: dict = {"left": None, "right": None}
_kinect_tile_last_read: dict = {"left": 0.0, "right": 0.0}
_kinect_tile_lock = threading.Lock()
# Tracks whether the side-tile webcams are currently held open, so the preview
# writer releases them exactly once on the overlay's on→off transition.
_kinect_preview_tiles_open = [False]


# How long a side-tile open waits for a REAL frame before giving up. Short:
# a tile is a thumbnail, the compositor has a placeholder, and the slot is
# retried on the next composite anyway.
# How long a side-tile open waits for a REAL frame before giving up.
#
# SIZED AGAINST _CAMERA_OPEN_TIMEOUT_S (4.0 s), which bounds the whole tile
# open, using measured numbers rather than a guess. Worst observed MSMF tile
# open: a transient open failure (0.04 s) + the 0.25 s retry sleep + a second
# open (0.68 s) + set(W)/set(H) (0.90 s) = 1.87 s, leaving ~2.1 s. The frame
# itself arrived 0.30-0.42 s after the sets in every measured cycle on both
# webcams, so 1.0 s is ~2.4x the observed worst case and still fits inside the
# bound with headroom. A tile that misses is a placeholder for one composite
# and is retried on the next, so the cheap direction is the right one.
_TILE_OPEN_FRAME_BUDGET_S = 1.0
# Same budget for the face-track producer's own open. Longer than the tile's:
# this handle is the one the whole loop runs on, and a camera that is merely
# warming up (documented at _probe_camera_index: ~2 s of False reads after a
# cold open) must not be thrown away as dead.
_LOOP_OPEN_FRAME_BUDGET_S = 2.5

# The resolution the face-track producer ACTUALLY requests for a CAMERAS entry.
# NAMED, because two call sites now have to agree on it: the producer itself,
# and list_cameras(), which recommends indices to paste into CAMERAS and must
# therefore prove them at THIS size rather than only at its own sweep
# resolution. Those are not the same question on this rig — measured
# 2026-09-06, JARVIS stopped, through core.camera_backend.open_camera: the
# Kinect V2 delivers 1920x1080 at 30.1 fps under Media Foundation and exactly
# 0 frames at 1280x720, 640x480, or with no resolution set (it falls back to
# 512x424 and then fails every read). A hardcoded duplicate here is precisely
# the stale-copy shape this codebase pays for most, so there is one copy.
_LOOP_OPEN_WIDTH = 1280
_LOOP_OPEN_HEIGHT = 720


def _open_tile_capture(idx: int, name: "str | None" = None) -> "cv2.VideoCapture | None":
    """Open a side-tile webcam at DirectShow index `idx`, modest 640×480 since
    it's only a thumbnail. Returns an opened capture or None. Serialised on
    _camera_io_lock (DirectShow heap-corrupts on overlapping open/release).
    NEVER raises.

    THIS IS WHERE THE PRODUCER DIED (measured 2026-09-05, py-spy, live PID).
    The thread sat forever on `cap.set(CAP_PROP_FRAME_HEIGHT, 480)` for a sick
    USB 2.0 webcam, INSIDE `with _camera_io_lock:`, so it published nothing for
    any camera - left, right and Kinect tiles all went dark - and, because a
    hang raises nothing, said not one word about it.

    Two guards, both cheap on the healthy path:
      * a QUARANTINED index is never opened at all (that is the only way to
        stop a known-sick device from finding this wedge again), and
      * the open itself is BOUNDED - it runs on a throwaway worker that owns
        the lock, and we walk away after _CAMERA_OPEN_TIMEOUT_S.
    The healthy path still performs exactly one open, as before - but since
    2026-09-05 that open goes through _camera_open(), which means Media
    Foundation and a translated index rather than DirectShow and a raw one.
    DirectShow cost +4.58 OS threads and +479 handles PER open/release cycle
    here (measured, 25 cycles, fresh process); MSMF cost -0.21 and +0.97."""
    if _camera_is_quarantined(idx):
        return None

    def _do_open():
        with _camera_io_lock:
            # require_frame: on MSMF a device another process holds reports
            # isOpened() True, accepts set(), reads the requested size back out
            # of get(), and then delivers nothing (measured 2026-09-05: 0 of 20
            # reads, against DirectShow's honest isOpened() == False). A tile
            # that holds such a handle would fail every read forever and feed
            # _invalidate_side_tile_indices - the amplifier that killed
            # v2.0.100. Proving a frame at open turns that into a placeholder,
            # which is what a busy camera looked like under DirectShow anyway.
            cap = _camera_open(idx, name=name, width=640, height=480,
                               require_frame=_TILE_OPEN_FRAME_BUDGET_S,
                               label=f"side tile index {idx}")
            if cap is None:
                return None
            return cap

    try:
        return _open_capture_bounded(idx, _do_open, label=f"side tile index {idx}")
    except Exception:
        logging.exception("[face-track] _open_tile_capture failed for index %s", idx)
        return None


# ── FAST PATH: reuse the face-track loop's frames, never re-open the device ──
# MEASURED LIVE 2026-09-04 (owner using the web dashboard) by watching the mtime
# of the four preview JPEGs. The loop's period is BURSTY, not steady:
#   * a 10 s window sat locked at 2.10 s per iteration = 0.48 fps per tile;
#   * a 30 s window averaged 1.93 fps, running at ~5 fps (200 ms iterations) and
#     then dropping into 0.5-1.0 s stalls;
#   * every stall is a BLOCKING webcam read - in the locked window, exactly two
#     ~1.00 s reads per iteration: one HERE (inside the composite) and one in the
#     loop itself. The frames they returned were genuinely new (7 file updates,
#     7 distinct images), so a read was waiting on a device delivering about
#     1 fps per open handle, not re-serving a frozen buffer.
# Either way the preview never reached the ~6.7 fps _HUD_CAM_PREVIEW_MIN_GAP
# allows, because the preview is published from inside this loop.
#
# This reader was opening a SECOND DirectShow graph — at 640x480 — on webcams the
# loop already holds open at 1280x720, and the loop ALREADY caches each camera's
# newest frame in _camera_latest_frame. The second open bought nothing while
# costing a whole blocking read per composite (35-70 ms in the good bursts, up to
# ~1.00 s in the bad ones), so it is removed here.
#
# HONEST LIMIT: whether the duplicate graph also CAUSED the slow reads is unproven
# — the other webcam (an eMeet C960) was double-opened too and read in ~0 ms.
# Removing the duplicate provably removes one read per composite; the read-timing
# warning added in _face_tracking_thread now names whichever camera is left
# gating the loop, which is the diagnostic that was missing all along.
#
# The 2026-07-10 rule that created this reader still holds and is ENFORCED below:
# a KINECT-backed slot must NEVER be reused (that is the bug that made both side
# tiles mirror the Kinect). Only real NAMED webcam entries qualify, and only while
# their cached frame is fresh — anything else falls through to the original
# open-and-read path, unchanged.
_KINECT_PREVIEW_TILE_REUSE_MAX_AGE = 2.0   # s; an older cache counts as absent

# ── THE SECOND IN-PROCESS OPENER (measured 2026-09-06) ───────────────────────
#
# The fast path above declines whenever the producer's cached frame is older
# than _KINECT_PREVIEW_TILE_REUSE_MAX_AGE, and the fallback under it then
# OPENED A SECOND HANDLE on a camera the producer is still holding and
# streaming. That is not a harmless duplicate. Measured in a clean room
# (JARVIS stopped, one process, both webcams, 3 cycles each, 12 s per phase,
# the real _camera_open shapes: producer 1280x720 require_frame=2.5, tile
# 640x480 require_frame=1.0):
#
#                       producer reads BEFORE   DURING     AFTER (tile released)
#   USB 2.0 Camera      208 ok /   0 fail       1 ok / 210 fail    0 ok / 239 fail
#   eMeet C960          211 ok /   0 fail       1 ok / 211 fail    0 ok / 239 fail
#
# Three findings, none of them optional:
#   1. The second MSMF open is GRANTED - it even satisfies require_frame, so
#      the "prove a frame at open" guard does not catch this case. The tile
#      gets the stream; the producer starves 98.6-99.5% of its reads.
#   2. RELEASING the tile handle does NOT give it back. The producer stayed at
#      0 ok / 239 fail for a further 12 s in every cycle; only a full
#      release+reopen recovers it - which is exactly the
#      "read failure #25 ... woke via release+reopen" pair in the session logs.
#   3. It is NOT a sick-camera effect. The healthy eMeet C960 died identically.
#      camera_backend's docstring measured contention CROSS-PROCESS ("both
#      backends leave the HOLDER undisturbed"); IN-PROCESS is the opposite.
#
# WHY IT ONLY EVER HIT THE RIGHT TILE. _read_side_tile_webcams runs from inside
# the PRIMARY camera's branch of the producer loop, immediately after the
# primary's frame is cached - so the primary slot's cache is 0 s old and always
# takes the fast path. The NON-primary camera is read AFTER the composite in
# the same iteration, so at composite time its cache is one whole loop period
# old, and on the first iteration it does not exist at all. On this rig the
# primary is the LEFT eMeet and the non-primary is the RIGHT USB 2.0 Camera,
# which is why 8 boots out of 8 - EVERY boot in the 2026-09-05 22:00 ->
# 2026-09-06 07:50 log window in which the producer actually held the right
# camera AND the tile had a right slot (22:38:43, 22:41:10, 23:20:21, 02:13:45,
# 02:23:17, 04:56:21, 06:01:36, 06:12:37) - logged a RIGHT read failure 7-13 s
# after "[kinect-preview] webcam tiles resolved by name", and not one of them
# had a self-diagnostic sweep before it: the nearest sweep was 37-44 s LATER.
#
# So: when the producer HOLDS the camera, the tile may never open its own
# handle. Its only honest source is the producer's cache, at whatever age that
# cache has. A duplicate open cannot help - it provably takes the stream away
# from the loop that needs it.
#
# The ceiling below is what stops a frozen thumbnail from being displayed as if
# it were live. It is sized above a full producer recovery (2.5 s open budget +
# up to one retry, plus the 25-fail / 2 s wake threshold) so a normal wake does
# not blink the tile to a placeholder, and well under a minute so a genuinely
# dead producer shows the "off" panel rather than a stale picture forever.
_TILE_PRODUCER_OWNED_MAX_AGE = 15.0        # s


def _producer_holds_side(slot: str) -> bool:
    """True iff the face-track producer currently HOLDS AN OPEN capture for the
    camera behind side-tile ``slot``.

    This is the whole precondition of the no-duplicate-open rule, and it is
    deliberately about the HANDLE, not about configuration: ``entry["cap"]`` is
    None for every state in which the producer has let go of a camera (open
    backoff, dead-after-N-fails, mid-reopen, quarantine bench, shutdown), and in
    exactly those states the tile opening its own handle is legitimate and is
    the only way the slot can show anything at all.

    NO RACE, AND NOT BY LUCK: _read_side_tile_webcams runs from inside
    _compose_kinect_preview, which runs from inside _hud_kinect_preview_write,
    which is called only from the producer loop itself. So the thread asking
    "does the producer hold this?" IS the producer, and it cannot be halfway
    through its own _open_capture while it is here. A caller on any OTHER thread
    would have to reckon with the window between _camera_open() returning and
    entry["cap"] being assigned, where this answers False for a camera that is
    about to be held — the unsafe direction.

    The handle/Kinect rules live in get_face_track_held_indices() and are NOT
    restated here — this is only the slot→index half. Two openers already
    needed this predicate independently (see that function), so a second copy
    of its reasoning is the stale duplicate waiting to happen. NEVER raises."""
    try:
        held = get_face_track_held_indices()
        if not held:
            return False
        for cam in CAMERAS:
            if not isinstance(cam, dict):
                continue
            if _percam_side(cam) != slot:
                continue
            if cam.get("index") in held:
                return True
    except Exception:
        pass
    return False


def _face_track_frame_for_slot(slot: str, now: float,
                               max_age: "float | None" = None):
    """Return the face-tracking loop's freshest frame for side-tile ``slot``
    ('left'/'right'), or None when there is none we are allowed to reuse.

    ``max_age`` overrides _KINECT_PREVIEW_TILE_REUSE_MAX_AGE. The caller passes
    the wider _TILE_PRODUCER_OWNED_MAX_AGE for a slot whose camera the producer
    is HOLDING, where a slightly stale cached frame is not a second-best option
    but the only frame that legitimately exists. NEVER raises."""
    ceiling = (_KINECT_PREVIEW_TILE_REUSE_MAX_AGE if max_age is None
               else float(max_age))
    try:
        for cam in CAMERAS:
            if not isinstance(cam, dict):
                continue
            cam_name = cam.get("name")
            # Kinect-backed slot (explicit type, or KINECT_AS_CAMERA hijacking an
            # UNNAMED entry — the same test _face_tracking_thread applies): its
            # cached frame is the KINECT, not this webcam. Never reuse it.
            if cam.get("type") == "kinect" or (KINECT_AS_CAMERA and not cam_name):
                continue
            if _percam_side(cam) != slot:
                continue
            idx = cam.get("index")
            # A benched camera has no live frame worth reusing, and letting the
            # fast path decline here would drop us into the OPEN fallback that
            # wedged the producer. Say "nothing" outright: the slot becomes a
            # placeholder and no DirectShow call is made for it at all.
            if _camera_is_quarantined(idx, now):
                return None
            with _camera_state_lock:
                frame = _camera_latest_frame.get(idx)
                seen_at = _camera_last_frame_at.get(idx, 0.0)
            if frame is None:
                return None
            if (now - seen_at) > ceiling:
                return None    # loop stalled/stopped -> fall back to our own read
            return frame
    except Exception:
        return None
    return None


def _read_side_tile_webcams(now: float) -> dict:
    """Read the two named side-tile WEBCAMS directly (throttled + cached) and
    return {'left': frame|None, 'right': frame|None}. A slot is None when its
    webcam name didn't resolve, the device won't open, or a read failed — the
    compositor then draws a dim placeholder for that slot (NEVER the Kinect).

    Opens persistent handles lazily and re-reads each only every
    _KINECT_PREVIEW_TILE_READ_INTERVAL seconds, returning the cached frame in
    between. A handle that starts failing is released so the next call re-opens
    it (so re-plugging / un-covering a webcam recovers without a restart).
    NEVER raises."""
    # Resolved LAZILY below: when both slots are served from the face-track
    # loop's cache we never need a DirectShow enumeration at all.
    name_idx: dict | None = None
    out: dict = {"left": None, "right": None}
    with _kinect_tile_lock:
        for slot in ("left", "right"):
            # FAST PATH (2026-09-04): the face-track loop already holds this
            # webcam open and has just cached its newest frame. Use that, and
            # release any duplicate handle we are still carrying — a second
            # graph on the same device costs a whole blocking read per
            # composite (measured ~1.00 s) and buys nothing.
            reused = _face_track_frame_for_slot(slot, now)
            if reused is not None:
                out[slot] = reused
                _kinect_tile_frames[slot] = reused
                _kinect_tile_last_read[slot] = now
                cap = _kinect_tile_caps.get(slot)
                if cap is not None:
                    _release_capture_guarded(cap, idx=f"tile/{slot}",
                                             label="side tile")
                    _kinect_tile_caps[slot] = None
                continue
            # PRODUCER-OWNED GATE (2026-09-06). The fast path just declined, and
            # before this gate existed that dropped straight into an open of a
            # camera the producer is STILL HOLDING. Measured: the second
            # in-process MSMF handle is granted, takes the stream, and leaves the
            # producer at 98.6-99.5% read failures — and releasing it does not
            # give the stream back, so the producer only recovers by
            # release+reopen. See _TILE_PRODUCER_OWNED_MAX_AGE for the numbers
            # and for why this fired once per boot on the NON-primary tile.
            #
            # So we never open. The producer's cache, at whatever age it has, is
            # the only honest source for this slot; past the ceiling the slot
            # goes to the placeholder rather than showing a frozen picture.
            if _producer_holds_side(slot):
                cap = _kinect_tile_caps.get(slot)
                if cap is not None:
                    # Nothing should be held here after this gate exists, but a
                    # handle opened before the producer (re)took the camera must
                    # not be left on the device.
                    _release_capture_guarded(cap, idx=f"tile/{slot}",
                                             label="side tile")
                    _kinect_tile_caps[slot] = None
                stale = _face_track_frame_for_slot(
                    slot, now, max_age=_TILE_PRODUCER_OWNED_MAX_AGE)
                out[slot] = stale
                _kinect_tile_frames[slot] = stale
                # COUNTED AT THE TILE-READ RATE, NOT THE COMPOSITE RATE. This
                # branch runs on every composite tick, but the code it replaces
                # only touched the device once per
                # _KINECT_PREVIEW_TILE_READ_INTERVAL — the throttle further down
                # served the cache in between. Counting every tick would
                # overstate what was prevented by the ratio of the two rates,
                # and this counter's whole job is to be quotable in a soak.
                if ((now - _kinect_tile_last_read.get(slot, 0.0))
                        >= _KINECT_PREVIEW_TILE_READ_INTERVAL):
                    _kinect_tile_last_read[slot] = now
                    _side_tile_gate_counts["producer_owned"] += 1
                    _note_tile_open_declined(slot, now)
                continue
            if name_idx is None:
                name_idx = _resolve_webcam_indices_by_name()
            idx = name_idx.get(slot)
            if idx is None:
                # No device of that name → no real webcam to show; drop any stale
                # handle/frame so the slot becomes a placeholder.
                cap = _kinect_tile_caps.get(slot)
                if cap is not None:
                    _release_capture_guarded(cap, idx=f"tile/{slot}",
                                             label="side tile")
                    _kinect_tile_caps[slot] = None
                _kinect_tile_frames[slot] = None
                continue
            # QUARANTINE GATE (2026-09-05). The producer wedged HERE, opening a
            # camera the face-track loop had already given up on: the fast path
            # declines the moment the loop's cached frame goes stale (2.0 s),
            # which is exactly when the camera is sick, so the fallback below
            # re-opened the wedging device on every composite. A benched camera
            # is not opened, not read and not released - its slot simply goes to
            # the placeholder, and the OTHER slot keeps publishing.
            if _camera_is_quarantined(idx, now):
                cap = _kinect_tile_caps.get(slot)
                if cap is not None:
                    _release_capture_guarded(cap, idx, f"side tile {slot}")
                    _kinect_tile_caps[slot] = None
                _kinect_tile_frames[slot] = None
                _kinect_tile_last_read[slot] = now
                continue
            # Throttle: reuse the cached frame between reads.
            if (now - _kinect_tile_last_read.get(slot, 0.0)
                    < _KINECT_PREVIEW_TILE_READ_INTERVAL):
                out[slot] = _kinect_tile_frames.get(slot)
                continue
            cap = _kinect_tile_caps.get(slot)
            if cap is None:
                cap = _open_tile_capture(
                    idx, name=_kinect_preview_webcam_names().get(slot))
                _kinect_tile_caps[slot] = cap
            if cap is None:
                _kinect_tile_frames[slot] = None      # → placeholder
                _kinect_tile_last_read[slot] = now
                continue
            ret, frame = False, None
            try:
                # Read on this slot's OWN handle — deliberately NOT under
                # _camera_io_lock. That lock exists to stop overlapping DirectShow
                # open/release (which heap-corrupt); a read neither opens nor
                # releases, and _kinect_tile_lock (held across this whole function)
                # already excludes a concurrent release of THIS handle. Holding
                # _camera_io_lock across a blocking cap.read() let one wedged webcam
                # stall every camera open/release across all threads — a
                # whole-subsystem hang (HIGH, 2026-07-08).
                ret, frame = cap.read()
            except Exception:
                ret, frame = False, None
            _kinect_tile_last_read[slot] = now
            if ret and frame is not None:
                _kinect_tile_frames[slot] = frame
                out[slot] = frame
            else:
                # Read failed — release so the next tick re-opens; placeholder now.
                _release_capture_guarded(cap, idx, f"side tile {slot}")
                _kinect_tile_caps[slot] = None
                _kinect_tile_frames[slot] = None
                # A failing read is the classic symptom of a bus re-enumeration
                # that MOVED the device. Invalidate the name→index memo so the
                # next tick re-resolves by NAME instead of re-opening whatever
                # now sits at the stale index (2026-07-14 audit).
                _invalidate_side_tile_indices()
    return out


def _release_side_tile_webcams() -> None:
    """Release both persistent side-tile capture handles (best-effort). Called
    when the overlay turns off so the webcams aren't held open needlessly."""
    with _kinect_tile_lock:
        for slot in ("left", "right"):
            cap = _kinect_tile_caps.get(slot)
            if cap is not None:
                # Guarded: this runs from inside the face-track loop, so a
                # blocking acquire here is another way to hang the producer.
                _release_capture_guarded(cap, idx=f"tile/{slot}",
                                         label="side tile")
            _kinect_tile_caps[slot] = None
            _kinect_tile_frames[slot] = None
            _kinect_tile_last_read[slot] = 0.0


def _release_side_tile_webcams_if_open() -> None:
    """Release the persistent side-tile webcam handles IFF they're currently
    marked open, then clear the open flag. Idempotent by design: it is safe to
    call every frame while in a composite-stopping state (camera_off /
    HUD-preview-disabled / overlay-off), because the flag guard makes the real
    release fire exactly once per open→closed edge. Extracted so BOTH the
    overlay-off edge in _hud_kinect_preview_write AND the camera-off / preview-
    disabled branch of the face-track loop release the tiles the same way —
    previously only the overlay edge did, so standby/low-mem leaked the handles.
    2026-07-08."""
    if _kinect_preview_tiles_open[0]:
        _release_side_tile_webcams()
        _kinect_preview_tiles_open[0] = False


def _placeholder_tile(label: str, w: int = 320, h: int = 240) -> "np.ndarray":
    """A dim placeholder tile for a side webcam that's off/covered/unavailable —
    a dark panel with a centred '<label> — off' caption. Drawn INSTEAD of the
    Kinect frame so the off-state is honest. Pure cv2/numpy."""
    tile = np.full((h, w, 3), 28, dtype=np.uint8)   # near-black panel
    text = f"{label} - off"
    try:
        font = cv2.FONT_HERSHEY_SIMPLEX
        scale = 0.5
        thick = 1
        (tw, th), _ = cv2.getTextSize(text, font, scale, thick)
        tx = max(4, (w - tw) // 2)
        ty = (h + th) // 2
        cv2.putText(tile, text, (tx, ty), font, scale, (140, 140, 140), thick,
                    lineType=cv2.LINE_AA)
    except Exception:
        pass
    return tile


# Throttled per-piece skip log for the Kinect preview (ISSUE 4). One failing
# overlay piece must NOT spam the console at frame-rate, but the owner should SEE
# that a piece was skipped (e.g. a webcam Teams has locked). We log each distinct
# piece-name at most once per _KINECT_PREVIEW_SKIP_LOG_INTERVAL seconds.
_KINECT_PREVIEW_SKIP_LOG_INTERVAL = 10.0
_kinect_preview_skip_log_last: dict = {}


def _kinect_preview_piece_skipped(piece: str) -> None:
    """Log (throttled) that one optional preview piece was skipped after throwing,
    so a locked webcam / overlay glitch is visible without blanking the preview or
    spamming. NEVER raises."""
    try:
        now = time.monotonic()
        last = _kinect_preview_skip_log_last.get(piece, 0.0)
        if (now - last) >= _KINECT_PREVIEW_SKIP_LOG_INTERVAL:
            _kinect_preview_skip_log_last[piece] = now
            print(f"  [kinect-preview] skipped '{piece}' (it threw) — preview "
                  "continues without it")
    except Exception:
        pass


# Last Kinect COLOR frame the compositor itself saw, so a transient color gap (a
# get_color_bgr(require_new=False) returning None right after a runtime reopen
# before color re-primes) can re-serve the last image instead of blanking the
# skeleton tile (the preview-keep-alive fix). Stored as a COPY so the bridge's
# buffer can't mutate it under us. A throttled log makes the gap visible.
_kinect_preview_last_color: list = [None]      # [np.ndarray | None]
# Wall-clock (time.time) when _kinect_preview_last_color was last refreshed with a
# genuinely-new color frame. Drives the 'LAST FRAME' staleness badge (P1-4): when
# the compositor re-serves this cached frame and it's older than
# _KINECT_PREVIEW_STALE_BADGE_S, we stamp a dim badge so the owner can tell a
# frozen tile from a live one.
_kinect_preview_last_color_at = [0.0]
_kinect_preview_color_none_log_last = [0.0]
# How stale the re-served cached color must be (seconds) before the preview gets
# the dim 'LAST FRAME' badge. ~1.5 s: longer than a normal frame interval so a
# live feed never flickers the badge, short enough that a real freeze shows fast.
_KINECT_PREVIEW_STALE_BADGE_S = 1.5
# One-time log latch: True once we've warned that the installed pykinect2 build
# exposes no IR stream (get_infrared_gray() is None) so a dark room degrades to a
# dimmed color preview rather than night-vision.
_kinect_ir_unavailable_logged = [False]


def _last_cached_kinect_color() -> "np.ndarray | None":
    """The last Kinect color frame the compositor saw (a fresh copy), or None if it
    has never produced one. Used to keep the skeleton tile alive across a transient
    color miss instead of returning None (which would blank the preview)."""
    frame = _kinect_preview_last_color[0]
    if frame is None:
        return None
    try:
        return frame.copy()
    except Exception:
        return None


def _kinect_preview_color_none_logged() -> None:
    """Throttled log that the Kinect color frame came back None inside the
    compositor (the exact intermittent the owner hit — skeleton 'rendered for a
    while then stopped'). Logged so it's visible in the session log next time.
    NEVER raises."""
    try:
        now = time.monotonic()
        if (now - _kinect_preview_color_none_log_last[0]
                ) >= _KINECT_PREVIEW_SKIP_LOG_INTERVAL:
            _kinect_preview_color_none_log_last[0] = now
            cached = _kinect_preview_last_color[0] is not None
            print("  [kinect-preview] color frame was None — "
                  + ("re-serving the last cached color frame"
                     if cached else "no cached frame yet, preview falls back"))
    except Exception:
        pass


# ── INFRARED (night-vision) preview fallback for a DARK room ──────────────────
# The Kinect RGB camera needs ambient light, so in a dark room the COLOR preview
# is black — but the Kinect v2 IR stream uses its own active illuminator and works
# in TOTAL darkness (it's how the skeleton tracks). When the color frame is too
# dark (mean brightness below this threshold) or color is None entirely, we build
# the preview from the IR stream instead — contrast-stretched to a viewable BGR
# canvas, upscaled to the color resolution so the EXISTING color-space skeleton
# projection + hand circle are reused verbatim — and stamp a small "IR" badge so
# the owner knows they're seeing night-vision. The color path is kept whenever the
# room is lit; the switch is automatic on brightness.
#
# 8-bit mean-brightness floor under which the color frame is treated as "too dark
# to use" and we fall back to IR. A lit room reads well above this; lights-off RGB
# sits near 0-12. Generous so a dim-but-usable room still keeps color.
_KINECT_PREVIEW_DARK_MEAN = 16.0


def _frame_mean_brightness(bgr: "np.ndarray | None") -> float:
    """Mean 8-bit brightness of a BGR (or grayscale) frame, or 0.0 for None/empty.
    Used to decide whether the color preview is too dark to use (→ IR fallback).
    Pure + cheap (np.mean over the whole frame); NEVER raises."""
    try:
        if bgr is None or getattr(bgr, "size", 0) == 0:
            return 0.0
        return float(np.mean(bgr))
    except Exception:
        return 0.0


def _frame_brightness_for_dark_check(bgr: "np.ndarray | None") -> float:
    """Brightness score used by the dark-room IR switch (P2-5). A WHOLE-FRAME mean
    mis-triggers IR fallback when a monitor-lit FACE sits on a mostly-dark wall:
    the bright face is a small fraction of the frame, so the mean reads 'dark' and
    we needlessly drop to night-vision. Instead we take the MAX of two signals so
    a small bright region keeps COLOR mode:

      • the mean of a CENTER CROP (the middle ~40%, where a seated face/torso
        is), so a lit subject on a dark surround still scores bright; and
      • a HIGH PERCENTILE (95th) of the whole frame, so any concentrated bright
        region (a face lit by a monitor anywhere in frame) keeps color.

    Returns 0.0 for None/empty. Pure + cheap; NEVER raises. Only the IR-switch
    decision uses this; _frame_mean_brightness stays the plain whole-frame mean."""
    try:
        if bgr is None or getattr(bgr, "size", 0) == 0:
            return 0.0
        arr = np.asarray(bgr)
        h = arr.shape[0]
        w = arr.shape[1] if arr.ndim >= 2 else 0
        if h <= 0 or w <= 0:
            return float(np.mean(arr))
        # Center crop: middle ~40% in each axis (at least 1px so tiny frames work).
        y0 = int(h * 0.3)
        y1 = max(y0 + 1, int(h * 0.7))
        x0 = int(w * 0.3)
        x1 = max(x0 + 1, int(w * 0.7))
        center = arr[y0:y1, x0:x1]
        center_mean = float(np.mean(center)) if center.size else 0.0
        # 95th percentile over the whole frame catches a bright patch anywhere.
        try:
            hi_pct = float(np.percentile(arr, 95.0))
        except Exception:
            hi_pct = float(np.max(arr))
        return max(center_mean, hi_pct)
    except Exception:
        return 0.0


def _ir_gray_to_bgr_canvas(ir_gray: "np.ndarray", width: int,
                           height: int) -> "np.ndarray | None":
    """Turn an 8-bit IR grayscale frame (Kinect IR is 512×424) into a CONTRAST-
    STRETCHED BGR canvas at the COLOR resolution (default 1920×1080), so the
    existing color-space skeleton projection + hand circle can be drawn on it
    UNCHANGED (we upscale the IR to the color canvas rather than re-projecting the
    skeleton into IR space). Returns the BGR canvas, or None if the frame is
    unusable. Pure cv2/numpy; NEVER raises.

    The bridge already normalises the 16-bit IR to 8-bit by its peak; here we add a
    percentile contrast STRETCH (clip the dim 2% / bright 1% tails and rescale to
    0-255) so a dark-room IR frame — which often sits in a narrow low band — pops to
    a clearly visible grayscale instead of a faint murk."""
    try:
        if ir_gray is None or getattr(ir_gray, "size", 0) == 0:
            return None
        gray = np.asarray(ir_gray)
        if gray.ndim != 2:
            return None
        gray = gray.astype(np.uint8, copy=False)
        # Percentile contrast stretch: map the [p_lo, p_hi] band to [0, 255]. This
        # is what makes the IR readable in the dark (the raw band is narrow/low).
        try:
            lo = float(np.percentile(gray, 2.0))
            hi = float(np.percentile(gray, 99.0))
            if hi - lo >= 1.0:
                stretched = (gray.astype(np.float32) - lo) * (255.0 / (hi - lo))
                gray = np.clip(stretched, 0, 255).astype(np.uint8)
        except Exception:
            pass  # fall back to the (already peak-normalised) frame on any glitch
        bgr_small = cv2.cvtColor(gray, cv2.COLOR_GRAY2BGR)
        tw = max(1, int(width))
        th = max(1, int(height))
        if (bgr_small.shape[1], bgr_small.shape[0]) == (tw, th):
            return bgr_small
        # Upscale the small IR frame to the full color canvas so the SAME color-
        # space joint projection lands correctly over it. INTER_NEAREST keeps the
        # IR crisp (it's a low-res depth-illuminator image, not a photo).
        return cv2.resize(bgr_small, (tw, th), interpolation=cv2.INTER_NEAREST)
    except Exception:
        return None


def _draw_ir_badge(bgr: "np.ndarray") -> bool:
    """Stamp a small glowing "IR" badge in the top-left of the preview so the owner
    knows the night-vision (infrared) path is active rather than the color camera.
    Returns True iff drawn. NEVER raises."""
    try:
        h, w = bgr.shape[:2]
        font = cv2.FONT_HERSHEY_SIMPLEX
        scale = max(0.6, w / 1600.0)
        thick = max(2, int(round(scale * 2)))
        label = "IR"
        (tw, th), base_ln = cv2.getTextSize(label, font, scale, thick)
        pad = int(round(8 * scale))
        x0, y0 = pad, pad
        bw, bh = tw + 2 * pad, th + base_ln + 2 * pad
        # Translucent dark plate + a cyan border + cyan text (matches the HUD).
        cyan = (255, 201, 76)        # BGR ≈ #4cc9ff
        overlay = bgr.copy()
        cv2.rectangle(overlay, (x0, y0), (x0 + bw, y0 + bh), (20, 20, 20), -1)
        cv2.addWeighted(overlay, 0.55, bgr, 0.45, 0.0, bgr)
        cv2.rectangle(bgr, (x0, y0), (x0 + bw, y0 + bh), cyan, max(2, thick // 1),
                      lineType=cv2.LINE_AA)
        cv2.putText(bgr, label, (x0 + pad, y0 + pad + th), font, scale, cyan,
                    thick, lineType=cv2.LINE_AA)
        return True
    except Exception:
        return False


def _draw_stale_badge(bgr: "np.ndarray") -> bool:
    """Stamp a DIM 'LAST FRAME' badge top-left of the preview when we're re-
    serving a CACHED color frame that's gone stale (P1-4) — so the owner can tell
    a FROZEN skeleton tile from a live one. Reuses _draw_ir_badge's translucent
    dark-plate look, but in a dim amber and at reduced opacity so it reads as a
    quiet 'this is old' marker rather than the bright cyan 'IR' active-mode badge.
    The cached-color path never co-occurs with IR mode, so the two badges never
    overlap. Returns True iff drawn. NEVER raises."""
    try:
        h, w = bgr.shape[:2]
        font = cv2.FONT_HERSHEY_SIMPLEX
        scale = max(0.6, w / 1600.0)
        thick = max(2, int(round(scale * 2)))
        label = "LAST FRAME"
        (tw, th), base_ln = cv2.getTextSize(label, font, scale, thick)
        pad = int(round(8 * scale))
        x0, y0 = pad, pad
        bw, bh = tw + 2 * pad, th + base_ln + 2 * pad
        # Same translucent dark plate as the IR badge, but dimmer + amber so it
        # reads as a quiet staleness marker, not an active-mode badge.
        amber = (90, 150, 200)       # BGR — a muted amber/grey
        overlay = bgr.copy()
        cv2.rectangle(overlay, (x0, y0), (x0 + bw, y0 + bh), (20, 20, 20), -1)
        cv2.addWeighted(overlay, 0.45, bgr, 0.55, 0.0, bgr)
        cv2.rectangle(bgr, (x0, y0), (x0 + bw, y0 + bh), amber, max(1, thick // 2),
                      lineType=cv2.LINE_AA)
        cv2.putText(bgr, label, (x0 + pad, y0 + pad + th), font, scale, amber,
                    max(1, thick - 1), lineType=cv2.LINE_AA)
        return True
    except Exception:
        return False


# Throttled log for IR-fallback activation so the owner sees in the session log
# that the preview switched to night-vision (and why), without frame-rate spam.
_kinect_ir_fallback_log_last = [0.0]


def _kinect_ir_fallback_logged(reason: str) -> None:
    """Throttled note that the preview fell back to the IR stream (dark room)."""
    try:
        now = time.monotonic()
        if (now - _kinect_ir_fallback_log_last[0]) >= _KINECT_PREVIEW_SKIP_LOG_INTERVAL:
            _kinect_ir_fallback_log_last[0] = now
            print(f"  [kinect-preview] room is dark ({reason}) — using the "
                  "infrared (night-vision) stream for the skeleton preview")
    except Exception:
        pass


def _kinect_ir_unavailable_log_once() -> None:
    """Log ONCE (first dark-trigger) that this pykinect2 build exposes no IR
    stream, so the owner understands why a dark room shows a dimmed color preview
    instead of night-vision. Latched so it never repeats. NEVER raises."""
    try:
        if not _kinect_ir_unavailable_logged[0]:
            _kinect_ir_unavailable_logged[0] = True
            print("  [kinect-preview] IR night-vision unavailable on this "
                  "pykinect2 build — dark preview uses dimmed color")
    except Exception:
        pass


def _compose_ir_preview_base(width: int = 1920,
                             height: int = 1080) -> "np.ndarray | None":
    """Build the IR night-vision preview BASE (contrast-stretched IR upscaled to the
    color canvas) for the dark-room fallback, or None when no IR frame is available
    (e.g. the installed pykinect2 build doesn't wire up the IR stream). The skeleton
    + hand circle are drawn by the caller on TOP of this base using the unchanged
    color-space projection. NEVER raises."""
    try:
        ir = _kinect_bridge.get_infrared_gray()
    except Exception:
        ir = None
    if ir is None:
        # First time the dark path finds no IR stream, log it once so the owner
        # knows the dark preview will be dimmed color, not night-vision.
        _kinect_ir_unavailable_log_once()
        return None
    canvas = _ir_gray_to_bgr_canvas(ir, width, height)
    if canvas is None:
        return None
    return canvas


def _compose_kinect_preview(now: float) -> "np.ndarray | None":
    """Build the composite preview image: the Kinect COLOR frame with the live
    skeleton + air-mouse hand circle + gesture pop drawn over it, with the two
    real WEBCAM frames stacked as small tiles down the right edge. Returns the
    BGR image to hand to the preview writer, or None when no Kinect frame at all
    is available (caller then leaves the plain webcam mirror in place). NEVER
    raises.

    DARK-ROOM NIGHT VISION: when the color frame is too dark (mean brightness below
    _KINECT_PREVIEW_DARK_MEAN) or color is None, the base is built from the Kinect
    v2 INFRARED stream instead — which uses the sensor's active illuminator and so
    works in TOTAL darkness (it's how the skeleton tracks). The IR frame (512×424)
    is contrast-stretched and upscaled to the color canvas so the EXISTING color-
    space skeleton projection + hand circle render over it unchanged, and a small
    "IR" badge marks night-vision mode. The color path is kept whenever the room is
    lit; the switch is automatic on brightness.

    The side tiles are the actual USB webcams ('Fullhan Webcam' = LEFT, 'USB 2.0
    Camera' = RIGHT), captured directly + throttled by _read_side_tile_webcams —
    NOT a duplicate of the Kinect. A webcam that's off/covered shows a dim
    placeholder tile, never the Kinect frame.

    FAIL-SAFE (ISSUE 4): the Kinect base (COLOR or IR) + SKELETON are the priority
    and ALWAYS render as long as a frame exists. EVERY optional overlay — the
    gesture pop, the IR badge, EACH side-tile webcam (one may be locked by Teams),
    and the tile composite — is wrapped in its OWN try/except, so a single failing
    piece is skipped (with a throttled log line) instead of blanking the whole
    preview. The only None return is when there is no Kinect color OR IR frame at
    all (caller then keeps the plain webcam mirror)."""
    try:
        fresh = _kinect_bridge.get_color_bgr(require_new=False)
    except Exception:
        fresh = None
    # DARK-ROOM IR FALLBACK: the RGB camera is black without ambient light, but the
    # Kinect v2 IR stream (active illuminator) works in total darkness. If color is
    # None OR too dark to be useful, build the base from the IR stream instead and
    # flag IR mode so we stamp an "IR" badge. The skeleton is drawn the SAME way
    # (color-space projection over an IR frame upscaled to the color canvas), so the
    # owner gets a visible night-vision skeleton instead of a black tile.
    ir_mode = False
    serving_stale_color = False     # P1-4: re-serving an aged cached color frame
    # P2-5: use the center-crop / high-percentile score (not the whole-frame mean)
    # so a monitor-lit face on a dark wall keeps COLOR mode instead of misfiring IR.
    color_too_dark = (fresh is not None
                      and _frame_brightness_for_dark_check(fresh) < _KINECT_PREVIEW_DARK_MEAN)
    if fresh is not None and not color_too_dark:
        # A usable, lit color frame — cache a copy (with its capture time) so a
        # later transient miss can re-serve it, and use a copy as our base (don't
        # scribble on the bridge's buffer).
        try:
            base = fresh.copy()
            # Cache a SEPARATE pristine copy, NOT `base`: the skeleton, IR/stale
            # badges and gesture-pop are drawn IN-PLACE on `base` below, so
            # aliasing the cache to `base` baked those overlays into the "last
            # color" frame — a later color-miss re-serve then drew the CURRENT
            # skeleton over a stale baked-in one (ghosted/double skeleton). Keep
            # the cache clean. 2026-07-08.
            _kinect_preview_last_color[0] = fresh.copy()
            _kinect_preview_last_color_at[0] = now
        except Exception:
            # Can't even copy the frame — hand back the original rather than
            # nothing (and skip caching).
            return fresh
    else:
        # Either no color frame, or the room is too dark for color. Prefer the IR
        # night-vision stream (works in the dark) for the base.
        ir_base = _compose_ir_preview_base()
        if ir_base is not None:
            base = ir_base
            ir_mode = True
            _kinect_ir_fallback_logged("color is None" if fresh is None
                                       else "color frame too dark")
        elif fresh is not None:
            # Dark color but NO IR available (e.g. this pykinect2 build doesn't wire
            # up IR): use the dark color frame anyway (degrade to the old behaviour)
            # rather than blank the preview. Cache it as the last color.
            try:
                base = fresh.copy()
                # Pristine cache copy, separate from `base` (drawn on in-place
                # below) — see the aliasing note on the lit-color branch. 2026-07-08.
                _kinect_preview_last_color[0] = fresh.copy()
                _kinect_preview_last_color_at[0] = now
            except Exception:
                return fresh
        else:
            # Color came back None and no IR — fall back to the LAST cached color
            # frame so the skeleton tile shows the last image instead of going dark.
            # Log it (throttled). Only None if we have no cached frame either.
            _kinect_preview_color_none_logged()
            base = _last_cached_kinect_color()
            if base is None:
                return None
            # P1-4: this is a RE-SERVED cached frame, NOT a live one. If it's older
            # than the staleness threshold, flag it so we stamp a dim 'LAST FRAME'
            # badge below — the owner needs to tell a frozen tile from a live feed.
            cached_age = now - _kinect_preview_last_color_at[0]
            if (_kinect_preview_last_color_at[0] > 0
                    and cached_age >= _KINECT_PREVIEW_STALE_BADGE_S):
                serving_stale_color = True
    # From here a Kinect base frame (color or IR) EXISTS — we must return at least
    # it. Each step below is independently guarded so no optional overlay can blank
    # it.

    # Skeleton (+ the air-mouse hand circle, itself guarded inside). Its own
    # guard so a projection/mapper glitch can't blank the base frame. The SAME
    # color-space projection is used in IR mode (the IR base was upscaled to the
    # color canvas), so the skeleton + hand circle land correctly either way.
    try:
        bodies = []
        try:
            bodies = _kinect_bridge.get_bodies()
        except Exception:
            bodies = []
        _draw_skeleton_on_color(base, bodies)
    except Exception:
        _kinect_preview_piece_skipped("skeleton")

    # Night-vision badge: stamp "IR" so the owner knows they're seeing the infrared
    # stream (dark room) rather than the color camera. Optional + guarded.
    if ir_mode:
        try:
            _draw_ir_badge(base)
        except Exception:
            _kinect_preview_piece_skipped("ir-badge")

    # P1-4 STALE-PREVIEW BADGE: when we're re-serving an AGED cached color frame
    # (color came back None, no IR), stamp a dim 'LAST FRAME' badge so a frozen
    # skeleton tile is obviously distinct from a live feed. Mutually exclusive
    # with IR mode (cached re-serve only happens when there's no IR), so the two
    # badges never overlap. Optional + guarded.
    if serving_stale_color:
        try:
            _draw_stale_badge(base)
        except Exception:
            _kinect_preview_piece_skipped("stale-badge")

    # B3: a brief glowing gesture-name badge when a gesture just fired. Optional.
    try:
        _draw_gesture_pop_on_color(base, now)
    except Exception:
        _kinect_preview_piece_skipped("gesture-pop")

    # B1: the two REAL side-tile webcams (own throttled capture; NOT the Kinect).
    # The READ is guarded as a whole, and EACH slot is turned into a tile (real
    # frame or dim placeholder) under its own guard so one locked/throwing webcam
    # can't take down the other tile or the composite.
    try:
        webcams = _read_side_tile_webcams(now)
    except Exception:
        _kinect_preview_piece_skipped("webcam-read")
        webcams = {}
    tiles = []
    for slot in ("left", "right"):
        try:
            frame = webcams.get(slot)
            if frame is not None:
                tiles.append(frame)
            else:
                tiles.append(_placeholder_tile(
                    _KINECT_PREVIEW_TILE_LABELS.get(slot, slot.title())))
        except Exception:
            _kinect_preview_piece_skipped(f"webcam-tile-{slot}")

    # Per-camera Kinect tile: publish the SKELETON-ANNOTATED base (before the
    # webcam side tiles are laid on) as the standalone "kinect" preview the web
    # Camera tab shows individually. Own try/except per the fail-safe contract.
    try:
        _hud_percam_preview_write("kinect", base, now)
    except Exception:
        _kinect_preview_piece_skipped("percam-kinect")

    # Composite the tiles down the right edge. If THIS throws, fall back to the
    # bare Kinect color+skeleton so the preview is never blank.
    try:
        return _composite_preview_image(base, tiles)
    except Exception:
        _kinect_preview_piece_skipped("composite")
        return base


def _composite_preview_image(base_bgr: "np.ndarray",
                             tiles: list) -> "np.ndarray":
    """Lay the webcam ``tiles`` down the RIGHT edge of ``base_bgr`` (the Kinect
    color+skeleton image), each a small thumbnail, and return the composite.

    Pure cv2/numpy + side-effect free (operates on a fresh canvas, never mutates
    ``base_bgr``) so it is unit-testable with tiny fake frames. With no tiles the
    base is returned unchanged. The tiles are scaled to a fixed fraction of the
    base width and stacked top-to-bottom; if they'd overflow the height they're
    simply clipped (the skeleton view is the priority, the tiles are context)."""
    if not tiles:
        return base_bgr
    h, w = base_bgr.shape[:2]
    tile_w = max(1, w // 5)                      # each tile ~20% of base width
    canvas = base_bgr.copy()
    y = 8
    pad = 8
    for frame in tiles:
        try:
            fh, fw = frame.shape[:2]
            if fw == 0 or fh == 0:
                continue
            tile_h = max(1, int(round(fh * (tile_w / float(fw)))))
            if y + tile_h > h:
                break                             # would overflow → stop stacking
            thumb = cv2.resize(frame, (tile_w, tile_h),
                               interpolation=cv2.INTER_AREA)
            x0 = w - tile_w - pad
            canvas[y:y + tile_h, x0:x0 + tile_w] = thumb
            # Thin cyan border so each tile reads as a distinct pane.
            cv2.rectangle(canvas, (x0, y), (x0 + tile_w - 1, y + tile_h - 1),
                          (255, 201, 76), 2)
            y += tile_h + pad
        except Exception:
            continue
    return canvas


def _hud_kinect_preview_write(now: float) -> bool:
    """If the Kinect skeleton overlay is enabled, build the Kinect color +
    skeleton (+ webcam tiles) composite and write it to the SHARED HUD preview
    JPEG, returning True iff it wrote. Returns False when the overlay is off or
    no Kinect frame was available — the caller then falls back to writing the
    plain primary-webcam mirror, so the HUD tile is never left blank.

    This is the single entry point the face-tracking loop calls; it honours the
    same throttle + atomic-write contract as _hud_camera_preview_write (it reuses
    that writer with the composed frame)."""
    if not _hud_kinect_skeleton_overlay_enabled():
        # Overlay just went off (or never on) — release the side-tile webcam
        # handles so they're not held open while unused. Only acts on the
        # on→off transition (the flag guards against repeated releases).
        _release_side_tile_webcams_if_open()
        return False
    # Throttle BEFORE composing (2026-07-08). _hud_camera_preview_write applies
    # the same _HUD_CAM_PREVIEW_MIN_GAP but only AFTER we hand it a frame, so at
    # the face-track loop's ~20 Hz cadence roughly 2/3 of the (expensive) Kinect
    # composites were built and then discarded by that throttle. Bail early when
    # a write isn't due so the composite is built only at the ~6.7 Hz emit rate.
    if (now - _hud_cam_preview_last_write[0]) < _HUD_CAM_PREVIEW_MIN_GAP:
        return False
    composed = _compose_kinect_preview(now)
    if composed is None:
        return False
    _kinect_preview_tiles_open[0] = True
    return _hud_camera_preview_write(composed, now)


# Webcam I/O health bookkeeping (self-diag 2026-05-28). When cv2's read()
# returns no frame the face-tracking thread can't always tell the user what
# went wrong — was the device just unplugged? Did Teams steal it mid-stream?
# Did the USB pipe stall? We track the last raw failure reason + when the
# device last yielded a frame so see_user / self-diagnostic can surface
# actionable detail instead of just "no frame".
_camera_last_read_error: dict[int, str]      = {}      # index → last error
_camera_last_read_error_at: dict[int, float] = {}      # index → ts
_camera_last_frame_at: dict[int, float]      = {}      # index → ts of last good frame
_camera_wake_attempts: dict[int, int]        = {}      # index → wake attempts since last good frame
_camera_recoveries: dict[int, int]           = {}      # index → cumulative successful wakes

# PREVIEW-RATE DIAGNOSTIC (2026-09-04). A BLOCKING cap.read() is what sets the
# face-tracking loop's period, and the loop's period is the HUD/web camera
# preview frame rate - the preview is published from inside it. A slow read is
# indistinguishable from a healthy one in every log line we had, which is how a
# 1.0 s stall PER CAMERA PER ITERATION (measured live: a 10 s window locked at a
# 2.10 s period = 0.48 fps per tile; a 30 s window averaged 1.93 fps with bursts
# to ~5 fps) stayed invisible. Record the cost
# of every read and say it out loud, throttled, when it is the bottleneck.
_camera_read_ms: dict[int, float]            = {}      # index -> last read cost (ms)
_CAMERA_SLOW_READ_WARN_MS    = 250.0   # a read this slow IS the loop period
_CAMERA_SLOW_READ_WARN_GAP_S = 60.0    # one line per camera per minute, at most
_camera_slow_read_warned_at: dict[int, float] = {}


def _warn_slow_camera_read(label: str, idx: int, ms: float, now: float) -> None:
    """Throttled one-liner naming the camera that is gating the preview rate.
    Never raises into the tracking loop."""
    try:
        if (now - _camera_slow_read_warned_at.get(idx, 0.0)) < _CAMERA_SLOW_READ_WARN_GAP_S:
            return
        _camera_slow_read_warned_at[idx] = now
        print(f"  [face-track] {label} (index {idx}) took {ms:.0f} ms to deliver "
              f"a frame - that one read caps the tracking loop, and therefore "
              f"the HUD/web camera preview, at ~{1000.0 / max(ms, 1.0):.1f} fps")
    except Exception:
        pass


# SHARED-PREVIEW FAILOVER ANNOUNCEMENTS (2026-09-05). The keep-alive at the
# bottom of the per-camera loop keeps the HUD tile alive when the PRIMARY
# camera never reaches its publish branch (benched, backing off, or failing to
# reopen). Keeping it alive is only half the job: showing the RIGHT webcam in
# the tile the owner reads as the LEFT one, and saying nothing, is exactly the
# kind of quiet substitution this file exists to stamp out. Both states are
# announced, throttled to one line per minute so a long bench can't flood the
# session log, and re-announced when the state changes.
_PREVIEW_FAILOVER_LOG_GAP_S = 60.0
# [last-log-ts, last-state-key] - state key flips when the substituted camera
# changes or the starved/substituted state flips, forcing a fresh line.
_preview_failover_log = [0.0, ""]


def _note_preview_failover(cam: dict, now: float) -> None:
    """The shared HUD preview is being served by a NON-primary camera because
    the primary could not publish. Throttled; never raises."""
    try:
        key = f"failover:{cam.get('index')}"
        if (key == _preview_failover_log[1]
                and (now - _preview_failover_log[0]) < _PREVIEW_FAILOVER_LOG_GAP_S):
            return
        _preview_failover_log[0] = now
        _preview_failover_log[1] = key
        primary = next((c for c in CAMERAS if c.get("primary")), None)
        p_lbl = (f"{primary.get('label')} (index {primary.get('index')})"
                 if primary else "the primary camera")
        msg = (f"  [face-track] {p_lbl} is not publishing (benched or backing "
               f"off) - the HUD camera tile is now showing "
               f"{cam.get('label')} (index {cam.get('index')}) instead. The "
               f"view in that tile is NOT the primary camera.")
        print(msg)
        logging.warning(msg.strip())
    except Exception:
        pass


def _note_preview_starved(now: float) -> None:
    """No camera produced a frame this iteration, so the shared HUD preview is
    going stale. Say WHY rather than letting the tile just go dark. Throttled;
    never raises."""
    try:
        key = "starved"
        if (key == _preview_failover_log[1]
                and (now - _preview_failover_log[0]) < _PREVIEW_FAILOVER_LOG_GAP_S):
            return
        _preview_failover_log[0] = now
        _preview_failover_log[1] = key
        benched = [f"{e.get('label') or idx} (index {idx})"
                   for idx, e in get_camera_quarantine().items()
                   if e.get("quarantined")]
        why = (f"benched: {', '.join(benched)}" if benched
               else "no camera delivered a frame this iteration")
        msg = (f"  [face-track] the HUD camera tile is going stale - no camera "
               f"could publish a frame ({why}). This is JARVIS reporting a "
               f"camera problem, NOT the HUD failing.")
        print(msg)
        logging.warning(msg.strip())
    except Exception:
        pass


# Serializes every cv2.VideoCapture open / release across threads (probe sweep,
# face-tracking, list-cameras, snapshot). DirectShow heap-corrupts when an
# abandoned probe worker's release() overlaps another thread's release(), so
# every cv2 capture handle is brought up and torn down inside this lock.
# RLock so a single thread can do open + release in one critical section.
class _CameraIOLock:
    """The process-wide camera I/O lock — an RLock that can be RETIRED.

    WHY THIS IS NOT JUST ``threading.RLock()`` (measured 2026-09-05, stub
    opener, no camera involved):

    The bounded-open machinery below abandons a worker that does not return in
    time. That worker is parked INSIDE ``with _camera_io_lock:`` — wedged in a
    C-level DirectShow call — and it never comes back, so with a plain RLock it
    OWNS THE PROCESS-WIDE CAMERA LOCK FOREVER. Everything downstream then fails
    while blaming the wrong thing, and it was all measured:

      * ``_camera_io_lock.acquire(timeout=1.0)`` from any other thread returned
        False permanently — which is the exact probe skills/self_diagnostic.py
        runs, so its webcam check would read UNVERIFIED for the rest of the
        session ("the face tracker holds _camera_io_lock") no matter how
        healthy the cameras were;
      * an open of the HEALTHY primary (index 2, the eMeet C960) returned None
        after its full timeout with the opener body executed ZERO times — it
        never touched DirectShow at all, it only queued on the dead lock;
      * three of those in 120 s printed
        "QUARANTINE Left webcam (PRIMARY) (index 2) - 3 failed recovery cycles
        ... (open wedged >1.0s) ... every OTHER camera keeps publishing"
        while benching the one camera that was fine and with no other camera
        publishing;
      * every ``_release_capture_guarded`` timed out and parked a leaked handle.

    So one sick camera still took every camera down — it just took three extra
    timeouts to get there, and it logged the opposite of what happened. That is
    the same end state the bounded-open work exists to prevent.

    THE FIX: when a worker is abandoned while it OWNS the lock, that lock is
    RETIRED — kept alive forever (its wedged owner still holds it and will
    ``release()`` it whenever DirectShow lets go, which must not explode) and
    replaced by a fresh RLock that live threads serialize on instead.

    ``acquire`` therefore polls in short slices rather than blocking on one
    underlying lock forever: a thread already queued on a lock that gets retired
    under it MIGRATES to the replacement instead of waiting for a wedge that is
    never coming back. On the healthy, uncontended path the very first slice
    succeeds, so this costs nothing.

    WHAT THIS DELIBERATELY DOES **NOT** WEAKEN: every RELEASE still happens
    inside whatever lock is CURRENT at the moment of the release — the wedged
    worker's own late teardown re-enters through this object, so it acquires the
    replacement, and no release ever overlaps another. Overlapping releases are
    what corrupt the DirectShow heap (0xc0000374); an abandoned OPEN racing a
    healthy open on a different device is the price this file already chose to
    pay when it started abandoning workers at all (see _camera_pending_releases
    and _defer_camera_release, which keep the same discipline for releases the
    producer could not perform in time).

    Drop-in for threading.RLock: ``acquire(blocking=True, timeout=-1)``,
    ``release()``, and the context-manager protocol — which is all any caller
    in this repo uses (skills/self_diagnostic.py's _CameraLockHold and
    _attempt_camera_wake both call ``acquire(timeout=...)`` / ``release()``).
    """

    # How long a waiter sits on one underlying lock before re-checking whether
    # that lock was retired under it. Far below every camera timeout in this
    # file (4 s / 5 s / 35 s), so a rotation is invisible; and irrelevant to
    # throughput because this lock is taken a handful of times a second at most.
    _RECHECK_S = 0.05

    def __init__(self) -> None:
        self._swap = threading.Lock()     # guards _lock / _owner / _hold_id
        self._lock = threading.RLock()    # the CURRENT underlying lock
        self._owner = None                # ident of the thread holding _lock
        # Bumped on every OUTERMOST acquire. A caller that saw hold N and then
        # asks to retire hold N is asking about THAT hold: if the owner let go
        # and took the lock again in between, the id has moved on and the
        # retirement is refused. Without it, retire() is a check-then-act race
        # that can rotate the lock out from under a LIVE camera operation -
        # which is the overlapping-teardown heap corruption, not a fix for it.
        self._hold_id = 0
        self._retired: list = []          # never released, never collected
        self._local = threading.local()   # per-thread stack of held locks

    def _stack(self) -> list:
        s = getattr(self._local, "stack", None)
        if s is None:
            s = []
            self._local.stack = s
        return s

    def _claim(self, lk, me) -> bool:
        """Record a just-acquired underlying lock, or refuse it if it has been
        retired in the meantime. Returns True when the caller may keep `lk`."""
        with self._swap:
            if lk is not self._lock:
                return False
            st = self._stack()
            if lk not in st:            # OUTERMOST hold, not a reentrant one
                self._hold_id += 1
                self._owner = me
            st.append(lk)
            return True

    # ---- threading.RLock-compatible surface ------------------------------
    def acquire(self, blocking: bool = True, timeout: float = -1) -> bool:
        me = threading.get_ident()
        if not blocking:
            timeout = 0.0
        deadline = (None if (timeout is None or timeout < 0)
                    else time.monotonic() + max(0.0, timeout))
        while True:
            with self._swap:
                lk = self._lock
            slice_s = self._RECHECK_S
            if deadline is not None:
                remaining = deadline - time.monotonic()
                if remaining <= 0.0:
                    # One last non-blocking try so a zero/expired budget can
                    # still take a free lock (matches RLock(blocking=False)).
                    if lk.acquire(False):
                        if self._claim(lk, me):
                            return True
                        lk.release()
                    return False
                slice_s = min(slice_s, remaining)
            if lk.acquire(True, slice_s):
                if self._claim(lk, me):
                    return True
                # Retired while we were queued on it. Hand it straight back and
                # re-aim at the replacement — THIS is what stops a poisoned lock
                # from parking every camera thread in the process forever.
                lk.release()

    def release(self) -> None:
        st = self._stack()
        if not st:
            raise RuntimeError("release of an un-acquired camera I/O lock")
        lk = st.pop()
        with self._swap:
            # Only clear ownership when this thread is giving up its LAST hold
            # on the lock that is still current (a nested hold, or a hold on an
            # already-retired lock, must not clear the live owner).
            if (lk is self._lock and lk not in st
                    and self._owner == threading.get_ident()):
                self._owner = None
        lk.release()

    def __enter__(self):
        self.acquire()
        return self

    def __exit__(self, exc_type, exc, tb):
        self.release()
        return False

    # ---- retirement ------------------------------------------------------
    def owner_hold(self) -> tuple:
        """``(owner_ident, hold_id)`` for the CURRENT lock — the token that
        ``retire_if_holding`` re-checks. Reading these two together is what
        lets a caller tell "this worker is wedged HOLDING the lock" (retire it)
        from "this worker is merely QUEUED behind someone else" (do not blame
        its camera) WITHOUT racing the holder."""
        with self._swap:
            return (self._owner, self._hold_id)

    def owner_ident(self):
        """Thread ident currently owning the CURRENT lock, or None."""
        with self._swap:
            return self._owner

    def retired_count(self) -> int:
        with self._swap:
            return len(self._retired)

    def retire_if_holding(self, owner_ident, hold_id, reason: str = "") -> int:
        """Retire the current lock ONLY if `owner_ident` still holds it under
        the same `hold_id` seen earlier. Returns the retired-lock count, or 0
        when the holder has moved on (in which case nothing is retired).

        THIS, NOT ``retire``, IS WHAT PRODUCTION CODE CALLS. A plain
        "read the owner, then retire" is a check-then-act race: the worker can
        release and re-take the lock for its own late teardown in that gap, and
        rotating the lock out from under a LIVE release is the overlapping
        DirectShow teardown (0xc0000374) this lock exists to prevent. The
        hold_id moves on every outermost acquire, so a stale token can never
        retire a live hold. The check and the swap happen in ONE critical
        section - re-checking and then rotating in two would be the same race
        one level down. NEVER raises."""
        try:
            with self._swap:
                if self._owner != owner_ident or self._hold_id != hold_id:
                    return 0
                n = self._retire_locked()
        except Exception:
            logging.exception("[face-track] guarded camera I/O lock retirement "
                              "failed")
            return 0
        self._announce_retirement(reason, n)
        return n

    def _retire_locked(self) -> int:
        """Swap in a fresh lock. Caller MUST hold ``self._swap``. Logging is
        deliberately left to the caller, outside the critical section."""
        self._retired.append(self._lock)
        self._lock = threading.RLock()
        self._owner = None
        return len(self._retired)

    def retire(self, reason: str = "") -> int:
        """Abandon the current underlying lock and install a fresh one.

        UNCONDITIONAL. Production code must go through ``retire_if_holding``;
        this is the primitive underneath it (and what tests use to force a
        rotation). Returns the new retired-lock count. NEVER raises."""
        try:
            with self._swap:
                n = self._retire_locked()
            self._announce_retirement(reason, n)
            return n
        except Exception:
            logging.exception("[face-track] camera I/O lock retirement failed")
            return -1

    def _announce_retirement(self, reason: str, n: int) -> None:
        """A subsystem-level recovery the owner cannot see is exactly the bug
        class this file exists to stamp out. NEVER raises."""
        try:
            # SAY ONLY WHAT IS KNOWN (2026-09-06). This line used to assert
            # that "the wedged worker keeps the old lock forever". That was
            # never measured, and it is false in the case that actually
            # produces most of these: an abandoned cam-probe worker measured
            # 2.74-3.25 s against a 2.50 s joiner budget, i.e. it came back
            # 0.2-0.8 s after being abandoned, released its handle and dropped
            # the retired lock, and the process was back to its baseline thread
            # count within 8 s. An external reviewer read this sentence as
            # evidence that every retirement permanently leaks a worker thread
            # and built a capacity argument on it. The honest statement is that
            # the abandoned worker keeps the OLD lock until it returns, and
            # nothing here knows whether that will be in a moment or never.
            msg = (f"  [face-track] the camera I/O lock was RETIRED "
                   f"({reason or 'holder abandoned'}). The abandoned worker "
                   f"keeps the OLD lock until it returns — which may be in a "
                   f"moment or never; nothing here can tell. Every other "
                   f"camera thread has been moved onto a fresh one, so opens, "
                   f"releases and the self-diagnostic webcam probe all work "
                   f"again instead of timing out and blaming a healthy camera. "
                   f"Retired locks this session: {n}.")
            print(msg)
            logging.warning(msg.strip())
        except Exception:
            logging.exception("[face-track] camera I/O lock retirement "
                              "announcement failed")


_camera_io_lock = _CameraIOLock()


def _release_on_current_camera_lock(cap) -> None:
    """Release `cap` under whatever camera I/O lock is CURRENT *right now*.

    Every caller of this already sits inside a worker holding _camera_io_lock,
    so on the normal path this is a reentrant no-op costing one uncontended
    acquire. It exists for the ONE case that is not normal: a worker that was
    abandoned, had its lock RETIRED under it (see _CameraIOLock), and only then
    unwedged. Such a worker holds a lock nobody else uses, so a bare
    ``cap.release()`` there would overlap the live threads' opens and releases
    - which is the DirectShow heap corruption (0xc0000374) this whole lock
    exists to prevent. Re-entering through the lock OBJECT re-aims at the
    replacement, so the late release is serialised after all. NEVER raises."""
    if cap is None:
        return
    try:
        with _camera_io_lock:
            cap.release()
    except Exception:
        logging.exception("[camera] release under the current camera I/O lock "
                          "failed")


# --------------------------------------------------------------------------
#  CAMERA QUARANTINE + BOUNDED CAMERA I/O  (2026-09-05)
# --------------------------------------------------------------------------
#
# THE DEFECT THIS CLOSES, measured on the owner's rig across two sessions:
# ONE sick webcam took the whole preview producer down, silently, for the rest
# of the session - all three tiles (left, right AND Kinect) went dark and never
# came back until a restart.
#
# It was NOT an exception and NOT an exit. Measured live with py-spy against the
# running PID (7 identical samples over 4 minutes, re-confirmed hours later):
#
#     Thread-67 (_face_tracking_thread)   <- ALIVE, idle, not moving
#         _open_tile_capture        (bobert_companion.py:4429)
#         _read_side_tile_webcams   (bobert_companion.py:4561)
#         _compose_kinect_preview   (bobert_companion.py:5101)
#         _hud_kinect_preview_write (bobert_companion.py:5195)
#         _face_tracking_thread     (bobert_companion.py:6119)
#
# The producer was parked inside a C-level DirectShow call - cap.set() on a
# freshly opened handle for the sick camera - INSIDE `with _camera_io_lock:`.
# Corroborated three times over: skills/self_diagnostic's probe does a real
# _camera_io_lock.acquire(timeout=2.5) and it returned False at 01:22:53,
# 01:52:53 and 02:22:53. A dead thread cannot hold an RLock; the loop had not
# died, it had HUNG, and nothing anywhere was watching for that.
#
# Three things were wrong, and all three are fixed here + in the loop:
#   1. UNBOUNDED CAMERA I/O UNDER A GLOBAL LOCK. cv2.VideoCapture / cap.set()
#      on a sick DirectShow device can block forever. Held under the process-
#      wide _camera_io_lock that is a whole-subsystem hang. Every camera open
#      the preview producer performs now runs on a throwaway worker with a
#      wall-clock cap (the pattern _probe_camera_index has used since July),
#      and every release it performs uses a BOUNDED acquire.
#   2. NO QUARANTINE. The sick camera opened fine every ~10 s and then failed
#      to read, so the recovery machinery retried it forever - a hot reopen
#      loop that eventually found the wedge. A camera that keeps needing rescue
#      is now benched, and the healthy cameras keep publishing.
#   3. NO LIVENESS SIGNAL. See _face_track_watchdog below.
#
# WHY THESE NUMBERS (all from the measured failure, not taste):
#   * STRIKES = 3. The soft-wake recovery fired at 01:22:03, ~01:22:14,
#     01:22:24 and 01:22:40 - four cycles, then the wedge. Quarantining on the
#     3rd fires ~25 s into the sickness, BEFORE the cycle that killed it. A
#     genuine USB power-save blip resolves in <1 s and never even reaches the
#     wake path (which needs 25 consecutive failures AND 2 s of silence), so it
#     scores zero strikes.
#   * WINDOW = 120 s. Strikes must be consecutive-ish to count: the observed
#     cycle period is ~10 s, so 120 s holds a dozen of them, while a camera
#     that misbehaves once an hour never accumulates a quarantine.
#   * BACKOFF 60 s -> 600 s, doubling. The failing cadence was one reopen every
#     ~10 s; 60 s is 6x that, which is what kills the hot loop, and it still
#     re-tests a transient fault within a minute. The 10-minute ceiling keeps a
#     camera that was merely unplugged recoverable without a restart.
_CAMERA_QUARANTINE_STRIKES   = 3       # failed rescue cycles before benching
_CAMERA_QUARANTINE_WINDOW_S  = 120.0   # strikes older than this decay away
_CAMERA_QUARANTINE_BASE_S    = 60.0    # first bench; doubles per re-offence
_CAMERA_QUARANTINE_MAX_S     = 600.0   # ceiling, so an unplug still self-heals
# Wall-clock cap on ONE DirectShow open performed by the preview producer.
# Measured: a healthy open on this rig completes well inside a second; the sick
# one never returned at all.
_CAMERA_OPEN_TIMEOUT_S       = 4.0
# Wall-clock cap on acquiring _camera_io_lock for a release. Skipping a release
# leaks a handle; BLOCKING on it hangs the producer, which is the bug. Leaking
# is the safe direction - an overlapping release is what corrupts the heap, a
# skipped one merely wastes a handle.
_CAMERA_IO_LOCK_TIMEOUT_S    = 5.0
# Wall-clock cap on the face-track loop's OWN 1280x720 open. Deliberately much
# more generous than the tile cap: this file already documents (see
# _probe_camera_index) that cv2.VideoCapture(CAP_DSHOW) can legitimately spend
# 20-30 s in its internal retry loop on an index with no device behind it, so
# anything at or below that would abandon opens that were going to succeed.
# 35 s sits above that measured ceiling: it can only ever fire on a call that
# was NEVER coming back, which turns "hang forever" into "hang once, say so,
# and keep the other cameras publishing".
_CAMERA_LOOP_OPEN_TIMEOUT_S  = 35.0
# How often the producer BEATS while it is parked waiting on one of those
# bounded opens. Load-bearing, not cosmetic: _CAMERA_LOOP_OPEN_TIMEOUT_S (35 s)
# is deliberately LONGER than the watchdog's _FACE_TRACK_STALL_WARN_S (30 s),
# so with a single blind join the producer went silent for the whole open and
# the watchdog fired on every LEGITIMATE open of an absent index - a boot that
# then completed normally was reported as a "WEDGED CAMERA CALL" with a stack
# dump, and every backoff-driven reopen of an unplugged camera re-shouted it
# every 120 s. The producer must keep saying "still here, still waiting on
# THIS open" for the whole wait; the open's OWN timeout - not the watchdog -
# is what reports a wedge on this path, and it does so with a better message.
# Anything comfortably below _FACE_TRACK_STALL_WARN_S works; 1 s costs ~35
# wakeups across a fully wedged open.
_CAMERA_OPEN_BEAT_INTERVAL_S = 1.0

# index -> {"strikes": [ts, ...], "until": ts, "reason": str, "since": ts,
#           "count": int, "backoff": float, "label": str}
_camera_quarantine: dict[int, dict] = {}
_camera_quarantine_lock = threading.Lock()

# Wall-clock budget the deferred-release reaper gives ONE attempt at
# _camera_io_lock, and the interval between attempts. Nothing here runs on the
# producer's clock - the reaper is a daemon of its own, so it can afford to
# keep asking.
_CAMERA_RELEASE_RETRY_S      = 2.0
# How long a handle may sit unreleasable before we say so out loud, ONCE. Sized
# above the longest legitimate hold this file documents (a dead CAP_DSHOW index
# retries internally for ~26-30 s), so crossing it is EVIDENCE of a real wedge
# rather than routine contention - evidence, not proof, and the message says
# which.
_CAMERA_RELEASE_ESCALATE_S   = 60.0

# Capture handles whose release could not be performed on the CALLER's clock.
# They are queued here for a reaper that retries the bounded acquire and then
# releases them INSIDE _camera_io_lock - the same contract every other release
# site in this file obeys. Entries: {"cap", "idx", "label", "since",
# "escalated"}.
#
# THIS USED TO BE A GRAVEYARD, AND THAT WAS TWO LIES AT ONCE (fixed 2026-09-05).
# The old code appended the handle to a list nothing ever drained and announced
# "the camera I/O lock is held by a wedged DirectShow call".
#
#   * THE CAUSE WAS NEVER ESTABLISHED. A 5 s acquire timeout proves exactly ONE
#     thing - we did not get the lock in 5 s. Healthy code in this process holds
#     it far longer than that, routinely: skills/self_diagnostic's
#     _probe_webcam_locked holds it across cv2.VideoCapture on indices 0, 1 AND
#     2 plus a PowerShell PnP query, every 30 minutes, concurrently with this
#     loop; _probe_camera_index holds it for its whole CAMERA_PROBE_TIMEOUT_SEC
#     budget per index - and budgets its OWN wait at
#     (timeout + 0.5) x CAMERA_PROBE_MAX (~42 s) for precisely this reason;
#     _open_with_warmup holds it across 15 warm-up reads at 0.05 s each. So the
#     most likely trigger was JARVIS's own diagnostic working exactly as
#     designed, and the log blamed DirectShow for it.
#   * THE COST WAS PERMANENT. The parked handle is a LIVE capture: its
#     DirectShow filter graph kept the USB device open for the remaining life
#     of the process, so every later reopen of that index had to contend with a
#     graph JARVIS itself still held. On a bandwidth-limited USB 2.0 camera
#     that is the documented failure mode - made permanent for the session by
#     the very code meant to survive it.
#
# The safety property that motivated the graveyard is KEPT INTACT: the handle
# is still never released off-lock, and the queue still holds a strong
# reference so CPython cannot run the destructor (which would call release()
# OUTSIDE the lock - the overlapping teardown that heap-corrupts DirectShow)
# behind our back. It is simply released when the lock frees, instead of never.
_camera_pending_releases: list = []
_camera_pending_lock = threading.Lock()
# Single-element cell holding the reaper thread, or None when idle. Read AND
# written only under _camera_pending_lock, so "the reaper is alive, it will
# handle this" and "the queue is empty, I may exit" can never both be believed.
_camera_release_reaper: list = [None]


def _camera_quarantine_entry(idx: int) -> dict:
    """Row for `idx`, created on first use. Caller holds the lock."""
    e = _camera_quarantine.get(idx)
    if e is None:
        e = {"strikes": [], "until": 0.0, "reason": None, "since": 0.0,
             "count": 0, "backoff": 0.0, "label": ""}
        _camera_quarantine[idx] = e
    return e


def _camera_is_quarantined(idx, now: float | None = None) -> bool:
    """True while `idx` is benched. NEVER raises - a bookkeeping fault must not
    be able to stop the producer from publishing the other cameras."""
    try:
        now = time.time() if now is None else now
        with _camera_quarantine_lock:
            e = _camera_quarantine.get(int(idx))
            return bool(e) and now < e["until"]
    except Exception:
        return False


def _camera_note_sick_cycle(idx, label: str, reason: str,
                            now: float | None = None) -> bool:
    """Record ONE failed rescue cycle for camera `idx` (a soft wake, a wedge
    release, or a bounded-open timeout). Returns True iff this call put the
    camera into quarantine. NEVER raises."""
    try:
        now = time.time() if now is None else now
        idx = int(idx)
        with _camera_quarantine_lock:
            e = _camera_quarantine_entry(idx)
            e["label"] = label or e["label"]
            if now < e["until"]:
                return False            # already benched; nothing to escalate
            cutoff = now - _CAMERA_QUARANTINE_WINDOW_S
            e["strikes"] = [t for t in e["strikes"] if t >= cutoff]
            e["strikes"].append(now)
            if len(e["strikes"]) < _CAMERA_QUARANTINE_STRIKES:
                return False
            # Escalating bench: 60 s, 120 s, 240 s ... capped at 600 s.
            prev = e["backoff"] or 0.0
            backoff = (_CAMERA_QUARANTINE_BASE_S if prev <= 0.0
                       else min(prev * 2.0, _CAMERA_QUARANTINE_MAX_S))
            e["backoff"] = backoff
            e["until"]   = now + backoff
            e["since"]   = now
            e["reason"]  = str(reason)[:240]
            e["count"]  += 1
            e["strikes"] = []
            count = e["count"]
        # Logged OUTSIDE the lock, and loudly: this is the line that tells the
        # owner one camera was benched rather than "JARVIS's cameras broke".
        # Say which tile actually goes dark. The old wording promised "every
        # OTHER camera keeps publishing" unconditionally, which was FALSE for
        # the primary: the shared HUD preview is published from the primary's
        # branch, so benching it used to blank the HUD tile too and this line
        # then pointed the owner at his webcam hardware. Benching the primary
        # now fails the shared tile over to another camera (announced by
        # _note_preview_failover), and this line says so.
        try:
            _is_primary = any(c.get("primary") and c.get("index") == idx
                              for c in CAMERAS)
        except Exception:
            _is_primary = False
        _effect = ("it is the PRIMARY, so the shared HUD camera tile fails "
                   "over to another camera (or goes stale if none can publish)"
                   if _is_primary else
                   "its own tile goes dark; every OTHER camera keeps publishing")
        msg = (f"  [face-track] QUARANTINE {label or 'camera'} (index {idx}) - "
               f"{_CAMERA_QUARANTINE_STRIKES} failed recovery cycles in "
               f"{_CAMERA_QUARANTINE_WINDOW_S:.0f}s ({reason}). Benched for "
               f"{backoff:.0f}s; {_effect}. Retry #{count} is automatic.")
        print(msg)
        logging.warning(msg.strip())
        return True
    except Exception:
        logging.exception("[face-track] quarantine bookkeeping failed for %s", idx)
        return False


def _camera_note_healthy(idx, label: str = "") -> None:
    """A real frame arrived - drop this camera's strikes and lift any bench.
    NEVER raises."""
    try:
        idx = int(idx)
        lifted = False
        with _camera_quarantine_lock:
            e = _camera_quarantine.get(idx)
            if not e:
                return
            if e["until"]:
                lifted = True
                e["until"] = 0.0
                e["since"] = 0.0
                e["reason"] = None
            e["strikes"] = []
            e["backoff"] = 0.0
        if lifted:
            msg = (f"  [face-track] {label or 'camera'} (index {idx}) is "
                   f"delivering frames again - quarantine lifted.")
            print(msg)
            logging.warning(msg.strip())
    except Exception:
        pass


def get_camera_quarantine() -> dict:
    """Snapshot copy of the quarantine registry, keyed by camera index."""
    now = time.time()
    with _camera_quarantine_lock:
        return {idx: {"quarantined": now < e["until"],
                      "quarantine_until": e["until"],
                      "quarantine_reason": e["reason"],
                      "quarantine_since": e["since"],
                      "quarantine_count": e["count"],
                      "quarantine_strikes": len(e["strikes"]),
                      "label": e["label"]}
                for idx, e in _camera_quarantine.items()}


def _drain_camera_pending_releases(timeout: float | None = None) -> int:
    """ONE pass over the deferred-release queue: release everything on it
    INSIDE _camera_io_lock. Returns how many handles were actually released.

    Waits at most `timeout` for the lock, so this is safe to call from any
    thread - it can never become the hang it exists to prevent. NEVER raises.

    Note the lock ORDER: the queue is snapshotted under _camera_pending_lock,
    which is then DROPPED before _camera_io_lock is taken. Nothing in this file
    ever takes them the other way round, so the reaper cannot deadlock against
    an enqueue."""
    try:
        timeout = _CAMERA_RELEASE_RETRY_S if timeout is None else timeout
        # CLAIM the batch atomically. Two passes can legitimately overlap (the
        # reaper thread plus a direct call), and while both would serialize on
        # _camera_io_lock rather than truly racing, letting both drain the same
        # entry would still mean release() twice on one handle. Claim-then-drain
        # makes each handle the property of exactly one pass.
        with _camera_pending_lock:
            batch = [i for i in _camera_pending_releases if not i.get("claimed")]
            for i in batch:
                i["claimed"] = True
        if not batch:
            return 0
        got = False
        try:
            got = _camera_io_lock.acquire(timeout=timeout)
        except Exception:
            logging.exception("[face-track] deferred release could not acquire "
                              "the camera I/O lock")
            got = False
        if not got:
            # Hand them back so the next pass retries them.
            with _camera_pending_lock:
                for i in batch:
                    i["claimed"] = False
            # Still busy. Say so ONCE per handle, and only after long enough
            # that "wedge" is a defensible reading - and even then, say what
            # was measured rather than naming a culprit we never observed.
            now = time.time()
            for item in batch:
                try:
                    waited = now - item.get("since", now)
                    if item.get("escalated") or waited < _CAMERA_RELEASE_ESCALATE_S:
                        continue
                    item["escalated"] = True
                    msg = (f"  [face-track] {item.get('label') or 'camera'} "
                           f"(index {item.get('idx')}) has been waiting "
                           f"{waited:.0f}s to be released - the camera I/O lock "
                           f"has stayed busy that whole time. That is longer "
                           f"than any legitimate holder in this process (a dead "
                           f"CAP_DSHOW index retries for ~30s), so a genuine "
                           f"wedge is LIKELY - but a busy lock is all that has "
                           f"actually been measured. Still retrying every "
                           f"{_CAMERA_RELEASE_RETRY_S:.0f}s; the handle is NOT "
                           f"abandoned.")
                    print(msg)
                    logging.warning(msg.strip())
                except Exception:
                    pass
            return 0
        released = 0
        try:
            for item in batch:
                cap = item.get("cap")
                try:
                    if cap is not None:
                        cap.release()
                    released += 1
                except Exception:
                    # Dropped from the queue anyway: retrying a release() that
                    # RAISED is how a double-release happens, and that is the
                    # heap corruption this whole lock exists to prevent.
                    logging.exception("[face-track] deferred release raised "
                                      "for index %s", item.get("idx"))
        finally:
            try:
                _camera_io_lock.release()
            except Exception:
                pass
        now = time.time()
        with _camera_pending_lock:
            for item in batch:
                try:
                    _camera_pending_releases.remove(item)
                except ValueError:
                    pass
        for item in batch:
            try:
                waited = now - item.get("since", now)
                msg = (f"  [face-track] deferred release of "
                       f"{item.get('label') or 'camera'} (index "
                       f"{item.get('idx')}) completed after {waited:.1f}s - the "
                       f"camera I/O lock was BUSY, not wedged. The DirectShow "
                       f"graph is gone and the device is free again.")
                logging.info(msg.strip())
                if item.get("escalated"):
                    # We printed a scary line about this handle; print the
                    # resolution too, or the log stands as an unretracted
                    # accusation.
                    print(msg)
            except Exception:
                pass
        return released
    except Exception:
        logging.exception("[face-track] deferred release pass failed")
        try:
            # A claim that is never handed back would strand the handle in the
            # queue unreleased forever - the very shape this function exists to
            # remove. Unclaim everything still queued so the next pass retries.
            with _camera_pending_lock:
                for i in _camera_pending_releases:
                    i["claimed"] = False
        except Exception:
            pass
        return 0


def _camera_release_reaper_loop() -> None:
    """Retry the deferred releases until the queue drains, then exit so an idle
    JARVIS carries no extra thread. NEVER raises: a bookkeeping fault here must
    not strand a live camera handle."""
    try:
        while True:
            _drain_camera_pending_releases()
            with _camera_pending_lock:
                if not _camera_pending_releases:
                    # Cleared under the SAME lock a new enqueue takes, so the
                    # next _defer_camera_release starts a fresh reaper instead
                    # of trusting this one.
                    _camera_release_reaper[0] = None
                    return
            time.sleep(_CAMERA_RELEASE_RETRY_S)
    except BaseException:
        try:
            with _camera_pending_lock:
                if _camera_release_reaper[0] is threading.current_thread():
                    _camera_release_reaper[0] = None
        except Exception:
            pass
        logging.exception("[face-track] deferred release reaper died")


def _defer_camera_release(cap, idx, label: str = "") -> bool:
    """Queue `cap` to be released INSIDE _camera_io_lock by the reaper thread.

    Returns True if it was queued. The strong reference held by the queue is
    load-bearing: it stops CPython from running the capture's destructor -
    which would call release() OFF-lock - while we wait for the lock. NEVER
    raises."""
    if cap is None:
        return False
    item = {"cap": cap, "idx": idx, "label": label,
            "since": time.time(), "escalated": False, "claimed": False}
    try:
        with _camera_pending_lock:
            _camera_pending_releases.append(item)
            t = _camera_release_reaper[0]
            if t is None or not t.is_alive():
                t = threading.Thread(target=_camera_release_reaper_loop,
                                     daemon=True, name="cam-release-reaper")
                t.start()          # cell set only AFTER a successful start, so
                _camera_release_reaper[0] = t   # a failed start is retried.
        return True
    except Exception:
        logging.exception("[face-track] could not queue deferred release "
                          "for index %s", idx)
        try:
            # Last resort: keep a strong reference SOMEWHERE, even with no
            # reaper running. A retained handle is a leak; a destructor firing
            # off-lock is a 0xc0000374. The next successful defer starts a
            # reaper that drains this one too.
            if item not in _camera_pending_releases:
                _camera_pending_releases.append(item)
        except Exception:
            pass
        return False


def _release_capture_guarded(cap, idx, label: str = "",
                             timeout: float | None = None) -> bool:
    """Release `cap` INSIDE _camera_io_lock, but give up after `timeout`.

    Returns True if the handle was released ON THIS CALL. On a timeout the
    handle is handed to the deferred-release reaper - which retries the bounded
    acquire and then releases it inside the SAME lock - and False is returned.
    False therefore means "not released YET", never "abandoned": see
    _camera_pending_releases for why the old graveyard both leaked a live
    camera and named a cause it had never established.

    This exists because the producer's release sites used a plain
    ``with _camera_io_lock:``: once an abandoned open worker owned that lock,
    the very next release wedged the producer a second time. NEVER raises."""
    if cap is None:
        return True
    timeout = _CAMERA_IO_LOCK_TIMEOUT_S if timeout is None else timeout
    got = False
    try:
        got = _camera_io_lock.acquire(timeout=timeout)
        if got:
            try:
                cap.release()
            except Exception:
                logging.exception("[face-track] release raised for index %s", idx)
            return True
    except Exception:
        logging.exception("[face-track] guarded release failed for index %s", idx)
    finally:
        if got:
            try:
                _camera_io_lock.release()
            except Exception:
                pass
    if not got:
        try:
            queued = _defer_camera_release(cap, idx, label)
            msg = (f"  [face-track] could not release {label or 'camera'} "
                   f"(index {idx}) within {timeout:.1f}s - the camera I/O lock "
                   f"is BUSY. Holder not identified: a {timeout:.1f}s acquire "
                   f"timeout only proves we did not get the lock, and the "
                   f"self-diagnostic's webcam probe legitimately holds it for "
                   f"longer than that. Release "
                   + ("DEFERRED - the reaper will perform it inside the lock, "
                      "so the device is not held for the rest of the session."
                      if queued else
                      "COULD NOT BE QUEUED - handle retained (never released "
                      "off-lock), so the device stays open until the process "
                      "exits."))
            print(msg)
            logging.warning(msg.strip())
        except Exception:
            pass
    return False


def _open_capture_bounded(idx, opener, label: str = "",
                          timeout: float | None = None,
                          beat=None):
    """Run `opener()` - which MUST do its own ``with _camera_io_lock:`` - on a
    throwaway daemon worker and give up after `timeout` seconds.

    Returns the capture, or None on failure OR timeout. On a timeout the worker
    is abandoned; when (if ever) it finishes, it releases whatever it opened
    from inside the same lock, so nothing is left dangling and no release ever
    overlaps another. Modelled on _probe_camera_index, which has used exactly
    this shape since 2026-07 for the same reason: cv2.VideoCapture(CAP_DSHOW)
    has no timeout of its own and a sick device never returns.

    `beat` is an optional one-argument callable - in practice
    _face_track_beat - invoked every _CAMERA_OPEN_BEAT_INTERVAL_S for as long
    as the open is outstanding. Pass it from the PREVIEW PRODUCER's thread and
    nowhere else: the heartbeat records the calling thread's ident for the
    watchdog's stack dump, so beating from another thread would both forge
    liveness the producer does not have and point the dump at the wrong stack.

    NEVER raises.

    CALL COUNT, HONESTLY (updated 2026-09-05): this wrapper itself performs no
    camera traffic at all - `opener` does, exactly once per invocation of this
    function. What `opener` costs changed when the openers moved to
    _camera_open(): on MSMF a first open fails transiently about 3-7% of the
    time (measured over 120 back-to-back opens of two webcams; it fails in
    ~40 ms where a success takes ~400-490 ms) and is retried once, which
    recovered every single case. So the worst case here is TWO opens plus one
    0.25 s sleep, not one. That is deliberate: without the retry a healthy
    camera would report a spurious open failure several times an hour, and
    spurious failures are what feed backoff and quarantine.
    """
    timeout = _CAMERA_OPEN_TIMEOUT_S if timeout is None else timeout
    box: dict = {"cap": None}
    abandoned = [False]

    def _run():
        cap = None
        try:
            cap = opener()
        except Exception:
            logging.exception("[face-track] bounded open raised for index %s", idx)
            cap = None
        if abandoned[0]:
            # Our joiner gave up long ago. Tear the handle down ourselves,
            # inside the lock, so the late success doesn't leak a device.
            if cap is not None:
                released = False
                try:
                    with _camera_io_lock:
                        cap.release()
                    released = True
                except Exception:
                    logging.exception(
                        "[face-track] abandoned open worker could not release "
                        "its late handle for index %s", idx)
                # Say what actually happened, in words that cannot be read as
                # "the camera came back": the caller was handed None long ago
                # and is NOT using this handle. (An opener that announced its
                # own success used to print "opened <cam> at index N" right
                # about here — a success line for a discarded capture, printed
                # after the abandon line.)
                try:
                    msg = (f"  [face-track] {label or 'camera'} (index {idx}) "
                           f"finished opening AFTER the attempt was abandoned; "
                           f"handle "
                           f"{'released' if released else 'NOT released (release raised)'}"
                           f" and discarded — the producer is NOT using it.")
                    print(msg)
                    logging.warning(msg.strip())
                except Exception:
                    pass
            return
        box["cap"] = cap

    t = threading.Thread(target=_run, daemon=True, name=f"cam-open-{idx}")
    t.start()
    if beat is None:
        t.join(timeout=timeout)
    else:
        # HEARTBEAT THE WAIT (2026-09-05). The caller is about to sit here for
        # up to `timeout` seconds, which for _CAMERA_LOOP_OPEN_TIMEOUT_S is
        # LONGER than the watchdog's stall threshold. A single blind join made
        # every legitimate 20-30 s DirectShow open on an absent index look
        # exactly like a wedge. Slice the join and say what we are waiting for,
        # so liveness reads "waiting on THIS open, N s in" instead of silence.
        _wait_t0 = time.monotonic()
        while True:
            _waited = time.monotonic() - _wait_t0
            _left = timeout - _waited
            if _left <= 0:
                break
            try:
                beat(f"opening {label or 'camera'} (index {idx}) "
                     f"{_waited:.0f}s/{timeout:.0f}s")
            except Exception:  # pragma: no cover - defensive: a beat must never break an open
                pass
            t.join(timeout=min(_CAMERA_OPEN_BEAT_INTERVAL_S, _left))
            if not t.is_alive():
                break
    # SAY WHAT THE WORKER COULD NOT. The opener runs on a thread that is
    # forbidden to print (it may be abandoned) and logging goes nowhere in the
    # daemon, so _camera_open() queues its backend decision instead and this
    # joiner delivers it. See _drain_camera_backend_notes.
    _drain_camera_backend_notes()
    if t.is_alive():
        abandoned[0] = True
        # DID THIS WORKER ACTUALLY REACH DIRECTSHOW, OR IS IT ONLY QUEUED?
        # The opener takes _camera_io_lock first, so a worker that does NOT own
        # the lock never called cv2 at all - it is stuck behind SOMEONE ELSE's
        # camera operation. The two cases need opposite handling, and treating
        # them alike is what benched the healthy primary in the measured
        # failure (its opener body ran ZERO times and still scored strikes):
        #   * OWNS the lock -> genuinely wedged inside DirectShow while holding
        #     the process-wide lock it will never give back. RETIRE that lock so
        #     every other camera thread stops queueing on a corpse, and score
        #     the strike: this camera really is sick.
        #   * does NOT own it -> contention, not a fault of THIS camera. Say so
        #     and score NOTHING. (Exactly the mistake _probe_camera_index's
        #     PHASE 1 comment already documents: a queued worker reported as a
        #     dead camera.)
        # The retirement is what ESTABLISHES the wedge, so it happens BEFORE
        # the log line rather than after it: retire_if_holding re-checks, under
        # the lock's own mutex, that this worker still holds the exact hold it
        # was seen holding. A non-zero return is proof; anything else is not,
        # and gets reported as what it is.
        retired = 0
        try:
            owner, hold = _camera_io_lock.owner_hold()
            if owner == t.ident:
                retired = _camera_io_lock.retire_if_holding(
                    t.ident, hold,
                    f"{label or 'camera'} (index {idx}) wedged inside its "
                    f"DirectShow open")
        except Exception:  # pragma: no cover - defensive: foreign lock object
            logging.exception("[face-track] could not retire the camera I/O "
                              "lock for index %s", idx)
        if retired:
            msg = (f"  [face-track] {label or 'camera'} (index {idx}) did not "
                   f"finish opening within {timeout:.1f}s - DirectShow is wedged "
                   f"inside the open. Abandoning the attempt so the preview "
                   f"producer keeps running for every other camera.")
            print(msg)
            logging.warning(msg.strip())
            _camera_note_sick_cycle(idx, label, f"open wedged >{timeout:.1f}s")
        else:
            msg = (f"  [face-track] {label or 'camera'} (index {idx}) gave up "
                   f"after {timeout:.1f}s without EVER being shown to reach "
                   f"DirectShow - it does not hold the camera I/O lock, so it "
                   f"either spent the budget queued behind another camera "
                   f"operation or has already left the open. No strike is "
                   f"scored against this camera: nothing here says it is sick.")
            print(msg)
            logging.warning(msg.strip())
        return None
    return box["cap"]


def _detect_face(frame_bgr: np.ndarray) -> tuple[float, float] | None:
    """Returns (fx, fy) 0.0–1.0 face-centre coords, or None."""
    if _face_cascade is None:
        return None
    h, w = frame_bgr.shape[:2]
    gray = cv2.cvtColor(frame_bgr, cv2.COLOR_BGR2GRAY)
    # Equalize histogram so backlit / dim-room frames don't fall below the
    # cascade's contrast threshold. Cheap (~1 ms at 1280x720).
    gray = cv2.equalizeHist(gray)
    # scaleFactor 1.1 → 1.05 gives finer pyramid steps (more positions checked
    # per image scale) — material recall bump for heads that fall between the
    # cascade's stride boundaries on the previous setting.
    faces = _face_cascade.detectMultiScale(
        gray, scaleFactor=1.05, minNeighbors=4, minSize=(40, 40)
    )
    # Escalation pass: when the strict frontal cascade returns nothing, retry
    # once at minNeighbors=3 but with a larger minSize to keep false positives
    # from tiny shadow artifacts in check. Only runs on frames the strict pass
    # already rejected, so per-frame FP rate stays bounded.
    if len(faces) == 0:
        faces = _face_cascade.detectMultiScale(
            gray, scaleFactor=1.05, minNeighbors=3, minSize=(60, 60)
        )
    # Frontal cascade misses heads turned past ~30°. Fall through to the
    # profile cascade — and a mirrored second pass since profileface is
    # trained on left-facing heads only — before giving up.
    if len(faces) == 0 and _profile_cascade is not None:
        prof = _profile_cascade.detectMultiScale(
            gray, scaleFactor=1.05, minNeighbors=4, minSize=(40, 40)
        )
        if len(prof) > 0:
            faces = prof
        else:
            mirror = cv2.flip(gray, 1)
            prof_m = _profile_cascade.detectMultiScale(
                mirror, scaleFactor=1.05, minNeighbors=4, minSize=(40, 40)
            )
            if len(prof_m) > 0:
                faces = [(w - x - fw, y, fw, fh) for (x, y, fw, fh) in prof_m]
    if len(faces) == 0:
        return None
    x, y, fw, fh = max(faces, key=lambda f: f[2] * f[3])   # largest face
    fx = (x + fw / 2) / w
    fy = (y + fh / 2) / h
    if MIRROR_EYES_X: fx = 1.0 - fx
    if MIRROR_EYES_Y: fy = 1.0 - fy
    return fx, fy


def _probe_camera_index(idx: int, timeout_sec: float = CAMERA_PROBE_TIMEOUT_SEC) -> bool:
    """Open a camera index with a hard wall-clock timeout.

    A camera open has no timeout of its own and a sick device can fail to
    return at all, so the open runs on a worker thread and the main flow gives
    up after `timeout_sec` — the worker may keep running, but it's daemon and
    will finish (or never). Returns True only if the camera opened AND yielded
    a real frame in time.

    ``idx`` is and stays a DIRECTSHOW index: it is what CAMERAS holds, what
    this sweep rewrites, and what --list-cameras prints. The BACKEND that
    actually opens it is _camera_open()'s business (Media Foundation by
    default since 2026-09-05, with the index translated to match), which is
    also what stopped a dead index in this sweep costing +103 handles a step.
    """
    # BENCHED INDEX -> DO NOT OPEN IT AT ALL (2026-09-06). This is the half of
    # the bound that has teeth: scoring strikes on the retirement branch below
    # only counts wedges, it does not stop them. A camera that has already
    # wedged _CAMERA_QUARANTINE_STRIKES times is one whose next open costs
    # another abandoned worker and another retired lock for no new information,
    # so the probe must decline to start one - the same rule the preview
    # producer's own quarantine gate has followed since 2026-09-05, applied at
    # the call site that had no gate. Benches expire (60 s, doubling to 600 s),
    # so an index that was merely busy still re-tests itself without a restart.
    # Said out loud, because "not probed" and "probed and failed" are different
    # facts and the owner is entitled to know which one he is looking at.
    if _camera_is_quarantined(idx):
        print(f"  [cam-probe] index {idx}: NOT probed — benched after "
              f"{_CAMERA_QUARANTINE_STRIKES} wedged opens; each retry abandons "
              f"a worker inside the camera driver and retires the camera I/O "
              f"lock. It re-tests itself when the bench expires.")
        return False
    result = {"ok": False}
    started = threading.Event()      # set the instant the worker OWNS the lock

    def _open():
        # Hold the camera I/O lock across the whole open+release so an
        # abandoned worker (one whose main-thread joiner timed out) can't
        # race a release with another camera operation later on. If this
        # worker is wedged inside cv2.VideoCapture, the main thread bails
        # via t.join(timeout=...) without trying to acquire the lock —
        # subsequent camera ops will simply wait for the wedge to clear
        # before re-using DirectShow plumbing.
        with _camera_io_lock:
            # THE BUDGET STARTS HERE, NOT AT THREAD START (2026-07-14 audit).
            # Callers fan out "in parallel" (probe_cameras_and_update_config
            # sweeps 12 indices at once; _preflight_cameras one thread per
            # camera) — but EVERY worker serializes on this lock, and each dead
            # index holds it for its full budget. The joiner's clock, however,
            # started when the THREAD started, so the 2nd worker in the queue
            # could burn its entire allowance just WAITING and be reported
            # "wedged" without ever calling cv2.VideoCapture. That is why
            # healthy cameras were being marked bad ("failed to open in 2.0s")
            # and why the by-name rescue — a SERIAL re-probe — appeared to
            # "fix" them: it wasn't the name, it was finally getting the lock.
            started.set()
            # ONE BUDGET FOR THE WHOLE WORKER, STAMPED HERE (2026-09-06).
            # The read loop below used to start ITS deadline after the open
            # returned, so the worker's real cost was open + (timeout_sec-0.2)
            # while its joiner only ever waited timeout_sec + 0.5. Any open
            # slower than 0.7 s therefore OVERRAN the joiner by construction,
            # and the joiner's overrun branch does not merely give up - it
            # RETIRES the process-wide camera I/O lock and announces a wedge.
            # Measured on this rig 2026-09-06, index 0 held by another process
            # (see worker_timing.py in the session scratchpad), timeout_sec=2.0:
            #     open 0.936 / 1.053 / 1.189 / 1.441 s, then 8 reads over
            #     1.80 s -> worker_total 2.740 / 2.856 / 2.990 / 3.249 s
            #     against a 2.500 s joiner budget: OVER on 4 of 4.
            # Every one of those printed "wedged inside its camera open" and
            # retired a lock, and 8 s later the process was back to its normal
            # thread count - i.e. NOTHING was wedged and NOTHING was leaked;
            # the arithmetic manufactured the diagnosis. A soak of the same
            # call at the boot cadence retired one lock per attempt, forever,
            # because nothing but the caller running out of calls ever stopped
            # it. Stamping the deadline HERE makes open+reads fit inside the
            # caller's own timeout_sec, so an overrun once again means what the
            # joiner says it means: a call that did not come back.
            budget_ends = time.monotonic() + max(0.05, timeout_sec - 0.2)
            cap = None
            try:
                # require_frame is deliberately NOT used here: this probe has
                # its own read-until-deadline loop below, whose budget scales
                # with timeout_sec so the tiny-timeout unit tests stay fast.
                # Two nested frame budgets would only make the timing harder to
                # reason about. The open itself still goes through
                # _camera_open(), so the index is translated for whichever
                # backend is in force and a dead DirectShow index no longer
                # costs +103 handles per sweep step.
                cap = _camera_open(idx, label=f"probe index {idx}")
                if cap is not None:
                    # RETRY reads until the probe deadline — a WARMING camera
                    # opens instantly but returns False frames for its first
                    # ~2s (the Logi measured exactly that), so the old single
                    # immediate read() failed healthy devices and the by-name
                    # shuffled-index rescue could never succeed. The deadline
                    # scales with timeout_sec so tiny-timeout unit tests stay
                    # fast. 2026-07-10. It is stamped at the top of the worker
                    # (budget_ends), NOT here: a camera that opens instantly
                    # still gets the whole warm-up window, while one with a
                    # slow open spends the caller's budget instead of silently
                    # doubling it and tripping the joiner's wedge branch.
                    deadline = budget_ends
                    while True:
                        ret, _ = cap.read()
                        if ret:
                            result["ok"] = True
                            break
                        if time.monotonic() >= deadline:
                            break
                        time.sleep(0.25)
            except Exception:
                pass
            finally:
                # Through the lock OBJECT: an abandoned probe worker whose lock
                # was retired must not release outside the lock live threads
                # use. See _release_on_current_camera_lock.
                _release_on_current_camera_lock(cap)

    t = threading.Thread(target=_open, daemon=True)
    t.start()
    # PHASE 1 — wait for the worker to actually OWN _camera_io_lock. Time spent
    # queued behind a sibling probe is NOT this camera's fault and must not eat
    # its budget. Bounded generously (siblings can legitimately hold the lock
    # for their own full budget), and a timeout here is reported honestly as a
    # contention failure rather than a dead camera.
    lock_budget = max(2.0, (timeout_sec + 0.5) * max(1, CAMERA_PROBE_MAX))
    if not started.wait(timeout=lock_budget):
        print(f"  [cam-probe] index {idx}: still queued for the camera lock "
              f"after {lock_budget:.1f}s — treating as unavailable")
        return False
    # PHASE 2 — now the worker is doing real work; give it its full budget.
    # +0.5s over the worker's own read deadline so a worker that succeeds at
    # the buzzer isn't misread as wedged by a same-instant join expiry.
    t.join(timeout=timeout_sec + 0.5)
    _drain_camera_backend_notes()
    if t.is_alive():
        # Wedged in the C-level open call. Abandon the worker and report
        # failure — the underlying handle will be released when the worker
        # eventually returns (or when the process exits).
        #
        # RETIRE THE LOCK IT IS SITTING ON (2026-09-05). PHASE 1 proved this
        # worker OWNS _camera_io_lock (started only fires from inside the
        # ``with``), so abandoning it here used to poison the process-wide
        # camera lock exactly as an abandoned bounded-open worker did: every
        # later open, every later release and skills/self_diagnostic's
        # acquire(timeout=2.5) would fail forever, and the face-track loop
        # would score quarantine strikes against cameras that never blocked.
        # Same defect, second call site — closed the same way.
        retired = 0
        try:
            owner, hold = _camera_io_lock.owner_hold()
            if owner == t.ident:
                retired = _camera_io_lock.retire_if_holding(
                    t.ident, hold,
                    f"cam-probe index {idx} wedged inside its camera open")
        except Exception:  # pragma: no cover - defensive: foreign lock object
            logging.exception("[cam-probe] camera I/O lock retire failed for "
                              "index %s", idx)
        if retired:
            # A RETIREMENT MUST COST THIS CAMERA A STRIKE (2026-09-06).
            # WHAT WAS WRONG: the producer's bounded opener has scored a
            # quarantine strike on this exact branch since 2026-09-05, but THIS
            # call site retired the process-wide lock and told the quarantine
            # registry nothing at all. Nothing anywhere counted probe wedges,
            # so nothing could ever stop one: the retirement count was exactly
            # the number of times a caller happened to call, and boot happens
            # to call three times per camera (first pass, retry pass, by-name
            # rescue). A session log showing "3 retirements, then stable for 17
            # minutes" was therefore read as proof of a bound when it was only
            # proof that preflight had finished - it had DROPPED the camera, so
            # nothing retried it, so nothing could be retired. Soaked at the
            # boot cadence with the camera left in place (2026-09-06, one probe
            # every 6 s), the same call retired ONE LOCK PER ATTEMPT with no
            # ceiling whatsoever.
            # Feeding the SAME registry the producer uses is what turns that
            # into a real bound: three wedges bench the index, the gate at the
            # top of this function then refuses to open it at all, and the
            # bench backs off 60 -> 600 s. The count stops because the CODE
            # stops it, not because the caller ran out of calls.
            try:
                _lbl = next((c.get("label") or "" for c in CAMERAS
                             if c.get("index") == idx), "")
            except Exception:
                _lbl = ""
            _camera_note_sick_cycle(idx, _lbl,
                                    f"probe open wedged >{timeout_sec:.1f}s")
        return False
    return result["ok"]


def _camera_rescued_by_name(cam: dict, static_idx: int,
                            timeout_sec: float = CAMERA_PROBE_TIMEOUT_SEC) -> bool:
    """A configured camera whose STATIC index failed to probe may simply have
    shuffled to a different LIVE DirectShow index (USB re-enumeration). The
    face-track opener (_open_capture) already resolves the entry's 'name' to the
    live index at OPEN time and prefers it over the static index — but the boot
    probes only test the static index, so a present-but-shuffled camera was
    wrongly marked bad and dropped from CAMERAS before the opener ever got to
    name-resolve it. Mirror _open_capture here: if the entry carries a 'name',
    resolve it to a live index and probe THAT. Returns True when the name
    resolves to a DIFFERENT, openable live index (camera is present → keep it;
    _open_capture will resolve it by name at open). Never raises. 2026-07-08."""
    try:
        if not isinstance(cam, dict):
            return False
        name = cam.get("name")
        # Same rule as _open_capture (v2.0.39): KINECT_AS_CAMERA only applies
        # to kinect-typed/UNNAMED entries — this stale copy of the old
        # condition made the rescue return False INSTANTLY for every named
        # webcam while the flag was on, so a shuffled camera could never be
        # rescued (live 2026-07-10: the Logi sat healthy at its new index
        # through three boots while this line vetoed every rescue attempt).
        want_kinect = (cam.get("type") == "kinect"
                       or (KINECT_AS_CAMERA and not name))
        if not name or want_kinect:
            return False
        live = _dshow_name_to_index(name)
        if live is None:
            print(f"  [cam-probe] '{name}' rescue: name did not resolve "
                  f"(static {static_idx}) — cannot rescue")
            return False
        if live == static_idx:
            # SAME index — not a shuffle, but the FIRST-PASS probe runs on the
            # quick 2.0s budget and the Logi's first frame measures ~2.0s
            # whenever the Kinect (re)joins the DirectShow bus. Live
            # 2026-07-12 (Kinect power-brick fix brought the sensor BACK):
            # 'name resolved to 2 (static 2) — cannot rescue' + 'failed to
            # open in 2.0s' dropped a healthy LEFT cam sitting at its own
            # index. Re-probe HERE at the rescue budget before giving up —
            # a slow warm-up is not a dead device.
            if _probe_camera_index(live, timeout_sec=timeout_sec):
                print(f"  [cam-probe] '{name}' at its own index {live} passed "
                      f"the retry-budget probe ({timeout_sec:.1f}s) — keeping "
                      f"it (slow warm-up, not a dead device)")
                return True
            print(f"  [cam-probe] '{name}' rescue: still no frames at its own "
                  f"index {live} after {timeout_sec:.1f}s — cannot rescue")
            return False
        if _probe_camera_index(live, timeout_sec=timeout_sec):
            print(f"  [cam-probe] '{name}' failed at static index {static_idx} "
                  f"but opened at LIVE index {live} (USB re-enumeration shuffle) "
                  f"— keeping it (opener resolves by name)")
            return True
        return False
    except Exception:
        return False


def find_camera_locking_processes() -> list[str]:
    """Return display names of currently-running processes known to grab
    exclusive webcam locks (Teams, Zoom, OBS, etc.). Empty list if psutil
    is missing or no suspects are running. Used to give the user an
    actionable hint when the probe finds zero cameras.
    """
    try:
        import psutil
    except ImportError:
        return []
    suspects: list[str] = []
    try:
        for proc in psutil.process_iter(attrs=["name"]):
            try:
                name = (proc.info.get("name") or "").lower()
                if name in CAMERA_LOCK_PROCESSES and proc.info["name"] not in suspects:
                    suspects.append(proc.info["name"])
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
    except Exception:
        return []
    return suspects


# ── camera reopen scheduling (P1-3 "live camera-contention yield") ─────────
# THE SINGLE OWNER of entry["next_reopen_at"]. It used to be assigned in THREE
# places inside _face_tracking_thread and only ONE of them consulted contention:
#   * the recovery path re-armed a flat 2 s on every FAILED reopen, overwriting
#     the 30 s yield the wedge branch had just scheduled, one tick later;
#   * the soft-wake failure path carried a second copy of the same flat 2 s;
#   * only the wedge branch called find_camera_locking_processes().
# So the backoff decayed to 2 s and the loop went straight back to hammering
# DirectShow - the overlapping open/release churn this file names at the
# WAKE_AFTER comment as "the leading suspect for the silent crash cascade".
# Worse, in the exact scenario the feature was written for (Teams holding the
# device) the wedge branch is UNREACHABLE: the soft wake fires at ~25-40
# consecutive failures, its own reopen fails, and its failure path parks the
# entry in the recovery path with `fails` frozen below MAX_READ_FAILURES - which
# is only ever reset on SUCCESS - so CONTENTION_BACKOFF_SEC never executed once
# and the "appears LOCKED by ..." hint never printed.
# Now every scheduling decision goes through here, contention is re-evaluated on
# EVERY attempt, and the number the caller logs is the number that was stored.
# 2026-08-20 audit (stale-duplicate + honest-failure).
CAMERA_REOPEN_BACKOFF_SEC     = 2.0    # normal "don't hammer reopen" spacing
CAMERA_CONTENTION_BACKOFF_SEC = 30.0   # a known webcam-locking app holds it
# find_camera_locking_processes() walks every process, and the reopen path can
# now ask up to once per backoff window per camera; a short shared TTL keeps
# that off the face-track loop's critical path without ever serving an answer
# old enough to matter against a 2 s decision.
_CAMERA_LOCKER_CACHE_TTL_S = 5.0
_camera_locker_cache: list = [0.0, []]
_camera_locker_cache_lock = threading.Lock()


def _camera_lockers_cached(now: float | None = None) -> list[str]:
    """find_camera_locking_processes() behind a short TTL cache."""
    now = time.time() if now is None else now
    with _camera_locker_cache_lock:
        if (_camera_locker_cache[0]
                and (now - _camera_locker_cache[0]) < _CAMERA_LOCKER_CACHE_TTL_S):
            return list(_camera_locker_cache[1])
    lockers = find_camera_locking_processes()
    with _camera_locker_cache_lock:
        _camera_locker_cache[0] = now
        _camera_locker_cache[1] = list(lockers)
    return list(lockers)


def _schedule_camera_reopen(entry: dict, label: str, index,
                            now: float | None = None,
                            lockers: list[str] | None = None
                            ) -> tuple[float, list[str]]:
    """Arm this camera entry's next reopen attempt and say what was armed.

    Returns ``(backoff_seconds, lockers)``. Callers MUST NOT write
    ``entry["next_reopen_at"]`` themselves - a second writer is exactly how the
    contention yield rotted. Both state transitions LOG once: entering the
    widened backoff, and leaving it again.
    """
    now = time.time() if now is None else now
    if lockers is None:
        lockers = _camera_lockers_cached(now)
    if lockers:
        backoff = CAMERA_CONTENTION_BACKOFF_SEC
        if not entry.get("contention_logged"):
            entry["contention_logged"] = True
            print(f"  [face-track] {label} (index {index}) appears LOCKED by "
                  f"{', '.join(lockers)} — backing off reopen to "
                  f"{backoff:.0f}s. Close {lockers[0]} to free the camera.")
    else:
        backoff = CAMERA_REOPEN_BACKOFF_SEC
        if entry.get("contention_logged"):
            # Degraded -> recovered must be LOGGED, not a silent speed-up.
            entry["contention_logged"] = False
            print(f"  [face-track] {label} (index {index}) no longer appears "
                  f"locked — reopen backoff restored to {backoff:.0f}s.")
    entry["next_reopen_at"] = now + backoff
    return backoff, list(lockers)


def probe_cameras_and_update_config() -> tuple[list[int], list[int]]:
    """At startup, try the configured CAMERA indices. If both fail, fall back
    to probing indices 0..CAMERA_PROBE_MAX-1 to find any working webcam, and
    rewrite CAMERAS in-place so face tracking can actually run.

    Each probe is capped at CAMERA_PROBE_TIMEOUT_SEC so a missing index can
    no longer freeze startup for ~26 s of DSHOW retries.

    Returns (working_indices, failed_configured_indices).
    """
    if not CAMERA_PROBE_ENABLED:
        return [], []

    # Helper: probe a list of indices IN PARALLEL — total time becomes the
    # longest single probe (~3 s) instead of the sum (~30 s for 10 indices).
    def _probe_many(indices: list[int]) -> dict[int, bool]:
        results: dict[int, bool] = {}
        threads = []
        def _runner(i):
            try:
                results[i] = _probe_camera_index(i)
            except Exception:
                logging.exception("[cam-probe] _runner failed for index %s", i)
                results[i] = False
        for i in indices:
            t = threading.Thread(target=_runner, args=(i,), daemon=True)
            t.start()
            threads.append(t)
        # BUDGET-AWARE BATCH JOIN (2026-07-14 bug-hunt). A flat per-thread
        # timeout=CAMERA_PROBE_TIMEOUT_SEC+0.5 (3.5s) abandoned any probe still
        # QUEUED behind the camera I/O lock — but _probe_camera_index itself
        # deliberately allows up to CAMERA_PROBE_MAX*(timeout+0.5) (~42s) for the
        # queue wait (a dead index holds the lock 20-30s per cv2.VideoCapture),
        # so a runner abandoned at 3.5s never wrote results[i] and a PRESENT
        # camera queued behind a ghost was dropped as "not found". Use one
        # global deadline scaled by batch size so the batch honours the same
        # lock-queue reasoning PHASE-1 does, and wait for ALL runners (so a late
        # runner can't mutate `results` while the caller iterates it).
        _deadline = time.monotonic() + (CAMERA_PROBE_TIMEOUT_SEC + 0.5) * max(1, len(indices))
        for t in threads:
            _remaining = _deadline - time.monotonic()
            if _remaining <= 0:
                break
            t.join(timeout=_remaining)
        return results

    # Step 1: probe configured indices in parallel
    configured = [cam["index"] for cam in CAMERAS]
    cfg_results = _probe_many(configured)
    working_configured: list[int] = []
    for idx in configured:
        if cfg_results.get(idx, False):
            working_configured.append(idx)
            print(f"  [cam-probe] index {idx}: working ✓")
        else:
            # NAME-RESOLUTION RESCUE (2026-07-08): the static index may be stale
            # after a USB shuffle. If the camera's name resolves to a different
            # openable live index, keep the entry (its static index stays in
            # working_configured so Step 2 preserves it; _open_capture re-resolves
            # by name at open) rather than dropping a present camera.
            cam = next((c for c in CAMERAS if c.get("index") == idx), None)
            if cam is not None and _camera_rescued_by_name(cam, idx):
                working_configured.append(idx)
            else:
                print(f"  [cam-probe] index {idx}: failed to open")

    # Step 2: if any configured cameras worked, keep the original config
    if working_configured:
        good = [cam for cam in CAMERAS if cam["index"] in working_configured]
        CAMERAS[:] = good
        # PROMOTE a survivor to PRIMARY if the configured primary failed its
        # probe here. Mirrors the _preflight_cameras guard: the HUD preview WRITE
        # and precise primary-face tracking are BOTH gated on cam["primary"], so
        # a rebuilt CAMERAS with zero primary leaves the HUD tile dark and the
        # eyes on side-snap/drift for the whole session. This function runs AFTER
        # preflight, so a camera that passed preflight but stalled on THIS ~3s
        # probe (USB blip / an app grabbed it) could otherwise strip the only
        # primary. 2026-07-08.
        if CAMERAS and not any(c.get("primary") for c in CAMERAS):
            CAMERAS[0]["primary"] = True
            print(f"  [cam-probe] configured primary camera was dropped — "
                  f"promoted {CAMERAS[0].get('label')} "
                  f"(index {CAMERAS[0].get('index')}) to primary")
        return working_configured, [i for i in configured if i not in working_configured]

    # Step 3: short-circuit — if a known webcam-locking app (Teams / Zoom /
    # OBS / Snap Camera) is running, don't bother sweeping. The cameras
    # aren't going to appear no matter how many indices we try.
    suspects = find_camera_locking_processes()
    if suspects:
        print(f"  [cam-probe] no configured cameras worked — and "
              f"{', '.join(suspects)} is holding the webcam lock. "
              f"Skipping fallback sweep.")
        print(f"  [cam-probe] close {suspects[0]} and restart, or run "
              f"`python bobert_companion.py --list-cameras`")
        return [], configured

    # Step 4: no obvious culprit — probe indices 0..MAX-1 in parallel
    print(f"  [cam-probe] no configured cameras worked — sweeping 0..{CAMERA_PROBE_MAX - 1} in parallel")
    sweep_indices = [i for i in range(CAMERA_PROBE_MAX) if i not in configured]
    sweep_results = _probe_many(sweep_indices)
    found: list[int] = []
    for idx in sorted(sweep_results.keys()):
        if sweep_results[idx]:
            found.append(idx)
            print(f"  [cam-probe] index {idx}: working ✓ (fallback)")

    if not found:
        # Surface the most likely culprit before returning empty so the user
        # knows what to close instead of just seeing 'cameras dead' again.
        suspects = find_camera_locking_processes()
        if suspects:
            print(f"  [cam-probe] no cameras found — these running apps commonly "
                  f"hold webcam locks: {', '.join(suspects)}")
            print(f"  [cam-probe] close them and re-run, or `python bobert_companion.py --list-cameras`")
        else:
            print(f"  [cam-probe] no cameras found and no known webcam-locking apps "
                  f"are running — webcams may be unplugged or disabled in Device Manager")
        return [], configured

    # Rewrite CAMERAS with the found indices. First found = "left", second =
    # "right" (heuristic — user can re-run --list-cameras to confirm).
    new_cams = []
    for i, idx in enumerate(found[:2]):
        if i == 0:
            new_cams.append({
                "index": idx, "label": f"Probed webcam (index {idx})",
                "primary": True, "look_x": 0.15, "look_y": 0.5,
            })
        else:
            new_cams.append({
                "index": idx, "label": f"Probed webcam (index {idx})",
                "primary": False, "look_x": 0.85, "look_y": 0.5,
            })
    CAMERAS[:] = new_cams
    return found, [i for i in configured if i not in found]


# --------------------------------------------------------------------------
#  CAMERA-PREVIEW PRODUCER LIVENESS: heartbeat + watchdog  (2026-09-05)
# --------------------------------------------------------------------------
#
# THE FACT THAT WAS MISSING FROM THE LOG. The owner's three camera tiles went
# dark ~30 minutes into two consecutive sessions and stayed dark until a
# restart, and the session log said NOTHING - no traceback, no "Stopped", no
# further [face-track] line of any kind for the following hour. He concluded
# his webcam hardware had failed again. It had not.
#
# Measured with py-spy against the live PID: the producer thread was ALIVE the
# whole time, blocked inside a C-level DirectShow call (see the quarantine
# block above for the full stack). So every theory of the form "the loop exited
# and the exception was swallowed" is WRONG, and so is any fix that only makes
# exits loud. The loop did not exit. It hung, and nothing was watching.
#
# TWO instruments, because there are two failure shapes and neither covers the
# other:
#   * THE HEARTBEAT + WATCHDOG (here) catch the shape that actually happened -
#     a producer that is alive and stuck. Nothing else can: an exit handler
#     never runs, an exception never fires, the process never dies. The
#     watchdog re-reports on a backoff and names the STAGE, then dumps the
#     stuck thread's Python stack straight into the session log - i.e. it hands
#     the owner the py-spy answer for free, at the moment it happens.
#   * THE SUPERVISOR (_face_tracking_thread, below) catches every shape where
#     the loop really does stop, INCLUDING the one exit that is silent by
#     construction today: a BaseException such as SystemExit slips past the
#     loop's `except Exception`, skips the release loop and the "Stopped" print
#     (plain statements after the `while`, not a finally), and is then dropped
#     without a word by threading's default excepthook, which returns early for
#     SystemExit. Measured under this exact interpreter + logging setup: an
#     uncaught Exception in a daemon thread DOES reach the session log, an
#     uncaught SystemExit produces absolutely nothing.
#
# WHY 30 s. The producer's measured iteration period is bursty - up to ~2.1 s
# under load - and the dashboard already calls a tile dead at 5 s
# (_CAMERA_PREVIEW_STALE_S). 30 s is >14x the worst healthy iteration, so a
# slow burst cannot trip it, and it is 6x the point at which the owner can SEE
# the tiles are dead, so the log now explains the blank tiles within half a
# minute instead of never.
#
# WHY IT MAY SIT BELOW _CAMERA_LOOP_OPEN_TIMEOUT_S (35 s) - the one thing that
# makes that legal. The producer BEATS THROUGHOUT a bounded open, every
# _CAMERA_OPEN_BEAT_INTERVAL_S, from inside _open_capture_bounded. Until
# 2026-09-05 it did not, and this threshold fired on the ordinary 20-30 s
# CAP_DSHOW block that _probe_camera_index documents for an index with no
# device behind it: unplugging a webcam turned a normal boot into an ERROR
# reading "WEDGED CAMERA CALL, not a hardware failure" plus a stack dump, and
# every backoff-driven recovery reopen re-shouted it every 120 s. A watchdog
# that fires on a condition this same file calls legitimate is noise, not
# signal. So: do NOT remove that beat without raising this constant above
# _CAMERA_LOOP_OPEN_TIMEOUT_S. Pinned by ProducerBeatsWhileOpeningTests in
# tests/monolith/test_monolith_camera_quarantine.py.
_FACE_TRACK_STALL_WARN_S    = 30.0    # no heartbeat for this long = stalled
_FACE_TRACK_STALL_REWARN_S  = 120.0   # then re-shout every 2 min, not every tick
_FACE_TRACK_WATCHDOG_TICK_S = 5.0     # how often the watchdog looks

_face_track_heartbeat: dict = {
    "at": 0.0,            # monotonic-ish wall clock of the last beat
    "stage": "not started",
    "iters": 0,
    "tid": 0,             # producer thread ident, for the stack dump
    "started_at": 0.0,
}
_face_track_heartbeat_lock = threading.Lock()
_face_track_stall_state: dict = {"warned_at": 0.0, "stalled": False,
                                 "since": 0.0}


def _face_track_beat(stage: str, now: float | None = None) -> None:
    """Producer says 'still moving, currently doing <stage>'. Cheap enough to
    call several times per iteration; NEVER raises."""
    try:
        with _face_track_heartbeat_lock:
            _face_track_heartbeat["at"] = time.time() if now is None else now
            _face_track_heartbeat["stage"] = stage
            _face_track_heartbeat["tid"] = threading.get_ident()
    except Exception:
        pass


def _face_track_beat_iteration(now: float | None = None) -> None:
    """Top-of-loop beat: also counts iterations so a stall is distinguishable
    from a loop that is spinning without publishing."""
    try:
        with _face_track_heartbeat_lock:
            _face_track_heartbeat["iters"] += 1
    except Exception:
        pass
    _face_track_beat("loop top", now)


def get_face_track_held_indices() -> set:
    """THE answer to "which cv2 camera indices is the producer holding open".

    ONE PLACE, on purpose. Every in-process opener has to ask this question
    before it touches a device — measured 2026-09-06, in-process, on this rig:
    a second MSMF handle on a camera the producer is streaming is GRANTED, takes
    the stream, and leaves the producer at 98.6-99.5% read failures, and
    releasing the second handle does NOT give it back (only the producer's own
    release+reopen recovers). Both webcams behaved identically, so this is not a
    sick-device effect. ``core/camera_backend.py``'s "both backends leave the
    HOLDER undisturbed" was measured ACROSS processes; in-process is the
    opposite, and in-process is the only way JARVIS runs.

    Two openers have already had to answer it independently — the side-tile
    compositor (_producer_holds_side, above) and the self-diagnostic webcam
    probe (skills/self_diagnostic.py) — which is exactly how this project's
    signature STALE DUPLICATE starts. New callers use this; they do not walk
    _face_track_caps themselves.

    A Kinect-backed entry is excluded because the producer reaches the sensor
    through pykinect2, never through cv2.VideoCapture, so it holds no cv2 index
    for that slot and collides with no webcam opener. The test is the same one
    _open_capture applies (explicit ``{"type": "kinect"}`` OR the
    KINECT_AS_CAMERA opt-in hijacking an UNNAMED entry), not the narrower
    type-only test, or an unnamed slot on a Kinect rig reads as a held webcam.

    ``entry["cap"] is None`` means the producer has LET GO — open backoff, dead
    after N failed reads, mid-reopen, quarantine bench, shutdown — and in those
    states another opener collides with nothing and must not be blocked, or the
    device could never be shown again.

    ONE WINDOW THIS CANNOT SEE, and a caller off the producer thread has to
    handle it: between _camera_open() returning a handle and the loop assigning
    it to entry["cap"], this answers False for a camera that is about to be
    held. The side tile is exempt because it runs ON the producer thread (see
    _producer_holds_side); skills/self_diagnostic.py is not, which is why it
    also consults the producer HEARTBEAT — a beat inside the window means "holds
    or is about to open" — and fails closed. Copy that pattern, not just this
    call. NEVER raises; returns an empty set when the producer is not running."""
    held: set = set()
    try:
        for entry in (_face_track_caps[0] or []):
            if not isinstance(entry, dict) or entry.get("cap") is None:
                continue
            cam = entry.get("cam")
            if not isinstance(cam, dict):
                continue
            cam_name = cam.get("name")
            if cam.get("type") == "kinect" or (KINECT_AS_CAMERA and not cam_name):
                continue
            idx = cam.get("index")
            if idx is not None:
                held.add(idx)
    except Exception:
        pass
    return held


def get_face_track_liveness(now: float | None = None) -> dict:
    """Is the camera-preview producer actually running? Snapshot of the
    heartbeat plus the derived age, for self-diagnostic / see_user.

    ``age_s`` is None when the producer has never beaten (not started)."""
    now = time.time() if now is None else now
    with _face_track_heartbeat_lock:
        hb = dict(_face_track_heartbeat)
    at = hb.get("at", 0.0) or 0.0
    hb["age_s"] = (now - at) if at else None
    hb["stalled"] = bool(at) and (now - at) >= _FACE_TRACK_STALL_WARN_S
    return hb


def _face_track_thread_stack(tid: int) -> str:
    """Python stack of thread `tid` right now, as text. This is the whole point
    of the watchdog: a hang leaves no traceback, so we go and take one.
    Returns a short explanation instead of raising when the frame is gone."""
    try:
        frame = sys._current_frames().get(int(tid))
        if frame is None:
            return "(producer thread not found in sys._current_frames)"
        return "".join(traceback.format_stack(frame)).rstrip()
    except Exception as e:      # pragma: no cover - introspection is best-effort
        return f"(stack unavailable: {type(e).__name__}: {e})"


def _face_track_watchdog_check(now: float | None = None) -> bool:
    """One watchdog pass. Returns True iff it reported a stall on this call.

    Reports LOUDLY (print + logging.error) with the stage, the age, and the
    stuck thread's stack; re-reports only every _FACE_TRACK_STALL_REWARN_S; and
    says so again when the producer starts moving. NEVER raises - a watchdog
    that can throw is a watchdog that stops watching."""
    try:
        now = time.time() if now is None else now
        with _face_track_heartbeat_lock:
            at = _face_track_heartbeat.get("at", 0.0) or 0.0
            stage = _face_track_heartbeat.get("stage", "?")
            iters = _face_track_heartbeat.get("iters", 0)
            tid = _face_track_heartbeat.get("tid", 0)
        if not at:
            return False                      # never started; nothing to judge
        age = now - at
        if age < _FACE_TRACK_STALL_WARN_S:
            if _face_track_stall_state["stalled"]:
                stalled_for = now - (_face_track_stall_state["since"] or now)
                _face_track_stall_state["stalled"] = False
                _face_track_stall_state["warned_at"] = 0.0
                _face_track_stall_state["since"] = 0.0
                msg = (f"  [face-track] WATCHDOG: the camera-preview producer "
                       f"is moving again after {stalled_for:.0f}s stalled "
                       f"(now at '{stage}').")
                print(msg)
                logging.warning(msg.strip())
            return False
        if (_face_track_stall_state["stalled"]
                and (now - _face_track_stall_state["warned_at"])
                < _FACE_TRACK_STALL_REWARN_S):
            return False
        if not _face_track_stall_state["stalled"]:
            _face_track_stall_state["stalled"] = True
            _face_track_stall_state["since"] = at
        _face_track_stall_state["warned_at"] = now
        msg = (f"  [face-track] WATCHDOG: the camera-preview producer has not "
               f"moved for {age:.0f}s - it is STALLED, not stopped, at stage "
               f"'{stage}' after {iters} iterations. Every camera tile will be "
               f"stale until it moves. This is a WEDGED CAMERA CALL, not a "
               f"hardware failure of every camera at once. Producer stack:\n"
               f"{_face_track_thread_stack(tid)}")
        print(msg)
        logging.error(msg.strip())
        return True
    except Exception:
        try:
            logging.exception("[face-track] watchdog check raised")
        except Exception:
            pass
        return False


def _face_track_watchdog(stop_event, tick: float | None = None) -> None:
    """Watchdog thread body: poll _face_track_watchdog_check until stopped."""
    tick = _FACE_TRACK_WATCHDOG_TICK_S if tick is None else tick
    try:
        while not stop_event.wait(tick):
            _face_track_watchdog_check()
    except Exception:   # pragma: no cover - defensive: the loop above cannot raise
        logging.exception("[face-track] watchdog thread died")


def _face_track_note_stopped(reason: str, exc: BaseException | None = None
                             ) -> None:
    """THE line whose absence cost the owner an evening: say that the producer
    stopped, and why. Emitted from the supervisor's `finally`, so it runs for a
    normal shutdown, for an escaped Exception, AND for a BaseException such as
    SystemExit that today vanishes without a trace. NEVER raises."""
    try:
        msg = (f"  [face-track] STOPPED - the camera-preview producer is no "
               f"longer running. Reason: {reason}. Every camera tile stays "
               f"dark until JARVIS restarts it.")
        print(msg)
        if exc is not None:
            logging.error(msg.strip(), exc_info=(type(exc), exc,
                                                 exc.__traceback__))
            try:
                print("".join(traceback.format_exception(
                    type(exc), exc, exc.__traceback__)).rstrip())
            except Exception:
                pass
        else:
            logging.error(msg.strip())
    except Exception:
        pass


def _face_track_release_all(caps) -> None:
    """Release every capture the producer holds, each inside _camera_io_lock
    but with a BOUNDED acquire (a wedged lock must not turn shutdown into a
    second hang). NEVER raises."""
    try:
        for entry in (caps or []):
            try:
                c = entry.get("cap") if isinstance(entry, dict) else None
                if c is None:
                    continue
                cam = entry.get("cam") or {}
                _release_capture_guarded(c, cam.get("index"),
                                         cam.get("label", "camera"))
                entry["cap"] = None
            except Exception:
                logging.exception("[face-track] release on shutdown")
    except Exception:
        logging.exception("[face-track] release sweep failed")


# The producer's live capture list, published so the supervisor's `finally` can
# tear it down even when the body never returns normally.
_face_track_caps: list = [None]


def _face_tracking_thread():
    """SUPERVISOR around the real producer loop (_face_tracking_thread_body).

    Exists so the producer CANNOT stop quietly. Whatever happens - clean stop,
    an Exception that escapes the per-iteration handler, or a BaseException
    like SystemExit that the default threading excepthook drops on the floor -
    the `finally` releases the cameras, clears the preview, and logs one line
    saying the producer stopped and why. It also runs the liveness watchdog for
    exactly as long as the producer is meant to be running.

    Signature and thread target are unchanged, so nothing else moves."""
    _face_track_caps[0] = []
    _face_track_beat("starting")
    wd_stop = threading.Event()
    wd = threading.Thread(target=_face_track_watchdog, args=(wd_stop,),
                          daemon=True, name="face-track-watchdog")
    wd.start()
    reason = "returned normally"
    exc: BaseException | None = None
    try:
        _face_tracking_thread_body()
        # A return WITHOUT the stop event is not a shutdown, it is a defect -
        # and it used to be indistinguishable from a healthy exit in the log.
        reason = ("stop event set (normal shutdown)"
                  if _face_track_stop.is_set()
                  else "the producer loop RETURNED without the stop event set "
                       "(e.g. no cameras could be opened)")
    except BaseException as e:
        exc = e
        reason = f"unhandled {type(e).__name__}: {e}"
        raise
    finally:
        wd_stop.set()
        _face_track_release_all(_face_track_caps[0])
        # Camera is fully off now - drop the HUD preview frame so it doesn't
        # linger (moved here from the body so it runs on EVERY exit path).
        try:
            _hud_camera_preview_remove()
        except Exception:
            logging.exception("[face-track] preview remove on shutdown")
        _face_track_beat("stopped")
        _face_track_note_stopped(reason, exc)


def _face_tracking_thread_body():
    """
    Multi-camera attention tracking:
      • Primary camera sees you → track face position precisely
      • Only a side camera sees you → look toward that camera's preset
      • No one sees you → eyes drift back to centre
    """
    global _smooth_x, _smooth_y, _last_sent_x, _last_sent_y
    SMOOTH   = 0.12   # primary-cam tracking smoothness
    SNAP     = 0.18   # side-cam snap-to-direction smoothness
    DRIFT    = 0.015  # drift back to centre when no face
    MIN_MOVE = 0.02
    # If c.read() returns False this many times in a row, the capture is
    # presumed wedged (Teams stole the cam, USB hub flickered, DirectShow
    # driver returned half-init Mat headers). Release and reopen instead of
    # continuing to call .read() on a dead handle (heap-corrupting on Logitech).
    MAX_READ_FAILURES = 60
    # LIVE CAMERA-CONTENTION YIELD (P1-3): when a camera won't reopen AND a known
    # webcam-locking app (Teams / Zoom / OBS …) is running, the device isn't
    # coming back until that app releases it — so widen THIS entry's reopen
    # backoff to ~30 s instead of retrying every 2 s, to stop hammering
    # DirectShow (each failed CAP_DSHOW open churns the driver) while it's locked.
    # Reset to the normal backoff the moment the locker disappears. BOTH values
    # and the whole decision live in _schedule_camera_reopen at MODULE scope —
    # there is exactly ONE writer of entry["next_reopen_at"]; never re-inline it.
    # Self-diag 2026-05-29: bumped WAKE_AFTER from 10→25 and added a wall-
    # clock gate (WAKE_AFTER_SEC) after observing the right webcam log a
    # "read failure #1 → woke via release+reopen" burst roughly every 30 s.
    # The pattern is a brief USB power-save blip — the device returns no
    # frame for ~1 s, then resumes on its own. Kicking it via release+reopen
    # at fail-count 10 (~0.5-1 s of downtime) churns the driver pointlessly
    # and is the leading suspect for the silent crash cascade. We now require
    # both ~25 consecutive failed reads AND at least 2 s elapsed since the
    # last good frame before triggering the soft wake, so transient blips
    # heal themselves silently.
    WAKE_AFTER          = 25
    WAKE_AFTER_SEC      = 2.0   # AND require >= this many seconds of silence
    WAKE_BACKOFF_SEC    = 3.0   # don't wake more than once per ~3 s
    # Only log once we're past WAKE_AFTER (i.e. about to act). A USB power-
    # save blip resolves in <1 s and shouldn't leave any trace in the log.
    LOG_FIRST_AT_FAILS  = 25
    LOG_EVERY_N_FAILS   = 25    # then every Nth fail beyond that

    def _open_capture(cam):
        # `cam` is the CAMERAS dict (or, for back-compat, a bare int index).
        # A slot is a Kinect source when it carries {"type": "kinect"} OR the
        # global KINECT_AS_CAMERA opt-in is on — in either case we hand the
        # loop a kinect_bridge.KinectCapture, which exposes the same
        # .read()->(ret,bgr) / .release() contract as cv2.VideoCapture, so the
        # rest of _face_tracking_thread is unchanged. The Kinect runtime is a
        # shared singleton, so this never collides with cv2's DirectShow heap.
        if isinstance(cam, dict):
            idx = cam["index"]
            cam_name = cam.get("name")
            # KINECT_AS_CAMERA must not HIJACK a NAMED webcam entry: with the
            # flag on and a HEALTHY Kinect, BOTH webcam slots silently became
            # Kinect color streams and the real webcams went unread (live
            # 2026-07-10 — every "individual" camera tile showed the same
            # Kinect view; masked for weeks because a wedged Kinect fell back
            # to the webcams anyway). The flag now only lets kinect-typed or
            # UNNAMED entries use the sensor.
            want_kinect = (cam.get("type") == "kinect"
                           or (KINECT_AS_CAMERA and not cam_name))
        else:
            idx = cam
            cam_name = None
            want_kinect = KINECT_AS_CAMERA
        # LIVENESS (2026-09-05). EVERYTHING below this line can block ON THE
        # PRODUCER THREAD: the friendly-name DirectShow enumeration, the Kinect
        # bridge open, and the bounded cv2 open itself. The initial
        # `for cam in CAMERAS` sweep has no other beat BETWEEN cameras - the
        # supervisor beats "starting" once and then nothing until the loop top -
        # so without this a two-camera boot could go quiet for two full open
        # windows and be reported as a wedge. _open_capture is a closure inside
        # the producer body, so this only ever runs on the producer thread.
        _face_track_beat(f"opening camera index {idx}")
        # NAME-BASED RESOLUTION (P0-1, the mic-shuffle bug class): if the entry
        # carries a "name", resolve the LIVE DirectShow index by that friendly-
        # name substring at OPEN time and PREFER it over the static "index". A USB
        # re-enumeration that shuffles indices would otherwise leave a wrong-but-
        # working index silently tracking the WRONG camera. The static index is
        # the FALLBACK, used only when the name doesn't resolve (pygrabber missing
        # / device unplugged). Never applies to a Kinect slot (no DSHOW index).
        if cam_name and not want_kinect:
            live_idx = _dshow_name_to_index(cam_name)
            if live_idx is not None:
                if live_idx != idx:
                    print(f"  [face-track] '{cam_name}' resolved to LIVE index "
                          f"{live_idx} (static was {idx}) — using live index "
                          f"(USB re-enumeration shuffle detected)")
                idx = live_idx
            else:
                print(f"  [face-track] '{cam_name}' did not resolve by name "
                      f"(pygrabber missing or device absent) — falling back to "
                      f"static index {idx}")
        if want_kinect:
            try:
                kc = _kinect_bridge.KinectCapture()
                if kc.isOpened():
                    print(f"  [face-track] Using Kinect v2 color stream as camera "
                          f"(index {idx})")
                    return kc
                print(f"  [face-track] Kinect requested but unavailable "
                      f"({kc._open_error}); falling back to webcam index {idx}")
            except Exception as e:  # pragma: no cover - defensive: bridge import/open glitch
                print(f"  [face-track] Kinect open failed ({e}); "
                      f"falling back to webcam index {idx}")
        # Serialize against probe-sweep / list-cameras / snapshot opens &
        # releases. Without this, an abandoned probe worker's eventual
        # release() can collide with this open or its failure-path
        # release() and trash DirectShow's heap.
        #
        # BOUNDED since 2026-09-05. This is the SAME call shape that was
        # measured wedged forever in _open_tile_capture - cv2.VideoCapture +
        # cap.set() on a sick device, under the process-wide camera lock - and
        # the session log shows this opener hitting that very device every ~10 s
        # ("opened usb 2.0 camera at index 0"). Which of the two wedged first
        # was luck. Neither is unbounded now.
        _label = cam_name if cam_name else (
            cam.get("label") if isinstance(cam, dict) else f"index {idx}")

        def _backend_open():
            with _camera_io_lock:
                # require_frame: this loop's whole job is frames. A handle that
                # opens and never delivers is worse than no handle - it is the
                # state that produces an endless read-failure cascade, and on
                # MSMF it is exactly what a device another process holds looks
                # like (measured 2026-09-05: isOpened() True, set() True,
                # get() reads back 1280x720, 0 of 20 reads produce anything,
                # while a DirectShow contender got an honest isOpened() ==
                # False). Returning None instead hands the caller the same
                # "couldn't open" it already knows how to back off from.
                return _camera_open(idx, name=cam_name,
                                    width=_LOOP_OPEN_WIDTH,
                                    height=_LOOP_OPEN_HEIGHT,
                                    require_frame=_LOOP_OPEN_FRAME_BUDGET_S,
                                    label=str(_label))

        # beat= is what lets _FACE_TRACK_STALL_WARN_S (30 s) legally sit BELOW
        # this 35 s cap - see _CAMERA_OPEN_BEAT_INTERVAL_S. Only the producer
        # thread may pass it, and this closure only ever runs there.
        c = _open_capture_bounded(idx, _backend_open, label=_label,
                                  timeout=_CAMERA_LOOP_OPEN_TIMEOUT_S,
                                  beat=_face_track_beat)
        if c is not None:
            # ANNOUNCED HERE, BY THE JOINER, AND ONLY FOR A HANDLE THIS CALL
            # HANDS BACK TO THE LOOP. It used to be printed inside _dshow_open,
            # i.e. on the worker, before _open_capture_bounded's _run checks
            # `abandoned` — so an ABANDONED open still printed "opened <cam> at
            # index N" moments AFTER "Abandoning the attempt…", for a capture
            # _run then released and threw away. Worse, it landed LAST, so it
            # read as the camera having come back. That line is the one the
            # 01:22 timeline was reconstructed from ("read failure #25 ->
            # opened -> woke"); it has to mean the producer holds this capture,
            # and nothing else.
            # Still covers the initial open AND every reopen / wake path (they
            # all come through _open_capture), which the one-shot 'Opened …'
            # line below does not, and still reads back the index we actually
            # opened so a name→index shuffle stays VISIBLE.
            print(f"  [face-track] opened {_label} at index {idx}")
        return c

    # Open all configured cameras at HD. Each entry is a mutable dict so
    # individual captures can be released & reopened independently mid-loop.
    caps: list[dict] = []
    # Published so the SUPERVISOR's finally can release these handles even when
    # this body never returns normally (a BaseException used to skip the whole
    # release sweep below).
    _face_track_caps[0] = caps
    for cam in CAMERAS:
        c = _open_capture(cam)
        if c is not None:
            caps.append({"cam": cam, "cap": c, "fails": 0,
                         "next_reopen_at": 0.0, "next_wake_at": 0.0,
                         # P1-3 camera-contention yield: True once we've logged
                         # the actionable "a locker holds this cam" hint for this
                         # entry, so it stays one-time until the locker clears.
                         "contention_logged": False})
            w = int(c.get(cv2.CAP_PROP_FRAME_WIDTH))
            h = int(c.get(cv2.CAP_PROP_FRAME_HEIGHT))
            print(f"  [face-track] Opened {cam['label']} (index {cam['index']}) at {w}x{h}")
        else:
            print(f"  [face-track] Could not open {cam['label']} (index {cam['index']}) — skipping")

    if not caps:
        print(f"  [face-track] No cameras available. Try: --list-cameras")
        _hud_camera_preview_remove()   # no camera → ensure no stale preview frame
        return

    primary_seen_recently = 0.0   # timestamp of last primary detection

    while not _face_track_stop.is_set():  # pragma: no cover - live-capture daemon loop (per-frame camera read/detect/smooth, runs until stop)
        try:
            # LIVENESS. One beat per iteration, plus finer-grained beats around
            # the calls that can block in C (below). The watchdog thread turns a
            # missing beat into a loud log line WITH this thread's stack - the
            # diagnostic whose absence made a wedged webcam look like three
            # dead cameras and a hardware fault.
            _face_track_beat_iteration()
            # Always read from cameras so the latest frames stay fresh for see_user,
            # even when the tracker is paused (e.g. during speaking/listening).
            paused = _face_track_pause.is_set()
            # camera_off is the *separate* signal for genuinely-off states. The
            # voice-time `paused` case deliberately does NOT set it — the camera
            # stays visibly ON while JARVIS listens/talks; only heavy detection
            # stops. It IS set for the real camera-off states the brief requires
            # to keep blanking the preview:
            #   • the explicit event (_face_track_camera_off) — the hook the
            #     KINECT_REVIEW P0 low-memory guard sets when host RAM/VRAM is
            #     exhausted, so we stop mirroring HD frames under memory pressure;
            #   • standby / empty room (_standby_mode) — JARVIS is parked, so the
            #     HUD shows its 'CAMERA OFF' placeholder rather than a live feed.
            camera_off = (_face_track_camera_off.is_set()
                          or bool(_standby_mode[0]))

            # HUD camera preview: blank it ONLY when the camera is genuinely off
            # (camera_off) or the feature is disabled — NOT merely because we're
            # paused for voice. Removing the temp file makes the HUD fall back to
            # its 'camera off' placeholder and leaves nothing lingering on disk.
            # The per-frame write for the primary camera happens below.
            if camera_off or not _hud_camera_preview_enabled():
                _hud_camera_preview_remove()
                # SIDE-TILE LEAK FIX (2026-07-08): the composite's persistent
                # side-tile webcam handles are released by _hud_kinect_preview_
                # write ONLY on the skeleton-overlay on→off edge. Entering
                # camera_off (low-mem/standby) or HUD-preview-disabled ALSO stops
                # the composite, but _hud_kinect_preview_write is no longer called
                # in this state, so the tiles would stay open and leak. Release
                # them here on entry to ANY composite-stopping state; the helper's
                # flag guard makes it fire once, not every frame.
                _release_side_tile_webcams_if_open()

            # Read all cameras, run face detection on each
            primary_face = None
            side_hits: list[tuple[float, float]] = []
            # SHARED-PREVIEW PUBLISH BOOKKEEPING (2026-09-05). The single HUD
            # preview JPEG is written ONLY from the `cam["primary"]` branch far
            # below, which lives INSIDE this per-camera loop and therefore
            # behind every `continue` above it - the quarantine bench, the
            # reopen backoff, the failed reopen, the wake-path bench. So a
            # benched or backing-off PRIMARY silently stopped the whole HUD
            # camera tile, not just its own. These two carry the state the
            # post-loop keep-alive needs to publish anyway.
            #   primary_published - the primary reached the publisher branch.
            #   preview_fallback  - (cam, frame) of a HEALTHY non-primary that
            #                       produced a real frame this iteration.
            primary_published = False
            preview_fallback: tuple[dict, "np.ndarray"] | None = None

            now_loop = time.time()
            for entry in caps:
                cam = entry["cam"]
                c = entry["cap"]
                # QUARANTINE GATE (2026-09-05). A camera that has needed
                # rescuing _CAMERA_QUARANTINE_STRIKES times in a row is BENCHED:
                # not read, not woken, not reopened, and - critically - not
                # opened by the side-tile compositor either. Its own tile goes
                # dark; every other camera keeps publishing. Retrying it forever
                # is what walked the producer into a wedged DirectShow open.
                # NOTE: this `continue` also skips the SHARED preview write far
                # below (it is gated on cam["primary"]), which is why the
                # post-loop keep-alive at the bottom of this loop exists.
                if _camera_is_quarantined(cam["index"], now_loop):
                    if c is not None:
                        _release_capture_guarded(c, cam["index"], cam["label"])
                        entry["cap"] = None
                    continue
                _face_track_beat(f"camera {cam['index']}")
                # Recovery path: capture was released after too many failures.
                # Try to reopen if backoff window has elapsed.
                if c is None:
                    if now_loop < entry["next_reopen_at"]:
                        continue
                    _face_track_beat(f"reopen camera {cam['index']}")
                    new_c = _open_capture(cam)
                    if new_c is None:
                        # RE-EVALUATE contention on EVERY failed reopen. This
                        # line used to hardcode the 2 s spacing, silently
                        # overwriting the 30 s contention yield one tick after
                        # the wedge branch armed it. Fresh clock on purpose: an
                        # unavailable CAP_DSHOW index can block _open_capture
                        # for 20-30 s, so an already-stale loop-top timestamp
                        # would arm a window that has already expired.
                        _schedule_camera_reopen(entry, cam["label"],
                                                cam["index"])
                        continue
                    entry["cap"] = new_c
                    entry["fails"] = 0
                    entry["next_reopen_at"] = 0.0
                    entry["contention_logged"] = False
                    print(f"  [face-track] Reopened {cam['label']} (index {cam['index']}) after recovery")
                    c = new_c

                _face_track_beat(f"read camera {cam['index']}")
                _read_t0 = time.perf_counter()
                ret, frame = c.read()
                _read_ms = (time.perf_counter() - _read_t0) * 1000.0
                with _camera_state_lock:
                    _camera_read_ms[cam["index"]] = _read_ms
                if _read_ms >= _CAMERA_SLOW_READ_WARN_MS:
                    _warn_slow_camera_read(cam["label"], cam["index"],
                                           _read_ms, now_loop)
                if not ret:
                    entry["fails"] += 1
                    # Record the failure so see_user / self-diagnostic can
                    # surface "camera went silent N seconds ago" instead of
                    # just guessing. Single-line, throttled log so a stalled
                    # USB pipe can't drown the session log.
                    err_msg = "read returned no frame (cap.isOpened still True)"
                    with _camera_state_lock:
                        _camera_last_read_error[cam["index"]] = err_msg
                        _camera_last_read_error_at[cam["index"]] = now_loop
                    _note_camera_read_attempt(cam["index"], ok=False,
                                              fails=entry["fails"],
                                              error=err_msg)
                    last_good = _camera_last_frame_at.get(cam["index"], 0.0)
                    time_since_good = (now_loop - last_good) if last_good else -1.0
                    # Don't log USB power-save blips that resolve in <1 s.
                    # Only emit once we've crossed LOG_FIRST_AT_FAILS, then
                    # every Nth fail beyond that.
                    if (entry["fails"] >= LOG_FIRST_AT_FAILS
                            and entry["fails"] % LOG_EVERY_N_FAILS
                                == LOG_FIRST_AT_FAILS % LOG_EVERY_N_FAILS):
                        # BEFORE BLAMING THE CAMERA, COUNT THE RESTART.
                        # All 27 of these lines for the right webcam across the
                        # 8 restarts in session logs 2026-09-05_22-37-30 ..
                        # 2026-09-06_06-12-11 were classified 2026-09-06: 8 at
                        # camera-open +7..13 s (one per restart, NO scheduler
                        # line), 8 at the self-diag boot sweep, 11 at a
                        # 30-minute interval sweep, 0 left over. So a restart
                        # produces TWO of these inside 90 s, "every failure is
                        # the 30-minute probe" is wrong by exactly one per
                        # restart, and a debugger who greps for a scheduler
                        # entry behind the +9 s line, finds none, and concludes
                        # the USB device is failing has taken the wrong turn.
                        # Which call site opened the camera is answerable from
                        # the "[camera] <label>: opening with ..." lines - see
                        # _camera_backend_notes for why those went missing for
                        # every opener after the first, and what that hid. (The
                        # +9 s contender was the side tile's own-handle open;
                        # once it was gated, the 2026-09-06 07:55:26 restart
                        # logged NO boot-window failures at all.)
                        gap_str = (f"{time_since_good:.1f}s since last frame"
                                   if time_since_good >= 0 else "no good frame yet")
                        print(f"  [face-track] {cam['label']} (index {cam['index']}) "
                              f"read failure #{entry['fails']} — {gap_str}")
                    # Try a soft wake before escalating to the full reopen.
                    # Gate on BOTH consecutive-fail count AND wall-clock silence
                    # so a transient USB power-save blip (resolves in ~1 s) is
                    # tolerated without churning the driver.
                    if (entry["fails"] >= WAKE_AFTER
                            and time_since_good >= WAKE_AFTER_SEC
                            and now_loop >= entry["next_wake_at"]
                            and entry["fails"] < MAX_READ_FAILURES):
                        with _camera_state_lock:
                            _camera_wake_attempts[cam["index"]] = (
                                _camera_wake_attempts.get(cam["index"], 0) + 1)
                        # ONE strike per rescue cycle. A wake attempt IS a
                        # rescue: reaching it took 25 consecutive read failures
                        # AND 2 s of silence, so a USB power-save blip (resolves
                        # in <1 s) never scores. The measured death ran four of
                        # these cycles ~10 s apart before wedging; benching on
                        # the third fires ~25 s in, before that fourth cycle.
                        if _camera_note_sick_cycle(
                                cam["index"], cam["label"],
                                f"{entry['fails']} consecutive read failures; "
                                f"soft wake #{_camera_wake_attempts.get(cam['index'], 0)}",
                                now_loop):
                            entry["cap"] = None
                            _release_capture_guarded(c, cam["index"],
                                                     cam["label"])
                            continue
                        _face_track_beat(f"wake camera {cam['index']}")
                        # RELEASE inside the lock, REOPEN outside it. These
                        # used to share ONE `with _camera_io_lock:`, which
                        # DEADLOCKED the wake the moment the opener became
                        # bounded (2026-09-05): _open_capture now delegates to
                        # _open_capture_bounded, whose WORKER thread takes
                        # _camera_io_lock itself. That lock is an RLock -
                        # reentrant for the SAME thread only - so a producer
                        # parked in t.join() while holding it could never let
                        # the worker in. Measured, with no camera involved: the
                        # reopen returned None after the full
                        # _CAMERA_LOOP_OPEN_TIMEOUT_S every single time, froze
                        # all three tiles past _CAMERA_PREVIEW_STALE_S while it
                        # sat on the process-wide lock, and blamed a device
                        # that had never even been reached - killing the
                        # "woke via release+reopen" recovery outright. The lock
                        # still covers every open and every release; it is just
                        # taken by the code that performs them, never held by
                        # this thread across a join.
                        _release_capture_guarded(c, cam["index"], cam["label"])
                        # The old handle is now released — NEVER touch it
                        # again. Drop it from entry so that if the reopen
                        # below fails, the next loop iteration takes the
                        # recovery path (c is None → _open_capture) and
                        # re-opens cleanly instead of calling .read() on a
                        # RELEASED handle, which is heap corruption /
                        # 0xc0000374. 2026-05-30 deep audit.
                        entry["cap"] = None
                        new_c = None
                        woke_ret, woke_frame = False, None
                        time.sleep(0.15)
                        try:
                            # Use the shared name-resolving opener (the same
                            # one the initial + recovery opens use) rather
                            # than a raw cv2.VideoCapture on the STATIC
                            # cam["index"]. A USB re-enumeration can move the
                            # device to a new live index, so the static index
                            # would silently wake the WRONG camera (or a
                            # random webcam where the Kinect belongs),
                            # bypassing _dshow_name_to_index and the Kinect
                            # branch. This is exactly the mic/USB-shuffle
                            # event the name resolution exists to survive.
                            new_c = _open_capture(cam)
                            if new_c is not None and new_c.isOpened():
                                # NO cap.set() HERE ANY MORE (2026-09-05).
                                # _open_capture already applies 1280x720 and
                                # BUFFERSIZE=1 inside _camera_open, under
                                # _camera_io_lock and inside the bounded open
                                # worker. Repeating them here was redundant in
                                # every case and actively bad in the one that
                                # matters: these three ran OUTSIDE the lock and
                                # OUTSIDE the bound, on a device that had just
                                # failed 25 reads in a row - and an unbounded
                                # cap.set() on a sick camera is the exact call
                                # that wedged the producer for two hours
                                # (see _open_tile_capture). On MSMF each set()
                                # measures 0.35-0.50 s, so this also removes
                                # ~1 s of latency from every wake attempt.
                                # Warmup frame — first read often comes back
                                # empty even on a healthy reopen. Read OUTSIDE
                                # _camera_io_lock, like every other read in this
                                # file: holding it across a blocking cap.read()
                                # is the whole-subsystem hang already documented
                                # in _face_track_frame_for_slot.
                                try:
                                    new_c.read()
                                except Exception:
                                    pass
                                woke_ret, woke_frame = new_c.read()
                            else:
                                if new_c is not None:
                                    _release_capture_guarded(
                                        new_c, cam["index"], cam["label"])
                                new_c = None
                        except Exception:
                            # A DirectShow open/set/read on a half-init
                            # handle can raise — release the new handle so
                            # it can't leak; entry["cap"] stays None so the
                            # recovery path re-opens next iteration.
                            logging.exception("[face-track] wake reopen raised")
                            if new_c is not None:
                                _release_capture_guarded(
                                    new_c, cam["index"], cam["label"])
                            new_c = None
                            woke_ret, woke_frame = False, None
                        if new_c is not None and woke_ret and woke_frame is not None:
                            entry["cap"] = new_c
                            entry["fails"] = 0
                            with _camera_state_lock:
                                _camera_recoveries[cam["index"]] = (
                                    _camera_recoveries.get(cam["index"], 0) + 1)
                                _camera_last_read_error.pop(cam["index"], None)
                                _camera_last_read_error_at.pop(cam["index"], None)
                            print(f"  [face-track] {cam['label']} (index {cam['index']}) "
                                  f"woke via release+reopen")
                            # Use the wake's frame for this iteration so we
                            # don't waste a tick.
                            frame = woke_frame
                            ret   = True
                            c     = new_c
                        else:
                            entry["next_wake_at"] = now_loop + WAKE_BACKOFF_SEC
                            if new_c is not None:
                                # We managed to reopen but still no frame —
                                # the device is genuinely unresponsive. Keep
                                # the new handle so the MAX_READ_FAILURES
                                # branch below has something to release.
                                entry["cap"] = new_c
                                c = new_c
                            else:
                                # Both the wake's release AND the reopen
                                # failed. The original handle is already
                                # released; null out the entry so the
                                # recovery path (top of next iteration)
                                # takes over instead of touching a stale
                                # handle.
                                entry["cap"] = None
                                # Third copy of the flat-2s rule, deleted: this
                                # is the path a Teams-held camera actually takes
                                # (fails stalls at ~25-40, below
                                # MAX_READ_FAILURES), so it must consult
                                # contention too or the yield never runs at all.
                                _schedule_camera_reopen(entry, cam["label"],
                                                        cam["index"])
                                c = None
                    if not ret:
                        if entry["fails"] >= MAX_READ_FAILURES:
                            # Capture is wedged — release before .read() returns
                            # a half-initialized Mat and trashes the heap. Mark
                            # for reopen on the next loop after backoff.
                            if c is not None:
                                _release_capture_guarded(c, cam["index"],
                                                         cam["label"])
                            entry["cap"] = None
                            # A full wedge is unambiguously a failed rescue.
                            _camera_note_sick_cycle(
                                cam["index"], cam["label"],
                                f"capture wedged after {entry['fails']} "
                                f"failed reads", now_loop)
                            # LIVE CAMERA-CONTENTION YIELD (P1-3) — the decision
                            # (and the one-time "appears LOCKED by ..." hint) lives
                            # in _schedule_camera_reopen so the recovery and
                            # soft-wake paths can no longer undo it. _backoff is
                            # what was ACTUALLY armed, so the log line below,
                            # which used to promise 30 s and then quietly retry at
                            # 2 s, is now true.
                            _backoff, lockers = _schedule_camera_reopen(
                                entry, cam["label"], cam["index"], now_loop)
                            with _camera_state_lock:
                                _camera_last_read_error[cam["index"]] = (
                                    f"capture wedged after {entry['fails']} read failures"
                                    f" + {_camera_wake_attempts.get(cam['index'], 0)} wake attempts"
                                    + (f" (locked by {', '.join(lockers)})" if lockers else ""))
                                _camera_last_read_error_at[cam["index"]] = now_loop
                            print(f"  [face-track] {cam['label']} (index {cam['index']}) "
                                  f"dead after {entry['fails']} failed reads; will reopen in {_backoff:.1f}s")
                        # PREVIEW-KEEP-ALIVE FIX: a Kinect read MISS must NOT skip
                        # the skeleton preview write. The Kinect IS the primary
                        # "camera" on the owner's rig, so a transient color miss
                        # used to bare-`continue` past the preview write below,
                        # freezing then blanking the skeleton tile. Instead, still
                        # attempt the Kinect preview write for the primary camera
                        # (its require_new=False / cached-color fallback re-serves
                        # the last frame, keeping the tile alive) before continuing.
                        if (cam["primary"] and not camera_off
                                and _hud_camera_preview_enabled()):
                            try:
                                # The RETURN VALUE, not merely "we got here".
                                # A read miss means the primary has NO frame, so
                                # the composite is the only thing that can
                                # publish for it - and on the live rig the
                                # composite is OFF (KINECT_ENABLED=False), so
                                # this returns False and NOTHING was written.
                                # Recording True here would suppress the
                                # post-loop keep-alive and leave the tile dark
                                # in exactly the owner's fault mode: a camera
                                # that OPENS FINE every 10 s and then never
                                # delivers a frame.
                                primary_published = bool(
                                    _hud_kinect_preview_write(now_loop))
                            except Exception:
                                logging.exception(
                                    "[face-track] kinect preview write on read-miss failed")
                        continue
                entry["fails"] = 0
                _note_camera_read_attempt(cam["index"], ok=True)
                # A real frame is the only proof of health there is - the sick
                # camera OPENED fine every 10 s and still delivered nothing, so
                # nothing short of a frame may clear the strikes.
                _camera_note_healthy(cam["index"], cam["label"])
                # Cache frame for see_user action regardless of face detection
                with _camera_state_lock:
                    _camera_latest_frame[cam["index"]] = frame.copy()
                    _camera_last_frame_at[cam["index"]] = now_loop
                    # A real frame means whatever transient error we recorded
                    # has resolved — clear it so see_user reports clean state.
                    if cam["index"] in _camera_last_read_error:
                        _camera_last_read_error.pop(cam["index"], None)
                        _camera_last_read_error_at.pop(cam["index"], None)
                # Per-camera preview: EVERY webcam publishes its own tile (the
                # web Camera tab shows each eye individually); the primary-only
                # composite below is unchanged. Same enable gate + throttle
                # family as the main preview. 2026-07-10.
                if not camera_off and _hud_camera_preview_enabled():
                    _hud_percam_preview_write(_percam_side(cam), frame, now_loop)
                # Remember the first HEALTHY non-primary frame of this
                # iteration. It is what the post-loop keep-alive publishes to
                # the SHARED preview when the primary is benched/backing off
                # and the Kinect composite is unavailable (the live rig runs
                # KINECT_ENABLED=False, so the composite returns False there
                # and this fallback is the ONLY thing that keeps the HUD
                # camera tile alive). Never silent: the keep-alive logs which
                # camera it substituted.
                if not cam["primary"] and preview_fallback is None:
                    preview_fallback = (cam, frame)
                # Mirror the PRIMARY camera's live frame to the HUD preview file
                # (a small overwriting JPEG). We write it whenever the primary
                # camera is producing frames — INCLUDING while paused for voice
                # (listening/thinking/speaking) — so the HUD camera tile stays
                # visibly ON and the air-mouse/gaze keep getting frames. We only
                # stop when the camera is genuinely off (low-memory/standby, via
                # camera_off, handled above) or the feature is disabled. Gated by
                # HUD_CAMERA_PREVIEW.
                if (cam["primary"] and not camera_off
                        and _hud_camera_preview_enabled()):
                    # THE MEASURED WEDGE POINT lives under here
                    # (_hud_kinect_preview_write -> _compose_kinect_preview ->
                    # _read_side_tile_webcams -> _open_tile_capture), so beat
                    # with that stage name: the watchdog's stall line then says
                    # exactly which call never came back.
                    _face_track_beat("kinect composite preview write")
                    # PART A: prefer the Kinect color + LIVE SKELETON composite
                    # (incl. the two webcam tiles) when the overlay is enabled +
                    # the Kinect is streaming; it returns False when off/no
                    # frame, so we fall back to the plain primary-webcam mirror
                    # and the HUD tile is never left blank.
                    if not _hud_kinect_preview_write(now_loop):
                        _hud_camera_preview_write(frame, now_loop)
                    primary_published = True
                if paused:
                    # Skip the HEAVY cv2 face detection + eye-control servo math
                    # while paused for voice — that recognition cost is what the
                    # pause exists to save. The camera/preview above already kept
                    # the tile live, so the HUD never shows 'CAMERA OFF' merely
                    # because JARVIS is listening or speaking.
                    continue
                try:
                    face = _detect_face(frame)
                except cv2.error:
                    # An OpenCV-internal failure (e.g. an OpenCL/GPU hiccup, or a
                    # malformed frame) used to unwind the whole tracking thread
                    # with a traceback every iteration. Degrade to "no face this
                    # frame" and back off briefly so we don't hot-loop the error.
                    logging.exception("[face-track] _detect_face failed; skipping frame")
                    time.sleep(0.5)
                    continue
                if not face:
                    continue
                # Record that this specific camera just saw a face
                with _camera_state_lock:
                    _camera_last_seen[cam["index"]] = now_loop
                if cam["primary"]:
                    primary_face = face
                else:
                    side_hits.append((cam["look_x"], cam["look_y"]))

            # SHARED-PREVIEW KEEP-ALIVE (2026-09-05). THE DEFECT THIS CLOSES:
            # the single HUD camera preview is published from ONE branch that
            # sits inside the per-camera loop above and is gated on
            # `cam["primary"]`. Every `continue` before it therefore takes the
            # WHOLE preview down, not just that camera's tile:
            #   * the quarantine bench  (a benched PRIMARY -> 60-600 s dark),
            #   * `now_loop < entry["next_reopen_at"]` (reopen backoff),
            #   * a failed reopen,
            #   * the wake path's own bench.
            # On the live rig the PRIMARY is index 2 (the eMeet C960), so the
            # very camera most likely to be stolen by Teams/Zoom is the one
            # whose bench blanked the HUD - the owner's original symptom, and
            # the reason the quarantine log line promising "every OTHER camera
            # keeps publishing" read as a lie. Publish from here instead when
            # the primary never reached its branch.
            #
            # Preference order, and NEVER silent about which one it used:
            #   1. the Kinect composite (needs no primary handle at all), then
            #   2. a healthy non-primary frame, announced as a substitution,
            #   3. nothing to publish - say so, with the reason.
            if (not primary_published and not camera_off
                    and _hud_camera_preview_enabled()):
                try:
                    _face_track_beat("shared preview keep-alive")
                    if not _hud_kinect_preview_write(now_loop):
                        if preview_fallback is not None:
                            _fb_cam, _fb_frame = preview_fallback
                            if _hud_camera_preview_write(_fb_frame, now_loop):
                                _note_preview_failover(_fb_cam, now_loop)
                        else:
                            _note_preview_starved(now_loop)
                except Exception:
                    # A preview fault must never be able to stop the producer -
                    # that is the entire bug class this file is defending.
                    logging.exception(
                        "[face-track] shared preview keep-alive failed")

            # Average all side cameras that see the face → handles "both cameras
            # see you" (= looking forward) gracefully.
            side_hit = None
            if side_hits:
                side_hit = (
                    sum(h[0] for h in side_hits) / len(side_hits),
                    sum(h[1] for h in side_hits) / len(side_hits),
                )

            # If we're paused, frames have been refreshed but skip the tracking math
            if paused:
                time.sleep(0.05)
                continue

            # Decide target eye position by priority
            global last_face_seen
            now = time.time()
            if primary_face:
                tx, ty = primary_face
                primary_seen_recently = now
                last_face_seen = now
                _smooth_x += SMOOTH * (tx - _smooth_x)
                _smooth_y += SMOOTH * (ty - _smooth_y)
            elif side_hit and (now - primary_seen_recently) > 0.4:
                # Primary has lost the face — follow the side camera
                tx, ty = side_hit
                last_face_seen = now
                _smooth_x += SNAP * (tx - _smooth_x)
                _smooth_y += SNAP * (ty - _smooth_y)
            else:
                _smooth_x += DRIFT * (0.5 - _smooth_x)
                _smooth_y += DRIFT * (0.5 - _smooth_y)

            if (abs(_smooth_x - _last_sent_x) > MIN_MOVE or
                    abs(_smooth_y - _last_sent_y) > MIN_MOVE):
                send(eyes_x=round(_smooth_x, 3), eyes_y=round(_smooth_y, 3))
                _last_sent_x = _smooth_x
                _last_sent_y = _smooth_y

            time.sleep(0.05)
        except Exception:
            logging.exception("[face-track] error in tracking loop iteration")
            time.sleep(0.1)

    # TEARDOWN MOVED (2026-09-05) to _face_tracking_thread's `finally` -
    # _face_track_release_all + _hud_camera_preview_remove + the stop line. As
    # plain statements HERE they ran only on a clean fall-through: a
    # BaseException (SystemExit) skipped all three and the producer vanished
    # without releasing a camera and without a single word in the log.


def get_monitors() -> list[tuple[int, int, int, int]]:
    """Detect all physical monitors via Win32. Returns [(x, y, w, h), ...]."""
    if sys.platform != "win32":
        return []
    import ctypes
    from ctypes import wintypes
    monitors = []
    MonitorEnumProc = ctypes.WINFUNCTYPE(
        ctypes.c_int, wintypes.HMONITOR, wintypes.HDC,
        ctypes.POINTER(wintypes.RECT), wintypes.LPARAM,
    )
    def _cb(hmonitor, hdc, lprect, lparam):
        r = lprect.contents
        monitors.append((r.left, r.top, r.right - r.left, r.bottom - r.top))
        return 1
    cb_proc = MonitorEnumProc(_cb)
    ctypes.windll.user32.EnumDisplayMonitors(0, 0, cb_proc, 0)
    return monitors


def list_monitors_cli():
    mons = get_monitors()
    if not mons:
        print("No monitors detected (or running on non-Windows).")
        return
    print(f"Detected {len(mons)} monitor(s):\n")
    for i, (x, y, w, h) in enumerate(mons):
        # Heuristic guess at which physical position it occupies
        if y < 0:
            guess = "ABOVE the others"
        elif y > 0:
            guess = "BELOW the others"
        elif x == 0:
            guess = "leftmost (likely primary)"
        elif x > 0:
            guess = f"to the right of x={x}"
        else:
            guess = f"to the LEFT of primary (x={x})"
        print(f"  [{i}] x={x:>5}, y={y:>5}, {w}x{h}   — {guess}")
    print("\nCopy these into the MONITORS dict at the top of the script.")
    print("Example:")
    print("  MONITORS = {")
    for i, (x, y, w, h) in enumerate(mons):
        name = ["middle", "right", "left", "top", "extra"][i] if i < 5 else f"mon{i}"
        print(f'      "{name}": ({x}, {y}, {w}, {h}),')
    print("  }")


def list_microphones():
    """Print all available audio input devices with their indexes."""
    print("Available microphones (input devices):\n")
    devices = sd.query_devices()
    default_in = sd.default.device[0] if sd.default.device else None
    for i, d in enumerate(devices):
        if d["max_input_channels"] > 0:
            marker = "  ← system default" if i == default_in else ""
            print(f"  [{i:>2}] {d['name']}  ({d['max_input_channels']} ch, "
                  f"{int(d['default_samplerate'])} Hz){marker}")
    print("\nTo use a specific mic, set MICROPHONE_INDEX at the top of the script.")


def list_speakers():
    """Print all available audio output devices with their indexes."""
    print("Available speakers (output devices):\n")
    devices = sd.query_devices()
    default_out = sd.default.device[1] if sd.default.device else None
    for i, d in enumerate(devices):
        if d["max_output_channels"] > 0:
            marker = "  ← system default" if i == default_out else ""
            print(f"  [{i:>2}] {d['name']}  ({d['max_output_channels']} ch, "
                  f"{int(d['default_samplerate'])} Hz){marker}")


# Device auto-switching state.
#
# "in"/"out" are the SELECTED indices. In the owner's follow-the-default
# configuration they hold the index of the device WINDOWS CURRENTLY CALLS THE
# DEFAULT, re-resolved on every refresh pass from a LIVE MMDevice read
# (_endpoint_device_identity). That is not a pin: the value is a RESULT of the
# current default, recomputed at most DEVICE_CHECK_INTERVAL after it moves, so
# it tracks the owner's Stream Deck instead of freezing on one device.
#
# None means "could not resolve — let sounddevice resolve the default at open
# time". CORRECTED 2026-08-21: None used to be the follow-the-default contract
# itself, on the belief that device=None re-resolves the default at every open.
# It does not. sounddevice maps device=None to Pa_GetDefaultInput/OutputDevice,
# a struct field each host API fills in ONCE inside Pa_Initialize, so device=
# None re-reads the SAME endpoint forever — the very freeze the reinit exists
# to break. Leaving the index None therefore followed the default JARVIS BOOTED
# ON, not the current one (proved live in
# session_2026-08-21_00-00-51.log). None is now the FALLBACK, kept because it
# is the best available answer on a host with no MMDevice API.
#
# "last_in_*"/"last_out_*" are TRACKING state for the change detector only —
# never used to open anything. Both the index AND the name are stored because
# MME truncates device descriptions to 31 characters, so two distinct endpoints
# routinely enumerate under an identical name and a name-only compare misses a
# real 4 → 3 switch entirely (defect D1, 2026-08-20).
#
# "last_in_endpoint"/"last_out_endpoint" hold the WINDOWS endpoint id that the
# tracked identity came from (None whenever that direction is pinned by
# MICROPHONE_INDEX/PREFERRED_* — then the default endpoint describes a
# different device and is not evidence about this one). They are what lets the
# change detector tell a real switch between two identically-named endpoints
# from a PortAudio renumbering. "last_default_endpoints" is the (render,
# capture) pair the follow-the-default trigger compares against, rebased ONLY
# after a real re-enumeration.
_device_cache = {"in": None, "out": None, "checked_at": 0.0,
                 "last_in_name": None, "last_out_name": None,
                 "last_in_index": None, "last_out_index": None,
                 "last_in_endpoint": None, "last_out_endpoint": None,
                 "last_default_endpoints": None,
                 "last_devices_signature": None,
                 "last_reenum_at": 0.0}

# Periodic FORCED PortAudio re-enumeration cadence (2026-07-14 bug-hunt, #4).
# The device signature is sourced from sd.query_devices(), whose result
# PortAudio FREEZES until the very sd._terminate()/_initialize() the signature
# gate is blocking — so a plugged/unplugged mic never changes the signature,
# the gate short-circuits forever, and mid-session USB hotplug auto-switch is
# DEAD in steady state. The literal fix (drop the gate) would reinit every
# DEVICE_CHECK_INTERVAL (4s) — constant destructive teardown churn + a
# 0xc0000374 window every 4s. Instead, keep the cheap 4s gate but force a real
# re-enumeration at most this often when the mic is idle, so hotplug is picked
# up within a few minutes without the churn.
DEVICE_REENUM_INTERVAL = 300.0
# Serializes _refresh_devices so two callers (e.g. listen loop + a skill)
# can't both be tearing PortAudio down at the same time, and so the wake-word
# pause/resume bracket around sd._terminate() isn't racing with concurrent
# sd.query_devices() calls coming from a peer refresh.
# LOCK DISCIPLINE (2026-08-14): when both are needed the order is ALWAYS
# _device_refresh_lock -> _mic_lock (the _pa_gate teardown-gate lock), never
# the reverse — see the matching note at _mic_lock's definition.
_device_refresh_lock = threading.Lock()


def _devices_signature():
    """Hashable snapshot of the current PortAudio device list.

    Used by _refresh_devices() to skip the destructive
    sd._terminate()/sd._initialize() cycle when nothing has actually
    changed. The reinit is what gives us USB hotplug detection but it is
    also what causes 0xc0000374 heap corruption against live streams
    (crash-fix-1 in jarvis_todo.md), so we only pay that cost when the
    device list legitimately differs from the last enumeration.

    Captures (index, name, in-channels, out-channels) per device so a
    plug/unplug that shifts indices, a renamed endpoint, or a capability
    change all force a fresh enumeration."""
    try:
        devices = sd.query_devices()
    except Exception:
        return None
    try:
        return tuple(
            (i, d.get("name", ""),
             d.get("max_input_channels", 0),
             d.get("max_output_channels", 0))
            for i, d in enumerate(devices)
        )
    except Exception:
        return None


# Speakable aliases for the endpoints the owner actually switches between from
# his Stream Deck. The generic parse below is technically correct but produces
# unspeakable strings for exactly these ('CORSAIR VOID ELITE Wireless Gaming
# Dongle'), and the follow-the-default announcement reads the result OUT LOUD
# ("Switched to <this>, sir."). Matched case-insensitively as a substring of the
# RAW description, so an MME-truncated variant still hits. Deliberately narrow:
# anything not listed here keeps the generic parse untouched (a broad 'speakers'
# entry would swallow 'Speakers (Realtek)' → 'Realtek', which callers like the
# boot sequence and suit_up rely on).
_FRIENDLY_DEVICE_ALIASES = (
    ("corsair",    "your headset"),
    ("void elite", "your headset"),
    ("snowball",   "the Blue Snowball"),
)

# Endpoint descriptions that carry NO brand at all once parsed. Spoken bare they
# read like a proper noun ("Switched to Speakers, sir"), so they get possessed.
_GENERIC_ENDPOINT_NAMES = {"speakers", "speaker", "headphones", "headset",
                           "microphone", "output", "input"}


def _parens_balanced(s: str) -> bool:
    """True when every ')' in `s` closes an earlier '(' and none are left open.
    Used by _friendly_device_name to tell a NESTED parenthetical
    ('Realtek(R) Audio' — keep whole) from two SIBLING ones
    ('2- USB) (Realtek' — the greedy span spilled across both)."""
    depth = 0
    for ch in s:
        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth < 0:
                return False
    return depth == 0


def _friendly_device_name(raw: str) -> str:
    """Speakable short name for a sounddevice description, e.g.
    'Microphone (USB Mic), MME' → 'USB Mic';
    'Headset Microphone (Gaming Headset), Windows DirectSound' → 'Gaming Headset';
    'Speakers (Realtek)' → 'Realtek';
    'Headset Microphone (CORSAIR VOID ELITE …)' → 'your headset' (alias table);
    'Speakers (2- USB Audio Device)' → 'USB Audio Device' (MME index prefix);
    'Speakers (DualSense Wireless Co' → 'DualSense Wireless Co' (MME cuts the
    description at 31 chars, closing paren included)."""
    if not raw:
        return ""
    low = raw.lower()
    for needle, alias in _FRIENDLY_DEVICE_ALIASES:
        if needle in low:
            return alias
    first = raw.split(",")[0].strip()
    # Trademark markers are noise the TTS reads out ("Realtek R Audio").
    name = re.sub(r"\((?:R|TM|C)\)", "", first, flags=re.I).strip()
    # Prefer the OUTERMOST parenthetical so a nested marker doesn't truncate the
    # brand: 'Speakers (Realtek(R) Audio)' must not become 'Realtek(R'. Falls
    # back to the first group when the greedy span isn't properly nested (two
    # sibling parentheticals, e.g. 'Microphone (2- USB) (Realtek)').
    m = re.search(r"\((.+)\)", name)
    if m and not _parens_balanced(m.group(1)):
        m = re.search(r"\(([^)]+)\)", name)
    if m:
        inner = m.group(1).strip()
    elif "(" in name and ")" not in name:
        # MME truncates at 31 characters, which routinely amputates the closing
        # paren ('Speakers (DualSense Wireless Co'). Take what survives.
        inner = name.split("(", 1)[1].strip()
    else:
        inner = ""
    if inner:
        name = inner
    else:
        for prefix in ("Headset Microphone ", "External Microphone ",
                       "Microphone ", "Headphones ", "Speakers "):
            if name.startswith(prefix):
                name = name[len(prefix):].strip() or name
                break
    # Windows/MME disambiguates duplicate endpoints with a '2- ' index prefix;
    # spoken, that becomes "two dash USB Audio Device".
    name = re.sub(r"^\d+-\s*", "", name).strip()
    name = name.strip(" ()").strip()
    if not name:
        # Nothing but punctuation survived ('Microphone ()') — fall back to the
        # endpoint's leading word, which the generic map below can possess.
        name = re.split(r"[\s(]+", first)[0].strip() or first
    if name.lower() in _GENERIC_ENDPOINT_NAMES:
        return f"your {name.lower()}"
    return name


# Speech-queue dedup state — protects _speak_pending against the looping
# notification bug where the same toast text lands in pending_speech.json
# repeatedly (because the notification listener loses its _seen_ids state
# on bounce). In-memory only: spans a single JARVIS lifetime, which is the
# window in which a runaway loop actually does damage. Window is wide
# enough to suppress a runaway flood but well under notification_triage's
# 300s SNOOZE_SECONDS so legitimate re-announcements still get through.
_RECENT_SPEECH_DEDUPE_WINDOW = 60.0
_recent_spoken_messages: dict[str, float] = {}
_recent_spoken_lock = threading.Lock()


def _speech_was_recently_spoken(message: str) -> bool:
    """Return True if `message` was spoken inside the dedupe window. Also
    prunes expired entries so the dict stays small."""
    now = time.time()
    cutoff = now - _RECENT_SPEECH_DEDUPE_WINDOW
    with _recent_spoken_lock:
        # Prune as we go — cheap and bounded by how many distinct messages
        # we speak per minute.
        for k in list(_recent_spoken_messages.keys()):
            if _recent_spoken_messages[k] < cutoff:
                del _recent_spoken_messages[k]
        last = _recent_spoken_messages.get(message, 0.0)
        return last >= cutoff


def _mark_speech_spoken(message: str) -> None:
    with _recent_spoken_lock:
        _recent_spoken_messages[message] = time.time()


# Serialises concurrent writers of pending_speech.json (see proactive_announce).
_pending_speech_lock = threading.Lock()


# ─── FOCUS MODE / do-not-disturb state (skills/focus_mode.py drives it) ──────
#
# WHY THIS LIVES HERE (in the monolith, not the skill): proactive_announce is
# the single chokepoint for ALL unsolicited speech (print milestones, weather,
# Teams nudges, timer reminders, self-diag…). The one clean place to HOLD that
# speech while the owner is heads-down is the top of proactive_announce — so the
# focus flag + the "missed" buffer must be readable from here without importing
# the skill (which may not have loaded, and which we must never hard-depend on).
# The skill flips these via the setters below; the gate reads them. Direct
# command responses call _speak() (not proactive_announce), so this gate
# suppresses ONLY unsolicited output — wake-word + command replies keep working.
#
# Single-element-list idiom (GIL-atomic read/write, no lock needed for a simple
# bool/float cell) matches the monolith's other runtime latches (_sleep_mode,
# _standby_mode, …). NEVER-RAISES is the contract: every helper below swallows
# its own errors and degrades to "focus off" so a bad focus state can never
# silence JARVIS or crash a daemon that announces.
_focus_mode  = [False]    # True while the owner is in a focus / DND block
_focus_until = [0.0]      # 0.0 = indefinite; else an epoch auto-resume time

# Bounded buffer of announcements suppressed WHILE focused, newest last. Each
# entry is a (message, source, ts) tuple. Capped so a chatty skill during a long
# focus block can't grow it unbounded; oldest dropped first. In-memory only:
# a crash mid-focus loses the recap, which is an acceptable tradeoff for zero
# extra disk churn on the hot proactive path (persistence is optional and left
# out on purpose — the recap is a nicety, not a durable record).
_FOCUS_MISSED_CAP = 50
_focus_missed_buffer: list = []
_focus_missed_lock = threading.Lock()
# Serialises the timed-block True→False expiry transition so concurrent daemon
# callers of focus_mode_active() can't double-build/double-announce the recap
# (2026-07-07 review). Distinct from _focus_missed_lock, which _build_focus_recap
# re-takes — sharing it would deadlock.
_focus_resume_lock = threading.Lock()


def focus_mode_active() -> bool:
    """True while a focus / do-not-disturb block is engaged.

    ALSO self-heals a TIMED block: if _focus_until has passed, this flips focus
    OFF and fires the resume-recap (so the owner hears what they missed even if
    the auto-resume Timer never ran — e.g. it was cancelled at shutdown, or the
    process was asleep). The recap-on-expiry is best-effort and guarded so this
    predicate — called on the hot proactive path — never raises.

    Kept lock-free for the common read (a plain bool/float cell); the expiry
    transition takes the missed-buffer lock only when it actually fires."""
    try:
        if not _focus_mode[0]:
            return False
        until = _focus_until[0]
        if until and time.time() >= until:
            # Timed block elapsed — resume now and announce the recap. Clearing
            # the flag BEFORE building the recap is deliberate: proactive_announce
            # is now un-gated, so the recap enqueues normally instead of being
            # swallowed back into the missed buffer.
            #
            # RESUME LATCH (2026-07-07 review, LOW): proactive_announce (hence this
            # predicate) is called from dozens of daemon timers/watchers, so two
            # threads can pass the expiry check at the same instant. Without a
            # latch BOTH flip the flag and BOTH build the recap — the missed-buffer
            # lock lets one drain it (the real recap) and hands the other an empty
            # buffer → a spurious "nothing came up" spoken alongside the real one
            # (or, racing a manual resume, the real recap lost). Serialise the
            # True→False transition on a dedicated lock (NOT _focus_missed_lock,
            # which _build_focus_recap re-takes — that would deadlock) so only the
            # thread that actually flips it builds + announces the recap.
            recap = None
            with _focus_resume_lock:
                if not _focus_mode[0]:
                    return False            # another thread already resumed
                _focus_mode[0]  = False
                _focus_until[0] = 0.0
                try:
                    recap = _build_focus_recap(clear=True,
                                               prefix="Focus time's up, sir")
                except Exception:
                    recap = None
            if recap:
                try:
                    proactive_announce(recap, source="focus_mode")
                except Exception:
                    pass
            return False
        return True
    except Exception:
        # Any unexpected error → behave as if focus is OFF (fail open: better to
        # let an announcement through than to strand the owner in silence).
        return False


def set_focus_mode(on: bool, *, until: float = 0.0) -> None:
    """Setter used by skills/focus_mode.py. `until` is an epoch auto-resume time
    (0.0 = indefinite). NEVER raises."""
    try:
        _focus_mode[0]  = bool(on)
        _focus_until[0] = float(until) if on else 0.0
    except Exception:
        pass


def focus_missed_count() -> int:
    """How many announcements are currently held. NEVER raises."""
    try:
        with _focus_missed_lock:
            return len(_focus_missed_buffer)
    except Exception:
        return 0


def focus_missed_snapshot() -> list:
    """A COPY of the held-announcement buffer (does NOT clear). NEVER raises."""
    try:
        with _focus_missed_lock:
            return list(_focus_missed_buffer)
    except Exception:
        return []


def clear_focus_missed() -> None:
    """Drop all held announcements. NEVER raises."""
    try:
        with _focus_missed_lock:
            _focus_missed_buffer.clear()
    except Exception:
        pass


def _build_focus_recap(*, clear: bool, prefix: str = "While you were focused, sir") -> str:
    """Summarise the missed buffer into one spoken sentence, e.g.
    "While you were focused, sir: 3 things — the print finished, a weather
    alert, and a Teams message." Caps the spoken length by naming only the first
    few and folding the remainder into a count. Optionally clears the buffer
    (the recap consumers pass clear=True so a second 'resume' doesn't repeat).
    Returns "" when nothing was missed. NEVER raises."""
    try:
        with _focus_missed_lock:
            items = list(_focus_missed_buffer)
            if clear:
                _focus_missed_buffer.clear()
    except Exception:
        items = []
    n = len(items)
    if n == 0:
        return f"{prefix} — nothing came up while you were focused."
    # Name the first few messages; trim each so the sentence stays speakable.
    NAMED = 3
    fragments = []
    for msg, _src, _ts in items[:NAMED]:
        frag = (msg or "").strip().rstrip(".")
        if len(frag) > 80:
            frag = frag[:77].rstrip() + "…"
        fragments.append(frag)
    noun = "thing" if n == 1 else "things"
    head = f"{prefix}: {n} {noun}"
    if not fragments:
        return head + "."
    remainder = n - len(fragments)
    if len(fragments) == 1:
        listed = fragments[0]
    else:
        listed = ", ".join(fragments[:-1]) + ", and " + fragments[-1]
    if remainder > 0:
        listed += f", plus {remainder} more"
    return f"{head} — {listed}."


def proactive_announce(message: str, source: str = "skill",
                       *, mood: str | None = None,
                       volume_scale: float = 1.0) -> bool:
    """Public proactive-speech API for skills.

    Skills that want JARVIS to speak something unprompted (print milestones,
    Teams nudges, timer reminders, etc.) should call this — it appends the
    message to pending_speech.json and the main listen loop will drain the
    queue at the next turn boundary. Returns True on successful enqueue.

    `source` is just a tag for the console fallback log so it's obvious which
    skill produced an announcement that couldn't be written to disk.

    `mood` (optional) is the voice_mood layer opt-in. When set, the drainer
    forwards it as mood= to _speak() so the queued utterance lands with the
    matching preset (urgent_clipped for VIP alerts, concerned_soft for
    self-diagnostic problems, etc.).
    """
    # ── FOCUS MODE GATE ──────────────────────────────────────────────────────
    # This is the whole point of focus / do-not-disturb: while the owner is
    # heads-down, DO NOT enqueue unsolicited speech. Instead HOLD it in the
    # bounded missed buffer so 'resume' / auto-resume can recap what he missed.
    # We return True so the caller believes it was handled (it was — deferred,
    # not dropped). Because this ONLY gates proactive_announce, direct command
    # responses (which call _speak) are untouched — wake-word + commands still
    # speak normally while focused. Gated on the config kill-switch so a bad
    # focus state can never permanently silence JARVIS: if the feature is off we
    # never even consult the flag. Wrapped so a bug here can never break the
    # (very hot) announce path — on any error we fall through and enqueue as
    # normal.
    try:
        # Read the flag FRESH from core.config (not the star-imported copy) so a
        # Settings toggle / user_settings.json override takes effect without a
        # restart — same live-read pattern the skills use.
        _focus_enabled = True
        try:
            import core.config as _cfg
            _focus_enabled = bool(getattr(_cfg, "FOCUS_MODE_ENABLED", True))
        except Exception:
            _focus_enabled = True
        if _focus_enabled and focus_mode_active():
            with _focus_missed_lock:
                _focus_missed_buffer.append((message, source, time.time()))
                if len(_focus_missed_buffer) > _FOCUS_MISSED_CAP:
                    del _focus_missed_buffer[:-_FOCUS_MISSED_CAP]
            return True
    except Exception:
        pass  # fail open — never let the focus gate break a real announcement
    # Serialise the whole read-modify-write. proactive_announce is called from
    # many daemon threads (timers, promises, Teams/weather/device-flap nudges);
    # without this two concurrent enqueues both read state N, both append, and
    # the later os.replace clobbers the earlier writer's entry — a silently
    # dropped announcement. The unique mkstemp temp already prevents tmp
    # collisions; this prevents the lost update.
    _pending_speech_lock.acquire()
    try:
        proj_dir   = os.path.dirname(os.path.abspath(__file__))
        queue_path = os.path.join(proj_dir, "pending_speech.json")
        data: list = []
        if os.path.exists(queue_path):
            try:
                with open(queue_path, "r", encoding="utf-8") as f:
                    raw = f.read().strip()
                if raw:
                    try:
                        decoded, _ = json.JSONDecoder().raw_decode(raw)
                        if isinstance(decoded, list):
                            data = decoded
                    except Exception:
                        data = []
            except Exception:
                data = []
        entry: dict = {"ts": time.time(), "message": message}
        if mood:
            entry["mood"] = mood
        if volume_scale != 1.0:
            # Per-utterance TTS volume (boss-mode / night-owl whisper). Lets the
            # volume_scale co-writers route through this single locked path
            # instead of doing their own unsynchronised pending_speech.json writes.
            entry["volume_scale"] = float(volume_scale)
        data.append(entry)
        # Cap the pending-speech queue. Every enqueue rewrites the whole file
        # (O(n²)); a lagging drainer or a chatty skill (timer reminders,
        # device-flap alerts, Teams nudges) must not grow it unbounded. Keep
        # the most recent 50 announcements. 2026-05-30 audit.
        if len(data) > 50:
            data = data[-50:]
        fd: int = -1
        tmp: str | None = None
        try:
            fd, tmp = tempfile.mkstemp(dir=proj_dir, suffix=".tmp")
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                fd = -1   # fdopen took ownership of the descriptor
                json.dump(data, f, indent=2)
            os.replace(tmp, queue_path)
            tmp = None
        except Exception:
            if fd >= 0:
                try: os.close(fd)
                except Exception: pass  # pragma: no cover - defensive: os.close of an owned descriptor effectively never raises
            if tmp is not None:
                try: os.unlink(tmp)
                except Exception: pass
            raise
        return True
    except Exception as e:
        # Read-only share, full disk, perms — surface the message to console so
        # the announcement isn't silently lost.
        print(f"  [{source}] speech-queue write failed ({e}); announcement: {message}")
        return False
    finally:
        _pending_speech_lock.release()


def _update_check_thread():
    """Background, throttled once-per-day update check. Sleeps briefly so it
    doesn't compete with the boot bring-up, then asks core.update_checker to
    compare this build to the latest GitHub release and, if a newer one exists,
    queue ONE spoken nudge via proactive_announce. Best-effort + total — any
    failure is swallowed so it can never affect the main loop. Started from
    main() (skipped in staging)."""
    try:
        time.sleep(45)  # let whisper load + the boot greeting finish first
        from core import update_checker as _uc
        _uc.boot_nudge(
            lambda m: proactive_announce(m, source="update_check"),
            enabled=UPDATE_CHECK_ENABLED,
        )
    except Exception as e:  # pragma: no cover - defensive; boot_nudge is total
        print(f"  [update_check] skipped: {e}")


def _enqueue_device_announcement(message: str) -> None:
    """Audio-device change notifier. Thin wrapper around proactive_announce()
    so the device-change call site keeps its dedicated `[audio]` log tag for
    the console-fallback path."""
    proactive_announce(message, source="audio")


def _wake_word_resume_or_report(det) -> bool:
    """Bring the wake-word detector back after a device refresh, or say so.

    2026-08-20 honest-failure fix. The call site was:

        try:
            paused_det.resume()
        except Exception as e:
            print(f"  [audio] wake-word resume failed: {e}")

    core/wake_word.Detector.resume() does not RAISE on failure — it clears
    _running and returns False — so that `except` was dead code for the only
    failure mode that actually happens, and the boolean was dropped on the
    floor. Once _running is clear, the pause site's `if det.is_running()` guard
    skips the detector on every later refresh, so nothing ever retries: one
    transient endpoint blip during a hotplug silently disarmed acoustic
    barge-in for the rest of the session. (Standby wake-word ACTIVATION is
    unaffected — that runs off the Whisper transcript and a separate
    _standby_wake_detector object — so the loss is real but bounded.)

    Two things the obvious fixes get wrong, hence this shape:
      * resume() cannot be retried. Its first line is `if not self._paused:
        return False`, and the failing path already cleared _paused before it
        failed. The retry has to be start(), which re-inits the engine and
        clears _stop_flag.
      * Clearing skill_wake_listener._detector does nothing: _refresh_devices
        never BUILDS a detector, it only pauses the one it finds. Setting it to
        None just guarantees it is never restarted.

    No sleeps and no retry loop: this runs with _device_refresh_lock held, and
    stalling here delays every get_input_device()/get_output_device() caller.
    Returns True when the detector is listening again."""
    ok = False
    try:
        ok = bool(det.resume())
    except Exception as e:
        print(f"  [audio] wake-word resume raised: {type(e).__name__}: {e}")
    if not ok:
        try:
            ok = bool(det.start())
        except Exception as e:
            print(f"  [audio] wake-word restart raised: "
                  f"{type(e).__name__}: {e}")
    if not ok:
        print("  [audio] WAKE-WORD DETECTOR IS DOWN after a device refresh "
              "— voice barge-in is disarmed until it is restarted")
        try:
            _enqueue_device_announcement(
                "The wake-word detector dropped during a device change, sir "
                "— barge-in is disarmed until you restart it.")
        except Exception as e:
            print(f"  [audio] wake-word down-announcement failed: {e}")
    return ok


def _input_openable(idx: int) -> bool:
    """True when an InputStream can actually be opened on `idx` at JARVIS's
    capture format (SAMPLE_RATE / mono / float32).

    _pick_device() gates input selection on this so a device that merely
    *enumerates* but cannot be opened is skipped in favour of the next
    preferred mic — instead of being selected and then failing the real
    InputStream open with -9996/-9994 and silently falling back to the
    system-default mic. Two cases this catches in practice:
      • a phantom endpoint left behind by a just-unplugged headset (some
        headsets linger in the device list for a beat after they drop);
      • a WDM-KS-only device (e.g. the Realtek USB adapter) whose exclusive
        endpoint won't honour 16 kHz, so the check raises 'format not
        supported'.
    check_input_settings only queries Pa_IsFormatSupported — it does not open
    a stream — so this is cheap and safe to call during a device refresh."""
    try:
        sd.check_input_settings(device=idx, samplerate=SAMPLE_RATE,
                                channels=1, dtype="float32")
        return True
    except Exception:
        return False


def _pick_device(preferred_names: list[str], want_input: bool) -> tuple[int | None, str]:
    """Find the first preferred device that's connected — and, for inputs,
    that can actually be opened at the capture format. Returns (index, name)
    or (None, '') if no preference matched a usable device.

    Scanning continues past an unopenable match (e.g. the WDM-KS variant of a
    device, or a phantom headset endpoint) so a lower-index dud never masks a
    higher-index, openable variant of the same or a lower-priority device."""
    try:
        devices = sd.query_devices()
    except Exception:
        return None, ""
    for pref in preferred_names:
        for i, d in enumerate(devices):
            name = d["name"]
            if pref.lower() not in name.lower():
                continue
            if want_input:
                if d["max_input_channels"] > 0 and _input_openable(i):
                    return i, name
            elif d["max_output_channels"] > 0:
                return i, name
    return None, ""


# ── Live Windows default-endpoint poll (follow-the-default, 2026-08-20) ────
# PortAudio CANNOT see a default-device change on its own. Pa_GetDefaultOutput
# Device() returns hostApis[Pa_GetDefaultHostApi()]->info.defaultOutputDevice —
# a STRUCT FIELD each host API fills in ONCE, inside Pa_Initialize. sd.default
# .device re-reads that field on every access (measured here: 0.00006 ms/call,
# and it resolves to concrete indices — [1, 7] = 'Microphone (Blue Snowball )'
# / 'Speakers (Realtek USB2.0 Audio)', not the Sound Mapper), but the value
# behind it is FROZEN until sd._terminate()/sd._initialize() runs. It is the
# same freeze DEVICE_REENUM_INTERVAL exists for on the hotplug side — which is
# why "re-resolve the identity on the 4 s cadence" cannot by itself make
# follow-the-default responsive: every re-resolution returns the same stale
# endpoint until a re-enumeration happens. The owner presses a Stream Deck key
# and JARVIS keeps using the old mic/speakers for up to DEVICE_REENUM_INTERVAL
# (300 s), then announces the switch minutes late.
#
# Windows itself answers LIVE, through the MMDevice API — the very COM
# interface audio/audio_switch.py uses to SET the default endpoint. This is the
# READER for that WRITER. Cost with the enumerator cached, measured on this
# machine: 1.15 ms (render) + 0.63 ms (capture) per poll, against 0.077 ms for
# a full sd.query_devices(); paid at most once per DEVICE_CHECK_INTERVAL (4 s)
# because _refresh_devices' own time gate fronts it. It opens NO device.
#
# eConsole is the role queried: it is the "preferred device" WMME reports
# through DRVM_MAPPER_PREFERRED_GET — the one PortAudio's own default follows —
# and every switcher in practice (audio_switch.py's SetDefaultEndpoint loop
# included) moves all three roles together.
#
# Endpoint ids ('{0.0.0.00000000}.{guid}') are also the only STABLE audio
# identity available here: they do not renumber like PortAudio indices and are
# not truncated at 31 characters like MME names, so they are what tells a real
# switch from a renumbering in the announcement guard below.
_WIN_ENDPOINT_MAX_SETUP_FAILS = 3
_win_endpoint_setup_fails = [0]
_win_endpoint_tls = threading.local()


def _win_endpoint_enumerator():
    """Per-THREAD MMDeviceEnumerator, or None when the MMDevice API isn't
    usable here. Never raises.

    Per-thread on purpose: COM apartments are per-thread, and _refresh_devices
    runs on whichever thread reached get_input_device()/get_output_device()
    first (main voice loop, ambient workers, the face tracker, diagnostic
    daemons). Sharing one apartment-threaded interface pointer across threads
    is the classic RPC_E_WRONG_THREAD bug; a threading.local sidesteps it
    without marshalling.

    STICKY: after _WIN_ENDPOINT_MAX_SETUP_FAILS setup failures the poll is off
    for the rest of the session — a machine without comtypes/pycaw must not pay
    a failing import every 4 s forever. It then degrades to exactly the
    pre-2026-08-20 behaviour (the DEVICE_REENUM_INTERVAL sweep), never to a
    wrong answer."""
    enum = getattr(_win_endpoint_tls, "enumerator", None)
    if enum is not None:
        return enum
    if _win_endpoint_setup_fails[0] >= _WIN_ENDPOINT_MAX_SETUP_FAILS:
        return None
    try:
        import comtypes
        from pycaw.pycaw import IMMDeviceEnumerator
        from pycaw.constants import CLSID_MMDeviceEnumerator
        try:
            # Refcounted and idempotent per thread. RPC_E_CHANGED_MODE (this
            # thread already joined the MTA) is not fatal — CoCreateInstance
            # below is what actually decides whether we can query.
            comtypes.CoInitialize()
        except Exception:
            pass
        enum = comtypes.CoCreateInstance(
            CLSID_MMDeviceEnumerator, IMMDeviceEnumerator,
            comtypes.CLSCTX_INPROC_SERVER)
        _win_endpoint_tls.enumerator = enum
        _win_endpoint_setup_fails[0] = 0
        return enum
    except Exception as e:
        _win_endpoint_setup_fails[0] += 1
        if _win_endpoint_setup_fails[0] >= _WIN_ENDPOINT_MAX_SETUP_FAILS:
            print(f"  [audio] Windows default-endpoint poll unavailable "
                  f"({type(e).__name__}: {e}) — follow-the-default falls back "
                  f"to the {DEVICE_REENUM_INTERVAL:.0f}s re-enumeration sweep")
        return None


def _win_default_endpoints() -> tuple[str | None, str | None]:
    """(default RENDER endpoint id, default CAPTURE endpoint id) as Windows
    reports them RIGHT NOW, or (None, None) when unavailable.

    A per-call failure (no default device at all because everything is
    unplugged, a transient COM error) returns (None, None) and drops the
    cached enumerator so the next pass rebuilds it — it does NOT count toward
    the sticky setup-failure budget, or a 12-second stretch with no audio
    hardware would disable the feature until restart. Never raises: this runs
    inside _refresh_devices, which the main loop depends on."""
    enum = _win_endpoint_enumerator()
    if enum is None:
        return (None, None)
    try:
        out_id = enum.GetDefaultAudioEndpoint(0, 0).GetId()   # eRender/eConsole
        in_id = enum.GetDefaultAudioEndpoint(1, 0).GetId()    # eCapture/eConsole
        return (out_id or None, in_id or None)
    except Exception:
        _win_endpoint_tls.enumerator = None
        return (None, None)


# ── Endpoint id → PortAudio index, WITHOUT a re-enumeration (2026-08-21) ───
# WHAT A DEFAULT-DEVICE MOVE ACTUALLY NEEDS, established by measurement on this
# machine rather than assumed:
#
#   • PortAudio's DEVICE LIST is frozen at Pa_Initialize, but the owner's
#     Stream Deck does NOT plug anything in — it moves the Windows default
#     BETWEEN endpoints that are already enumerated. Measured 2026-08-21 while
#     the live JARVIS was running: every ACTIVE MMDevice endpoint on this box
#     (Blue Snowball, CORSAIR VOID ELITE, Realtek USB2.0, both NVIDIA HDMI
#     sinks, the Xbox NUI array, the eMeet webcam) already had a row in the
#     FROZEN sd.query_devices() list. So the new device's INDEX is obtainable
#     without ever calling sd._terminate().
#   • What the re-enumeration uniquely provides is the refreshed value behind
#     `device=None` — Pa_GetDefaultInputDevice(), i.e.
#     hostApis[Pa_GetDefaultHostApi()]->defaultInputDevice. That is the DEFAULT
#     HOST API's own idea of the default. Measured: sd.default.hostapi is MME
#     (0) here, and MME's default_input_device/default_output_device were 1 and
#     6 — byte-identical to the endpoints MMDevice reports as the live
#     eConsole defaults ('Microphone (Blue Snowball )' / 'Headset Earphone
#     (CORSAIR VOID …)'). So resolving the LIVE endpoint's friendly name inside
#     the DEFAULT HOST API reproduces exactly the index a reinit would hand
#     `device=None` — which is why an explicit index here is a faithful
#     substitute for the teardown, not an approximation of it.
#   • The teardown therefore remains necessary for exactly ONE thing: a device
#     that is NOT in the frozen list (true USB hotplug). That is what
#     DEVICE_REENUM_INTERVAL and the signature check are for, and they are
#     untouched.
#
# Restricting the match to the DEFAULT HOST API is load-bearing twice over: it
# reproduces `device=None`'s answer as above, and it collapses the four
# duplicate rows every endpoint has (MME / DirectSound / WASAPI / WDM-KS) to
# the one PortAudio would itself have picked.
_win_endpoint_names: dict[str, str] = {}
_win_endpoint_names_lock = threading.Lock()


def _win_endpoint_friendly_name(endpoint_id: str | None) -> str | None:
    """Windows' friendly name for one endpoint id ('Speakers (Realtek USB2.0
    Audio)'), or None when it can't be read. Opens NO device — this is a
    property-store read on the endpoint object. Never raises.

    CACHED because a friendly name changes only when the owner renames the
    device in Sound settings, while this is consulted on every refresh pass.
    The cache is DROPPED BY THE CALLER whenever a cached name fails to resolve
    against the device list (see _endpoint_device_identity), so a rename costs
    one failed pass rather than needing a restart — the stale-duplicate rule
    applied to a cache instead of to code."""
    if not endpoint_id:
        return None
    with _win_endpoint_names_lock:
        hit = _win_endpoint_names.get(endpoint_id)
    if hit is not None:
        return hit
    enum = _win_endpoint_enumerator()
    if enum is None:
        return None
    try:
        from comtypes import GUID
        from pycaw.pycaw import PROPERTYKEY
        pk = PROPERTYKEY()
        # PKEY_Device_FriendlyName — the same string Sound settings shows and
        # the same string PortAudio builds its MME/WASAPI names from.
        pk.fmtid = GUID("{A45C254E-DF1C-4EFD-8020-67D146A850E0}")
        pk.pid = 14
        store = enum.GetDevice(endpoint_id).OpenPropertyStore(0)  # STGM_READ
        val = store.GetValue(pk)
        name = val.GetValue()
        try:
            val.clear()
        except Exception:
            pass
    except Exception:
        # Same policy as _win_default_endpoints: a per-call COM failure drops
        # the cached enumerator so the next pass rebuilds it, and does NOT
        # count against the sticky setup-failure budget.
        _win_endpoint_tls.enumerator = None
        return None
    if not isinstance(name, str) or not name:
        return None
    with _win_endpoint_names_lock:
        _win_endpoint_names[endpoint_id] = name
    return name


def _forget_endpoint_name(endpoint_id: str | None) -> None:
    """Drop one cached friendly name (the device was renamed, or the name no
    longer matches anything PortAudio enumerates)."""
    if not endpoint_id:
        return
    with _win_endpoint_names_lock:
        _win_endpoint_names.pop(endpoint_id, None)


def _endpoint_device_identity(endpoint_id: str | None,
                              want_input: bool) -> tuple[int | None, str]:
    """(index, name) of the PortAudio device that IS the Windows endpoint
    ``endpoint_id``, resolved against the EXISTING (frozen) enumeration — or
    (None, "") when it can't be resolved unambiguously.

    This is the whole cheap half of follow-the-default: it lets a Stream Deck
    press be ADOPTED on the next 4 s pass by opening an explicit index, with no
    sd._terminate()/sd._initialize() and therefore no 0xc0000374 window and no
    waiting for the mic to fall idle.

    MATCHING. Candidates are restricted to the DEFAULT HOST API (see the block
    comment above) and to the right direction. A candidate matches when its
    name equals the friendly name, or — because MME truncates descriptions to
    31 characters — when it is exactly 31 characters long and is a prefix of
    it.

    AMBIGUITY IS A FAILURE, NOT A COIN FLIP. Two endpoints sharing an
    MME-truncated 31-character name is a real configuration on this machine
    (defect D1), and picking the wrong one would open the WRONG microphone —
    strictly worse than today's stale-but-known device. More than one candidate
    therefore returns (None, ""), which degrades to exactly the pre-2026-08-21
    behaviour: device=None plus the re-enumeration path.

    Opens NO device and probes NO format: this runs on the refresh path while
    the owner's mic is live, so it must stay a pure lookup. A resolved index
    that turns out to be unopenable is already covered downstream —
    get_input_device() re-queries it and record_speech retries with
    device=None."""
    friendly = _win_endpoint_friendly_name(endpoint_id)
    if not friendly:
        return None, ""
    try:
        host = sd.default.hostapi
    except Exception:
        host = None
    if not isinstance(host, int) or isinstance(host, bool) or host < 0:
        return None, ""
    try:
        devices = list(sd.query_devices())
    except Exception:
        return None, ""
    hits: list[tuple[int, str]] = []
    for i, d in enumerate(devices):
        if not isinstance(d, dict):
            continue
        if d.get("hostapi") != host:
            continue
        chans = ("max_input_channels" if want_input else "max_output_channels")
        try:
            if int(d.get(chans, 0)) <= 0:
                continue
        except Exception:
            continue
        name = d.get("name") or ""
        if name == friendly or (len(name) == 31 and friendly.startswith(name)):
            hits.append((i, name))
    if len(hits) != 1:
        # Nothing matched → the endpoint is genuinely absent from the frozen
        # list (true hotplug, or a rename that invalidated the cached name), so
        # forget the name and let the re-enumeration path do its job. Several
        # matched → ambiguous, and silence beats the wrong mic.
        if not hits:
            _forget_endpoint_name(endpoint_id)
        return None, ""
    return hits[0]


def _default_device_identity(want_input: bool) -> tuple[int | None, str]:
    """(index, name) of the endpoint PORTAUDIO calls the default input
    (want_input=True) or output — for CHANGE DETECTION and ANNOUNCEMENT WORDING
    ONLY.

    "PortAudio calls", not "Windows calls": sd.default.device reads
    Pa_GetDefaultInput/OutputDevice, and those return a struct field frozen at
    Pa_Initialize time, so this lags a real default switch until the next
    sd._terminate()/sd._initialize(). Polling it faster changes nothing. The
    LIVE answer comes from _win_default_endpoints() above, which is what
    _refresh_devices uses to decide that a re-enumeration is due; this function
    then reports what PortAudio actually resolved, which is what every
    device=None stream open will use and therefore the right thing to announce.

    NOT THE FOLLOW-THE-DEFAULT PATH — the FALLBACK for it (corrected
    2026-08-21). The owner selects his mic and speakers from a Stream Deck,
    which moves the WINDOWS DEFAULT; JARVIS follows that through
    _endpoint_device_identity(), which resolves the LIVE endpoint id to a row in
    the current enumeration. This function is consulted only when that
    resolution fails, and then purely so the refresh loop can still SEE and NAME
    whatever PortAudio happens to be resolving. Its result must NEVER be written
    into _device_cache["in"]/["out"]: it is a STALE index by construction (the
    frozen struct field above), so caching it would pin JARVIS to the endpoint
    it booted on — which is exactly the bug the 2026-08-20 version shipped.

    Total by construction: sd.default.device may be a 2-tuple, None, or a
    non-subscriptable stub, and PortAudio reports 'no default' as -1. Every one
    of those maps to (None, "") so this can never raise into the device loop."""
    try:
        dflt = sd.default.device
        idx = dflt[0 if want_input else 1] if dflt else None
    except Exception:
        return None, ""
    if not isinstance(idx, int) or isinstance(idx, bool) or idx < 0:
        return None, ""
    try:
        info = sd.query_devices(idx)
        name = info.get("name", "") if isinstance(info, dict) else ""
    except Exception:
        name = ""
    return idx, (name or "")


def _device_name_present(name: str) -> bool | None:
    """Is `name` still in PortAudio's enumeration?

    True / False when the device list can be read, None when it can't (or is
    empty) — 'unknown', which callers must NOT treat as a loss. Used by
    _announce_device_change to tell a deliberate switch (previous endpoint still
    there, the owner just moved the default) from a genuine disappearance (the
    headset powered off). Read-only: no reinit, no stream open."""
    if not name:
        return None
    try:
        names = [d.get("name", "") for d in sd.query_devices()]
    except Exception:
        return None
    if not names:
        return None
    return name in names


def _announce_device_change(prev_name: str, new_name: str,
                            want_input: bool) -> None:
    """Speak an audio-device switch.

    NEUTRAL BY DEFAULT (2026-08-20). The owner drives his mic and speakers from
    a Stream Deck, so a change is normally DELIBERATE — narrating it as a fault
    ("your headset appears to have dropped off") was wrong on both directions of
    every intentional switch. The historical loss wording is kept for the one
    case that really is a loss: the previous endpoint is GONE from PortAudio's
    enumeration. That is decided from the DEVICE LIST, never from the name — a
    headset-shaped name is not evidence that the headset died, and 'unknown'
    (list unreadable) deliberately falls to the neutral line."""
    new_friendly = (_friendly_device_name(new_name)
                    or ("the fallback mic" if want_input
                        else "the default speakers"))
    if _device_name_present(prev_name) is False:
        prev_lower = (prev_name or "").lower()
        if "headset" in prev_lower or "headphone" in prev_lower:
            msg = (f"Switched to {new_friendly}, sir — "
                   f"your headset appears to have dropped off.")
        else:
            old_friendly = (_friendly_device_name(prev_name)
                            or ("the previous mic" if want_input
                                else "the previous speakers"))
            msg = (f"Switched to {new_friendly}, sir — "
                   f"{old_friendly} appears to have disconnected.")
    else:
        msg = f"Switched to {new_friendly}, sir."
    _enqueue_device_announcement(msg)


def _refresh_devices(force: bool = False):
    """Re-check preferred devices if enough time has passed.
    Logs a message when the active device changes.

    PortAudio caches its device list at sd._initialize() time; it never
    notices USB hotplug on its own. To pick up a freshly-plugged/unplugged
    mic mid-session we have to call sd._terminate() + sd._initialize().
    That call is hostile to any sd.InputStream that's already open: the
    teardown frees backing state out from under live callbacks (0xc0000374
    heap corruption — see crash-fix-1 in jarvis_todo.md).

    Three mitigations together make it safe:
      • _device_refresh_lock serializes concurrent refresh attempts and
        protects the critical section from peer sd.query_devices() callers.
      • The persistent wake-word InputStream is paused before re-init and
        resumed after.
      • The _pa_gate TEARDOWN GATE (2026-08-14): the destructive reinit may
        start only by atomically — under _mic_lock — verifying that NO stream
        owner flag is set AND latching _pa_reinit_active in the same step.
        Owners claim their flags under the same lock only while the latch is
        clear (_pa_claim_owner, bounded wait). Claim-before-open plus
        close-before-release make a reinit under a live/opening/closing
        guarded stream structurally impossible; the old one-shot flag
        snapshot could race the long native teardown window."""
    now = time.time()
    if not force and (now - _device_cache["checked_at"] < DEVICE_CHECK_INTERVAL):
        return

    # Snapshot the current device list *before* the lock so we can decide
    # whether the destructive sd._terminate()/sd._initialize() cycle below
    # is actually warranted. PortAudio's query is read-only and cheap; the
    # reinit is what tears live stream state down (0xc0000374 — see the
    # _devices_signature() docstring).
    current_sig = _devices_signature()

    with _device_refresh_lock:
        # Re-check inside the lock — a peer thread may have just refreshed
        # while we were waiting, in which case there's nothing to do.
        now = time.time()
        if not force and (now - _device_cache["checked_at"] < DEVICE_CHECK_INTERVAL):
            return

        # If the device list hasn't drifted since the last enumeration we
        # skip the reinit entirely: every avoided sd._terminate() is one
        # less window in which an active wake-word or barge-in InputStream
        # can land on freed PortAudio state. We still bump checked_at so
        # the time gate above re-arms for another DEVICE_CHECK_INTERVAL.
        # force=True (e.g. get_current_mic_name()) always re-enumerates.
        #
        # BUT the signature can't be trusted to detect USB HOTPLUG: it's built
        # from sd.query_devices(), which PortAudio freezes until the reinit this
        # gate blocks — so a plugged/unplugged mic never trips it. To still catch
        # hotplug in steady state, fall THROUGH to the reinit once every
        # DEVICE_REENUM_INTERVAL even when the signature matches (the reinit is
        # still deferred below if any mic/TTS stream is live, so this adds no
        # teardown-during-capture risk). 2026-07-14 bug-hunt (#4).
        last_sig = _device_cache["last_devices_signature"]
        _reenum_due = (now - _device_cache.get("last_reenum_at", 0.0)
                       >= DEVICE_REENUM_INTERVAL)
        # FOLLOW-THE-DEFAULT TRIGGER (2026-08-20). The owner moves his mic and
        # speakers from a Stream Deck, i.e. by moving the WINDOWS DEFAULT — and
        # a moved default changes NEITHER current_sig (it is built from
        # sd.query_devices(), the table PortAudio freezes until the very reinit
        # this gate blocks) NOR sd.default.device (a struct field frozen at the
        # same moment). So before this trigger existed the ONLY thing that ever
        # picked a Stream Deck press up was _reenum_due — up to
        # DEVICE_REENUM_INTERVAL = 300 s of JARVIS still capturing from the old
        # mic and replying through the old speakers, then announcing the switch
        # minutes after the fact, with no way to force it sooner (the only
        # force=True caller is get_current_mic_name(), which no voice action
        # reaches). _win_default_endpoints() answers LIVE and cheap, so a press
        # now costs at most one DEVICE_CHECK_INTERVAL (4 s) instead of 300 s,
        # while pure hotplug keeps the 300 s ceiling. When the MMDevice API is
        # unavailable this is (None, None) and the old behaviour is exactly
        # what remains.
        #
        # THE 2026-08-20 VERSION OF THIS TRIGGER DID NOT WORK, AND THE FIRST
        # LIVE BOOT PROVED IT (session_2026-08-21_00-00-51.log).
        # It suppressed itself whenever a stream owner was live
        # (`and not _owners_busy`) on the reasoning that firing into a
        # guaranteed deferral would only churn the wake-word stream and print a
        # deny line. But record_speech re-opens the mic continuously and TTS
        # plays constantly, so on an awake session an owner is live essentially
        # ALWAYS: the trigger never asserted once in 15 minutes, the Stream Deck
        # press was never followed, and the log still filled with 34 deny lines
        # (from the cache-cleared re-pick path, which the follow-the-default
        # contract leaves permanently armed — see _cache_cleared below).
        #
        # THE REAL ERROR WAS EQUATING "FOLLOW THE DEFAULT" WITH "RE-ENUMERATE".
        # A Stream Deck press does not plug anything in; it moves the default
        # between endpoints PortAudio ALREADY has rows for. _endpoint_device_
        # identity() resolves the live endpoint id to one of those rows for the
        # price of a property-store read, so the press can be ADOPTED on this
        # very pass — no sd._terminate(), no 0xc0000374 window, and no waiting
        # for a mic that never falls idle. See that helper's block comment for
        # the measurements behind "the resolved index is what a reinit would
        # have produced anyway".
        #
        # So the trigger now fires REGARDLESS of _owners_busy, because the
        # response is no longer destructive. _owners_busy survives for what it
        # was always actually good for: deciding whether pausing the wake-word
        # stream is worth it (core/wake_word.resume() is documented
        # un-retryable, so every avoided pause matters). The destructive reinit
        # is escalated to ONLY when the cheap adoption fails — i.e. the new
        # default is genuinely not in the frozen list, which is true hotplug.
        _owners_busy = False
        with _pa_gate:
            _owners_busy = _pa_streams_live()
        _now_eps = _win_default_endpoints()
        _prev_eps = _device_cache.get("last_default_endpoints")
        _have_eps = _now_eps != (None, None)
        if _have_eps and _prev_eps is None:
            # First observation of the session: a BASELINE, never a change —
            # boot already enumerates, and announcing "switched" for the
            # endpoint JARVIS started on would be a lie.
            _device_cache["last_default_endpoints"] = _prev_eps = _now_eps
        _default_moved = bool(_have_eps and _prev_eps is not None
                              and _now_eps != _prev_eps)
        # Can this move be followed CHEAPLY, from the existing enumeration?
        # A direction HARD-pinned by MICROPHONE_INDEX/SPEAKER_INDEX never
        # follows the default at all, so it can never be the reason a teardown
        # is needed. PREFERRED_* is deliberately NOT consulted here: a
        # PREFERRED_ list that matches nothing still falls through to the
        # default, and asking _pick_device would mean a second round of its
        # _input_openable() probe opens on every pass. Erring toward "check it"
        # can only cost one unnecessary re-enumeration (exactly what 2026-08-20
        # did on every move); erring the other way would let the baseline rebase
        # on a move that was never actually applied, i.e. silently DROP a press.
        _follows_default = (MICROPHONE_INDEX is None or SPEAKER_INDEX is None)
        _default_adopted = True
        if _default_moved and _follows_default:
            if MICROPHONE_INDEX is None:
                _default_adopted &= (
                    _endpoint_device_identity(_now_eps[1],
                                              want_input=True)[0] is not None)
            if SPEAKER_INDEX is None:
                _default_adopted &= (
                    _endpoint_device_identity(_now_eps[0],
                                              want_input=False)[0] is not None)
            if _default_adopted:
                print("  [audio] the Windows default audio endpoint moved — "
                      "re-picking from the current enumeration so JARVIS "
                      "follows it (no PortAudio teardown needed)")
            else:
                print("  [audio] the Windows default audio endpoint moved to a "
                      "device that is not in PortAudio's current enumeration — "
                      "a full re-enumeration is required to follow it")
        if _default_moved and _default_adopted:
            # REBASE NOW, not after a reinit. The 2026-08-20 rule ("rebase only
            # after a real re-enumeration, or a deferred pass would forget the
            # press") was right for a teardown-only mechanism and is exactly
            # what turned an un-runnable teardown into an endless retry: the
            # baseline never moved, so the same move re-asserted every 4 s
            # forever. When the press is adopted on THIS pass it is not
            # forgotten — it is APPLIED — so the baseline must move with it.
            # (With both directions hard-pinned nothing follows the default, so
            # the move is irrelevant and is rebased silently.)
            _device_cache["last_default_endpoints"] = _now_eps
        # A move that WAS adopted must not also force the destructive path:
        # the cheap re-pick below is the whole response. A move that was NOT
        # adopted still does, because only a re-enumeration can reach a device
        # PortAudio has never seen.
        _reinit_wanted = bool(force or _reenum_due
                              or (_default_moved and not _default_adopted)
                              or last_sig is None or current_sig is None
                              or current_sig != last_sig)
        _sig_unchanged = not _reinit_wanted
        # A CLEARED cache is a re-pick REQUEST, not a steady state: the four
        # invalidating call sites (get_input_device / get_output_device's
        # stale-index probes, record_speech's failed InputStream open,
        # _play_audio_safe's playback retry) set in/out=None + checked_at=0.0
        # expecting the next pass to re-pick. Short-circuiting on an unchanged
        # signature alone made that invalidation a NO-OP — get_input_device()
        # then returned None (= the system-default mic) for up to
        # DEVICE_REENUM_INTERVAL. An unchanged signature still skips the
        # DESTRUCTIVE reinit below (see the _sig_unchanged branch in the
        # reinit chain); it must not skip the cheap re-pick. 2026-07-21 audit.
        _cache_cleared = (_device_cache["in"] is None
                         or _device_cache["out"] is None)
        # An ADOPTED default move is the second kind of re-pick request, and it
        # is the one that made this feature work at all: _sig_unchanged is True
        # for it (no teardown is wanted — that is the point), so without this
        # term the early return below would swallow the Stream Deck press on
        # the very pass that was able to follow it. 2026-08-21.
        _repick_due = _cache_cleared or (_default_moved and _default_adopted
                                         and _follows_default)
        if _sig_unchanged and not _repick_due:
            # Nothing to re-pick and no teardown wanted — so if a teardown was
            # previously being held off, it is not being held off any more.
            _log_reinit_deferral(None)
            _device_cache["checked_at"] = now
            return

        # Pause the wake-word detector's persistent InputStream so PortAudio
        # can be torn down without dangling stream state. resume() reopens
        # it after we've re-enumerated. Only needed when a destructive reinit
        # may actually run — the unchanged-signature repick-only fall-through
        # never tears PortAudio down, so pausing there would just churn the
        # wake-word stream every DEVICE_CHECK_INTERVAL while the cache is
        # legitimately empty (no preferred device connected).
        #
        # ...and never when an owner already holds a stream (_owners_busy,
        # sampled above): the gate below would DEFER the reinit anyway, so
        # pausing here would close+reopen the wake-word stream for nothing —
        # and core/wake_word.resume() is documented as un-retryable, so every
        # avoided pause is one less chance to lose barge-in for the session.
        wl = sys.modules.get("skill_wake_listener")
        det = getattr(wl, "_detector", None) if wl is not None else None
        paused_det = None
        if (not _sig_unchanged and not _owners_busy and det is not None
                and hasattr(det, "pause") and hasattr(det, "is_running")):
            try:
                if det.is_running():
                    det.pause()
                    paused_det = det
            except Exception as e:
                print(f"  [audio] wake-word pause failed: {e}")

        try:
            # Force PortAudio to re-enumerate so USB plug/unplug events
            # show up in sd.query_devices(). This sd._terminate()/_initialize()
            # cycle frees backing state out from under EVERY open stream, not
            # just the wake-word one we pause below — so if the main loop is
            # live inside record_speech (its InputStream open), tearing
            # PortAudio down here corrupts the heap (0xc0000374). The
            # wake-word pause does not cover record_speech, barge-in, or
            # ambient streams.
            #
            # TEARDOWN GATE (2026-08-14): the owner check and the reinit latch
            # are ONE atomic step under _mic_lock (_pa_gate). The old one-shot
            # flag snapshot here ran BEFORE the natives, so an owner could
            # claim AND open a stream inside the tens-to-hundreds-of-ms native
            # window. Now _pa_claim_owner refuses (bounded wait) while the
            # latch is up, so no claim — and therefore no open — can interleave
            # into the native window. When any owner holds a stream we SKIP the
            # destructive reinit and just re-pick from the existing
            # enumeration; the drift gets picked up on the next refresh once
            # the owners are briefly idle — which happens every utterance /
            # 20s timeout. The natives themselves run OUTSIDE _mic_lock (only
            # the latch protects them) so claimants time out instead of
            # queueing behind a slow WASAPI teardown.
            #
            # ORDER MATTERS, AND IT WAS WRONG (fixed 2026-08-21). The owner
            # checks used to be tested BEFORE `_sig_unchanged`, so a pass that
            # wanted no teardown at all — the cache-cleared re-pick, which the
            # follow-the-default contract used to leave permanently armed —
            # still printed "device drift detected …" every time a mic happened
            # to be live. That is where all 34 deny lines in
            # session_2026-08-21_00-00-51.log came from: not one of them
            # described a real deferral, because on those passes there was no
            # drift and nothing to defer. "Is a teardown even wanted?" is now
            # answered FIRST, and only then "may it run?".
            do_reinit = False
            _defer_reason = None
            _defer_message = ""
            with _pa_gate:
                if _sig_unchanged:
                    # No teardown wanted: either the cache was invalidated (a
                    # re-pick REQUEST) or the Windows default moved to a device
                    # already in this enumeration. Both are answered by the
                    # cheap _pick_device / _endpoint_device_identity re-pick
                    # below, over the EXISTING device list; no destructive
                    # reinit (and none of its 0xc0000374 risk) is needed or
                    # wanted, and this path never latches the gate, so
                    # claimants never wait on a re-pick. 2026-07-21 audit,
                    # re-ordered 2026-08-21.
                    pass
                elif _pa_mic_capture_live():
                    _defer_reason = "mic"
                    _defer_message = (
                        "  [audio] device drift detected but a mic/audio stream is "
                        "live (record_speech, get_mic_buffer Path B, ambient "
                        "listen, or a diagnostic/enrolment capture) — "
                        "deferring PortAudio reinit to avoid a mid-capture "
                        "teardown (0xc0000374). Logged once; the next line "
                        "about it will be when the deferral ends.")
                elif _tts_playback_active[0]:
                    _defer_reason = "tts"
                    _defer_message = (
                        "  [audio] device drift detected but TTS playback is "
                        "live — deferring PortAudio reinit to avoid tearing down "
                        "the barge-in stream (0xc0000374). Logged once; the "
                        "next line about it will be when the deferral ends.")
                elif _pa_close_pending[0]:
                    # H-6 (2026-08-20). A caller handed a native
                    # Pa_CloseStream to a daemon, its bounded wait expired,
                    # and it ABANDONED the daemon — so its owner flag is
                    # already (correctly) down while PortAudio is still
                    # executing the close. Tearing PortAudio down now is the
                    # same 0xc0000374 heap corruption the owner flags exist to
                    # prevent, reached through the one hole they cannot cover.
                    # The count retires itself when the daemon returns, so a
                    # merely-slow close costs one deferred pass; only a truly
                    # wedged one defers indefinitely — and then deferring is
                    # correct. The cheap _pick_device re-pick below still runs,
                    # so already-enumerated devices keep switching.
                    _defer_reason = "close"
                    _defer_message = (
                        "  [audio] device drift detected but an abandoned "
                        "native close is still in flight — deferring "
                        "PortAudio reinit (the daemon is still inside "
                        "Pa_CloseStream; sd._terminate() there is "
                        "0xc0000374). Logged once; the next line about it "
                        "will be when the deferral ends.")
                else:
                    _pa_reinit_active[0] = True
                    do_reinit = True
            # OUTSIDE the lock: _log_reinit_deferral prints, and printing under
            # _mic_lock would put I/O inside the teardown-gate's critical
            # section (the lock discipline above forbids slow work there).
            _log_reinit_deferral(_defer_reason, _defer_message)
            if do_reinit:
                try:
                    sd._terminate()
                    sd._initialize()
                    # Only a REAL re-enumeration re-arms the periodic hotplug
                    # sweep — a deferred (mic-active) pass must retry soon, not
                    # wait another DEVICE_REENUM_INTERVAL. 2026-07-14 #4.
                    _device_cache["last_reenum_at"] = now
                    # The follow-the-default baseline is normally rebased the
                    # moment the move is ADOPTED (above), which is the common
                    # case. This rebases it for the OTHER case: a move to a
                    # device that was not in the frozen list, which only a real
                    # re-enumeration can reach — so it is rebased only once that
                    # re-enumeration has actually happened. Rebasing THAT on a
                    # deferred pass would forget the press.
                    if _have_eps:
                        _device_cache["last_default_endpoints"] = _now_eps
                except Exception as e:
                    print(f"  [audio] PortAudio re-init failed: {e}")
                finally:
                    # ALWAYS drop the latch — a stuck latch would time out
                    # every future claim (JARVIS deaf AND mute). notify_all so
                    # bounded waiters re-check immediately instead of burning
                    # their whole timeout.
                    with _pa_gate:
                        _pa_reinit_active[0] = False
                        _pa_gate.notify_all()

            # FOLLOW-THE-DEFAULT, RESOLVED (2026-08-21). The 2026-08-20 rule was
            # "leave the index None so every open re-resolves the current
            # default". That reasoning had a false premise: sounddevice resolves
            # device=None through Pa_GetDefaultInput/OutputDevice, a struct
            # field frozen at Pa_Initialize — so device=None does not re-resolve
            # ANYTHING, it re-reads the SAME stale endpoint until a teardown.
            # Leaving it None did not follow the default; it followed whatever
            # the default was at boot.
            #
            # What follows the default is resolving the LIVE endpoint id to a
            # row in the current enumeration and opening THAT index. It does not
            # pin, because it is re-derived from a fresh MMDevice read on every
            # pass — the index is a RESULT of the live default, never a memory
            # of an old one. When it cannot be resolved (no MMDevice API, an
            # ambiguous MME-truncated name, a device not in the frozen list)
            # it falls back to None, i.e. precisely the previous behaviour.
            _resolved_in = (None, "")
            _resolved_out = (None, "")

            # Input
            if MICROPHONE_INDEX is not None:
                in_idx = MICROPHONE_INDEX
                try: in_name = sd.query_devices(in_idx)["name"]
                except Exception: in_name = ""
                in_track = (in_idx, in_name)
            else:
                in_idx, in_name = _pick_device(PREFERRED_INPUT_DEVICES, want_input=True)
                # No preference matched — which is the owner's NORMAL
                # configuration (PREFERRED_INPUT_DEVICES is empty because his
                # Stream Deck selects the mic by moving the Windows default, and
                # a name-pinned list beat the default even when the pinned
                # device was a powered-off headset that still enumerates and
                # still passes check_input_settings — 90 minutes deaf,
                # 2026-08-20).
                if in_idx is None:
                    _resolved_in = _endpoint_device_identity(_now_eps[1],
                                                             want_input=True)
                    in_idx, in_name = _resolved_in
                    in_track = (_resolved_in if in_idx is not None
                                else _default_device_identity(want_input=True))
                else:
                    in_track = (in_idx, in_name)
            # Did this direction's identity come from the WINDOWS DEFAULT? Only
            # then does the default endpoint id below describe the same device.
            # True both when the default was RESOLVED to an index and when it
            # was left to device=None — in both cases the tracked identity is
            # the default's.
            in_from_default = (MICROPHONE_INDEX is None
                               and (in_idx is None
                                    or _resolved_in[0] is not None))

            # Output
            if SPEAKER_INDEX is not None:
                out_idx = SPEAKER_INDEX
                try: out_name = sd.query_devices(out_idx)["name"]
                except Exception: out_name = ""
                out_track = (out_idx, out_name)
            else:
                out_idx, out_name = _pick_device(PREFERRED_OUTPUT_DEVICES, want_input=False)
                # Same contract for playback: the default speakers follow the
                # Stream Deck too.
                if out_idx is None:
                    _resolved_out = _endpoint_device_identity(_now_eps[0],
                                                              want_input=False)
                    out_idx, out_name = _resolved_out
                    out_track = (_resolved_out if out_idx is not None
                                 else _default_device_identity(want_input=False))
                else:
                    out_track = (out_idx, out_name)
            out_from_default = (SPEAKER_INDEX is None
                                and (out_idx is None
                                     or _resolved_out[0] is not None))

            # Log + announce changes, for BOTH directions.
            #
            # The guard compares (INDEX, NAME) — name alone missed a real switch
            # between two endpoints sharing an MME-truncated name (D1), and in
            # the follow-the-default configuration the picked name is "" on
            # every pass, which suppressed the log AND the announcement outright
            # (D2). Boot (None → first device) is logged but never spoken.
            # Wording is chosen inside _announce_device_change: neutral for a
            # deliberate switch, loss phrasing only when the previous endpoint
            # has actually vanished from the device list.
            #
            # One Stream Deck press usually moves BOTH defaults (the headset is
            # mic AND speakers), so both branches enqueue — deliberately. The
            # two lines are IDENTICAL text in that case, and _speak_pending's
            # seen_in_batch / _speech_was_recently_spoken dedupe collapses them
            # to one spoken sentence; when the endpoints differ the owner gets
            # both, which is the information he asked for. Do NOT "fix" this by
            # announcing only one direction.
            #
            # WHAT COUNTS AS A SWITCH, AND WHAT ONLY COUNTS AS A RE-KEY
            # (2026-08-20, second pass). Tracking the pair is right; ANNOUNCING
            # on either half moving is not. Twenty lines below, this same
            # function states the property that makes the index untrustworthy
            # here: "Indices can shift across a reinit even when the underlying
            # hardware is unchanged." On this machine inputs enumerate before
            # outputs, so powering off the DualSense pad — or any other input
            # appearing/disappearing — slides every OUTPUT index down by one
            # while the default speakers never move, and the old guard spoke
            # "Switched to Realtek USB2.0 Audio, sir." about the endpoint
            # JARVIS was already using. Claiming a switch that did not happen
            # is the same sin as claiming a success that did not happen.
            #
            # So: the NAME moving is a switch. The INDEX moving alone is a
            # switch only with POSITIVE EVIDENCE that the endpoint really
            # changed — the Windows endpoint id, which neither renumbers nor
            # truncates. That evidence is exactly what D1 needed (two endpoints
            # sharing an MME-truncated 31-character name, where a real switch
            # moves ONLY the index): the pair-compare keeps detecting it, and
            # the endpoint id is what makes it speakable. With no evidence
            # available (no MMDevice API, or a direction pinned by
            # MICROPHONE_INDEX/PREFERRED_* so the default endpoint describes a
            # different device) an index-only shift is TRACKED and LOGGED but
            # not spoken — silence beats a confident wrong sentence.
            _ep_now = {"in": (_now_eps[1] if in_from_default else None),
                       "out": (_now_eps[0] if out_from_default else None)}
            for _kind, (_track_idx, _track_name) in (("in", in_track),
                                                     ("out", out_track)):
                if not _track_name:
                    continue   # nothing identifiable to track, log, or say
                # .get(), not [] — a KeyError here would escape _refresh_devices
                # (the enclosing try has only a finally) and take down every
                # get_input_device() caller, i.e. the main loop. The tracking
                # keys are new in 2026-08-20, so an older cache dict handed in
                # by a caller/test may not carry them.
                _prev_name = _device_cache.get(f"last_{_kind}_name")
                _prev_idx  = _device_cache.get(f"last_{_kind}_index")
                if _track_name == _prev_name and _track_idx == _prev_idx:
                    continue
                _label = "mic" if _kind == "in" else "speakers"
                print(f"  [audio] {_label} → [{_track_idx}] {_track_name}")
                _prev_ep = _device_cache.get(f"last_{_kind}_endpoint")
                _new_ep  = _ep_now.get(_kind)
                _endpoint_moved = (_new_ep is not None and _prev_ep is not None
                                   and _new_ep != _prev_ep)
                if _prev_name and (_track_name != _prev_name
                                   or _endpoint_moved):
                    _announce_device_change(_prev_name, _track_name,
                                            want_input=(_kind == "in"))
                elif _prev_name:
                    print(f"  [audio] {_label} index moved "
                          f"[{_prev_idx}] → [{_track_idx}] with the same "
                          f"endpoint — re-keying silently, not announcing a "
                          f"switch that did not happen")
                _device_cache[f"last_{_kind}_name"]  = _track_name
                _device_cache[f"last_{_kind}_index"] = _track_idx
                _device_cache[f"last_{_kind}_endpoint"] = _new_ep

            _device_cache["in"]         = in_idx
            _device_cache["out"]        = out_idx
            _device_cache["checked_at"] = now
            # Recompute the signature *after* the reinit so the next pass
            # compares against the freshly-enumerated list, not the stale
            # snapshot taken before the lock. Indices can shift across a
            # reinit even when the underlying hardware is unchanged.
            _device_cache["last_devices_signature"] = _devices_signature()
        finally:
            if paused_det is not None:
                _wake_word_resume_or_report(paused_det)


def get_input_device() -> int | None:
    # Hard-disabled mic (staging green candidate / MICROPHONE_INDEX < 0): no
    # device, no capture, and crucially DON'T fall through to the "using system
    # default" path below — that message (and the None it returns, which every
    # InputStream open treats as the default mic) is exactly how staging ended
    # up listening. _mic_input_disabled is defined just below; resolved at call
    # time so the forward reference is fine.
    if _mic_input_disabled():
        return None
    _refresh_devices()
    idx = _device_cache["in"]
    if idx is None:
        return None
    # Validate that the cached index is still queryable. PortAudio's
    # device list can go stale between _refresh_devices() calls — e.g.
    # a USB mic dropping off, or sd._terminate()/_initialize() shifting
    # indices. Opening an InputStream with a stale index raises
    # PortAudioError("Error querying device N") mid-stack and crashed
    # the main loop (see session_2026-05-28_20-39-03.log). Clearing the
    # cache and returning None lets sounddevice fall back to the system
    # default; the next _refresh_devices() pass will re-pick.
    try:
        sd.query_devices(idx)
        return idx
    except Exception as e:
        print(f"  [audio] cached mic index {idx} no longer queryable ({e}); using system default")
        _device_cache["in"] = None
        _device_cache["checked_at"] = 0.0
        return None


def get_output_device() -> int | None:
    _refresh_devices()
    idx = _device_cache["out"]
    if idx is None:
        return None
    try:
        sd.query_devices(idx)
        return idx
    except Exception as e:
        print(f"  [audio] cached speaker index {idx} no longer queryable ({e}); using system default")
        _device_cache["out"] = None
        _device_cache["checked_at"] = 0.0
        return None


def _mic_input_disabled() -> bool:
    """True when audio INPUT must not be opened AT ALL: the staging/blue-green
    GREEN candidate (the mic is owned by the live prod instance) or an explicit
    MICROPHONE_INDEX < 0. A negative index otherwise fell through
    get_input_device() → None → the SYSTEM DEFAULT mic, so every capture path
    silently opened the default microphone — defeating 'no mic' AND competing
    with prod for the device (the staging block at the top of this file says it
    must NOT touch the audio devices prod owns). 2026-05-31."""
    if _is_staging():
        return True
    return MICROPHONE_INDEX is not None and MICROPHONE_INDEX < 0


def get_current_mic_name() -> str:
    """Friendly name of whatever mic is currently selected."""
    _refresh_devices(force=True)
    idx = _device_cache["in"]
    if idx is None:
        return "(system default)"
    try:
        return f"[{idx}] {sd.query_devices(idx)['name']}"
    except Exception:
        return f"[{idx}] (unknown)"


def get_current_speaker_name() -> str:
    """Friendly name of whatever output device is currently selected.

    Refreshes FIRST, symmetrically with get_current_mic_name(). Until
    2026-09-06 this read _device_cache["out"] with no refresh at all, so the
    spoken answer to "what speakers are you using" came from a cache rather
    than from the live default render endpoint. It happened to be right,
    because get_output_device() refreshes on every TTS playback and JARVIS
    speaks constantly — i.e. it was correct by accident of timing, not by
    construction. That is precisely the "names a device it never read" shape
    that produced this session's other audio defects, so the asymmetry is
    closed rather than left resting on how chatty JARVIS happens to be.
    """
    _refresh_devices(force=True)
    idx = _device_cache["out"]
    if idx is None:
        return "(system default)"
    try:
        return f"[{idx}] {sd.query_devices(idx)['name']}"
    except Exception:
        return f"[{idx}] (unknown)"


def list_cameras(max_check: int = CAMERA_PROBE_MAX):
    """Probe camera indexes at their max resolution, save a preview JPEG
    for each working one so you can tell which physical camera is which.

    Each probe is wrapped in a thread+timeout so a missing index or a sick
    device cannot stall the sweep.

    The indices printed are DIRECTSHOW indices, because those are what the user
    pastes into CAMERAS. Which backend opens them is _camera_open()'s business.

    THE KINECT DOES NOT DROP OUT OF THIS LISTING, AND THE ANSWER IS
    RESOLUTION-DEPENDENT. An earlier version of this docstring claimed Media
    Foundation "never delivers a frame" from the Kinect V2 and was "strictly
    WORSE for this one device", so the sensor supposedly vanished from the
    sweep. Re-measured on this rig 2026-09-06 with JARVIS stopped, through the
    shipped opener (core.camera_backend.open_camera), fresh process per figure:

        MSMF  msmf idx 0  1920x1080 : 1920x1080, 30.05-30.10 fps, 91/91 reads
                                      in 3 s, first frame 0.03 s, mean
                                      brightness ~122.  (n=3)
        MSMF  msmf idx 0  1280x720  : opens, get() reads back 512x424, then
                                      EVERY read fails - 0 frames in 5 s.
                                      640x480 and "no resolution set" behave
                                      identically.  (n=2 each)
        DSHOW dshow idx 1 1920x1080 : 1 refused open and 15.1 fps once in 7
                                      tries; the other 5 gave 1.0 fps with
                                      mean brightness 0.0 - BLACK frames. It
                                      ignores any requested size.  (n=7)

    So at 1920x1080 - the ONLY size this sweep ever requests - Media
    Foundation is ~30x BETTER here, not worse, and the Kinect is listed as
    working. `python bobert_companion.py --list-cameras` on 2026-09-06 printed
    "Camera 1: working (1920x1080) [OK, brightness=124.4]", the brightest
    entry in the whole sweep. (A frameless device would not "drop out" either:
    _open_with_warmup reports opened=True for any non-None capture, and the
    line below then reads "opened but no frame".)

    THE HAZARD THAT IS REAL is that this tool's whole purpose is to tell the
    owner which index to paste into CAMERAS - and a CAMERAS entry is opened by
    the face-track producer at _LOOP_OPEN_WIDTH x _LOOP_OPEN_HEIGHT with a
    require_frame budget, i.e. 1280x720, where this device yields nothing at
    all. "Working at 1920x1080" alone would therefore be advice the face
    tracker cannot honour: it logs "Could not open ... skipping" and the
    camera is dropped. Hence the CONFIRM probe below - every index that works
    at the sweep's resolution is re-opened at the producer's, and one that
    fails is printed with an explicit do-not-paste warning rather than a bare
    "working".

    NOTE ALSO: this sweep only PRINTS. It rewrites nothing - see the closing
    "Then edit the CAMERAS list" line. The function that actually rewrites
    CAMERAS is probe_cameras_and_update_config() via _probe_camera_index(),
    which passes NO resolution and so still measures 0 frames on the Kinect
    and still excludes it. If you want the sensor for face tracking, go
    through audio/kinect_bridge.KinectCapture and the official runtime, not
    cv2 - which is also what this file's config comment ("never grab index 1,
    that's the Kinect colour stream") has always said.
    """
    out_dir = os.path.join(os.path.dirname(os.path.abspath(__file__)), "camera_previews")
    os.makedirs(out_dir, exist_ok=True)

    # Check for lock-holders up front — saves the user staring at "not
    # available" for every index when the real cause is Teams in the tray.
    suspects = find_camera_locking_processes()
    if suspects:
        print(f"⚠  These running apps commonly hold webcam locks: {', '.join(suspects)}")
        print(f"   If cameras show 'not available' below, close them and re-run.\n")

    print(f"Scanning indices 0..{max_check - 1} (timeout {CAMERA_PROBE_TIMEOUT_SEC}s each)…")

    def _open_with_warmup(idx: int, width: int = 1920, height: int = 1080,
                          what: str = "") -> tuple[bool, bool, int, int, float, "np.ndarray | None"]:
        """Returns (opened, got_frame, w, h, mean_brightness, frame_or_None).

        ``width``/``height`` are a parameter and not a constant because this
        sweep asks TWO questions of every working index — "does it deliver at
        the sweep's 1920x1080" and "does it deliver at the resolution a
        CAMERAS entry is actually opened at" — and on this rig those have
        different answers for the Kinect (see this function's docstring)."""
        result = {"opened": False, "ret": False, "w": 0, "h": 0,
                  "bright": 0.0, "frame": None}
        def _do():
            # Same serialization rationale as _probe_camera_index._open:
            # if this worker wedges past the join() timeout, the lock keeps
            # its eventual release() from colliding with later camera ops.
            with _camera_io_lock:
                # The INDEX PRINTED BY THIS TOOL IS A DIRECTSHOW INDEX, because
                # that is what the user pastes into CAMERAS. _camera_open()
                # keeps that contract and translates internally for whichever
                # backend actually opens the device.
                cap = _camera_open(idx, width=width, height=height,
                                   label=f"list-cameras index {idx}"
                                         f"{what}")
                try:
                    if cap is None:
                        return
                    result["opened"] = True
                    # Warm up — many cameras need several frames before auto-exposure works
                    for _ in range(15):
                        cap.read()
                        time.sleep(0.05)
                    ret, frame = cap.read()
                    if ret:
                        result["ret"] = True
                        result["h"], result["w"] = frame.shape[:2]
                        result["bright"] = float(frame.mean())
                        result["frame"] = frame
                except Exception:
                    pass
                finally:
                    # Through the lock OBJECT - see
                    # _release_on_current_camera_lock.
                    _release_on_current_camera_lock(cap)

        t = threading.Thread(target=_do, daemon=True)
        t.start()
        # Generous timeout for list-cameras (warm-up frames take ~0.75 s alone)
        t.join(timeout=max(CAMERA_PROBE_TIMEOUT_SEC, 5.0))
        _drain_camera_backend_notes()
        if t.is_alive():
            # Abandoned while it OWNS _camera_io_lock — retire that lock, or
            # this diagnostic command silently kills camera I/O for the whole
            # running process (the face-track producer included). Same defect
            # as the bounded opener's, third call site.
            try:
                owner, hold = _camera_io_lock.owner_hold()
                if owner == t.ident:
                    _camera_io_lock.retire_if_holding(
                        t.ident, hold,
                        f"list-cameras index {idx}{what} wedged inside its "
                        f"camera open")
            except Exception:  # pragma: no cover - defensive: foreign lock object
                logging.exception("[list-cameras] camera I/O lock retire failed "
                                  "for index %s", idx)
        return (result["opened"], result["ret"], result["w"], result["h"],
                result["bright"], result["frame"])

    def _usable_by_face_tracker(idx: int) -> bool:
        """Does index ``idx`` still deliver at the resolution a CAMERAS entry
        is opened at? Only asked of an index that already produced a frame.

        RETRIED ONCE before it is believed. A "no" here prints DO-NOT-PASTE
        advice about the owner's own webcam, so a transient must not produce
        one: MSMF fails 3-7% of back-to-back reopens (measured; see
        core.camera_backend.default_retries), and a camera another app grabs
        between the two probes looks identical to a format refusal. Two
        failures in a row on a device that delivered a frame seconds earlier
        is a format answer, not a flake.

        Costs one extra open, and only for an index that WORKS - two of twelve
        on this rig. On Media Foundation that is ~free (+0.97 handles per
        open/release cycle, measured); a DirectShow-only device pays +479, but
        it pays that only if it is a real working camera the owner is about to
        configure, which is exactly when the answer is worth buying."""
        for _ in range(2):
            _, loop_ret, _, _, _, _ = _open_with_warmup(
                idx, _LOOP_OPEN_WIDTH, _LOOP_OPEN_HEIGHT,
                what=f" at {_LOOP_OPEN_WIDTH}x{_LOOP_OPEN_HEIGHT}")
            if loop_ret:
                return True
        return False

    unusable: list[int] = []
    for i in range(max_check):
        opened, ret, w, h, mean_brightness, frame = _open_with_warmup(i)
        loop_ok = True
        if ret and frame is not None:
            path = os.path.join(out_dir, f"camera_{i}.jpg")
            cv2.imwrite(path, frame)
            quality = "OK" if mean_brightness > 10 else "⚠ BLACK / blocked"
            status = f"working  ({w}x{h})  [{quality}, brightness={mean_brightness:.1f}]  → preview saved"
            # THE SECOND QUESTION. "Works at 1920x1080" is not the same claim
            # as "works as a CAMERAS entry" — see this function's docstring for
            # the Kinect measurements that make them differ.
            loop_ok = _usable_by_face_tracker(i)
        elif opened:
            status = "opened but no frame"
        else:
            status = "not available"
        print(f"  Camera {i}: {status}")
        if not loop_ok:
            unusable.append(i)
            print(f"      ⚠  DO NOT PUT INDEX {i} IN CAMERAS. It delivers a frame at "
                  f"{w}x{h}, but none at {_LOOP_OPEN_WIDTH}x{_LOOP_OPEN_HEIGHT} — which is "
                  f"what the face-track loop opens a CAMERAS entry at, so it would be "
                  f"dropped with \"Could not open … skipping\".")
            print("         Usual cause: a device with ONE fixed format (the Kinect V2 "
                  "colour stream is exactly this — 1920x1080 or nothing). If this is an "
                  "ordinary webcam, another app grabbed it mid-sweep; close it and re-run.")
    print(f"\nPreviews saved to: {out_dir}")
    print("Open the JPEGs to identify which index is the Kinect, left webcam, and right webcam.")
    print("Then edit the CAMERAS list at the top of the script.")
    if unusable:
        print(f"⚠  Skip {', '.join(str(i) for i in unusable)} — flagged above as "
              f"unusable at {_LOOP_OPEN_WIDTH}x{_LOOP_OPEN_HEIGHT}.")


def pause_face_tracking():
    """Pause the HEAVY face detection + eye-control during voice activity.

    This yields the eyes (so the listening/thinking/speaking animations own
    them) and skips the cv2 cascade recognition cost — but it does NOT turn the
    camera off. The capture loop keeps grabbing/caching frames and keeps writing
    the HUD preview, so the camera tile stays visibly ON and the air-mouse/gaze
    keep getting frames while JARVIS listens or talks. To genuinely blank the
    camera (low-memory guard / standby) use set_face_tracking_camera_off()."""
    _face_track_pause.set()

def resume_face_tracking():
    _face_track_pause.clear()

def set_face_tracking_camera_off():
    """Force the HUD camera preview to its 'CAMERA OFF' placeholder while the
    capture loop keeps running. For the genuinely camera-off states the brief
    requires to STILL blank the preview — the KINECT_REVIEW P0 low-memory guard
    (stop mirroring HD frames under RAM/VRAM exhaustion) and any explicit
    'camera should appear off' need. Standby is detected directly from
    _standby_mode in the loop and needs no call here."""
    _face_track_camera_off.set()

def clear_face_tracking_camera_off():
    """Undo set_face_tracking_camera_off() — let the live preview resume once
    the low-memory / camera-off condition clears."""
    _face_track_camera_off.clear()


# ──────────────────────────────────────────────────────────────────────────
#  PROACTIVE / IDLE BEHAVIOR  — JARVIS-style spontaneous observations
# ──────────────────────────────────────────────────────────────────────────

def should_be_proactive() -> bool:
    """Decide whether to fire a proactive comment right now."""
    if not PROACTIVE_ENABLED:
        return False

    # FOCUS / DO-NOT-DISTURB gate. Spontaneous proactive comments take the
    # should_be_proactive() → _do_proactive_turn() → _speak() path, which
    # BYPASSES proactive_announce's focus gate (the only place focus was
    # consulted). Without this check a focus block is still interrupted by
    # unprompted observations — the exact intrusion DND exists to prevent.
    # Mirror the proactive_announce gate: live-read the FOCUS_MODE_ENABLED
    # kill-switch so a Settings toggle applies without a restart, and fail OPEN
    # so a bug here can never permanently silence proactive comments. 2026-07-08.
    try:
        _focus_on = True
        try:
            import core.config as _cfg
            _focus_on = bool(getattr(_cfg, "FOCUS_MODE_ENABLED", True))
        except Exception:
            _focus_on = True
        if _focus_on and focus_mode_active():
            return False
    except Exception:
        pass

    silence = time.time() - last_speech_time
    if silence < PROACTIVE_MIN_SILENCE:
        return False

    # Voice-mood suppression — when the user was just detected as stressed,
    # the adapter writes 'voice_mood_stressed_until' into memory; honour
    # that 15-minute quiet window before checking face/probability.
    if _voice_mood_response is not None:
        try:
            with _memory_lock:
                if _voice_mood_response.is_stress_suppression_active(load_memory()):
                    return False
        except Exception:
            pass

    # Must be able to see the user (so we're not talking to an empty room)
    if PROACTIVE_REQUIRE_FACE:
        if last_face_seen == 0.0 or (time.time() - last_face_seen) > 60:
            return False

    # Probability scales from 0 at MIN_SILENCE to 1 at MAX_SILENCE
    span = max(1, PROACTIVE_MAX_SILENCE - PROACTIVE_MIN_SILENCE)
    progress = (silence - PROACTIVE_MIN_SILENCE) / span
    progress = max(0.0, min(1.0, progress))
    # Each check has at most a 35% chance even at max silence
    return random.random() < (progress * 0.35)


def generate_proactive_comment() -> str:
    """Use the LLM + memory to write a brief JARVIS-style observation."""
    system = _system_prompt + (
        "\n\nYou are now generating a PROACTIVE comment. Your owner has been "
        "quiet for a while but you can see them at their desk. "
        "Pick ONE of: a brief observation about something you remember they're "
        "working on, a thoughtful question about a recent topic, a short interesting "
        "fact related to their interests, or a check-in. "
        "Keep it to ONE sentence. Do not start with 'Hey' or any greeting. "
        "Sound natural, like you just thought of it."
    )
    user = "(There has been silence. Generate one short proactive comment.)"
    try:
        text = _llm_quick(system=system, user=user, max_tokens=120)
        return text.strip().split("\n")[0]
    except Exception as e:
        print(f"  [proactive] generation failed: {e}")
        return ""


# ──────────────────────────────────────────────────────────────────────────
#  LATE-NIGHT CHECK  (1:00 AM – 5:00 AM dry remark before complying)
# ──────────────────────────────────────────────────────────────────────────
# When the user gives a command during the wee hours, prepend a brief,
# in-character JARVIS remark before the actual response. Cycles through a
# small phrase bank so it doesn't get repetitive, and throttles to one
# remark per LATE_NIGHT_COOLDOWN seconds so rapid-fire commands during a
# late-night session don't get a remark stacked on every single one.
#
# Suppressed for the rest of the night when the user explicitly says
# "no comments tonight" (or similar). Suppression is stored in memory
# under "late_night_no_comments_until" — an ISO date string — and is
# cleared automatically at the next 5 AM rollover.

LATE_NIGHT_START_HOUR = 1        # inclusive
LATE_NIGHT_END_HOUR   = 5        # exclusive  → window is 01:00:00 – 04:59:59
LATE_NIGHT_COOLDOWN   = 600      # seconds between remarks (10 min)

LATE_NIGHT_PHRASES = (
    "It's nearly {hr} AM, sir. The suit can wait until morning, but very well.",
    "Past {hr} in the morning, sir — I'll assume you know what you're doing.",
    "{hr} AM, sir. Sleep is, statistically, also an option.",
    "Working through the night again, sir? Right away.",
    "It is well past midnight, sir. As you wish.",
    "I'd remark on the hour, sir, but you've clearly already noticed.",
    "{hr} AM. I do hope this is important, sir.",
    "Burning the proverbial candle at both ends, sir. On it.",
)

LATE_NIGHT_SUPPRESS_PHRASES = (
    "no comments tonight",
    "no remarks tonight",
    "spare me the commentary",
    "no commentary tonight",
    "skip the remarks",
    "skip the commentary",
)

# Module-level cursor for round-robin phrase rotation
_late_night_phrase_idx: list[int]  = [0]
_late_night_last_remark: list[float] = [0.0]


def _in_late_night_window(now: float | None = None) -> bool:
    """True if the local hour is in the late-night remark window."""
    lt = time.localtime(now if now is not None else time.time())
    return LATE_NIGHT_START_HOUR <= lt.tm_hour < LATE_NIGHT_END_HOUR


def _late_night_session_key(now: float | None = None) -> str:
    """A YYYY-MM-DD key identifying the current late-night session.
    Treats the whole 01:00–04:59 block as belonging to that calendar date,
    so a suppression set at 02:30 covers the rest of that same night.
    """
    return time.strftime("%Y-%m-%d", time.localtime(now if now is not None else time.time()))


def _is_late_night_suppressed(memory: dict, now: float | None = None) -> bool:
    """True if the user has muted late-night remarks for tonight."""
    until = (memory or {}).get("late_night_no_comments_until", "")
    if not until:
        return False
    return until == _late_night_session_key(now)


def _set_late_night_suppression(memory: dict) -> None:
    """Mute late-night remarks for the rest of this calendar night."""
    key = _late_night_session_key()
    # Persist against a FRESH locked load, NEVER the passed-in dict. The caller
    # (maybe_late_night_remark) hands us the main loop's long-lived boot snapshot,
    # and save_memory() is a whole-file json.dump + os.replace overwrite. Session
    # facts are written to disk only by learn_from_turn -> merge_memory (its own
    # fresh-locked load/merge/save) and never mirrored back into that snapshot, so
    # saving the stale dict here would clobber bobert_memory.json and discard every
    # fact/project/topic learned this session — the exact bug already fixed on the
    # shutdown path and used by the phrase-rotation writer.
    try:
        with _memory_lock:
            _fresh = load_memory()
            _fresh["late_night_no_comments_until"] = key
            save_memory(_fresh)
    except Exception as e:
        print(f"  [late-night] failed to persist suppression: {e}")
    # Keep the in-session snapshot consistent so _is_late_night_suppressed() sees
    # the suppression for the rest of this loop without a disk re-read.
    if isinstance(memory, dict):
        memory["late_night_no_comments_until"] = key


def _matches_suppress_phrase(text: str) -> bool:
    """Word-boundary match against LATE_NIGHT_SUPPRESS_PHRASES, short utterances only."""
    tl = (text or "").strip().lower()
    if not tl or len(tl.split()) > 8:
        return False
    for p in LATE_NIGHT_SUPPRESS_PHRASES:
        if re.search(r'\b' + re.escape(p) + r'\b', tl):
            return True
    return False


def _late_night_hour_word(now: float | None = None) -> str:
    """Format the current late-night hour for phrase interpolation.
    e.g. 03:14 → '3', 01:02 → '1'. (Always within 1..4 inside the window.)
    """
    lt = time.localtime(now if now is not None else time.time())
    return str(lt.tm_hour)


def maybe_late_night_remark(user_text: str, memory: dict) -> str:
    """Return a one-line dry remark to speak before complying, or '' if
    no remark is appropriate right now.

    Side effects:
      - If the user said a suppression phrase, sets the memory flag and
        returns a brief acknowledgement.
      - Updates the cooldown timestamp + phrase-rotation cursor when a
        remark is returned.
    """
    if not _in_late_night_window():
        return ""

    if _matches_suppress_phrase(user_text):
        _set_late_night_suppression(memory)
        return "As you wish, sir. Silent until morning."

    if _is_late_night_suppressed(memory):
        return ""

    now = time.time()
    if now - _late_night_last_remark[0] < LATE_NIGHT_COOLDOWN:
        return ""

    idx = _late_night_phrase_idx[0] % len(LATE_NIGHT_PHRASES)
    phrase = LATE_NIGHT_PHRASES[idx].format(hr=_late_night_hour_word(now))
    _late_night_phrase_idx[0] = (idx + 1) % len(LATE_NIGHT_PHRASES)
    _late_night_last_remark[0] = now
    return phrase


# ──────────────────────────────────────────────────────────────────────────
#  THINKING ANIMATION  (slow eye sweep while LLM generates a response)
# ──────────────────────────────────────────────────────────────────────────

def _thinking_loop(stop_evt: threading.Event):
    t = 0.0
    _i = 0
    while not stop_evt.is_set():
        try:
            x = 0.5 + 0.38 * math.sin(t * 0.8)          # slow left-right sweep
            y = 0.62 + 0.06 * math.sin(t * 2.5)          # subtle up-down bob
            send(eyes_x=round(x, 3), eyes_y=round(y, 3))
            t += 0.10
            # Keep the main-loop watchdog satisfied while the LLM thinks.
            # On the LOCAL model a single reply can take 20–40 s under VRAM
            # pressure; without a tick here the 60 s heartbeat goes stale
            # mid-think and the watchdog false-trips, aborting the *next*
            # record_speech (the 2026-05-30 12:18 stall). This animation
            # only runs while JARVIS is actively thinking, so ticking here
            # means exactly "the main loop is alive and working".
            _i += 1
            if _i % 20 == 0:          # ≈ every 1 s of wall-clock (20 × 0.05s)
                _heartbeat()
            time.sleep(0.05)
        except Exception:
            logging.exception("_thinking_loop iteration failed")
            time.sleep(0.05)


def _llm_error_reply() -> str:
    """Honest, persona-consistent line spoken when the LLM turn itself raised
    (not a backend-down path — those have their own messages — but an
    unexpected exception escaping _call_llm's prologue or local route). Never
    fabricates an answer to the user's question; just admits the turn failed so
    the caller can return instead of propagating the crash to the main loop."""
    return ("I'm afraid I ran into a problem forming that reply, sir — "
            "please try again.")


def get_response_with_animation(user_text: str) -> str:
    """Run the thinking eye animation concurrently while the LLM thinks."""
    pause_face_tracking()
    set_state("thinking")

    stop_evt  = threading.Event()
    anim      = threading.Thread(target=_thinking_loop, args=(stop_evt,), daemon=True)
    anim.start()

    # _call_llm is guarded internally on every backend branch, but its prologue
    # (tone/route classifiers) and the local route's helpers can still raise.
    # If anything escapes here, the try/finally MUST still stop+join the
    # animation daemon: a leaked _thinking_loop keeps calling _heartbeat()
    # forever, which falsifies the main-loop watchdog (it never sees a stale
    # beat, so it can't recover the wedge). And the exception itself must not
    # propagate — the outer main loop only catches KeyboardInterrupt, so an
    # unguarded raise here crashes the whole conversation loop. Returning an
    # honest fallback keeps the LLM branch non-propagating like the others.
    try:
        reply = _call_llm(user_text)
    except Exception:
        logging.exception("get_response_with_animation: _call_llm raised")
        reply = _llm_error_reply()
    finally:
        stop_evt.set()
        anim.join(timeout=2)
    return reply


# ──────────────────────────────────────────────────────────────────────────
#  AUDIO RECORDING  (energy-based VAD)
# ──────────────────────────────────────────────────────────────────────────


# ── TEMPORARY PERF PROBE (2026-09-06 latency work) ───────────────────────
import time as _prof_time
_PROF_ON = bool(os.environ.get("JARVIS_PERF_PROBE"))
_PROF_PATH = os.environ.get("JARVIS_PERF_PROBE",
                            "") or "perf_probe.tsv"
_prof_lock = threading.Lock()


def _prof(tag, extra=""):
    if not _PROF_ON:
        return
    try:
        with _prof_lock:
            with open(_PROF_PATH, "a", encoding="utf-8") as f:
                f.write(f"{_prof_time.perf_counter():.6f}\t{tag}\t"
                        f"{threading.get_ident()}\t{extra}\n")
    except Exception:
        pass
# ── END TEMPORARY PERF PROBE ─────────────────────────────────────────────


def _prof_ollama(r):
    """Ollama's own per-request timings, for the probe TSV."""
    try:
        j = r.json()
        return (f"total={j.get('total_duration',0)/1e6:.1f} "
                f"load={j.get('load_duration',0)/1e6:.1f} "
                f"peval={j.get('prompt_eval_duration',0)/1e6:.1f} "
                f"ptok={j.get('prompt_eval_count',0)} "
                f"eval={j.get('eval_duration',0)/1e6:.1f} "
                f"etok={j.get('eval_count',0)}")
    except Exception:
        return "unparsed"

_last_recording_peak = 0.0   # set by record_speech, read by callers

# ── SPECULATIVE TRANSCRIPTION (2026-09-06 latency work) ───────────────────
#
# Every spoken turn pays SILENCE_SECS (1.4 s) of pure dead air before ANY work
# starts — int(1.4 * 16000 / 1024) = 21 chunks the loop below must count out
# after the owner's last voiced frame. Measured at 1,340 ms p50, 16 % of
# speak-to-speak latency, spent doing nothing. Whisper then costs another
# 1,427 ms p50 on top of it.
#
# Those two are strictly sequential today and need not be. Once ~0.45 s of
# silence has passed, the utterance is very probably finished: snapshot it and
# start transcribing in the background while the loop keeps counting. If the
# owner does resume, the snapshot is discarded and a fresh one is taken at the
# next pause; if he does not, the transcript is ready (or nearly) the moment
# the hangover expires.
#
# WHY THIS IS NOT A CORRECTNESS TRADE. The snapshot is only ever accepted when
# NO voiced frame arrived after it — enforced by _spec_stt["chunks"] being
# invalidated in the rms > VAD_THRESHOLD branch, not by a timing guess. So the
# accepted audio differs from the full buffer by trailing SILENCE ONLY, and
# faster-whisper's Silero VAD filter drops that silence before decoding either
# way. tests/test_speculative_stt.py pins the invalidation rule; the
# transcript-identity claim was measured on real recordings (see the module
# docstring of scratchpad e5_spec_stt.py in the 2026-09-06 latency work).
#
# DEFAULT OFF as of 2026-09-06 adversarial review. The invariant above is
# sound and could not be broken -- no frame above VAD_THRESHOLD ever arrived
# after an accepted snapshot -- but it is the WRONG invariant. VAD_THRESHOLD
# (raw RMS 0.008) is an ENDPOINT gate, not a speech detector, and it is far
# coarser than what Whisper can read once _process_capture_chunk's AGC and
# apply_capture_auto_gain (up to 10x) have run. This machine's own logs
# (n=465 real captures) put the median WHOLE-UTTERANCE peak at 0.0087 and p75
# at 0.0098 -- i.e. almost every chunk of a normal sentence sits BELOW the
# gate, which is exactly what the 1.4 s hangover exists to carry. Snapshotting
# at 0.45 s therefore discards real speech that the full buffer transcribes
# correctly. Measured end-to-end through this loop with the prod model:
#   full buffer -> 'Turn off the lights in the kitchen.'
#   snapshot    -> 'Turn off the light.'          (peak 0.0083, p25)
#   snapshot    -> 'Turn off the lights in the'   (peak 0.0087, p50)
# A wrong command executed silently is worse than a slow one. Re-enable only
# once the snapshot gate is at least as sensitive as the decoder -- e.g. trip
# on the CAPTURE_AUTO_GAIN_NOISE_FLOOR (0.005) or on a fraction of peak_rms,
# not on VAD_THRESHOLD.
# Set JARVIS_SPECULATIVE_STT=1 to re-enable; the default now transcribes
# exactly as before the 2026-09-06 latency work.
_SPECULATIVE_STT = (os.environ.get("JARVIS_SPECULATIVE_STT", "0")
                    .strip().lower() not in ("0", "false", "no", "off"))
# How much silence to see before betting the utterance is over. Below ~0.35 s
# ordinary stop-consonants and mid-sentence breaths trip it (wasted GPU, never
# a wrong transcript); above ~0.6 s there is too little hangover left to hide
# Whisper behind.
_SPEC_STT_SILENCE_SECS = float(os.environ.get("JARVIS_SPECULATIVE_STT_SECS",
                                              "0.45"))
# Shortest snapshot worth decoding — below this the callers reject the capture
# anyway (`len(audio) < SAMPLE_RATE * 0.4`).
_SPEC_STT_MIN_SECS = 0.4
# How long _transcribe_capture waits on an in-flight speculative decode before
# it starts SAYING so. This is not a latency bound and must not be described as
# one — see the proof in _transcribe_capture. _HARD is the last-resort valve for
# a worker that is wedged rather than merely slow.
_SPEC_STT_WAIT = float(os.environ.get("JARVIS_SPECULATIVE_STT_WAIT", "8"))
_SPEC_STT_HARD_WAIT = float(os.environ.get("JARVIS_SPECULATIVE_STT_HARD_WAIT",
                                           "20"))

# The in-flight speculative decode. Written only by record_speech (mic thread)
# and read by the capture callers on the same thread, so the dict needs no lock
# of its own; `thread`/`result` are touched by the worker, which is why result
# is written exactly once, last.
_spec_stt: dict = {
    "token": 0,        # bumped per capture; a stale worker's result is ignored
    "gen": 0,          # bumped the moment the in-flight snapshot stops being
                       # this utterance (a voiced frame, or the next capture).
                       # The worker re-checks it on the far side of _stt_lock
                       # and abandons the decode — see _spec_stt_note_voiced.
    "chunks": -1,      # snapshot length in chunks, or -1 once invalidated
    "thread": None,
    "result": None,    # (text, conf) once the worker finishes
}


def _spec_stt_reset() -> None:
    """Start a new capture: nothing from the previous one may be reused."""
    _spec_stt["token"] += 1
    # Bumping the token already stops a late worker WRITING its result; bumping
    # gen also stops it DOING the work. An orphan's decode is unusable by
    # definition, and every second it spends holding _stt_lock is stolen from
    # the capture that just started.
    _spec_stt["gen"] += 1
    _spec_stt["chunks"] = -1
    _spec_stt["thread"] = None
    _spec_stt["result"] = None


def _spec_stt_note_voiced() -> None:
    """A voiced frame arrived — any pending snapshot is no longer a complete
    prefix of this utterance, so it must never be accepted.

    THIS is the correctness guarantee, and it is a fact about what was heard,
    not a timing guess: a snapshot survives only when literally no frame above
    VAD_THRESHOLD followed it.

    CANCELLING the decode as well (2026-09-06 review) is a LATENCY guarantee,
    and it was missing: setting chunks = -1 stopped the prefix being spoken but
    nothing told the worker, which ran on holding _stt_lock for a full pass.
    _transcribe_capture skips its join entirely once chunks < 0, so the real
    end-of-capture decode went straight to transcribe() and blocked on that
    same lock — the mid-sentence-pause turn paid for TWO Whisper passes and
    waited out the useless one. Measured on the helpers here: one turn, decodes
    of [16000, 32000] samples where only the 32000 is wanted.

    A decode already inside faster-whisper still cannot be interrupted — that
    residual is unfixable without preemption, and is one of the standing
    reasons _SPECULATIVE_STT ships off."""
    if _spec_stt["chunks"] >= 0:
        _spec_stt["chunks"] = -1
        _spec_stt["gen"] += 1


def _spec_stt_should_snapshot(silence_n: int, spec_at: int, n_chunks: int,
                              spec_min_chunks: int) -> bool:
    """Take a speculative snapshot on THIS chunk?  Exactly at the trip point
    (so one snapshot per silence run), only with no snapshot already standing,
    only with enough audio to be worth decoding, and only when no earlier
    speculative decode is still running (bounding us to one at a time)."""
    if not _SPECULATIVE_STT:
        return False
    if _spec_stt["chunks"] >= 0 or silence_n != spec_at:
        return False
    if n_chunks < spec_min_chunks:
        return False
    t = _spec_stt["thread"]
    return t is None or not t.is_alive()


def _spec_stt_start(snapshot, peak_rms: float, n_chunks: int) -> None:
    """Transcribe `snapshot` on a daemon thread. Never raises into the mic
    loop — a failure here just means the normal path does the work."""
    token = _spec_stt["token"]
    gen = _spec_stt["gen"]

    def _worker():
        res = None
        try:
            # CANCELLATION CHECK 1 — before any work. The owner can resume in
            # the gap between t.start() and this line; under GIL contention
            # with the audio callback that gap is real milliseconds.
            if _spec_stt["gen"] != gen:
                return
            audio, _gain = apply_capture_auto_gain(snapshot, peak_rms)
            # NEVER QUEUE on _stt_lock (2026-09-06 review). A speculative
            # decode is a bet, and a bet that has to wait its turn has already
            # lost: whoever holds the lock is mid-decode, and the voice thread's
            # own fallback transcribe() would then sit behind BOTH of us — the
            # feature would have ADDED latency to the turn it exists to shorten.
            # If the model is busy, fold and let the normal path do the work.
            # transcribe() is the blocking entry point, so take the lock
            # ourselves and call _transcribe_impl, whose contract is exactly
            # "_stt_lock held".
            if _stt_lock.acquire(blocking=False):
                try:
                    # CANCELLATION CHECK 2 — on the far side of the lock, the
                    # last instant before the model is committed. Winning the
                    # lock is not the same as still being wanted.
                    if _spec_stt["gen"] != gen:
                        return
                    res = _transcribe_impl(audio)
                finally:
                    _stt_lock.release()
            elif _debug_mode[0]:
                print("  [spec-stt] model busy — folding, no bet placed")
        except Exception as _e:
            print(f"  [spec-stt] speculative decode failed "
                  f"({type(_e).__name__}: {_e}) — falling back")
            res = None
        if _spec_stt["token"] == token:
            _spec_stt["result"] = res
    try:
        t = threading.Thread(target=_worker, daemon=True, name="spec-stt")
        _spec_stt["chunks"] = n_chunks
        _spec_stt["thread"] = t
        t.start()
    except Exception as _e:
        # Thread exhaustion is a live hazard in this codebase — degrade, never
        # raise into the capture loop.
        print(f"  [spec-stt] could not start ({type(_e).__name__}: {_e})")
        _spec_stt["chunks"] = -1
        _spec_stt["thread"] = None


def _transcribe_capture(audio):
    """transcribe(`audio`), but collect the speculative decode instead when
    this capture produced a valid one. Same (text, conf) return either way.

    `audio` must already be auto-gained — the speculative worker applies the
    same gain to its own snapshot from the same (final) peak RMS, so the two
    paths feed faster-whisper identically-scaled samples."""
    t = _spec_stt.get("thread")
    if _SPECULATIVE_STT and t is not None and _spec_stt.get("chunks", -1) >= 0:
        # This join is NOT a latency bound, and the comment here used to claim
        # it was ("Bounded: a wedged decode must not hold the voice thread").
        # It cannot be one, by construction: transcribe() below acquires
        # _stt_lock, and a still-running worker is INSIDE that same lock. So
        # abandoning the join does not free the voice thread — it queues a
        # SECOND, redundant decode behind the very one we just gave up on, and
        # we pay both. Measured on the real helpers with a 12 s stalled worker:
        # 1,400 ms with the feature off vs 13,401 ms giving up at 8 s.
        # Waiting for the decode already in flight is therefore never slower
        # than giving up on it, and usually much faster.
        t.join(timeout=_SPEC_STT_WAIT)
        if t.is_alive():
            print(f"  [spec-stt] decode still running after {_SPEC_STT_WAIT:.0f}s"
                  f" — waiting for it rather than queueing a second decode"
                  f" behind it on _stt_lock")
            t.join(timeout=_SPEC_STT_HARD_WAIT)
        res = _spec_stt.get("result")
        # Re-check the snapshot rule: only trailing silence may separate the
        # decoded audio from the final buffer.
        if res is not None and _spec_stt.get("chunks", -1) >= 0:
            if _debug_mode[0]:
                print(f"  [spec-stt] used speculative transcript "
                      f"({_spec_stt['chunks']} chunks)")
            return res
    return transcribe(audio)

# Raw (pre auto-gain) audio + sample-rate of the most recent mic capture, stashed
# by _capture_utterance so the background-audio gate can run voice-ID on it
# (_ambient_learn_from_gated) WITHOUT plumbing the buffer through the return
# signature. None on the inject path (no real audio) and after a non-mic turn.
# Mirrors the single-global idiom of _last_recording_peak above. 2026-06-07.
_last_capture_audio: "np.ndarray | None" = None
_last_capture_sr: int = 0

# 2026-05-30 [self-heal]: guard for the silent-mic warning emitted by
# record_speech when raw mic RMS stays at zero past MIC_SILENT_WARN_SECONDS
# while JARVIS is awake. Resets once an audible chunk is seen, so a transient
# driver glitch + recovery can re-warn next time.
#
# 2026-08-20 (honest reporting): it was one print per PROCESS, into a console
# that does not exist under pythonw. The reset arm is `elif rms > 1e-5`, and
# core.audio_processor._AUDIBLE_RMS_FLOOR is that same 1e-5, so on a device
# handing back true digital silence the latch could never clear — the owner got
# exactly one line, ever, describing the one fault he cannot ask JARVIS about
# (the mic is how you ask). It now re-warns on a bounded interval, re-arms when
# the selected input changes, and SAYS it once per stretch.
#
# What it deliberately does NOT do is demote the device. Under the
# follow-the-default contract (see _refresh_devices / _default_device_identity)
# _device_cache["in"] is left None on purpose so every stream open re-resolves
# the Windows default; a skip-list written into that cache is exactly the
# pinning that contract exists to prevent — and it was pinning a
# still-enumerable dead endpoint that left this box deaf for 90 minutes.
# PREFERRED_INPUT_DEVICES is empty here, so there is no "next preferred entry"
# to demote to either. The honest move is to name the endpoint and the remedy.
_silent_mic_warned = [False]
_silent_mic_warned_at = [0.0]
_silent_mic_warned_device = [""]
# Bounded re-warn so a persistent fault stays visible across a long session
# without becoming chatter. Not a config knob: MIC_SILENT_WARN_SECONDS already
# owns the "how long is too long" decision; this only bounds repetition.
MIC_SILENT_REWARN_SECONDS = 900.0


def _report_silent_mic(silent_age: float, now: float) -> bool:
    """Report a mic that enumerates and opens but returns only zeros.

    Console AND spoken, because the failure mode removes the owner's ability to
    ask. Throttled by MIC_SILENT_REWARN_SECONDS, and re-armed immediately when
    the selected input device changes (a fresh endpoint that is ALSO silent is
    new information). Returns True when it reported this time.

    Never raises: this runs inside record_speech's per-chunk loop."""
    try:
        device = _device_cache.get("last_in_name") or ""
    except Exception:
        device = ""
    changed = device != _silent_mic_warned_device[0]
    if (_silent_mic_warned[0] and not changed
            and (now - _silent_mic_warned_at[0]) < MIC_SILENT_REWARN_SECONDS):
        return False
    _silent_mic_warned[0] = True
    _silent_mic_warned_at[0] = now
    _silent_mic_warned_device[0] = device
    try:
        named = _friendly_device_name(device) or "your active microphone"
    except Exception:
        named = "your active microphone"
    print(f"  [vad] WARNING: raw mic RMS has been ≈0 for {silent_age:.0f}s "
          f"while JARVIS is awake on {device or 'the default input'} — likely "
          f"silent-mic hardware/driver fault. Check Windows Privacy → "
          f"Microphone, verify the active input device, and try unplug/replug "
          f"if USB. (threshold "
          f"MIC_SILENT_WARN_SECONDS={MIC_SILENT_WARN_SECONDS})")
    try:
        proactive_announce(
            f"Sir, {named} has been completely silent for "
            f"{int(silent_age)} seconds — I can hear nothing at all from it. "
            f"Check Windows microphone privacy, or switch input devices and "
            f"I'll follow.",
            source="audio")
    except Exception as e:
        print(f"  [vad] silent-mic announcement failed: {e}")
    return True

# ── Main-loop watchdog (bug-5) ────────────────────────────────────────────
# Guards against record_speech() (or anything else on the main thread)
# hanging indefinitely on a flaky mic. The main loop ticks the heartbeat
# by calling _heartbeat() around each of its 'Listening' / 'Recording' /
# 'Sleeping' / '[inject]' status-line prints; a daemon thread polls every
# 10s and, if it's been >60s since the last tick, sets the reset signal
# so the open InputStream's audio_q.get(timeout=0.1) wakes, the
# `with _record_stream:` block exits (closing the stream), and the main
# loop snaps back to its top.
_MAIN_LOOP_HEARTBEAT_TIMEOUT = 60.0   # seconds of silence before recovery
_MAIN_LOOP_WATCHDOG_INTERVAL = 10.0   # how often the watchdog checks
_main_loop_heartbeat = [time.time()]
_watchdog_reset_signal = threading.Event()
_watchdog_stop_event   = threading.Event()   # only for test cleanup


# The on-disk half of the heartbeat, for the out-of-process reader:
# core/diagnostic_daemons._check_stuck_loop. Throttled so a 30 Hz-ish loop does
# not become a 30 Hz writer; the reader only ever looks at the mtime.
_MAIN_LOOP_HEARTBEAT_PUBLISH_S = 1.0
_last_heartbeat_publish = [0.0]
_main_loop_heartbeat_path_cache = [""]


def _main_loop_heartbeat_path() -> str:
    """Path of the liveness file core/diagnostic_daemons watches.

    IMPORTED from the reader rather than re-joined here. This repo's #1 bug
    class is one rule living in two copies, and a heartbeat whose writer and
    watcher disagree about the path is a permanently-firing false alarm (the
    exact defect this whole heartbeat replaces). Resolved lazily and cached:
    the daemons module is already imported by the time the main loop ticks.
    """
    if not _main_loop_heartbeat_path_cache[0]:
        try:
            from core.diagnostic_daemons import MAIN_LOOP_HEARTBEAT_FILE as _p
            _main_loop_heartbeat_path_cache[0] = _p
        except Exception:
            # Degraded fallback only — same resolver the daemon uses, so the
            # two still agree unless core.paths itself is unimportable.
            try:
                from core.paths import data_file as _data_file
                _main_loop_heartbeat_path_cache[0] = _data_file(
                    "main_loop_heartbeat")
            except Exception:
                return ""
    return _main_loop_heartbeat_path_cache[0]


def _publish_main_loop_heartbeat(force: bool = False, now: float | None = None):
    """Touch the main-loop liveness file, at most once a second.

    UNCONDITIONAL by design. The previous liveness signal was hud_state.json's
    mtime, whose writer starts `if not HUD_ENABLED: return` — so turning the
    HUD off froze the signal and the anomaly watcher reported a stuck main loop
    every 30 minutes, forever, on a perfectly healthy JARVIS. Nothing may gate
    this call. Never raises: instrumentation must not be able to kill the loop
    it measures."""
    now = time.time() if now is None else now
    if not force and (now - _last_heartbeat_publish[0]
                      < _MAIN_LOOP_HEARTBEAT_PUBLISH_S):
        return
    _last_heartbeat_publish[0] = now
    try:
        path = _main_loop_heartbeat_path()
        if not path:
            return
        # Plain truncate-write: the reader only uses getmtime(), there is a
        # single writer, and an atomic replace would cost a temp file per
        # second for no benefit.
        with open(path, "w", encoding="utf-8") as f:
            f.write(f"{now:.3f}\n")
    except Exception:
        pass


def _heartbeat():
    """Mark the main loop as alive. Called by the main loop just before
    each of its four status-line prints (Listening / Recording / Sleeping
    / [inject]). Also clears any stale reset signal — if we got here, the
    last recovery succeeded and the loop is healthy again.

    Publishes the on-disk heartbeat too (throttled), so the out-of-process
    anomaly watcher measures the SAME liveness the in-process watchdog does."""
    _main_loop_heartbeat[0] = time.time()
    _publish_main_loop_heartbeat(now=_main_loop_heartbeat[0])
    if _watchdog_reset_signal.is_set():
        _watchdog_reset_signal.clear()


def _main_loop_watchdog_check(now: float | None = None,
                              threshold: float | None = None) -> bool:
    """One tick of the watchdog. Returns True if a stall was detected and
    the reset signal was just raised. Separated from the thread loop so a
    unit test can drive a single tick without sleeping."""
    if now is None:
        now = time.time()
    limit = threshold if threshold is not None else _MAIN_LOOP_HEARTBEAT_TIMEOUT
    age = now - _main_loop_heartbeat[0]
    if age > limit and not _watchdog_reset_signal.is_set():
        print(f"[watchdog] main loop stalled — recovering "
              f"(heartbeat {age:.1f}s old)")
        _watchdog_reset_signal.set()
        return True
    return False


def _main_loop_watchdog_thread():
    """Daemon: wake every _MAIN_LOOP_WATCHDOG_INTERVAL seconds and check
    whether the main loop's heartbeat is stale. Best-effort — never let
    a check exception take the thread down."""
    while not _watchdog_stop_event.is_set():
        try:
            _main_loop_watchdog_check()
        except Exception as e:
            print(f"[watchdog] check failed: {e}")
        # Use Event.wait so tests can stop the thread promptly.
        if _watchdog_stop_event.wait(_MAIN_LOOP_WATCHDOG_INTERVAL):
            return


def _recover_from_main_loop_error(exc: BaseException) -> None:
    """Best-effort recovery after one main-loop turn raised an unexpected
    exception. The main `while True:` body wraps each iteration in
    `except Exception` and calls this, then `continue`s to the next turn, so
    a single malformed turn (a callee raising — e.g. an LLM-dispatch fault)
    can no longer propagate out of main() and take the assistant permanently
    offline. The watchdog only recovers a STALLED loop (stale heartbeat); it
    does nothing for a loop that threw and exited — there is no supervisor
    relaunching the detached pythonw process, so the loop must self-heal here.

    Logs the full traceback (matching the _thinking_loop / face-track per-
    iteration nets) and returns the HUD/avatar to idle. Never raises — a
    failure inside the recovery path must not re-break the loop it protects."""
    try:
        logging.exception("[main-loop] turn failed — recovering and "
                          "continuing to next turn: %r", exc)
    except Exception:
        pass
    try:
        set_state("idle")
    except Exception:
        pass


def _process_capture_chunk(chunk: np.ndarray,
                           sample_rate: int = SAMPLE_RATE,
                           skip_ns: bool = False) -> np.ndarray:
    """Run a single mic chunk through the noise-cancel-1 pipeline (AEC →
    noise suppression → AGC). Falls through to the raw chunk when the
    processor module isn't available or any stage errors — VAD is run on
    the RAW signal by the caller so processing failures can never affect
    speech endpointing.

    skip_ns: drop ONLY the noise-suppression stage for this chunk. NS
    (noisereduce spectral gating) costs 1-2s of CPU per ~2.6s chunk — the
    caller passes True for clearly-silent idle chunks so the main loop
    isn't pinned processing guaranteed-discard audio (AEC/AGC still run so
    their adaptive state stays warm across the silence)."""
    if not _audio_master_enabled[0] or _audio_processor is None:
        return chunk
    try:
        proc = _audio_processor.get_processor(sample_rate)
        return proc.process(
            chunk,
            enable_aec=bool(_audio_aec_enabled[0]),
            enable_ns=bool(_audio_ns_enabled[0]) and not skip_ns,
            enable_agc=bool(_audio_agc_enabled[0]),
        )
    except Exception as e:
        if _debug_mode[0]:
            print(f"  [audio-proc] process failed, passing through: {e}")
        return chunk


def _feed_playback_reference(audio: np.ndarray, sr: int) -> None:
    """Hand outgoing TTS audio to the noise-cancel-1 processor so its AEC
    layer has a far-end reference signal. Silent no-op if the module
    isn't loaded."""
    if not _audio_master_enabled[0] or _audio_processor is None:
        return
    try:
        _audio_processor.feed_playback(audio, sample_rate=sr)
    except Exception:
        pass


def _safe_close_stream(stream, timeout_sec: float = 2.0) -> None:
    """Stop+close a sounddevice stream without ever blocking the caller.

    sounddevice.close() at sounddevice.py:1167 has SIGSEGV'd in production
    (faulthandler caught it across multiple PIDs on 2026-05-29). The pattern
    here mirrors the previous barge_stream fix: stop synchronously, then
    close on a daemon thread guarded by `timeout_sec`. If native close hangs
    we ABANDON the daemon (it dies with the process) — see the H-3 note at
    the bottom of this function for why there is no sd.stop() "recovery".
    Use this in place of `with sd.InputStream(...)` so context-manager
    exits — which were the unprotected path — never crash the
    interpreter."""
    if stream is None:
        return
    try:
        stream.stop()
    except Exception:
        logging.exception("[audio] stream.stop raised — proceeding to close")
    done = threading.Event()
    def _do_close():
        try:
            stream.close()
        except Exception:
            logging.exception("[audio] stream.close raised — swallowing")
        finally:
            # H-6: retire the in-flight-close registration BEFORE waking the
            # caller, so a caller whose bounded wait SUCCEEDS never leaves a
            # phantom count behind. On the abandon path this runs late (or
            # never, if PortAudio truly wedged) — which is the whole point.
            _pa_close_done()
            done.set()
    t = threading.Thread(target=_do_close, daemon=True)
    # H-6 (2026-08-20): the wait below is bounded and we ABANDON the daemon on
    # timeout — while it is still inside Pa_CloseStream. Register the close so
    # _refresh_devices defers its destructive sd._terminate() until this native
    # call actually returns. This single edit covers BOTH abandon sites that
    # route here: record_speech's stream teardown and play_with_lipsync's
    # barge_stream teardown.
    _pa_close_handoff(t)
    if not done.wait(timeout=timeout_sec):
        # H-3 (2026-08-20): DO NOT call sd.stop() here. It is not a recovery —
        # it is a cross-close. Module-level sd.stop() (sounddevice 0.5.5,
        # sounddevice.py:406-418) ignores the stream you are holding and
        # instead stops+closes whatever `_last_callback` points at, and
        # `_last_callback` is published in exactly ONE place —
        # _CallbackContext.start_stream, reached only from
        # sd.play()/sd.rec()/sd.playrec(). Every stream that reaches this
        # helper is an explicitly constructed InputStream, so sd.stop() could
        # never free THIS handle; what it could do is stop+close the live TTS
        # play stream that play_with_lipsync's single-toucher reaper owns —
        # two threads inside Pa_CloseStream on one WASAPI stream, which is the
        # 0xc0000374 heap corruption the reaper contract at _reap_playback was
        # written to eliminate. It fired benignly three times in the session
        # logs (most recently 2026-08-20 03:34:47) only because no sd.play()
        # happened to be live. (H-7, same day, narrows the second half: a
        # reaper-owned play stream now leaves `_last_callback` at handoff, so
        # sd.stop() could no longer reach it. The rule is unchanged — it still
        # cannot free THIS handle, so it is all risk and no benefit, and the
        # risk returns the moment anything republishes that slot.) Abandoning
        # is the honest outcome: the daemon
        # keeps the close registered via _pa_close_pending, so _refresh_devices
        # defers its destructive sd._terminate() until PortAudio really returns.
        logging.warning(
            "[audio] stream.close hung >%.1fs — abandoning the close daemon "
            "(it dies with the process; the in-flight close stays registered "
            "with the teardown gate). sd.stop() is deliberately NOT called: it "
            "only acts on the last sd.play()/sd.rec() stream, so it cannot "
            "free this handle and would instead close a live TTS playback "
            "stream (double Pa_CloseStream -> 0xc0000374).", timeout_sec)


# ── Live taps on record_speech's mic stream ───────────────────────────────
# get_mic_buffer() (voice enrollment, speaker ID, the standby-audio loop)
# registers a queue here instead of opening a SECOND InputStream on the same
# device. Windows WASAPI starves/garbles concurrent opens on one mic — that
# was the root cause of the 2026-05-30 "records noise for ~70s → watchdog
# reset" stall: the standby-audio loop opened a competing stream every 5s,
# pushing record_speech's frames above the VAD floor so it recorded forever.
# When record_speech holds the mic, skills tap its frames; only when it's
# idle does get_mic_buffer fall back to opening its own stream.
_record_speech_active = [False]          # True while record_speech holds the mic
_tts_playback_active  = [False]          # True while play_with_lipsync owns the speakers + barge-in stream
_record_speech_sr     = [SAMPLE_RATE]    # sample rate of the live stream
# True while a get_mic_buffer Path-B temporary InputStream is live. SEPARATE from
# _record_speech_active (which record_speech owns exclusively) so Path B never has
# to save+restore record_speech's flag — the old save+restore was a lost-update
# race (HIGH, 2026-07-08): if record_speech began after Path B snapshotted the flag
# False but before Path B's finally, the finally stomped record_speech's genuine
# True back to False while its stream was live, re-opening the ~70s WASAPI stall +
# 0xc0000374 reinit-under-live-callback window the flag exists to close. Each owner
# now writes ONLY its own flag; _refresh_devices defers its destructive PortAudio
# reinit while ANY owner cell is set (checked atomically with the reinit latch
# under _mic_lock — see the _pa_gate teardown gate below, 2026-08-14).
_pathb_mic_active     = [False]
# REFCOUNT of live dedicated InputStreams held by skills/ambient_listen — its
# WASAPI system-audio loopback stream and/or its mic-fallback stream. Those daemons
# run for minutes and (unlike record_speech) set NONE of the other ownership flags,
# so _refresh_devices could sd._terminate()/_initialize() PortAudio out from under a
# live callback thread → 0xc0000374 heap corruption (HIGH, 2026-07-08).
# It is a COUNT, not a boolean: the mic worker and the loopback worker are separate
# skills that can run CONCURRENTLY, so a shared boolean let whichever exited first
# clear the guard while the other's stream was still live (bug-hunt 2026-07-08).
# ambient_listen increments on each stream open and decrements on close (via
# _pa_claim_owner/_pa_release_owner when the host exposes them, falling back to
# a plain _mic_lock-guarded ++/--); _refresh_devices defers its destructive
# reinit while the count is > 0.
_ambient_stream_active = [0]
# REFCOUNT of live sd.rec() probe captures held by skills/self_diagnostic's
# microphone probe (sweeps could overlap, hence a count like the ambient cell).
# The probe daemon's ~0.25s captures set NONE of the flags above, so before the
# teardown gate _refresh_devices could reinit PortAudio under a live sd.rec
# callback (0xc0000374). Claimed via _pa_claim_owner(refcount=True); released
# in a finally after the last capture. 2026-08-14.
_diag_capture_active = [0]
# True while skills/enroll_voice's local FALLBACK capture (its sd.rec or its
# InputStream twin) is live. Enrolment runs on the main voice thread only, so
# a plain boolean cell suffices. 2026-08-14.
_enroll_capture_active = [False]
# COUNT of native Pa_CloseStream calls that have been handed to an ABANDONABLE
# daemon thread (H-6, 2026-08-20). _safe_close_stream and play_with_lipsync
# both hand the native close to a daemon and then park on a BOUNDED wait; when
# that wait expires they ABANDON the daemon ("it dies with the process") and
# run their own finally, which drops their owner flag. But a caller timeout is
# POSITIVE EVIDENCE that the daemon is STILL INSIDE PortAudio's stop/close —
# so dropping the owner flag there told _refresh_devices "nobody owns a
# stream" and re-opened the exact sd._terminate()-during-a-live-native-call
# window (0xc0000374 heap corruption) the teardown gate was built to close.
#
# The owner flags themselves must keep telling the TRUTH — the barge-in gate,
# ambient listen, the face tracker, the dossier and the self-diagnostic probe
# all read them and would stall forever on a lie — so the in-flight native
# close gets its OWN cell instead of pinning somebody else's flag up.
#
# A COUNT, not a boolean: barge_stream, the play stream and record_speech's
# stream can each be abandoned independently and concurrently.
#
# INCREMENTED BY THE CALLER (_pa_close_handoff) while its own owner flag is
# STILL SET — the latch is provably clear at that moment (the caller's own
# flag is what keeps it clear), so the bump needs no _pa_claim_owner wait and
# can never fail. DECREMENTED BY THE DAEMON (_pa_close_done) in the finally
# that follows its native close, BEFORE it signals the caller's event.
# Consequence worth knowing: a daemon that merely finishes LATE releases the
# deferral by itself; only a daemon that never returns from PortAudio holds it
# for the life of the process — and in that case deferring is CORRECT, not
# merely conservative, because the native call really is still running.
#
# Deferral scope: this cell gates ONLY the destructive
# sd._terminate()/sd._initialize() pass. It deliberately does NOT deny
# _pa_claim_owner — opening a NEW stream while some other stream's close is
# wedged is exactly what the mic/TTS flags already allow — and it does NOT
# skip _refresh_devices' cheap _pick_device re-pick over the existing
# enumeration, so switching between ALREADY-ENUMERATED devices keeps working.
# What is lost while it is held: discovery of a device that was not in the
# last enumeration (true hotplug). See the deny chain in _refresh_devices.
#
# Read by _pa_streams_live + _refresh_devices' deny chain; MIRRORED in
# skills/self_diagnostic._mic_owned and registered from
# core/wake_word._safe_close_stream (stale-duplicate rule — all three).
_pa_close_pending = [0]
# Serialises every owner-flag write above AND the reinit latch below into ONE
# atomic domain (the _pa_gate Condition is built on this same lock).
# LOCK DISCIPLINE (deadlock rule, 2026-08-14): the only permitted order is
# _device_refresh_lock -> _mic_lock, never the reverse — so NEVER call
# _refresh_devices / get_input_device / get_output_device while holding
# _mic_lock, and never hold _mic_lock across native PortAudio calls or slow
# work. Flag/latch transitions only.
_mic_lock = threading.Lock()             # serialises mic-ownership flag + reinit-latch writes
# TEARDOWN GATE (2026-08-14, portaudio-teardown-race). True ONLY while
# _refresh_devices is inside its destructive sd._terminate()/sd._initialize()
# pass. Set atomically (under _mic_lock, via _pa_gate) after verifying that
# ZERO stream owners are live; owners claim their flags under the same lock
# only while this latch is clear (_pa_claim_owner, bounded wait). Because every
# stream open follows its claim and every release follows its close, an open
# stream implies a set flag implies the latch can never be taken — a reinit
# under a live/opening/closing guarded stream is structurally impossible. The
# old one-shot flag snapshot at the top of the reinit chain could race the
# tens-to-hundreds-of-ms native window (0xc0000374 heap corruption).
_pa_reinit_active = [False]
_pa_gate = threading.Condition(_mic_lock)

# ONE-SHOT DEFERRAL LOGGING (2026-08-21). _refresh_devices' deny chain used to
# print its reason on EVERY pass it deferred. Live proof that this is not a
# theoretical concern: session_2026-08-21_00-00-51.log carries 34 of those
# lines in 15 minutes — 25 "a mic/audio stream is live" and 9 "TTS playback is
# live" — because record_speech and TTS are essentially always live on an awake
# session, so a state that persists for minutes printed like an event that
# happened hundreds of times. A repeating condition is a STATE: log the
# transition in, and the transition out, and nothing in between. Holds the
# reason KEY that was last logged, or None while nothing is deferred.
_pa_defer_logged = [None]


def _log_reinit_deferral(reason: str | None, message: str = "") -> None:
    """Log the destructive-reinit deferral as a STATE TRANSITION.

    ``reason`` is a short stable key ("mic" / "tts" / "close") while the reinit
    is being held off, or None when it no longer is. The first pass that enters
    a reason prints ``message``; every later pass with the SAME reason prints
    nothing; the pass that clears it prints one closing line. A reason CHANGING
    (mic → tts) is a real transition and prints, because it is different
    information about why JARVIS is not following the device yet.

    Never raises — this sits on the path every get_input_device() caller takes,
    including the main voice loop."""
    try:
        prev = _pa_defer_logged[0]
        if reason == prev:
            return
        _pa_defer_logged[0] = reason
        if reason is not None:
            if message:
                print(message)
        elif prev is not None:
            print("  [audio] the PortAudio re-enumeration is no longer "
                  "deferred — the stream owner that was holding it released.")
    except Exception:
        pass


def _pa_mic_capture_live() -> bool:
    """True while any MIC-side capture owner holds (or is opening/closing) a
    stream. Caller MUST hold _mic_lock (_pa_gate). Sub-check of
    _pa_streams_live so the owner list exists in exactly ONE place."""
    return bool(_record_speech_active[0] or _pathb_mic_active[0]
                or _ambient_stream_active[0] or _diag_capture_active[0]
                or _enroll_capture_active[0])


def _pa_streams_live() -> bool:
    """THE canonical PortAudio owner check: True while ANY guarded stream owner
    is live (mic-side captures + TTS playback/barge-in) OR while an abandoned
    native Pa_CloseStream is still in flight (_pa_close_pending, H-6). Caller
    MUST hold _mic_lock. skills/self_diagnostic._mic_owned mirrors this list
    (minus the probe's own _diag_capture_active cell) — update BOTH together.

    VERIFIED 2026-08-20: its ONE caller is _refresh_devices' ADVISORY
    pre-check (`_owners_busy`), which decides whether it is worth pausing the
    wake-word stream and asserting the follow-the-default trigger this pass.
    That call does NOT gate the reinit — _refresh_devices spells the same
    checks out again inline, under the same lock, so each can print its own
    reason, and THAT inline chain is the site that actually gates it. Keep this
    function as the single written-down definition of the owner list, but
    understand that adding a cell here alone changes nothing binding: it must
    also go into _refresh_devices' deny chain below."""
    return (_pa_mic_capture_live() or bool(_tts_playback_active[0])
            or bool(_pa_close_pending[0]))


def _pa_claim_owner(cell, *, refcount: bool = False, timeout: float = 1.0,
                    deny_if=None) -> bool:
    """Atomically claim a PortAudio owner cell, honouring the reinit latch.

    Waits (BOUNDED — house rule: no unbounded waits) while _refresh_devices'
    destructive sd._terminate()/_initialize() pass is in flight, then sets the
    cell under _mic_lock (booleans -> True; refcounts -> +1). Returns False
    WITHOUT claiming when the latch stays up past ``timeout`` (the caller must
    skip this capture/playback cycle) or when ``deny_if()`` — evaluated under
    the lock — vetoes the claim. Every successful claim MUST be paired with
    exactly one _pa_release_owner at the same call depth, and the release must
    run only AFTER the owned stream's native close (close-then-release)."""
    deadline = time.monotonic() + timeout
    with _pa_gate:
        while _pa_reinit_active[0]:
            rem = deadline - time.monotonic()
            if rem <= 0:
                return False
            _pa_gate.wait(rem)
        if deny_if is not None and deny_if():
            return False
        cell[0] = (int(cell[0]) + 1) if refcount else True
        return True


def _pa_release_owner(cell, *, refcount: bool = False) -> None:
    """Release a cell claimed via _pa_claim_owner (booleans -> False;
    refcounts -> -1, floored at 0). Call ONLY after the owned stream's native
    teardown has completed — the flag must cover the stream's whole native
    lifetime or the gate can latch mid-close (0xc0000374)."""
    with _mic_lock:
        cell[0] = max(0, int(cell[0]) - 1) if refcount else False


def _pa_close_handoff(t: "threading.Thread") -> None:
    """Register an ABANDONABLE native Pa_CloseStream and start the daemon that
    performs it (H-6, 2026-08-20).

    The caller is about to hand ``t`` a live PortAudio stream and then park on
    a BOUNDED wait it is allowed to give up on. Bump _pa_close_pending FIRST,
    while the caller's own owner flag is still set: the reinit latch is
    provably clear at that instant (the caller's flag is what keeps it clear),
    so this needs no _pa_claim_owner wait and cannot fail. The daemon retires
    the count via _pa_close_done in the finally after its native close.

    If the thread cannot even be STARTED (``RuntimeError: can't start new
    thread`` — the same thread exhaustion _speak's belt-and-braces flag clear
    already guards against) the count is retired again before re-raising:
    otherwise a hand-off that never happened would defer hotplug for the life
    of the process.

    ONE definition, three call sites (_safe_close_stream and
    play_with_lipsync's two tts-reaper branches) plus the
    core/wake_word._safe_close_stream twin — do not inline copies."""
    with _mic_lock:
        _pa_close_pending[0] = int(_pa_close_pending[0]) + 1
    try:
        t.start()
    except BaseException:
        _pa_close_done()
        raise


def _pa_close_done() -> None:
    """Retire ONE in-flight native close. Called by the abandonable daemon in
    the finally that follows its Pa_CloseStream — BEFORE it sets the caller's
    done-event, so a caller whose bounded wait SUCCEEDS never leaves a phantom
    count behind. Floored at 0 so a stray call (a test driving the daemon body
    directly, a future double-retire) can never drive the gate negative and
    silently turn the deferral into a permanent PASS."""
    with _mic_lock:
        _pa_close_pending[0] = max(0, int(_pa_close_pending[0]) - 1)


def _pa_detach_play_stream(stream) -> bool:
    """Take the stream we just handed to the tts-reaper OUT of sounddevice's
    module-global ``_last_callback`` slot, so the NEXT ``sd.play()`` cannot
    touch it. Returns True when this call actually detached it.

    H-7 (2026-08-20) — the hole H-6 left open. H-3 deleted every EXPLICIT
    ``sd.stop()`` in the tree, but ``sd.play()`` calls it IMPLICITLY:
    ``_CallbackContext.start_stream`` begins with ``stop()``
    (sounddevice.py:2663), and module-level ``stop()`` is
    ``_last_callback.stream.stop(ignore_errors); _last_callback.stream.close(
    ignore_errors)`` (sounddevice.py:414-418). ``_StreamBase.close`` runs
    ``Pa_CloseStream(self._ptr)`` and only THEN nulls ``_ptr``, with no lock.

    So on the ABANDON path — the tts-reaper is still inside Pa_CloseStream, its
    caller's bounded wait expired, ``_tts_playback_active`` is (correctly)
    cleared — the very next utterance's ``sd.play()`` would run
    Pa_StopStream + a SECOND Pa_CloseStream against the handle the stranded
    reaper is still executing. Two threads in Pa_CloseStream on one WASAPI
    stream is the 0xc0000374 heap corruption the single-toucher contract
    exists to prevent, reached through the one path that contract explicitly
    accepts. ``_pa_close_pending`` cannot cover this: it deliberately gates
    only the destructive reinit and must NOT deny playback (a wedged close
    would otherwise mute JARVIS for the life of the process).

    The fence is ownership, not waiting: the moment the stream belongs to the
    reaper it leaves the shared slot, so it is provably unreachable by any
    later ``sd.play()``/``sd.stop()``/``sd.wait()``. This runs on EVERY
    handoff, not just the abandoned ones — one rule, one place, no branch to
    rot (the reaper is then the single toucher by construction rather than by
    luck, and the "benign Pa_CloseStream(NULL)" interaction described in
    _reap_playback's docstring stops happening at all).

    Safe against the object lifetime: the ctx in ``_last_callback`` is also
    referenced by the live stream itself (``_StreamBase._callback`` /
    ``_finished_callback`` hold it, and the numpy buffer hangs off the ctx),
    and the stream is referenced by the reaper thread's own argument — so
    dropping the module-global bookmark frees nothing PortAudio is reading.

    IDENTITY-CHECKED: only detaches when the slot still points at OUR stream.
    A slot holding somebody else's context means our stream is already
    unreachable (``stop()`` only ever touches the CURRENT ``_last_callback``),
    and nulling a live foreign context would strand ITS stream instead.
    Never raises — a sounddevice that has no such global (a test double, a
    future release) simply reports False."""
    if stream is None:
        return False
    try:
        ctx = getattr(sd, "_last_callback", None)
        if ctx is None or getattr(ctx, "stream", None) is not stream:
            return False
        sd._last_callback = None
        return True
    except Exception:
        logging.exception("[audio] could not detach the play stream from "
                          "sounddevice's _last_callback")
        return False


_record_speech_taps: "list[queue.Queue]" = []
_record_speech_taps_lock = threading.Lock()

# Hard ceiling on a single utterance. Once recording starts, the only other
# way out is SILENCE_SECS of sustained quiet — but if the mic feeds
# continuous above-threshold audio (music, a noisy room, a stuck driver
# buffer, or contention garbage) silence never lands and we'd record until
# the 60s watchdog kills the whole main loop. No real voice command runs
# this long; cap it and return what we have for transcription.
MAX_RECORDING_SECS = 30.0


def _fanout_record_frame(mono: "np.ndarray") -> None:
    """Push a captured mono frame to any registered taps. Runs on the
    PortAudio callback thread, so it must be cheap and exception-proof — a
    slow or dead tap consumer must never stall mic capture."""
    if not _record_speech_taps:
        return
    with _record_speech_taps_lock:
        taps = list(_record_speech_taps)
    for q in taps:
        try:
            q.put_nowait(mono)
        except Exception:
            pass


def add_record_tap(q: "queue.Queue") -> bool:
    """Register a queue to receive copies of record_speech's mic frames.
    Returns True if record_speech is currently live (so the caller knows the
    tap will actually deliver). Always pair with remove_record_tap in a
    finally."""
    with _record_speech_taps_lock:
        if q not in _record_speech_taps:
            _record_speech_taps.append(q)
    return bool(_record_speech_active[0])


def remove_record_tap(q: "queue.Queue") -> None:
    with _record_speech_taps_lock:
        try:
            _record_speech_taps.remove(q)
        except ValueError:
            pass


def record_speech(timeout: float | None = None) -> np.ndarray | None:
    """
    Blocks until the user speaks and finishes, then returns the audio.
    Returns None if `timeout` seconds pass without any speech starting.

    Uses a callback-based stream because some drivers (notably certain
    gaming headsets) don't honor blocking InputStream.read() — they return
    zero bytes immediately. Callback delivery works on all drivers.
    """
    # Blue/green: staging has no mic. Sleep briefly so the main loop's
    # busy-wait stays cheap, then yield None — the loop's `if audio is
    # None: continue` short-circuits cleanly and the inject drainer at
    # the top of the loop is what actually feeds work into staging.
    if _mic_input_disabled():
        time.sleep(0.5 if timeout is None else min(0.5, max(0.1, timeout)))
        return None
    CHUNK       = 1024
    PRE_BUFFER  = 12
    silence_lim = int(SILENCE_SECS * SAMPLE_RATE / CHUNK)
    # Speculative-transcription trip point, clamped so it can never land on or
    # past the real end-of-speech decision (a snapshot taken at silence_lim
    # would buy nothing) and never before there is any silence at all.
    spec_at = max(1, min(silence_lim - 1,
                         int(_SPEC_STT_SILENCE_SECS * SAMPLE_RATE / CHUNK)))
    spec_min_chunks = int(_SPEC_STT_MIN_SECS * SAMPLE_RATE / CHUNK)
    _spec_stt_reset()
    pre_ring: list[np.ndarray] = []
    chunks:   list[np.ndarray] = []
    recording   = False
    silence_n   = 0
    start_time  = time.time()
    peak_rms    = 0.0
    silent_peak = 0.0   # peak RMS while NOT recording (= ambient floor)

    audio_q: queue.Queue = queue.Queue()

    def _audio_cb(indata, frames, time_info, status):  # pragma: no cover - live mic stream callback
        # indata is (frames, channels); flatten to 1-D mono
        mono = indata[:, 0].copy() if indata.ndim > 1 else indata.copy()
        audio_q.put(mono)
        # Fan out to any skill taps so they never open a competing stream
        # on the same mic (WASAPI contention → the ~70s stall). Cheap +
        # exception-proof so it can't stall this callback.
        _fanout_record_frame(mono)

    # Resolve the mic index BEFORE claiming ownership. get_input_device()
    # → _refresh_devices() may run PortAudio's sd._terminate()/_initialize()
    # reinit (USB hotplug pickup); that MUST happen while the ownership flag
    # is still False, exactly as before — once we flip it True the reinit
    # path correctly defers. Resolving here also keeps the reinit out of the
    # window in which our own stream is live.
    _in_dev = get_input_device()
    # TOCTOU fix (0xc0000374): publish mic ownership BEFORE the InputStream is
    # opened+started, not after — and claim it through the _pa_gate TEARDOWN
    # GATE (2026-08-14), which atomically refuses the claim while
    # _refresh_devices is inside its destructive sd._terminate()/_initialize()
    # window. The old plain flag write closed the set-after-start gap but
    # could itself land INSIDE an in-flight native teardown (the refresher's
    # one-shot snapshot ran before the natives). A claim timeout (reinit hung
    # >1s) skips this cycle: the main loop treats None as no-speech and
    # re-loops. Any open/start failure below closes the stream and then clears
    # the flag so it is never left stuck True on a stream we don't hold.
    _record_speech_sr[0] = SAMPLE_RATE
    if not _pa_claim_owner(_record_speech_active):
        print("  [record_speech] PortAudio reinit in flight — "
              "skipping this capture cycle")
        return None
    # If get_mic_buffer Path B is mid-capture on this same device, we've just
    # signalled it to bail (Path B re-checks _record_speech_active every 0.2s and
    # breaks). Wait a BOUNDED moment for it to tear its temporary InputStream down
    # before we open ours, so two InputStreams never sit open together on one
    # WASAPI device — the ~70s double-open capture stall the tap path exists to
    # avoid (HIGH, 2026-07-08). Only waits when Path B is actually live (rare:
    # standby-audio / enrolment / speaker-ID); bounded so a stuck flag can never
    # delay live speech capture by more than ~0.6s.
    _pathb_wait_deadline = time.time() + 0.6
    while _pathb_mic_active[0] and time.time() < _pathb_wait_deadline:
        time.sleep(0.02)
    _record_stream = None
    # Defense-in-depth against a stale cached mic index: even after
    # get_input_device() validates, the device can disappear between
    # that query and InputStream open. Catch PortAudioError and retry
    # once with device=None so we don't crash main().
    try:  # pragma: no cover - opens+starts a live PortAudio input stream (needs real mic)
        try:
            _record_stream = sd.InputStream(
                samplerate=SAMPLE_RATE, channels=1, dtype="float32",
                blocksize=CHUNK, device=_in_dev,
                callback=_audio_cb)
        except sd.PortAudioError as e:  # pragma: no cover - live mic open-retry path (needs real device)
            print(f"  [record_speech] InputStream open failed on cached mic ({e}); retrying with system default")
            _device_cache["in"] = None
            _device_cache["checked_at"] = 0.0
            _record_stream = sd.InputStream(
                samplerate=SAMPLE_RATE, channels=1, dtype="float32",
                blocksize=CHUNK, device=None,
                callback=_audio_cb)
        # 2026-05-29 silent-crash fix: don't use `with _record_stream:` — the
        # implicit __exit__ calls sd close() unguarded, which SIGSEGV'd during
        # watchdog-driven exits and early returns. Start the stream and route
        # teardown through _safe_close_stream so close runs on a daemon thread.
        _record_stream.start()
    except Exception:
        # Open (incl. the system-default retry) or start() failed: we never
        # got a RUNNING stream, so drop the ownership flag we claimed above
        # before bailing, otherwise _refresh_devices would defer reinits
        # forever against a stream that doesn't exist. Close FIRST, release
        # SECOND (2026-08-14): a constructed-but-failed stream still holds
        # native state, and the flag must cover its close too or a reinit can
        # latch mid-teardown (same 0xc0000374 class as the main finally).
        logging.exception("[record_speech] InputStream open/start failed")
        try:
            _safe_close_stream(_record_stream)
        except Exception:
            pass
        _record_speech_active[0] = False
        return None
    record_start_ts = 0.0   # set when recording actually begins (VAD trip)
    try:  # pragma: no cover - live mic capture loop (blocks on real audio frames until utterance ends)
        while True:
            # Watchdog-driven recovery: if the main-loop watchdog has
            # flagged a stall (typically because we were stuck waiting on
            # audio_q.get and nothing was ever delivered), bail out. The
            # finally below closes the InputStream on the way out, which
            # the watchdog comment promises as part of recovery.
            if _watchdog_reset_signal.is_set():
                print("  [record_speech] watchdog reset signalled — "
                      "closing InputStream and returning")
                return None
            try:
                data = audio_q.get(timeout=0.1)
            except queue.Empty:
                # No audio arrived in the last 100ms — check watchdog + timeout
                if _watchdog_reset_signal.is_set():
                    print("  [record_speech] watchdog reset signalled — "
                          "closing InputStream and returning")
                    return None
                if (not recording and timeout is not None and
                        (time.time() - start_time) >= timeout):
                    if _debug_mode[0]:
                        print(f"  [vad] timeout — silent peak RMS={silent_peak:.4f} "
                              f"(threshold {VAD_THRESHOLD})")
                    return None
                continue

            # A frame arrived — the mic callback is alive and the loop is
            # cycling, so the main loop is healthy. Tick the watchdog here
            # (not only at record-start) so a stale heartbeat means "the mic
            # stopped delivering frames", never "the user is mid-utterance".
            # Without this, a long/continuous capture starved the heartbeat
            # and the 60s watchdog reset the loop mid-stream (the 2026-05-30
            # ~70s stall).
            _heartbeat()
            # Hard utterance ceiling: if continuous above-threshold audio
            # kept us recording past the cap, finalize now and let whisper
            # sort it out, rather than recording until the watchdog fires.
            if recording and (time.time() - record_start_ts) > MAX_RECORDING_SECS:
                print(f"  [record_speech] max utterance "
                      f"{MAX_RECORDING_SECS:.0f}s reached — finalizing")
                break

            rms = float(np.sqrt(np.mean(data ** 2)))
            if rms > peak_rms:
                peak_rms = rms

            # Publish a smoothed mic level to the HUD ~10 Hz. RMS is small
            # (≪1) so scale relative to the VAD threshold to fill the gauge.
            now_ts = time.time()
            if HUD_ENABLED and (now_ts - _last_mic_hud_write[0]) > 0.1:
                _last_mic_hud_write[0] = now_ts
                level = min(1.0, rms / max(VAD_THRESHOLD * 4.0, 1e-4))
                _write_hud_state(mic_level=level)

            # Surface VAD activity to skills/self_diagnostic. note_vad_poll
            # fires every chunk so the probe can tell the input loop is
            # actually running; note_vad_active fires only when we cross
            # the VAD floor so the probe can spot a "polling but never
            # tripping" stall. note_raw_rms feeds the silent-mic detector
            # (audible-chunk timestamp updates when rms crosses the hard-
            # ware floor, separate from VAD_THRESHOLD which gates speech).
            # Wrapped in try so an import-time issue with the audio_-
            # processor module can't kill the capture loop.
            try:
                from core import audio_processor as _ap_for_vad
                _ap_for_vad.note_vad_poll(now_ts)
                _ap_for_vad.note_raw_rms(rms, now_ts)
                if rms > VAD_THRESHOLD:
                    _ap_for_vad.note_vad_active(now_ts)
                # Silent-mic health check: if raw RMS has been ≈0 for
                # MIC_SILENT_WARN_SECONDS straight while JARVIS is awake,
                # the mic driver is almost certainly handing us null
                # frames (Windows mic-privacy block, USB unplug, dead
                # capture driver). Emit one warning per silent stretch
                # so the user sees a concrete pointer instead of just
                # "JARVIS isn't hearing me".
                silent_age = _ap_for_vad.seconds_since_audible_chunk()
                if (silent_age != float("inf")
                        and silent_age > float(MIC_SILENT_WARN_SECONDS)):
                    # _report_silent_mic owns the latch, the re-warn throttle
                    # and the spoken escalation.
                    _report_silent_mic(silent_age, now_ts)
                elif rms > 1e-5 and _silent_mic_warned[0]:
                    # Mic recovered — allow the warning to re-fire next
                    # time we drop silent for that long.
                    _silent_mic_warned[0] = False
                    _silent_mic_warned_at[0] = 0.0
                    _silent_mic_warned_device[0] = ""
                    print(f"  [vad] mic is audible again "
                          f"(RMS {rms:.5f}) — silent-mic warning re-armed")
            except Exception:
                pass

            # VAD decision uses the RAW RMS so existing VAD_THRESHOLD
            # tuning is unaffected by the processor's gain stage. We
            # only swap in the processed chunk when we *keep* it.
            # skip_ns: while idle with the raw RMS clearly under the
            # threshold, the chunk is headed for the pre-ring/discard —
            # running noisereduce's spectral gating on it (1-2s CPU per
            # 2.6s chunk) PINNED the main loop for minutes whenever room
            # noise hovered just below the threshold (py-spy 2026-07-12:
            # MainThread in spectral_gating_stationary, injected commands
            # starved 5+ min). AEC/AGC still run to keep their state warm;
            # full NS resumes the moment recording starts or rms rises.
            processed = _process_capture_chunk(
                data, SAMPLE_RATE,
                skip_ns=(not recording and rms < VAD_THRESHOLD * 0.75))
            if rms > VAD_THRESHOLD:
                if not recording:
                    recording = True
                    record_start_ts = time.time()
                    chunks.extend(pre_ring)
                    _heartbeat()
                    print("  🎙  Recording…")
                    pause_face_tracking()
                    set_state("listening")
                chunks.append(processed.copy())
                silence_n = 0
                _prof("voiced")
                # A voiced frame arrived AFTER a speculative snapshot, so that
                # snapshot is no longer this utterance — invalidate it. This is
                # the whole correctness guarantee: an accepted snapshot can
                # only ever differ from the final buffer by trailing silence.
                _spec_stt_note_voiced()
            else:
                if not recording and rms > silent_peak:
                    silent_peak = rms
                pre_ring.append(processed.copy())
                if len(pre_ring) > PRE_BUFFER:
                    pre_ring.pop(0)
                if recording:
                    chunks.append(processed.copy())
                    silence_n += 1
                    # Speculative transcription: bet the utterance is over and
                    # hide Whisper inside the remaining hangover. Only one
                    # decode in flight at a time (a resumed-then-paused
                    # utterance would otherwise queue several on _stt_lock).
                    if _spec_stt_should_snapshot(
                            silence_n, spec_at, len(chunks), spec_min_chunks):
                        _prof("spec_fire")
                        _spec_stt["result"] = None
                        _spec_stt_start(
                            np.concatenate(chunks).flatten(),
                            peak_rms, len(chunks))
                    if silence_n >= silence_lim:
                        _prof("vad_break")
                        break
                elif timeout is not None and (time.time() - start_time) >= timeout:
                    if _debug_mode[0]:
                        print(f"  [vad] timeout — silent peak RMS={silent_peak:.4f} "
                              f"(threshold {VAD_THRESHOLD})")
                    return None
    finally:
        # Close the stream BEFORE releasing mic ownership (2026-08-14): the
        # flag must cover the stream's whole native lifetime, or a reinit that
        # latches in the release→close gap runs Pa_Terminate while
        # stream.stop()/close() are still executing — exactly the 0xc0000374
        # class the _pa_gate teardown gate exists to kill. Tap consumers
        # (get_mic_buffer Path A2, the ambient tap) are deadline-bounded, so
        # the later flag drop costs them at most _safe_close_stream's 2s
        # bound — degraded, never hung. Do NOT swap this back to
        # release-then-close for tap latency.
        #
        # H-6 (2026-08-20) refines exactly ONE word of that claim: when
        # _safe_close_stream's own bounded wait expires it ABANDONS its close
        # daemon and returns, so the flag covers the native lifetime only up to
        # the abandon. The remainder is covered by _pa_close_pending, which
        # _safe_close_stream registers and the daemon retires. This flag itself
        # must still drop here — the barge-in gate, ambient listen, the face
        # tracker and the dossier read it and would stall forever on a lie.
        #
        # H-8 (2026-08-20): the flag clear gets its OWN finally. These used to
        # be two plain statements, and _safe_close_stream can now RAISE out of
        # the first one — _pa_close_handoff deliberately re-raises when the
        # close daemon cannot even be started ("RuntimeError: can't start new
        # thread", the thread exhaustion this codebase already treats as a live
        # hazard). One such raise and `_record_speech_active` stayed True for
        # the life of the process: _refresh_devices never re-enumerates again
        # (USB hotplug + follow-the-default dead), get_mic_buffer Path B
        # refuses every claim (speaker-ID, enrolment and standby audio return
        # None forever) and the self-diagnostic reports the mic permanently
        # owned — all silently, because the raise unwinds into the main loop's
        # per-iteration net. get_mic_buffer Path B already had this shape; this
        # copy did not (stale-duplicate rule).
        try:
            _safe_close_stream(_record_stream)
        finally:
            _record_speech_active[0] = False

    if _debug_mode[0]:
        print(f"  [vad] peak RMS={peak_rms:.4f}  threshold={VAD_THRESHOLD}  "
              f"ambient={silent_peak:.4f}")
    _prof("rec_return")
    global _last_recording_peak
    _last_recording_peak = peak_rms
    if not chunks:
        return None  # pragma: no cover - defensive: the loop only breaks after recording began, so chunks is never empty here
    return np.concatenate(chunks).flatten()


def apply_capture_auto_gain(audio_f32, peak_rms):
    """CONSERVATIVE input auto-gain (normalization) for the captured mic buffer,
    applied right BEFORE faster-whisper sees it on both the normal-turn and the
    standby/wake path.

    A quiet mic records clear speech at a low peak RMS (~0.01–0.06) where Whisper
    returns an EMPTY string and the wake word "JARVIS" is never detected. This
    boosts such audio toward a usable level WITHOUT degrading already-good audio.

    Returns ``(audio_f32, applied_gain)``:

      * auto-gain disabled, ``peak_rms`` already ≥ the loud-enough target, OR
        ``peak_rms`` at/below a tiny noise floor (so pure silence / room hiss is
        never amplified into Whisper hallucinations) → the audio is returned
        UNCHANGED with ``applied_gain == 1.0``.
      * otherwise the gain is ``min(MAX_GAIN, TARGET_PEAK / max(peak_rms, eps))``;
        the buffer is multiplied and HARD-CLIPPED to ``[-1.0, 1.0]`` to prevent
        overflow distortion, then returned with that gain.

    Never raises: any failure returns the ORIGINAL audio at gain 1.0 so a bad
    sample or a missing config knob can never break the capture path. The
    thresholds are read live from ``core.config`` so the Settings-GUI /
    ``user_settings.json`` override path reaches them.
    """
    try:
        if audio_f32 is None:
            return audio_f32, 1.0
        from core import config as _cfg
        if not getattr(_cfg, "CAPTURE_AUTO_GAIN_ENABLED", True):
            return audio_f32, 1.0
        target = float(getattr(_cfg, "CAPTURE_AUTO_GAIN_TARGET_PEAK", 0.25))
        max_gain = float(getattr(_cfg, "CAPTURE_AUTO_GAIN_MAX", 10.0))
        noise_floor = float(getattr(_cfg, "CAPTURE_AUTO_GAIN_NOISE_FLOOR", 0.005))
        peak = float(peak_rms)
        # Already loud enough, or so quiet it's silence/room hiss → leave it.
        # (peak <= noise_floor guards against amplifying pure noise into
        # hallucinated transcripts; peak >= target means normal audio, untouched.)
        if not (noise_floor < peak < target):
            return audio_f32, 1.0
        gain = min(max_gain, target / max(peak, 1e-9))
        if gain <= 1.0:
            return audio_f32, 1.0
        boosted = np.asarray(audio_f32, dtype=np.float32) * np.float32(gain)
        # Hard-clip so the boost can never overflow [-1, 1] into harsh distortion.
        np.clip(boosted, -1.0, 1.0, out=boosted)
        return boosted, float(gain)
    except Exception:
        # A normalization failure must never break capture — return the input.
        return audio_f32, 1.0


def get_mic_buffer(seconds: float,
                   sample_rate: int | None = None) -> np.ndarray | None:
    """Capture `seconds` of float32 mono audio for skills that need a fixed
    chunk of mic input (voice enrollment, speaker ID, etc.).

    Prefers to tap the wake-word listener's persistent InputStream when one
    is running — Windows WASAPI rejects a second open on the same input
    device, so a naive `sd.rec` from a skill while the listener is up will
    silently fail. Falls back to a fresh InputStream when no persistent
    stream exists, or when its sample rate doesn't match what was asked
    for (resampling would distort voiceprints).

    Returns None on capture failure or if sounddevice isn't available.
    """
    if _mic_input_disabled():
        # Mic hard-disabled (staging / MICROPHONE_INDEX<0): never open a capture
        # stream — get_input_device() would resolve it to the SYSTEM DEFAULT mic
        # and silently listen (this is what made staging transcribe in standby).
        return None
    target_sr = int(sample_rate or SAMPLE_RATE)
    need = max(1, int(target_sr * seconds))

    # Path A: tap the wake-word listener if available and rate-compatible.
    wl = sys.modules.get("skill_wake_listener")
    det = getattr(wl, "_detector", None) if wl is not None else None
    if (det is not None
            and getattr(det, "is_running", lambda: False)()
            and int(getattr(det, "sample_rate", 0)) == target_sr
            and hasattr(det, "add_tap")):
        tap_q: queue.Queue = queue.Queue()
        det.add_tap(tap_q)
        chunks: list[np.ndarray] = []
        captured = 0
        deadline = time.time() + seconds + 1.0
        try:
            while captured < need and time.time() < deadline:
                try:
                    frame = tap_q.get(timeout=0.2)
                except queue.Empty:
                    continue
                chunks.append(frame)
                captured += int(frame.size)
        finally:
            det.remove_tap(tap_q)
        if not chunks:
            return None
        out = np.concatenate(chunks).astype(np.float32, copy=False)
        return out[:need] if out.size > need else out

    # Path A2: tap record_speech's live stream if it owns the mic at a
    # compatible rate. This is the common case (the main loop is almost
    # always inside record_speech) and the whole point of the tap: never
    # open a SECOND InputStream on a mic record_speech is holding — WASAPI
    # contention there caused the 2026-05-30 ~70s capture stall. If
    # record_speech is live we either return its tapped audio or None
    # (skip this cycle); we deliberately do NOT fall through to Path B,
    # because Path B would re-introduce the competing open.
    if _record_speech_active[0] and int(_record_speech_sr[0]) == target_sr:
        tap_q2: queue.Queue = queue.Queue()
        add_record_tap(tap_q2)
        tapped: list[np.ndarray] = []
        got = 0
        deadline = time.time() + seconds + 1.0
        try:
            while got < need and time.time() < deadline:
                if not _record_speech_active[0]:
                    break   # record_speech closed the stream mid-tap
                try:
                    frame = tap_q2.get(timeout=0.2)
                except queue.Empty:
                    continue
                tapped.append(frame)
                got += int(frame.size)
        finally:
            remove_record_tap(tap_q2)
        if not tapped:
            return None
        out_t = np.concatenate(tapped).astype(np.float32, copy=False)
        return out_t[:need] if out_t.size > need else out_t

    # Path B: fall back to a temporary InputStream.
    chunks2: list[np.ndarray] = []
    q_local: queue.Queue = queue.Queue()

    def _cb(indata, frames, time_info, status):  # noqa: ARG001
        mono = indata[:, 0] if indata.ndim > 1 else indata
        q_local.put(mono.astype(np.float32, copy=False).copy())

    # MIC-OWNERSHIP GUARD (2026-07-07 bug-hunt, MED; 2026-07-08 race fix, HIGH).
    # Publish that a mic stream is LIVE before opening this Path-B InputStream, so
    # a concurrent _refresh_devices can't run sd._terminate()/sd._initialize() and
    # tear PortAudio out from under this stream's callback → heap corruption
    # (0xc0000374). record_speech guards its own open exactly this way; Path B was
    # the un-guarded twin (reached when record_speech isn't holding the mic at
    # target_sr — e.g. standby audio / voice enrollment / speaker-ID).
    #
    # Use a DEDICATED _pathb_mic_active flag rather than save+restore of
    # _record_speech_active. The old save+restore was a lost-update race: if
    # record_speech started after Path B snapshotted _record_speech_active=False
    # but before this finally ran, the finally stomped record_speech's genuine
    # True back to False while its InputStream was live — re-opening the exact
    # ~70s WASAPI-contention stall and 0xc0000374 window the flag exists to close.
    # record_speech owns _record_speech_active exclusively; Path B owns
    # _pathb_mic_active exclusively; _refresh_devices defers on ANY owner cell
    # (atomically, via the _pa_gate teardown gate). Path B no longer touches
    # _record_speech_active/_record_speech_sr at all, so it can never clobber
    # record_speech's ownership.
    #
    # Claim through _pa_claim_owner (2026-08-14): the deny_if preserves the
    # yield-to-record_speech rule — record_speech owns (or just grabbed) the
    # mic; Path A2 above only taps it when the sample rates MATCH, and opening
    # a SECOND InputStream on the same WASAPI device would re-introduce the
    # ~70s double-open capture stall (HIGH, 2026-07-08). A False return also
    # covers a destructive PortAudio reinit in flight (bounded wait timed
    # out). Either way: return None so the caller re-invokes and either taps
    # (A2) or skips this cycle — never double-opens, never opens into a
    # native teardown.
    if not _pa_claim_owner(_pathb_mic_active,
                           deny_if=lambda: bool(_record_speech_active[0])):
        return None
    try:
        # 2026-05-29 silent-crash fix: avoid `with sd.InputStream(...)`. Open the
        # stream explicitly and tear it down via _safe_close_stream so the close
        # path can't SIGSEGV the interpreter during exceptional exits.
        try:
            stream = sd.InputStream(samplerate=target_sr, channels=1,
                                    dtype="float32", blocksize=1024,
                                    device=get_input_device(), callback=_cb)
        except Exception as e:
            print(f"  [get_mic_buffer] InputStream open failed: {e}")
            return None
        try:
            stream.start()
            captured = 0
            deadline = time.time() + seconds + 1.0
            while captured < need and time.time() < deadline:
                if _record_speech_active[0]:
                    # record_speech just grabbed the mic — yield immediately so we
                    # don't sit as a second open stream on the same device. The
                    # finally below closes our stream and clears _pathb_mic_active.
                    break
                try:
                    frame = q_local.get(timeout=0.2)
                except queue.Empty:
                    continue
                chunks2.append(frame)
                captured += int(frame.size)
        except Exception as e:
            print(f"  [get_mic_buffer] InputStream failed: {e}")
            return None
        finally:
            _safe_close_stream(stream)
    finally:
        # The nested finally above closed the stream FIRST; release only after
        # (close-then-release, 2026-08-14) so the flag covers the stream's
        # whole native lifetime.
        _pa_release_owner(_pathb_mic_active)
    if not chunks2:
        return None
    out2 = np.concatenate(chunks2).astype(np.float32, copy=False)
    return out2[:need] if out2.size > need else out2


# ──────────────────────────────────────────────────────────────────────────
#  SPEECH-TO-TEXT  (Whisper — fully local)
# ──────────────────────────────────────────────────────────────────────────

_stt = None  # lazy-loaded on first transcribe() call
_stt_device = None      # resolved at load time: "cuda" or "cpu"
_stt_model_name = None  # resolved at load time: actual model loaded
_stt_engine = None      # "faster_whisper" or "openai_whisper"
# Serialises BOTH the lazy model load AND every transcribe() call. CTranslate2
# (faster-whisper's backend) is NOT safe for concurrent .transcribe() on one
# model instance — two threads transcribing at once corrupts native state and
# raises a C++ exception on a worker thread, which is UNCATCHABLE in Python and
# terminates the whole process (0xc0000409). One lock across load+inference
# guarantees single-threaded access to _stt. RLock (not Lock) so transcribe()
# can hold it across the whole call while the nested _ensure_whisper() re-enters
# it on the same thread without deadlocking. 2026-07-08.
_stt_lock = threading.RLock()


# Patterns in the stringified exception that indicate the CUDA runtime DLLs
# (cublas64_12.dll / cudnn64_9.dll / cudart64_*.dll) couldn't be loaded.
# When we see one of these we surface remediation steps instead of just
# the raw error, and treat the failure as environmental (auto-fall back to
# CPU; don't keep re-queuing a code-fix task).
_CUDA_DLL_ERROR_PATTERNS = (
    "cublas64", "cudnn64", "cudart64", "nvcuda.dll",
    "is not found or cannot be loaded",
    "could not load library", "library not found",
)


def _is_cuda_dll_error(exc: BaseException) -> bool:
    """True when `exc` looks like a CUDA runtime DLL load failure rather
    than e.g. an out-of-memory or wrong-model-name error. Used to pick
    between 'retry on CPU silently' and 'surface remediation steps'."""
    s = f"{type(exc).__name__}: {exc}".lower()
    return any(p in s for p in _CUDA_DLL_ERROR_PATTERNS)


def _cuda_dll_remediation_note() -> str:
    """Single-line remediation hint for CUDA DLL load failures. Includes
    what _register_cuda_dll_dirs actually saw so the user knows whether
    the pip package is missing vs. just unreachable."""
    reg  = getattr(_register_cuda_dll_dirs, "_registered", []) or []
    miss = getattr(_register_cuda_dll_dirs, "_missing", [])    or []
    reason = getattr(_register_cuda_dll_dirs, "_reason", None)
    parts = [
        "CUDA runtime DLLs (cublas64_12.dll / cudnn64_9.dll) are not loadable.",
        "Fix: pip install --upgrade nvidia-cublas-cu12 nvidia-cudnn-cu12  "
        "(or set WHISPER_DEVICE='cpu' to skip GPU).",
    ]
    if reason:
        parts.append(f"DLL-dir scan: {reason}.")
    elif reg or miss:
        parts.append(f"DLL-dir scan: registered {len(reg)}, missing {len(miss)}.")
    return " ".join(parts)


def _resolve_whisper_device() -> str:
    """Honour WHISPER_DEVICE, falling back to CPU when CUDA isn't actually
    available. Returns 'cuda', 'cuda:N' (a specific GPU index), or 'cpu'.
    Prefers ctranslate2's CUDA check
    (faster-whisper backend) over torch.cuda because Py 3.14 + the cu124
    torch wheel doesn't ship yet — but faster-whisper / ctranslate2 has
    its own CUDA runtime and can see the 3090 just fine.

    'cuda' is honoured verbatim even if the runtime check fails; the
    actual load attempt in _ensure_whisper() will then fall back to CPU
    with a clearer error message. 'auto' silently falls back to CPU when
    no GPU backend reports a device."""
    pref = (WHISPER_DEVICE or "auto").lower()
    if pref == "cpu":
        return "cpu"
    if pref == "cuda" or pref.startswith("cuda:"):
        # "cuda" (default GPU) or "cuda:N" (pin STT to a specific GPU — e.g.
        # "cuda:1" to run Whisper on a second card and keep the primary free).
        return pref
    # auto — try ctranslate2 first (covers faster-whisper), then torch
    try:
        import ctranslate2 as _ct2
        if _ct2.get_cuda_device_count() > 0:
            return "cuda"
    except Exception as e:
        print(f"  [whisper] ctranslate2 CUDA check failed: {type(e).__name__}: {e}")
    try:
        import torch
        if torch.cuda.is_available():
            return "cuda"
    except Exception:
        pass
    return "cpu"


def _register_cuda_dll_dirs() -> None:
    """ctranslate2 needs cublas64_12.dll + cudnn64_9.dll at runtime. The
    nvidia-cublas-cu12 + nvidia-cudnn-cu12 pip packages drop them under
    site-packages\\nvidia\\{cublas,cudnn}\\bin\\ but Python on Windows
    doesn't auto-search those directories. Register them once so the
    DLL loader sees them on the first faster_whisper import.

    Records its outcome on the function object so the STT probe and the
    Whisper loader can surface 'why did CUDA fail' to the user:
      ._done       -> True once registration has been attempted
      ._registered -> list of dirs that were successfully add_dll_directory'd
      ._missing    -> list of dirs that should exist but don't
      ._reason     -> human-readable failure note (None on success)
    """
    if getattr(_register_cuda_dll_dirs, "_done", False):
        return
    _register_cuda_dll_dirs._registered = []
    _register_cuda_dll_dirs._missing    = []
    _register_cuda_dll_dirs._reason     = None
    try:
        import nvidia
    except ImportError as e:
        _register_cuda_dll_dirs._reason = (
            f"nvidia pip namespace not importable ({e}); ctranslate2 will "
            f"fail to find cublas/cudnn — install with: "
            f"pip install --upgrade nvidia-cublas-cu12 nvidia-cudnn-cu12"
        )
        print(f"  [cuda-dll] {_register_cuda_dll_dirs._reason}")
        _register_cuda_dll_dirs._done = True
        return
    except Exception as e:
        _register_cuda_dll_dirs._reason = f"nvidia import raised: {type(e).__name__}: {e}"
        print(f"  [cuda-dll] {_register_cuda_dll_dirs._reason}")
        _register_cuda_dll_dirs._done = True
        return

    try:
        base = list(nvidia.__path__)[0]
    except Exception as e:
        _register_cuda_dll_dirs._reason = f"could not resolve nvidia.__path__: {e}"
        print(f"  [cuda-dll] {_register_cuda_dll_dirs._reason}")
        _register_cuda_dll_dirs._done = True
        return

    # Both PATH prepend AND add_dll_directory: ctranslate2's LoadLibraryEx
    # call chain reaches the PATH-based search before the secure-search
    # paths registered via add_dll_directory in some Python builds, so
    # belt-and-braces is the only reliable cure.
    #
    # History: 2026-05-29 first attempt used add_dll_directory only and
    # silently failed inside ctranslate2 on Python 3.14 — first symptom was
    # `[transcribe] failed: Library cublas64_12.dll is not found`. Adding
    # the PATH prepend fixed it. Re-confirmed 2026-05-30 10:29 after a
    # fresh boot reproduced the same `cublas64_12.dll is not found` error
    # because a code refactor reverted the PATH prepend at some point.
    _existing_path = os.environ.get("PATH", "")
    for sub in ("cublas", "cudnn"):
        bin_dir = os.path.join(base, sub, "bin")
        if not os.path.isdir(bin_dir):
            _register_cuda_dll_dirs._missing.append(bin_dir)
            continue
        # PATH prepend — primary fix for ctranslate2 / faster-whisper.
        if bin_dir not in _existing_path:
            os.environ["PATH"] = bin_dir + os.pathsep + os.environ.get("PATH", "")
            _existing_path = os.environ["PATH"]
        # add_dll_directory — secondary, for other DLL loaders that DO
        # honour the secure-search list (some pip C extensions do).
        try:
            os.add_dll_directory(bin_dir)
            _register_cuda_dll_dirs._registered.append(bin_dir)
        except (FileNotFoundError, OSError) as e:
            # add_dll_directory failure doesn't undo the PATH prepend,
            # so faster-whisper still works — record the partial success.
            _register_cuda_dll_dirs._missing.append(f"{bin_dir} (add_dll_directory: {e})")
            # Still record as registered since the PATH prepend works.
            _register_cuda_dll_dirs._registered.append(bin_dir)

    if _register_cuda_dll_dirs._registered:
        print(f"  [cuda-dll] registered {len(_register_cuda_dll_dirs._registered)} dir(s): "
              f"{', '.join(os.path.basename(os.path.dirname(d)) for d in _register_cuda_dll_dirs._registered)}")
    if _register_cuda_dll_dirs._missing:
        print(f"  [cuda-dll] WARNING: missing {len(_register_cuda_dll_dirs._missing)} expected dir(s) — "
              f"reinstall with: pip install --upgrade nvidia-cublas-cu12 nvidia-cudnn-cu12")
        if not _register_cuda_dll_dirs._reason:
            _register_cuda_dll_dirs._reason = (
                f"missing CUDA DLL dirs: {_register_cuda_dll_dirs._missing}"
            )
    _register_cuda_dll_dirs._done = True


# Set by the startup preflight (_startup_preflight) when cublas64_12.dll
# cannot be located in any standard install path. _ensure_whisper() reads
# this and forces device='cpu' + compute_type='int8' so we skip the slow
# CUDA load → DLL-error → CPU-fallback dance that bloats boot time.
_force_whisper_cpu_int8 = False

# Count of consecutive transcribe() CUDA/OOM failures. The recovery path drops
# _stt and reloads, but on a card that OOMs mid-decode the reload picks the SAME
# over-budget GPU config → load→OOM→drop→reload livelock. After 2 consecutive
# CUDA failures we flip _force_whisper_cpu_int8 so _ensure_whisper() reloads on
# CPU int8 (slower but crash-proof) instead of retrying the doomed GPU load. A
# single clean transcribe resets the counter. 2026-07-08.
_consecutive_whisper_cuda_failures = 0
_WHISPER_CUDA_FAILURE_LIMIT = 2


def _whisper_cuda_plan(dev_index: int):
    """Decide HOW (and WHETHER) to load Whisper on cuda:{dev_index} without
    OOM-ing. Returns (compute_type, fallback_to_cpu, reason).

    Root cause of the 0xc0000409 crash: a 4 GB card (e.g. GTX 1650 SUPER)
    cannot hold large-v3-turbo in float16 (~3.1 GB weights) PLUS the CTranslate2
    transcribe workspace (~1-1.5 GB). The overflow raises a CUDA-OOM on a
    CTranslate2 worker thread mid-transcribe — UNCATCHABLE in Python — which
    calls std::terminate and kills the whole process. So:
      * on a small card (< ~8 GB total) pick int8 (~1.6 GB weights, half the
        footprint) instead of float16, and
      * preflight FREE VRAM — if there isn't comfortable headroom for the chosen
        precision + workspace, fall back to CPU int8 (slower but crash-proof)
        rather than attempting a load that will OOM.
    Uses torch.cuda.mem_get_info when available; if it isn't, returns a
    conservative int8 plan and skips the free-VRAM gate (best effort). int8 is
    only marginally less accurate than float16 for large-v3-turbo. 2026-07-08."""
    try:
        import torch
        free, total = torch.cuda.mem_get_info(dev_index)
        free_mb = int(free // (1024 * 1024))
        total_mb = int(total // (1024 * 1024))
    except Exception as e:
        return "int8", False, (f"VRAM probe unavailable ({type(e).__name__}); "
                               f"defaulting to int8")
    # Small cards can't afford float16 + workspace — force int8.
    compute_type = "int8" if total_mb < 8192 else "float16"
    need_mb = 4800 if compute_type == "float16" else 3000
    if free_mb < need_mb:
        return compute_type, True, (
            f"cuda:{dev_index} has {free_mb} MB free < {need_mb} MB needed for "
            f"{compute_type}; using CPU int8 to avoid an OOM crash")
    return compute_type, False, (
        f"cuda:{dev_index}: {free_mb} MB free / {total_mb} MB total → {compute_type}")


def _ensure_whisper():
    """Load the Whisper model the first time it's actually needed. Thin
    thread-safe wrapper: double-checks _stt and serialises the actual build
    under _stt_lock so two threads hitting a cold model can't both spin up a
    CTranslate2 instance at once (concurrent native init is the same race that
    crashes concurrent transcribe). The heavy lifting is in
    _ensure_whisper_locked()."""
    global _stt
    if _stt is not None:
        return
    with _stt_lock:
        if _stt is not None:      # another thread loaded it while we waited
            return
        _ensure_whisper_locked()


def _ensure_whisper_locked():
    """Actual Whisper load — ALWAYS invoked with _stt_lock held (via
    _ensure_whisper). Prefers `faster-whisper` (CTranslate2-based, 2-4x faster
    on CPU AND GPU than openai-whisper, and ships CUDA runtime for Py 3.14 where
    torch's cu124 wheel doesn't exist yet). Falls back to openai-whisper if
    faster-whisper isn't installed.
    Picks `WHISPER_MODEL_CUDA` on GPU, `WHISPER_MODEL_CPU` on CPU."""
    global _stt, _stt_device, _stt_model_name, _stt_engine
    _register_cuda_dll_dirs()
    device = _resolve_whisper_device()          # 'cuda' | 'cuda:N' | 'cpu'
    # Split into (base, index) for faster-whisper's device_index. 'cuda:1' pins
    # STT to a specific GPU (e.g. a second card) so it never competes with the
    # primary card's resident models. A bad/missing index degrades to GPU 0.
    base_dev = "cuda" if device.startswith("cuda") else "cpu"
    dev_index = 0
    if base_dev == "cuda" and ":" in device:
        try:
            dev_index = int(device.split(":", 1)[1])
        except (ValueError, IndexError):
            dev_index = 0
    # Preflight already verified cublas64_12.dll is missing — short-circuit
    # straight to CPU so we don't waste 5-10s on the CUDA load attempt that
    # the existing inner try/except would have caught anyway.
    if _force_whisper_cpu_int8 and base_dev == "cuda":
        print(f"  [whisper] preflight flagged cublas64_12.dll missing — "
              f"forcing CPU + int8 (skipping CUDA load attempt)")
        base_dev, dev_index = "cpu", 0
    # VRAM-aware plan for CUDA — choose a compute_type that FITS the target card
    # and bail to CPU when it lacks headroom, so we never trigger the uncatchable
    # worker-thread OOM that terminates the process (the 0xc0000409 crash).
    cuda_compute = "float16"
    if base_dev == "cuda":
        cuda_compute, _cpu_fallback, _plan_reason = _whisper_cuda_plan(dev_index)
        print(f"  [whisper] VRAM plan — {_plan_reason}")
        if _cpu_fallback:
            base_dev, dev_index = "cpu", 0
    model  = WHISPER_MODEL_CUDA if base_dev == "cuda" else WHISPER_MODEL_CPU
    dev_label = f"{base_dev}:{dev_index}" if base_dev == "cuda" else base_dev

    # ── Engine 1: faster-whisper (preferred for GPU speed + Py 3.14 CUDA) ──
    try:
        from faster_whisper import WhisperModel as _FWM
        compute_type = cuda_compute if base_dev == "cuda" else "int8"
        print(f"Loading faster-whisper '{model}' on {dev_label} "
              f"(compute_type={compute_type})…")
        try:
            _stt = _FWM(model, device=base_dev, device_index=dev_index,
                        compute_type=compute_type)
            _stt_engine = "faster_whisper"
            _stt_device = dev_label
            _stt_model_name = model
            print(f"faster-whisper '{model}' ready on {dev_label}.\n")
            return
        except Exception as e:
            if base_dev == "cuda":
                if _is_cuda_dll_error(e):
                    note = _cuda_dll_remediation_note()
                    print(f"  [whisper] faster-whisper CUDA load failed (CUDA DLL "
                          f"missing): {e}")
                    print(f"  [whisper] {note}")
                else:
                    print(f"  [whisper] faster-whisper CUDA load failed: {e}")
                # DOWNGRADE the model for the CPU retry: the CUDA path picked
                # WHISPER_MODEL_CUDA (large-v3-turbo), which on CPU int8 runs at
                # a small fraction of realtime and makes STT effectively
                # unusable. Mirror the openai-whisper fallback below (which sets
                # model = WHISPER_MODEL_CPU) and load the small CPU model. 2026-07-08.
                model = WHISPER_MODEL_CPU
                print(f"  [whisper] retrying on CPU with int8 using '{model}'…")
                _stt = _FWM(model, device="cpu", compute_type="int8")
                _stt_engine = "faster_whisper"
                _stt_device = "cpu"
                _stt_model_name = model
                print(f"faster-whisper '{model}' ready on cpu (fallback).\n")
                return
            raise
    except ImportError:
        pass  # faster-whisper not installed — fall through to openai-whisper
    except Exception as _fw_err:
        # faster-whisper IS installed but its model LOAD failed (non-ImportError):
        # first-run HF Hub download failure (network/disk), a corrupt CTranslate2
        # cache, a CPU-feature mismatch, or a CUDA error whose CPU retry above also
        # raised. The outer handler used to catch ONLY ImportError, so such a
        # failure escaped _ensure_whisper() entirely and — since it's called at
        # boot with no surrounding guard — aborted boot, WITHOUT ever attempting
        # the openai-whisper engine. Fall through to Engine 2 instead so a cached
        # or alternately-installed model can still bring STT up. 2026-07-08.
        _stt = None
        print(f"  [whisper] faster-whisper load failed "
              f"({type(_fw_err).__name__}: {_fw_err}); falling back to "
              f"openai-whisper.")

    # ── Engine 2: openai-whisper (legacy fallback) ─────────────────────────
    print(f"Loading openai-whisper '{model}' on {device}… "
          f"(faster-whisper unavailable — install with: pip install faster-whisper)")
    import whisper as _wlib
    try:
        _stt = _wlib.load_model(model, device=device)
    except Exception as e:
        if device == "cuda":
            if _is_cuda_dll_error(e):
                print(f"  [whisper] CUDA load of '{model}' failed (CUDA DLL "
                      f"missing): {e}")
                print(f"  [whisper] {_cuda_dll_remediation_note()}")
            else:
                print(f"  [whisper] CUDA load of '{model}' failed: {e}")
            print(f"  [whisper] falling back to CPU model '{WHISPER_MODEL_CPU}'.")
            device = "cpu"
            model = WHISPER_MODEL_CPU
            _stt = _wlib.load_model(model, device=device)
        else:
            raise
    _stt_engine = "openai_whisper"
    _stt_device = device
    _stt_model_name = model
    print(f"openai-whisper '{model}' ready on {device}.\n")


# Map pip distribution name → (import module name, JARVIS-style feature note for
# the spoken alert). If the import module differs from the pip name, the lookup
# falls back to the pip name itself. Features listed here generate a one-line
# spoken alert; packages without a feature note get a console warning only.
_DEP_IMPORT_NAME = {
    "openai-whisper": "whisper",
    "opencv-python":  "cv2",
    "edge-tts":       "edge_tts",
    "pillow":         "PIL",
    "pywin32":        "win32com",
    "paho-mqtt":      "paho.mqtt.client",
    # The dashed pip name does NOT match the import path for these, so the
    # default "-"→"_" fallback mis-resolves them and they were falsely reported
    # MISSING (plus a bogus pip-install line) on every boot of a working install.
    "winrt-Windows.Media.Control": "winrt.windows.media.control",
    "nvidia-cublas-cu12":          "nvidia.cublas",
    "nvidia-cudnn-cu12":           "nvidia.cudnn",
}
_DEP_FEATURE_NOTE = {
    "psutil":         "the system monitor is offline",
    "paho-mqtt":      "the Bambu printer monitor is offline",
    "opencv-python":  "face tracking is offline",
    "edge-tts":       "text-to-speech is offline",
    "pyttsx3":        "the offline TTS fallback is unavailable — a network blip will silence me",
    "anthropic":      "the Claude backend is offline",
    "mss":            "screen vision is offline",
    "pyautogui":      "UI automation is offline",
    "pywin32":        "Windows automation is offline",
    "pystray":        "the system tray applet is offline",
}


def _parse_requirements(path: str) -> list[str]:
    """Pull pip-distribution names out of requirements.txt. Skips comments,
    blank lines, and trailing inline comments. Strips version specifiers and
    extras so 'paho-mqtt>=2.0  # comment' → 'paho-mqtt'."""
    pkgs: list[str] = []
    try:
        with open(path, "r", encoding="utf-8") as f:
            for raw in f:
                line = raw.split("#", 1)[0].strip()
                if not line:
                    continue
                # Skip pip option lines (--extra-index-url, --index-url, -r,
                # -e, -c, …) — they're directives, not package names, and
                # were being mis-parsed into a bogus '--extra-index-url'
                # "missing package" warning at boot.
                if line.startswith("-"):
                    continue
                # Strip version specifiers / extras / env markers
                name = re.split(r"[<>=!~;\[\s]", line, maxsplit=1)[0].strip()
                if name:
                    pkgs.append(name)
    except Exception as e:
        print(f"  [dep-check] could not read {path}: {e}")
    return pkgs


def check_dependencies() -> list[str]:
    """Walk requirements.txt, report any packages whose import fails, and
    speak a one-line alert naming the silently-disabled features. Returns
    the list of missing pip-distribution names (empty list = all good)."""
    import importlib
    req_path = os.path.join(os.path.dirname(os.path.abspath(__file__)), "requirements.txt")
    pkgs = _parse_requirements(req_path)
    missing: list[str] = []
    for pkg in pkgs:
        mod = _DEP_IMPORT_NAME.get(pkg, pkg.replace("-", "_"))
        try:
            importlib.import_module(mod)
        except Exception:
            missing.append(pkg)

    if not missing:
        print("  [dep-check] all requirements.txt packages importable.")
        return missing

    print(f"  [dep-check] WARNING: {len(missing)} package(s) from requirements.txt "
          f"are missing from the active environment:")
    for pkg in missing:
        feat = _DEP_FEATURE_NOTE.get(pkg, "")
        suffix = f"  ({feat})" if feat else ""
        print(f"    - {pkg}{suffix}")
    print(f"  [dep-check] install with:  pip install {' '.join(missing)}")

    # Build the spoken alert: one line, JARVIS-style understatement. Only
    # mention features we have a human-readable note for; if multiple, list
    # the first two so the alert stays short.
    feature_msgs = [(_DEP_FEATURE_NOTE[p], p) for p in missing if p in _DEP_FEATURE_NOTE]
    if feature_msgs:
        if len(feature_msgs) == 1:
            feat, pkg = feature_msgs[0]
            alert = f"Sir, {feat} — {pkg} is missing."
        else:
            parts = ", ".join(f"{feat} ({pkg} missing)" for feat, pkg in feature_msgs[:2])
            extra = "" if len(feature_msgs) <= 2 else f", and {len(feature_msgs) - 2} more"
            alert = f"Sir, a few things are offline: {parts}{extra}."
        try:
            _speak(alert)
            conversation_history.append({"role": "assistant", "content": alert})
        except Exception as e:
            print(f"  [dep-check] spoken alert failed: {e}")

    return missing


def transcribe(audio: np.ndarray) -> tuple[str, dict]:
    """Thread-safe entry point: holds _stt_lock across the ENTIRE call so no two
    threads ever touch the CTranslate2 model at once — not the .transcribe()
    call, not the lazy generator draining (list(segments_gen)) where the native
    decode actually happens. _stt_lock is an RLock, so the nested
    _ensure_whisper() re-acquires it on this thread without deadlocking. This is
    what makes concurrent transcription safe; a race here corrupts native state
    and terminates the process (0xc0000409)."""
    with _stt_lock:
        return _transcribe_impl(audio)


def _transcribe_impl(audio: np.ndarray) -> tuple[str, dict]:
    """Returns (text, confidence) where confidence has no_speech_prob and avg_logprob.
    Abstracts over faster-whisper (preferred, GPU-accelerated on 3090) and
    openai-whisper (legacy fallback). Both produce the same return shape.
    MUST be called with _stt_lock held (via transcribe())."""
    global _stt, _consecutive_whisper_cuda_failures, _force_whisper_cpu_int8
    try:
        _ensure_whisper()
        if _stt_engine == "faster_whisper":
            # faster-whisper returns (segments_generator, info). Drain to a
            # list so we can compute averages. vad_filter=True skips
            # 'inaudible' chunks; same model dims as openai-whisper.
            # vad_filter=True runs faster-whisper's built-in Silero VAD before
            # transcribing; on quiet/desk mics it frequently drops LEGITIMATE
            # speech (a real "JARVIS" scores below the gate) and returns zero
            # segments -> "". Use a permissive threshold, and if it STILL finds
            # nothing, retry ONCE WITHOUT the VAD filter so a genuine utterance
            # is never silently lost — the difference between "heard you" and a
            # wall of [standby] ignored: ''. The caller's audio already cleared
            # the mic VAD gate, so it is not pure silence.
            segments_gen, info = _stt.transcribe(
                audio, language="en",
                vad_filter=True,
                vad_parameters=dict(threshold=0.3, min_speech_duration_ms=80),
                beam_size=5,
            )
            segments = list(segments_gen)
            if not segments:
                segments_gen, info = _stt.transcribe(
                    audio, language="en",
                    vad_filter=False,
                    beam_size=5,
                )
                segments = list(segments_gen)
            # Native decode completed without a CUDA fault — clear the
            # consecutive-failure counter so one transient OOM never sticks us
            # on CPU int8. 2026-07-08.
            _consecutive_whisper_cuda_failures = 0
            text = " ".join((s.text or "").strip() for s in segments).strip()
            if not segments:
                # info still carries some signal even on empty transcription
                nsp = float(getattr(info, "no_speech_prob", 1.0) or 1.0)
                return text, {"no_speech_prob": nsp, "avg_logprob": -10.0}
            n = len(segments)
            no_speech = sum(float(getattr(s, "no_speech_prob", 0.0) or 0.0)
                            for s in segments) / n
            logprob   = sum(float(getattr(s, "avg_logprob", 0.0) or 0.0)
                            for s in segments) / n
            return text, {"no_speech_prob": no_speech, "avg_logprob": logprob}

        # openai-whisper path (legacy). Modern openai-whisper (v20250115+)
        # removed the fp16= kwarg — precision is now derived from the dtype
        # the model was loaded with, so passing it raises TypeError.
        result = _stt.transcribe(audio, language="en")
        # Clean decode — reset the consecutive CUDA-failure counter (see the
        # faster-whisper branch above). 2026-07-08.
        _consecutive_whisper_cuda_failures = 0
        text = result["text"].strip()
        segments = result.get("segments", [])
        if not segments:
            return text, {"no_speech_prob": 1.0, "avg_logprob": -10.0}
        n = len(segments)
        no_speech = sum(s.get("no_speech_prob", 0.0) for s in segments) / n
        logprob   = sum(s.get("avg_logprob",    0.0) for s in segments) / n
        return text, {"no_speech_prob": no_speech, "avg_logprob": logprob}
    except Exception as e:
        _err = f"{type(e).__name__}: {e}"
        print(f"  [transcribe] failed: {_err}")
        # On a CUDA/VRAM error (the standby whisper-tiny + the main large
        # model + Ollama/vision can crowd the 3090's 24 GB), free fragmented
        # VRAM and DROP the model so the next utterance reloads from a clean
        # state instead of repeatedly failing from a half-broken GPU context.
        # The current utterance is lost (the user re-speaks) but recovery is
        # automatic. 2026-05-30 deep audit.
        if any(k in _err.lower() for k in
               ("out of memory", "cuda", "cublas", "cudnn", "cudart")):
            try:
                import torch
                if torch.cuda.is_available():
                    torch.cuda.empty_cache()
            except Exception:
                pass
            _stt = None
            # Track consecutive CUDA faults. Dropping + reloading the SAME
            # over-budget GPU config just re-OOMs (load→OOM→drop→reload
            # livelock), so after _WHISPER_CUDA_FAILURE_LIMIT flip the sticky
            # flag _ensure_whisper() reads → next reload lands on CPU int8
            # (crash-proof) instead of the doomed GPU load. 2026-07-08.
            _consecutive_whisper_cuda_failures += 1
            if (_consecutive_whisper_cuda_failures >= _WHISPER_CUDA_FAILURE_LIMIT
                    and not _force_whisper_cpu_int8):
                _force_whisper_cpu_int8 = True
                print(f"  [transcribe] {_consecutive_whisper_cuda_failures} "
                      f"consecutive CUDA failures — forcing CPU int8 on reload "
                      f"to break the OOM→reload livelock")
            print("  [transcribe] dropped GPU model after CUDA error — "
                  "reloading on next utterance")
        return "", {"no_speech_prob": 1.0, "avg_logprob": -10.0}


# is_ambient_music / is_valid_speech + _MUSIC_MARKERS moved to
# core/speech_filter.py (re-exported at the top of this file).


# ──────────────────────────────────────────────────────────────────────────
#  TONE DETECTOR  (cheap pre-LLM pass over the user's transcript)
# ──────────────────────────────────────────────────────────────────────────
#
# MCU JARVIS reads Tony's mood and adjusts his register on the fly. We
# mimic that with a tiny pure-Python classifier that runs on every
# transcribed utterance BEFORE the LLM call. Detected stress markers —
# swearing, urgency words, clipped imperatives, exclamation, or the user
# repeating themselves across turns — produce a per-turn addendum to the
# system prompt instructing JARVIS to skip pleasantries and be terse.

# Tone-classifier DATA + heuristics moved to core/tone_detector.py (imported at
# the top of this file). The per-utterance caches below stay here — they're
# runtime state, not classification logic.

# Cache the most recent user utterance's tone so get_followup_response
# can reuse it without re-running the detector (and to keep the register
# stable across a multi-step action chain).
_last_user_tone: list[str | None] = [None]

# Cache the most recent user utterance text so the context-aware TTS layer
# (core.tts.detect_emergency_keywords) can score 'fuck'/'shit'/'help' on
# whatever sir just said. Set in _call_llm before LLM dispatch, read by
# _resolve_tts_preset(). Mirrors _last_user_tone's lifecycle.
_last_user_text: list[str | None] = [None]

# Five-label emotion classification from core/emotion_tracker — cached per
# utterance so the follow-up loop reuses the same register without re-running
# the heuristics. Stored as the EmotionResult so synthesise() can fetch the
# preset name without re-classifying.
_last_emotion: list[object | None] = [None]


def detect_tone(user_text: str) -> str | None:
    """Thin wrapper over core.tone_detector.detect_tone: supply the user's
    PREVIOUS utterance from conversation_history so the pure classifier can
    spot cross-turn repetition, then delegate. Kept here (not re-exported)
    so every existing call site detect_tone(text) stays unchanged."""
    prev = next(
        (m["content"] for m in reversed(conversation_history[:-1])
         if m.get("role") == "user"),
        None,
    )
    return _tone_detector.detect_tone(user_text, prev_user_text=prev)


# Voice-emotion mood router (route_voice_emotion + _VOICE_MOOD_HINTS +
# _detect_excited + VOICE_EMOTION_ROUTER_ENABLED) moved to
# core/voice_emotion.py. The _last_voice_route cache below stays here
# (runtime state); route_voice_emotion is re-exported via the thin wrapper.

# Module-level cache of the route picked for the most recent user
# utterance. Mirrors `_last_user_tone[0]` so synthesise() and
# get_followup_response() can read the route without re-running the
# classifier (and so register stays stable across action chains).
_last_voice_route: list[dict | None] = [None]


def route_voice_emotion(user_text: str, now: float | None = None) -> dict:
    """Thin wrapper over core.voice_emotion.route_voice_emotion: supply the
    previous user utterance from conversation_history so the router's tone
    classifier can spot cross-turn repetition, then delegate. Call sites
    are unchanged."""
    prev = next(
        (m["content"] for m in reversed(conversation_history[:-1])
         if m.get("role") == "user"),
        None,
    )
    return _voice_emotion.route_voice_emotion(
        user_text, now=now, prev_user_text=prev)


# ──────────────────────────────────────────────────────────────────────────
#  LLM  (Claude or Ollama)
# ──────────────────────────────────────────────────────────────────────────

# Local-LLM fallback state — guarded so the winget install + ollama pull
# fire at most once per process. Set true on first attempt so a failed
# install doesn't hammer winget on every subsequent rate-limit.
_OLLAMA_INSTALL_TRIGGERED = [False]
_OLLAMA_PULL_TRIGGERED    = [False]


def _log_gpu_state(model_name: str) -> None:
    """One-shot nvidia-smi snapshot helper. Confirms Ollama is actually
    holding the model in VRAM on first use. Never raises — silently
    no-ops on non-NVIDIA hosts. Defers to core.gpu_state for the
    shared dedup set so embeddings + LLM + VLM share one log entry per
    model across the process."""
    try:
        from core import gpu_state as _gpu_state
        _gpu_state.log_gpu_state(model_name)
    except Exception:
        # Diagnostics must never block the Ollama call path.
        pass

# Resolved local-LLM model tag — filled on the first call to
# _get_local_llm_model() that actually finds an installed model (or honours
# the env override). Until then the resolver returns LOCAL_LLM_MODEL without
# caching, so a finished background pull promotes the user to qwen2.5:14b on
# the next call instead of being locked to a stale 'no models installed'
# choice. Single-element list so reassignment doesn't need a global stmt.
_RESOLVED_LOCAL_LLM_MODEL: list[str | None] = [None]

# Fallback chain for the local-LLM selector. First entry is the preferred
# default: gemma4:26b-a4b-it-qat — a 26B MoE (4B active → fast, ~70 tok/s
# class on the 3090) at 16 GB QAT, MULTIMODAL (text+image), 256K context.
# Because it also does vision, pointing LOCAL_VISION_MODEL at the SAME tag
# means the vision fallback re-uses the resident model instead of co-loading
# a second ~7 GB VLM — the co-load that used to brick the 24 GB card.
# Next: the qwen3 30B-A3B MoE (~18 GB q4, needs the 12k ctx window — see
# _local_num_ctx), then the dense 14B/8B for lower-VRAM boxes. The dense
# qwen2.5:32b was REMOVED from this chain 2026-07: ~22 GB resident left no
# headroom for whisper + vision and repeatedly bricked the GPU (the reason
# boots used to force the 14B via JARVIS_LOCAL_LLM_MODEL). That env var
# still bypasses this list entirely; the "first installed tag" step (below)
# catches anything off-list.
# Ordered best-first. `gemma4:12b` leads after the 2026-07-10 on-box bake-off:
# 7/7 on the REAL ~10k-token prod prompt (action grammar, honesty, reasoning),
# 0.6s warm turns, zero empty replies, 8.4GB fully resident @16k ctx, and
# MULTIMODAL (chat+vision share one resident model → no swap thrash).
# `qwen2.5:14b` is the proven failover (6/7, 13.5GB). NOTES: the qwen3:30b MoE
# was DROPPED — it redlines the 24GB card to <0.3GB free beside the voice clone
# (the OOM-brick zone); an on-box re-bench 2026-07-15 measured it at >240s for a
# first response because it must offload ~1.3GB to CPU (17.3GB free < 18.6GB) —
# it only becomes viable once TTS moves off the 3090 (master-plan P2). NOTE
# UPDATED 2026-07-15: `gemma4:26b-a4b-it-qat` is NO LONGER broken — the old
# EMPTY-output bug (ollama #15428/#16456) is fixed on the current ollama; a fresh
# on-box bench answered coherently, solved bat-and-ball, ran 106.8 tok/s, and sat
# 15.2GB fully resident (multimodal, same chat+vision-share win as gemma4:12b).
# It is STILL not auto-default because 15.2GB leaves only ~1.8GB headroom beside
# the resident voice clone — too little to absorb a chatterbox synthesis spike on
# the box the owner relies on. It becomes the clear default upgrade the moment TTS
# moves to CPU (P2 frees ~6GB). Until then gemma4:12b leads; the 26B is a one-flag
# opt-in via JARVIS_LOCAL_LLM_MODEL. Neither big model is auto-selected; "first
# available" can still pick them as a last resort, and the empty-response failover
# self-heals if that happens.
_LOCAL_LLM_PREFERENCE = (
    "gemma4:26b-a4b-it-qat",         # P2 phase B default: 26B MoE, multimodal, ~100 tok/s
    "gemma4:12b",                    # graceful lower-VRAM fallback (still multimodal)
    "qwen2.5:14b-instruct-q5_K_M",
    "qwen3:14b",
    "llama3.1:8b-instruct-q5_K_M",
)


# (connect, read) timeout for the foreground /api/chat generate. The READ
# leg is the load-bearing resilience knob: with stream=False, Ollama sends
# NOTHING until the whole reply is ready, so a runner that's up on /api/tags
# but can't actually generate (the classic Smart-App-Control-blocked-runner
# case — SAC blocks ggml.dll / the runner exe, /api/tags still answers 200,
# but /api/chat hangs) trips this read timeout and the caller falls back to
# Claude — instead of freezing the voice thread for the old flat 120 s. 50 s
# still comfortably covers a warm 500-token generation (≥10 tok/s; the 32B
# does ~49) once the boot warm-up has paid the one-time model-load cost.
_LOCAL_GENERATE_TIMEOUT = (5, 50)

# Bind the real requests.Timeout class at import time so the read-timeout
# `except` in _call_local_llm stays valid even when a test (or some other
# caller) swaps the module-level `requests` for a bare Mock — referencing
# `requests.Timeout` at handling time would otherwise resolve to a Mock
# attribute and raise "catching classes that do not inherit from BaseException".
_RequestsTimeout = requests.Timeout

# Wall-clock bound (seconds) for the two hot-path `ollama.chat` calls in
# _call_llm / get_followup_response. The stock ollama-python client defaults to
# timeout=None, so a wedged runner (model-load failure, GPU hang, SAC-blocked
# generate) would block the voice thread FOREVER and JARVIS goes permanently
# deaf — the watchdog only sets a flag at ~64 s, it can't unblock a native
# call. These two calls carry the full (uncompacted) system prompt so they run
# heavier than _call_local_llm's compact path; 60 s leaves comfortable headroom
# for a warm generation yet still degrades gracefully (their `except` falls back
# to the honest cloud/local message) instead of hanging. Matches the bounded
# /api/chat read leg in _call_local_llm (_LOCAL_GENERATE_TIMEOUT).
_OLLAMA_CHAT_TIMEOUT_S = 60.0


def _ollama_chat_bounded(model, messages):
    """`ollama.chat`, but bounded by a wall-clock timeout so a wedged runner
    raises (httpx TimeoutException) instead of blocking the voice loop forever.

    Routes through `ollama.Client(timeout=…)` (the host kwargs flow straight to
    the underlying httpx client). Raises on timeout/transport error so the
    caller's existing `except` degrades to its honest cloud/local fallback —
    NEVER returns a partial/None silently here. 2026-06-06 audit (P1-2)."""
    import ollama
    client = ollama.Client(host=LOCAL_LLM_BASE_URL, timeout=_OLLAMA_CHAT_TIMEOUT_S)
    return client.chat(model=model, messages=messages)


def _ollama_alive() -> bool:
    try:
        return requests.get(f"{LOCAL_LLM_BASE_URL}/api/tags", timeout=2).ok
    except Exception:
        return False


# Runtime self-heal throttle: at most one relaunch attempt per cooldown, and
# never two concurrently. (Single-element-list/dict globals per house style.)
_OLLAMA_HEAL_STATE = {"last": 0.0, "active": False}
_OLLAMA_HEAL_COOLDOWN_S = 120.0


def _ollama_selfheal_async() -> None:
    """MID-SESSION self-heal: relaunch a dead Ollama server on a daemon thread.

    Boot preflight calls _ensure_ollama_running() synchronously, but until now
    NOTHING healed a mid-session death — live outage 2026-07-10 09:13: ollama's
    llama-server wedged during a chat<->vision model swap ("GPU discovery
    watchdog timed out" + "Load failed"), and every later local turn just said
    unavailable until the next reboot. This fires the same restart logic in the
    background so the CURRENT turn still fails fast (honest fallback message)
    but the NEXT turn finds the server back up. Throttled to one attempt per
    _OLLAMA_HEAL_COOLDOWN_S and never concurrent. Never raises."""
    try:
        now = time.time()
        if (_OLLAMA_HEAL_STATE["active"]
                or now - _OLLAMA_HEAL_STATE["last"] < _OLLAMA_HEAL_COOLDOWN_S):
            return
        _OLLAMA_HEAL_STATE["last"] = now
        _OLLAMA_HEAL_STATE["active"] = True

        def _do():
            try:
                print("  [ollama] server unreachable at RUNTIME — self-heal "
                      "restart attempt (background)…")
                _ensure_ollama_running()
            except Exception as e:
                print(f"  [ollama] runtime self-heal raised {type(e).__name__}: {e}")
            finally:
                _OLLAMA_HEAL_STATE["active"] = False

        threading.Thread(target=_do, daemon=True, name="ollama-selfheal").start()
    except Exception:
        pass


def _reap_wedged_ollama() -> None:
    """Kill a WEDGED ollama stack before relaunching it.

    The API being unreachable while ollama.exe still has a process means the
    server is hung (live case 2026-07-10 09:13 — llama-server "GPU discovery
    watchdog timed out" mid model-swap and the server never answered again). A
    second `ollama serve` can't bind :11434 next to a wedged one, so kill BOTH
    ollama.exe AND llama-server.exe — killing only ollama ORPHANS its
    llama-server child, which keeps ~13.5GB of VRAM resident (learned
    2026-07-09). Only call when the API is unreachable: any such process is by
    definition not serving. Separate function so tests can mock it (a live
    taskkill during ci_sim would murder the REAL server). Never raises."""
    # STAGING/TEST GATE (2026-07-21 audit): the staging blue/green candidate
    # and the unit-test harness share this box with the REAL prod server — a
    # live taskkill from either murders prod's local brain mid-conversation
    # (the docstring's ci_sim worry, made structural instead of relying on
    # every test remembering to mock this function). Same four-signal
    # sentinel as _warm_up_local_llm_async.
    if (os.environ.get("JARVIS_STAGING", "").strip() == "1"
            or os.environ.get("JARVIS_TEST_MODE", "").strip() == "1"
            or "--staging" in sys.argv
            or _is_staging()):
        return
    if os.name != "nt":
        return
    for _img in ("ollama.exe", "llama-server.exe", "ollama app.exe"):
        try:
            subprocess.run(
                ["taskkill", "/IM", _img, "/F", "/T"],
                capture_output=True, text=True, timeout=10,
                creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0),
            )
        except Exception:
            pass
    try:
        time.sleep(2.0)   # let the GPU driver release the dead procs' VRAM
    except Exception:
        pass


def _ensure_ollama_running(timeout_sec: float = 90.0) -> bool:
    """Self-heal: if the local Ollama server (the local-model brain) isn't
    answering, START it and wait for it to come up. Ollama being DOWN — after a
    reboot that didn't relaunch its desktop app, a crash, or a manual quit — is
    the single worst local-brain outage: JARVIS then has no local model AND, if
    the Claude cap is also hit, no thinking backend at all ("my local model
    isn't responding, sir"). JARVIS already knows where ollama.exe lives, so it
    can relaunch the server headlessly. Returns True if Ollama is reachable after
    the attempt. Best-effort; never raises. 2026-07-09."""
    if _ollama_alive():
        return True
    # STAGING GATE (2026-07-21 audit): the staging/blue-green candidate may
    # OBSERVE the shared server (the fast path above) but must never reap or
    # spawn it — the staging branch disables tray/mic/cameras yet nothing
    # gated this boot step, so a staging boot could taskkill prod's ollama
    # stack mid-conversation. JARVIS_TEST_MODE is deliberately NOT in this
    # gate (the unit harness sets it suite-wide and tests exercise the real
    # start-when-down logic with Popen/_reap_wedged_ollama mocked);
    # _reap_wedged_ollama carries its own harder gate that does include it.
    if (os.environ.get("JARVIS_STAGING", "").strip() == "1"
            or "--staging" in sys.argv
            or _is_staging()):
        print("  [ollama] server is down but this is the STAGING instance — "
              "leaving the shared prod server alone (no reap, no spawn).")
        return False
    exe = None
    try:
        import shutil as _sh
        exe = _sh.which("ollama")
        if not exe:
            for c in (os.path.join(os.environ.get("LOCALAPPDATA", ""),
                                   "Programs", "Ollama", "ollama.exe"),
                      r"C:\Program Files\Ollama\ollama.exe",
                      r"C:\Program Files (x86)\Ollama\ollama.exe"):
                if c and os.path.isfile(c):
                    exe = c
                    break
    except Exception:
        exe = None
    if not exe:
        print("  [ollama] server is down and ollama.exe wasn't found — the local "
              "model is unavailable until Ollama is started.")
        return False
    # CONFIRM THE OUTAGE before escalating to a reap (2026-07-21 audit): a
    # single 2s /api/tags timeout is a BLIP, not a wedge — the probe times out
    # exactly when the server is busiest (a ~21GB model load, post-reboot CUDA
    # discovery), and reaping then taskkills a HEALTHY stack. Re-probe a few
    # times over ~12s and bail back to the fast path if it answers.
    for _probe in range(3):
        time.sleep(4.0)
        if _ollama_alive():
            return True
    # WEDGED-server reap (see _reap_wedged_ollama): a hung ollama would block
    # the fresh `ollama serve` from binding :11434, so clear it first.
    _reap_wedged_ollama()
    print(f"  [ollama] server is down — starting it headlessly ({exe} serve)…")
    try:
        # CREATE_NO_WINDOW, deliberately NOT DETACHED_PROCESS (2026-07-10):
        # detached gives ollama NO console, so every llama-server runner it
        # spawns (one per model load/swap) must ALLOCATE one — and with the
        # default-terminal delegation stuck on Windows Terminal, that popped a
        # visible WT window PER MODEL EVENT (the owner's "ghost windows that
        # disappear... something about AppData" — the titles were
        # AppData\...\Ollama\ollama.EXE / llama-server.exe). A HIDDEN console
        # is INHERITED by every child instead: zero windows, ever. Lifetime is
        # unaffected — the server still outlives JARVIS.
        flags = 0
        if os.name == "nt":
            flags = (getattr(subprocess, "CREATE_NO_WINDOW", 0)
                     | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0))
        subprocess.Popen([exe, "serve"], creationflags=flags,
                         stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                         close_fds=True)
    except Exception as e:
        print(f"  [ollama] failed to start server: {type(e).__name__}: {e}")
        return False
    # First start is SLOW: on a loaded multi-GPU box (3090 + 1650S) the CUDA
    # discovery + runner spin-up measured ~60s before /api/tags first answered
    # 200 (2026-07-09). A 30s wait gave up mid-discovery and logged a false
    # "may be unavailable", even though the model was reachable moments later —
    # so budget 90s here. It's a one-time boot cost; steady-state probes are ms.
    deadline = time.time() + timeout_sec
    while time.time() < deadline:
        if _ollama_alive():
            print("  [ollama] server is up.")
            return True
        time.sleep(1.0)
    print(f"  [ollama] server didn't answer within {timeout_sec:.0f}s — the local "
          "model may be unavailable this session.")
    return False


def _boot_tts_label() -> str:
    """What the boot header should say the TTS is — the engine that will
    ACTUALLY speak, not a config field that may belong to a different engine.

    The header used to print TTS_VOICE unconditionally. TTS_VOICE is an
    edge-tts voice id ("en-GB-RyanNeural"), so once TTS_BACKEND moved to
    'kokoro' (v2.0.84/85) every boot advertised an edge voice while Kokoro's
    bm_george was doing the talking — the same class of defect as preflight
    claiming "Claude API: reachable" without probing. Report the backend and
    the voice that backend really uses; fall back to the edge voice for the
    edge ladder. NEVER raises — a boot banner must not be able to stop boot.
    """
    try:
        backend = (globals().get("TTS_BACKEND", "edge") or "edge").lower()
    except Exception:
        backend = "edge"
    try:
        if backend == "kokoro":
            from core import kokoro_tts as _k
            voice = getattr(_k, "_VOICE", "") or "?"
            # is_available() is the same gate the synth ladder uses, so an
            # unusable model shows as the edge fallback the user will hear.
            if not _k.is_available():
                return f"edge:{TTS_VOICE} (kokoro selected but unavailable)"
            return f"kokoro:{voice} (CPU)"
        if backend == "xtts":
            return f"xtts:{os.path.basename(XTTS_VOICE_SAMPLE or '?')}"
        if backend == "pyttsx3":
            return "pyttsx3 (SAPI5)"
    except Exception:
        pass
    return f"edge:{TTS_VOICE}"


def _local_num_ctx(model: str) -> int:
    """Pick the Ollama num_ctx for a model so it fits 100 % on the 3090.

    THIN DELEGATE. The heuristic itself lives in core.ollama_opts so that
    non-monolith callers (core/orchestrator.py) can share it instead of
    sending no options at all — which is what they did until 2026-07-21, when
    a vision call that omitted num_ctx was proven to EVICT the warm 16k runner
    and reload the same model at its 262144 default, spilling it to CPU and
    killing the local brain every 300 s. See core/ollama_opts for the full
    incident record. This name is kept because the monolith and its test
    harness reference it everywhere.
    """
    from core.ollama_opts import local_num_ctx as _canonical
    return _canonical(model)


def _local_think_param(model: str):
    """Ollama `think` parameter for thinking-capable model families.

    Voice latency: a thinking block adds SECONDS before the first spoken word
    and leaks reasoning prose into TTS, so thinking must be off/minimal for the
    local voice brain. The API param is the ONLY correct mechanism — the
    `/no_think` prompt hack returned an EMPTY reply on qwen3:14b (2026-07-09),
    while `think:false` works (bench-verified 2026-07-10).

    Returns: False  → disable thinking (Qwen3/3.x, Gemma4 hybrids)
             "low"  → minimal reasoning (gpt-oss can't fully disable, only dial)
             None   → OMIT the param (pure-instruct models like qwen2.5 /
                      llama3.x — sending `think` to a non-thinking model is a
                      400 from Ollama)."""
    tag = (model or "").lower()
    if tag.startswith("gpt-oss"):
        return "low"
    for fam in ("qwen3", "gemma4", "deepseek-r1", "magistral"):
        # qwen3 prefix also covers qwen3.5 / qwen3.6 tags.
        if tag.startswith(fam):
            return False
    return None


def _get_local_llm_model() -> str:
    """Resolve which Ollama tag the local-LLM fallback should target.

    Priority order:
      1. JARVIS_LOCAL_LLM_MODEL env var (non-empty after stripping) — the
         documented A/B / low-VRAM escape hatch always wins.
      2. The owner's PERSISTED pick: LOCAL_LLM_MODEL when it differs from
         the shipped default (core.config._SHIPPED_LOCAL_LLM_MODEL) —
         i.e. the Settings-GUI dropdown / voice `set_model` value that
         _apply_user_settings restored at boot — provided it's installed
         (matched exactly, then by bare base name so a `:latest` variant
         counts). Before the 2026-07-21 audit the preference chain ran
         first, so the saved choice silently reverted on every restart.
      3. First entry in _LOCAL_LLM_PREFERENCE that's installed locally
         (matched exactly, then by bare base name so a `:latest` variant
         counts).
      4. First tag returned by Ollama's /api/tags — any installed model
         beats none, even off-list.
      5. LOCAL_LLM_MODEL — the preferred default. Returned (without
         caching) when Ollama is unreachable or has zero models, so the
         background pull triggered by _call_local_llm() targets the
         smart model and a finished pull is picked up on the next call.

    The selection is cached in _RESOLVED_LOCAL_LLM_MODEL once a real
    installed model (or the env override) is found, so the 'model
    selected' log line fires exactly once per process.
    """
    cached = _RESOLVED_LOCAL_LLM_MODEL[0]
    if cached:
        return cached

    override = (os.environ.get("JARVIS_LOCAL_LLM_MODEL") or "").strip()
    if override:
        _RESOLVED_LOCAL_LLM_MODEL[0] = override
        print(f"  [local-llm] model selected via JARVIS_LOCAL_LLM_MODEL: `{override}`")
        _log_gpu_state(override)
        return override

    try:
        r = requests.get(f"{LOCAL_LLM_BASE_URL}/api/tags", timeout=2)
        installed = [m.get("name", "") for m in r.json().get("models", [])] if r.ok else []
    except Exception:
        installed = []
    installed = [n for n in installed if n]

    if installed:
        installed_set = set(installed)
        # 2. The owner's persisted pick (Settings GUI / voice set_model, both
        # land in user_settings.json and are restored onto LOCAL_LLM_MODEL by
        # core.config._apply_user_settings at boot). "User-set" = differs from
        # the shipped default, captured ONCE in core.config BEFORE overrides
        # (never hard-code the tag here — stale-duplicate bug class). Only an
        # INSTALLED pick is honoured; an uninstalled one falls through to the
        # preference chain so a box whose saved tag was removed still boots
        # onto a working brain. 2026-07-21 audit.
        try:
            from core import config as _cfg
            _shipped = getattr(_cfg, "_SHIPPED_LOCAL_LLM_MODEL", LOCAL_LLM_MODEL)
        except Exception:
            _shipped = LOCAL_LLM_MODEL
        user_pick = (LOCAL_LLM_MODEL or "").strip()
        if user_pick and user_pick != _shipped:
            if user_pick in installed_set:
                pick = user_pick
            else:
                base = user_pick.split(":", 1)[0]
                pick = next((n for n in installed if n.split(":", 1)[0] == base), None)
            if pick:
                _RESOLVED_LOCAL_LLM_MODEL[0] = pick
                print(f"  [local-llm] model selected from user settings: `{pick}`")
                _log_gpu_state(pick)
                return pick
        for pref in _LOCAL_LLM_PREFERENCE:
            if pref in installed_set:
                pick = pref
            else:
                base = pref.split(":", 1)[0]
                pick = next((n for n in installed if n.split(":", 1)[0] == base), None)
            if pick:
                _RESOLVED_LOCAL_LLM_MODEL[0] = pick
                print(f"  [local-llm] model selected from preference chain: `{pick}`")
                _log_gpu_state(pick)
                return pick
        pick = installed[0]
        _RESOLVED_LOCAL_LLM_MODEL[0] = pick
        print(f"  [local-llm] no preferred model installed — using first available: `{pick}`")
        _log_gpu_state(pick)
        return pick

    return LOCAL_LLM_MODEL


def _next_local_llm_fallback(exclude: str) -> str | None:
    """Best INSTALLED Ollama model to fail over to when `exclude` produced no
    usable output (e.g. a broken quant that returns an empty string). Walks
    _LOCAL_LLM_PREFERENCE skipping the excluded model's BASE name, then any
    other installed tag. Returns None if nothing else is installed. Mirrors
    _get_local_llm_model's base-name matching so a `:latest` variant counts.
    2026-07-09 — added so one bad quant can't mute the local brain."""
    try:
        r = requests.get(f"{LOCAL_LLM_BASE_URL}/api/tags", timeout=2)
        installed = [m.get("name", "") for m in r.json().get("models", [])] if r.ok else []
    except Exception:
        installed = []
    installed = [n for n in installed if n]
    if not installed:
        return None
    excl_base = (exclude or "").split(":", 1)[0]
    installed_set = set(installed)
    for pref in _LOCAL_LLM_PREFERENCE:
        if pref.split(":", 1)[0] == excl_base:
            continue
        if pref in installed_set:
            return pref
        base = pref.split(":", 1)[0]
        alt = next((n for n in installed if n.split(":", 1)[0] == base), None)
        if alt:
            return alt
    # Off-list: any other installed model that isn't the excluded base.
    for n in installed:
        if n.split(":", 1)[0] != excl_base:
            return n
    return None


def _ollama_has_model(model: str) -> bool:
    """Is `model` ACTUALLY pulled? Exact tag match, allowing only the implicit
    ":latest" expansion ("m" <-> "m:latest", how Ollama names a bare-name pull).

    Deliberately NOT a base-name match (2026-07-21 audit): matching on the text
    before ':' returned True for any sibling tag, so _act_switch_llm's
    "only if installed" guard passed for 'qwen2.5:14b' when only
    'qwen2.5:14b-instruct-q5_K_M' was pulled — pinning the resolver cache at a
    tag Ollama 404s on EVERY turn, with no recovery until restart (the empty-
    response failover only fires on kind='empty', not the 404's kind='fail').
    Callers that want sibling resolution use _ollama_resolve_model below."""
    try:
        r = requests.get(f"{LOCAL_LLM_BASE_URL}/api/tags", timeout=2)
        if not r.ok:
            return False
        names = {m.get("name", "") for m in r.json().get("models", [])}
        if model in names:
            return True
        if ":" not in model:
            return f"{model}:latest" in names
        if model.endswith(":latest"):
            return model[: -len(":latest")] in names
        return False
    except Exception:
        return False


def _ollama_resolve_model(model: str) -> str | None:
    """Resolve a requested tag to the CONCRETE installed tag, or None.

    Order: exact match, then the bare-name <-> ":latest" equivalence, then the
    first installed tag denoting the SAME model per skills.model_picker's
    size-token-aware _same_model — so 'qwen2.5:14b' resolves to the installed
    'qwen2.5:14b-instruct-q5_K_M' but never to 'qwen2.5:32b-...' (different
    sizes are different models). Lets a switch request use the model that is
    ALREADY pulled instead of 404ing or re-pulling ~9 GB. Never raises."""
    want = (model or "").strip()
    if not want:
        return None
    try:
        r = requests.get(f"{LOCAL_LLM_BASE_URL}/api/tags", timeout=2)
        if not r.ok:
            return None
        names = [m.get("name", "") for m in r.json().get("models", []) if m.get("name")]
    except Exception:
        return None
    if want in names:
        return want
    if ":" not in want and f"{want}:latest" in names:
        return f"{want}:latest"
    if want.endswith(":latest") and want[: -len(":latest")] in names:
        return want[: -len(":latest")]
    try:
        from skills.model_picker import _same_model
    except Exception:
        return None
    for tag in names:
        if _same_model(want, tag):
            return tag
    return None


# A model holding ≥ this many bytes of VRAM is treated as the "big" resident
# brain (the qwen3:30b / qwen2.5:32b baseline sits at ~19–21 GB). Co-loading a
# second model on top of it is what over-commits the 24 GB card and bricks the
# GPU (REVIEW_FINDINGS_2 P0-2/P0-3). 12 GB cleanly separates the 30B-class brain
# from a 7B VLM (~7–8 GB) so the guard never trips on the VLM alone.
_OLLAMA_BIG_MODEL_VRAM_BYTES = 12 * 1024 * 1024 * 1024


def _ollama_loaded_models() -> list[dict]:
    """Models Ollama currently holds RESIDENT, via GET /api/ps.

    Returns the raw `models` list (each dict carries at least `name`,
    `model`, and `size_vram`), or [] on any failure (server down, old Ollama
    without /api/ps, HTTP error, timeout, non-JSON). Never raises — callers
    treat an empty list as 'residency unknown / nothing resident' and proceed
    conservatively. This is the canonical runtime residency check; unlike
    /api/tags (which lists INSTALLED models) /api/ps lists LOADED ones."""
    try:
        r = requests.get(f"{LOCAL_LLM_BASE_URL}/api/ps", timeout=2)
        if not r.ok:
            return []
        models = r.json().get("models", [])
        return models if isinstance(models, list) else []
    except Exception:
        return []


def _ollama_big_model_resident(exclude_model: str | None = None) -> str | None:
    """Name of a 'big' model (≥ _OLLAMA_BIG_MODEL_VRAM_BYTES of VRAM) Ollama
    holds resident RIGHT NOW, other than `exclude_model`. Returns the tag, or
    None if none qualifies (or residency can't be read).

    This is the runtime safety check for the VRAM brick: before JARVIS triggers
    a SECOND Ollama model load (e.g. the local VLM), it asks 'is the 30B brain
    already pinned in VRAM?'. If so, co-loading would over-commit the 24 GB card
    — the canonical fix is OLLAMA_MAX_LOADED_MODELS=1 on the SERVER (which makes
    Ollama EVICT instead of co-load), but that env is read by the server at its
    startup and can't be applied to an already-running server JARVIS didn't
    spawn. This guard is the belt-and-suspenders that protects regardless."""
    excl_base = (exclude_model or "").split(":", 1)[0]
    for m in _ollama_loaded_models():
        if not isinstance(m, dict):
            continue
        name = m.get("name") or m.get("model") or ""
        if not name:
            continue
        # Don't count the model we're about to (re)use against itself — a tag
        # that's already resident reuses its VRAM rather than co-loading.
        if excl_base and name.split(":", 1)[0] == excl_base:
            continue
        try:
            vram = int(m.get("size_vram") or 0)
        except (TypeError, ValueError):
            vram = 0
        if vram >= _OLLAMA_BIG_MODEL_VRAM_BYTES:
            return name
    return None


def _local_vision_model_already_resident() -> bool:
    """True when the local VLM tag is ALREADY loaded in VRAM right now.

    The two co-load gates in _call_local_vision exist to stop a SECOND model
    being pulled onto a card that's already holding the brain. Neither gate can
    tell 'load a 9 GB model' apart from 'reuse the 9 GB model that is sitting
    right there' — and since the v2.0.33 overhaul the shipped default is
    chat == vision == gemma4:12b (ONE multimodal model serving both), so the
    common case is precisely the second one: a vision call that needs ZERO new
    VRAM. The free-VRAM gate saw a nearly-full 24 GB card (whisper + chatterbox
    + the resident brain) and refused, and JARVIS said 'I couldn't see the
    screen' while the model it needed was already loaded. Asking /api/ps
    directly settles it. Matches on the base tag (before ':'), like every other
    residency check here, so gemma4:12b matches gemma4:12b-it-q4 etc."""
    base = (LOCAL_VISION_MODEL or "").split(":", 1)[0]
    if not base:
        return False
    for m in _ollama_loaded_models():
        if not isinstance(m, dict):
            continue
        name = m.get("name") or m.get("model") or ""
        if name and name.split(":", 1)[0] == base:
            return True
    return False


# Rough VRAM the local VLM needs to load safely (7B-class q4 weights + KV/decode
# workspace) plus a cushion so a load never lands right at the ceiling and OOMs
# mid-decode. Feeds the true-free-VRAM co-load gate in _call_local_vision.
_VLM_COLOAD_NEEDED_MB = 6000
_VLM_COLOAD_HEADROOM_MB = 1500

# How long a local-vision HTTP call may hold the caller. ask_vision runs on the
# MAIN VOICE THREAD for every caller except _glance, so this doubles as 'how long
# JARVIS may go deaf'. WARM = the model is already resident, so we're only paying
# for decode (measured 2-11 s for a 12B VLM on the 3090 — 60 s is ~5x headroom).
# COLD = Ollama still has to pull the weights off disk, which nothing can hurry.
# Two consecutive timeouts on either bound trip the wedge detector, which reaps
# the stuck runner. 2026-07-14 audit.
_LOCAL_VISION_TIMEOUT_WARM_S = 60
_LOCAL_VISION_TIMEOUT_COLD_S = 180


def _cuda0_free_vram_mb() -> int | None:
    """Best-effort FREE VRAM (MB) on cuda:0 across ALL frameworks — torch,
    faster-whisper/CTranslate2, chatterbox, Ollama, everything.

    Unlike _ollama_big_model_resident (which only sees what the OLLAMA server
    reports), this reads the DRIVER's own free-memory counter, so whisper +
    chatterbox (~6 GB the Ollama API is blind to) are correctly counted against
    the budget before a VLM co-load. Prefers torch.cuda.mem_get_info(0); falls
    back to `nvidia-smi`. Returns None when neither is available — the caller
    then relies on the Ollama residency check alone. 2026-07-08."""
    try:
        import torch
        free, _total = torch.cuda.mem_get_info(0)
        return int(free // (1024 * 1024))
    except Exception:
        pass
    try:
        import subprocess as _sp
        out = _sp.run(
            ["nvidia-smi", "--query-gpu=memory.free",
             "--format=csv,noheader,nounits", "-i", "0"],
            capture_output=True, text=True, timeout=3,
            creationflags=(_sp.CREATE_NO_WINDOW if sys.platform == "win32" else 0),
        )
        if out.returncode == 0:
            lines = (out.stdout or "").strip().splitlines()
            if lines:
                return int(lines[0].strip())
    except Exception:
        pass
    return None


# Debounce before concluding "Ollama is not installed". A single failed 2s
# /api/tags probe is NOT evidence of a missing install — 2026-07-02 live boot:
# the probe flapped once (server busy loading a model) and winget re-ran a
# full `Ollama.Ollama` install 17 seconds AFTER the same server had served
# embedding requests. Patchable so tests don't sleep.
_OLLAMA_INSTALL_RECHECK_S = 10.0


def _ollama_binary_present() -> bool:
    """True when an Ollama binary already exists on this box (PATH, the
    per-user install dir, or Program Files). Used to distinguish "installed
    but not responding" (never reinstall — that can rip the runtime out from
    under a live-but-slow server) from "genuinely not installed"."""
    try:
        import shutil as _sh
        if _sh.which("ollama"):
            return True
        candidates = [
            os.path.join(os.environ.get("LOCALAPPDATA", ""),
                         "Programs", "Ollama", "ollama.exe"),
            r"C:\Program Files\Ollama\ollama.exe",
            r"C:\Program Files (x86)\Ollama\ollama.exe",
        ]
        return any(c and os.path.isfile(c) for c in candidates)
    except Exception:
        # Fail toward "present": skipping an install is recoverable (log tells
        # the user), a spurious reinstall over a live server is not.
        return True


def _ollama_install_async() -> None:
    if _OLLAMA_INSTALL_TRIGGERED[0]:
        return
    _OLLAMA_INSTALL_TRIGGERED[0] = True

    def _do() -> None:
        # Debounce the flapped-probe case: wait, then re-probe before touching
        # winget. The caller decided Ollama was dead off ONE 2s probe.
        time.sleep(_OLLAMA_INSTALL_RECHECK_S)
        if _ollama_alive():
            print("  [local-llm] Ollama responded on re-probe — install skipped (transient probe flap).")
            return
        if _ollama_binary_present():
            print("  [local-llm] Ollama is installed but not responding — NOT reinstalling. "
                  "Start the Ollama app/service manually if this persists (SAC can block ggml.dll).")
            return
        print("  [local-llm] Ollama not detected — running `winget install Ollama.Ollama` in background…")
        try:
            import subprocess as _sp
            _sp.run(
                ["winget", "install", "--id", "Ollama.Ollama",
                 "--silent", "--accept-package-agreements", "--accept-source-agreements"],
                capture_output=True, text=True, timeout=600,
                creationflags=(_sp.CREATE_NO_WINDOW if sys.platform == "win32" else 0),
            )
            print(f"  [local-llm] winget install finished. Once Ollama is up, model `{LOCAL_LLM_MODEL}` will pull automatically.")
        except Exception as _e:
            print(f"  [local-llm] winget install failed: {_e}")

    threading.Thread(target=_do, daemon=True).start()


def _ollama_pull_async(model: str) -> None:
    if _OLLAMA_PULL_TRIGGERED[0]:
        return
    _OLLAMA_PULL_TRIGGERED[0] = True

    def _do() -> None:
        print(f"  [local-llm] pulling model `{model}` in background…")
        try:
            with requests.post(
                f"{LOCAL_LLM_BASE_URL}/api/pull",
                json={"name": model}, timeout=1800, stream=True,
            ) as r:
                for _ in r.iter_lines():
                    pass
            print(f"  [local-llm] model `{model}` ready.")
        except Exception as _e:
            print(f"  [local-llm] model pull failed: {_e}")

    threading.Thread(target=_do, daemon=True).start()


# Reinforces the essentials for the LOCAL baseline model (qwen2.5). It follows
# the action-token grammar + JARVIS persona less reliably than Claude, which in
# the runtime logs produced "claims it did X without doing it", verbose
# rambling, and unsolicited moralising. Appended at the FINAL (most-salient)
# position of the system prompt on every local call. 2026-05-30.
_LOCAL_MODE_DIRECTIVE = (
    "\n\n----------\n"
    "YOU ARE RUNNING ON THE LOCAL MODEL. Obey these rules EXACTLY:\n"
    "1. To DO anything on the computer (play music, set a timer, open an "
    "app or website, click, control devices, search the web, take a "
    "screenshot), you MUST output the literal token [ACTION: name, argument] "
    "— for example [ACTION: set_timer, 5 minutes] or [ACTION: play_music, "
    "Michael Jackson]. Do NOT describe doing it without the token.\n"
    "2. Use ONLY action names from the list above. NEVER invent an action "
    "(no [ACTION: calculate], [ACTION: answer], [ACTION: think], etc.). For "
    "anything you can answer from your own knowledge — arithmetic, facts, "
    "definitions, opinions, banter — just SAY the answer in one short "
    "sentence with NO token (e.g. 'Three hundred ninety-one, sir.').\n"
    "3. NEVER claim you have completed, queued, started, paused, resumed, or "
    "'taken the liberty of' something unless you emitted its [ACTION: ...] "
    "token in THIS reply. If you cannot do it, say so plainly in one sentence.\n"
    "4. Be CONCISE — one or two short sentences. Your words are spoken aloud.\n"
    "5. Do NOT lecture, moralise, or add unsolicited safety/health advice. "
    "Dry wit is welcome; the user is fine with profanity.\n"
    "6. NEVER invent live numbers you were not explicitly given — print "
    "percentage, current/total layer count, ETA, temperatures, prices, "
    "counts. If you lack an exact figure, say it plainly ('the print's still "
    "going, sir') or use the matching action (e.g. [ACTION: print_status]). "
    "Do NOT guess a total like 'layer 105 of 300' when the total is unknown, "
    "and do NOT claim you paused/started/stopped a print you didn't act on.\n"
    "7. Stay in character as JARVIS: composed, capable, faintly sardonic; "
    "address the user as 'sir'.\n"
    "----------\n"
)


_LOCAL_CHEATSHEET_CACHE: list[str | None] = [None]


# The single most important instruction on the LOCAL path. A small model with no
# guard invents the time, its own version, the weather, or a system stat instead
# of emitting the action that fetches the real value. This lives in ONE place and
# is used by BOTH local-prompt slimmers — the hand-curated _local_cheatsheet AND
# the prompt_router slim path. They used to diverge: the router path (the default
# since 2026-07-15) silently shipped WITHOUT this block, so local turns hedged or
# fabricated weather / version / whats_broken. Single-source it so that can't recur.
_LOCAL_NEVER_GUESS_GUARD = (
    "*** ALWAYS USE THE ACTION — NEVER GUESS THESE ***\n"
    "You do NOT know the current time, date, your version, the weather, or\n"
    "any system stat without running its action. NEVER state them from\n"
    "memory — emit the token and let the system fill in the real value:\n"
    "  [ACTION: get_time]            \"what time is it\" / \"what's the date\"\n"
    "  [ACTION: version_info]        \"what version are you on\" / \"when were you updated\"\n"
    "  [ACTION: weather_briefing]    \"what's the weather\" / \"is it going to rain\"\n"
    "  [ACTION: system_pulse]        \"system status\" / \"how are you running\" / CPU/RAM\n"
    "  [ACTION: whats_broken]        \"what's broken\" / \"anything wrong\"\n"
    "  [ACTION: list_timers]         \"list my timers\" / \"what timers are running\"\n"
    "  [ACTION: recognize_face]      \"who am I\" / \"who's here\" / \"who's at the desk\" / \"do you recognize me\"\n"
    "If sir asks any of the above, your reply must contain ONLY the action\n"
    "token (plus at most a short lead-in like \"One moment, sir.\"). Do not\n"
    "invent a time, version number, temperature, or status — you will be\n"
    "wrong. WHO is here is a LIVE CAMERA LOOK: even though you may know sir's\n"
    "name, never answer 'who am I' / 'who's here' from memory — he may be out\n"
    "of frame. Emit [ACTION: recognize_face] and report ONLY who the camera\n"
    "sees now (the recognised name, or that no one is in frame).\n"
)


def _local_cheatsheet() -> str:
    """A COMPACT action reference that REPLACES the ~18k-token PC_CONTROL_PROMPT
    for local-model calls.

    The full Claude-tuned PC_CONTROL_PROMPT is ~18,400 tokens. Feeding that to a
    14B local model every turn is the core reason local mode felt bad: (1) the
    prompt-eval of ~23k total tokens dominates latency, (2) instruction-
    following in a 14B model collapses on 20k+ token prompts ("lost in the
    middle") → hallucinated action execution + rambling, and (3) it forces a
    32k context whose KV cache (~9 GB) spills the model partly onto the CPU.

    This keeps the EXACT [ACTION: name, arg] grammar plus the most common
    actions spelled out, then appends EVERY registered action name straight
    from the live ACTIONS registry so nothing is unreachable and the list never
    drifts out of sync. ~2k tokens instead of ~18k. Cached after first build.
    """
    cached = _LOCAL_CHEATSHEET_CACHE[0]
    if cached is not None:
        return cached
    common = (
        "\n\n=== CONTROLLING THE PC ===\n"
        "To DO something, output a token EXACTLY like:  [ACTION: name, argument]\n"
        "Put it on its own line; the system runs it and hands you the result to\n"
        "comment on. Emit an action ONLY when sir wants something DONE — for\n"
        "ordinary conversation, just reply normally with no token.\n\n"
        + _LOCAL_NEVER_GUESS_GUARD +
        "\nMost-used actions (classic iTunes is GONE — the Apple Music app + music.apple.com are the player):\n"
        "  [ACTION: play_music, <artist/song/album>]   play a song/artist/album on Apple Music (music.apple.com)\n"
        "  [ACTION: play_playlist, <name>]   play ANY named playlist — streams it via Apple Music ('shuffle ' prefix shuffles). Use this for every 'play my/the <name> playlist', NOT apple_music.\n"
        "  [ACTION: list_playlists]   (points sir to the Apple Music app)   [ACTION: shuffle_library]   shuffle music via Apple Music\n"
        "  [ACTION: open_apple_music]   open the Apple Music app   [ACTION: music_status]   is Apple Music installed/running/what's playing\n"
        "  [ACTION: pause_music]  [ACTION: resume_music]  [ACTION: next_song]  [ACTION: previous_song]  [ACTION: now_playing]   (media keys — work on the app OR browser)\n"
        "  [ACTION: media_playpause]  [ACTION: media_next]  [ACTION: media_prev]\n"
        "  [ACTION: volume_up]  [ACTION: volume_down]  [ACTION: volume_mute]\n"
        "  [ACTION: set_volume, 30]   <- absolute: 'set the volume to 30 percent'\n"
        "  [ACTION: netflix, <title>]  [ACTION: spotify, <query>]\n"
        "  [ACTION: youtube_play, <video>]  <- 'play X on youtube': opens, FINDS\n"
        "      the first real video and CLICKS it (auto-fullscreen). Prefer this\n"
        "      whenever the user wants something PLAYED on youtube.\n"
        "  [ACTION: youtube, <search>]      <- search-only: just opens results\n"
        "  [ACTION: apple_music, <query>]  [ACTION: disney_plus, <title>]  [ACTION: hulu, <title>]\n"
        "  [ACTION: set_timer, 5 minutes]   (or '5 minutes for tea')   [ACTION: list_timers]   [ACTION: cancel_timer]  (no arg cancels the running one)\n"
        "  [ACTION: see_screen]  or  [ACTION: see_screen, middle]   look at the screen & describe it\n"
        "  [ACTION: find_on_screen, <thing>]   [ACTION: recall_screen]\n"
        "  [ACTION: kinect_status]   'kinect status' / 'is the kinect working'   (Xbox Kinect; honest if it's off/absent)\n"
        "  [ACTION: who_is_here]   'who is in the room' / 'is anyone here'   [ACTION: scan_room]   (Kinect skeleton: body count + distance)\n"
        "  [ACTION: kinect_look, <question>]   'what do you see through the kinect' / 'look through the kinect'\n"
        "  [ACTION: camera_status]   'what cameras do you have' / 'camera status'   (ALL cameras at once: both webcams + Kinect, with live health)\n"
        "  [ACTION: situational_awareness]   'where am I' / 'what am I doing' / \"what's my status\"   (fuses webcam gaze + Kinect presence into one read)\n"
        "  [ACTION: look_around]   'look around' / 'what do you see everywhere'   (describes EVERY camera at once; prefers the free local vision model)\n"
        "  [ACTION: enroll_face]   'learn my face' / 'remember my face' / 'this is me'   (face recognition; off by default, opt-in)\n"
        "  [ACTION: whoami]   'who am I' / 'do you recognize me' / \"who's at the desk\"   [ACTION: face_id_status]   'is face recognition on' / 'face id status'\n"
        "  [ACTION: forget_face, <name>]   forget a face   [ACTION: list_enrolled_faces]   who's enrolled\n"
        "  [ACTION: gesture_status]   'what gestures can you see' / 'is gesture control on'   (Kinect gesture control: wave=wake, raise hand=confirm, swipe=cancel)\n"
        "  [ACTION: gestures_on]   'turn on gesture control' / 'enable gestures'   [ACTION: gestures_off]   'turn off gesture control'\n"
        "  [ACTION: point_calibrate, <device>]   point-to-control: user POINTS at a device + says 'calibrate pointing for the desk lamp' (Kinect; off by default)\n"
        "  [ACTION: point_control, <on|off>]   user is POINTING at a calibrated device — 'turn that on' / 'that one off' fire this; it resolves the point + switches that device\n"
        "  [ACTION: list_point_targets]   'what can I point at'   [ACTION: point_control_on]   'turn on point control'   [ACTION: point_control_off]\n"
        "  [ACTION: guard_on]   'guard the room' / 'watch the room' / 'arm security' / 'keep watch'   (arm ALL cameras as a security array; snapshots + alerts on motion/intrusion)\n"
        "  [ACTION: guard_off]   'stand down' / 'disarm' / 'stop guarding'   [ACTION: guard_status]   'are you watching' / 'guard status'\n"
        "  [ACTION: web_search, <query>]   open a web search in the browser\n"
        "  [ACTION: open_url, <url>]   [ACTION: launch_app, <app name>]\n"
        "  [ACTION: open_on_monitor, <app or url> | <left|middle|right|top>]\n"
        "  [ACTION: type, <text to type>]   [ACTION: click, <what to click>]\n"
        "  [ACTION: move_window_to_monitor, <left|middle|right|top>]\n"
        "  [ACTION: minimize_window]   [ACTION: close_window]\n"
        "  [ACTION: check_system]   [ACTION: system_pulse]   [ACTION: check_print]\n"
        "  [ACTION: show_printer_camera]   'show me the printer camera' / 'pull up the H2D camera' / 'watch the print'   [ACTION: hide_printer_camera]   'close the printer camera'\n"
        "  [ACTION: weather_briefing]   [ACTION: news_briefing]   [ACTION: morning_briefing]\n"
        "  [ACTION: calendar_today]   \"what's on my calendar\" / \"what's on my schedule\" / \"do I have any meetings\"   (read the calendar; arg = today/tomorrow/this week; NOT morning_briefing)\n"
        "  [ACTION: queue_task, <task for Claude Code>]   [ACTION: show_tasks]\n"
        "  [ACTION: smart_home_control, <plain request>]   [ACTION: make_picture, <prompt>]\n"
        "Choosing YOUR OWN local brain (which Ollama model runs you):\n"
        "  [ACTION: current_model]       \"what model are you using\" / \"what's your brain\"\n"
        "  [ACTION: list_models]         \"what models do you have\" / \"what can you run on\"\n"
        "  [ACTION: set_model, <name>]   \"switch to the 32B\" / \"use the fast one\" / \"use qwen\"\n"
        "                                 (arg is a tag/size/alias: 32b, 14b, 8b, big, fast, qwen, llama)\n"
        "  [ACTION: set_brain, <local|cloud|auto>]   \"use local\" / \"use cloud / Claude\" / \"go auto\"\n"
    )
    # Append EVERY registered action name (late-bound from the live registry —
    # ACTIONS is fully populated by the time this runs at request time).
    allnames = ""
    try:
        names = sorted({k for k in ACTIONS.keys() if isinstance(k, str)})
        if names:
            allnames = (
                "\nEvery available action (same [ACTION: name, arg] grammar — "
                "use these exact names):\n  " + ", ".join(names) + "\n"
            )
    except Exception:
        pass
    tail = (
        "\nACTION RULES:\n"
        "- NEVER say you did / started / queued / opened / set something unless\n"
        "  you emitted its [ACTION: ...] token in THIS reply. If you cannot do\n"
        "  it, say so plainly in one sentence — do not pretend.\n"
        "- One action per reply unless the task plainly needs more.\n"
        "- The argument is plain text after the comma — no JSON, no quotes.\n"
        # Single-sourced from core.prompts so this cheatsheet path (the
        # JARVIS_DYNAMIC_LOCAL_PROMPT=0 fallback) can never silently drop the
        # confirmation-hold / ask-first rules again (2026-07-21 audit).
        + PC_CONTROL_SAFETY_RULES +
        "=== END PC CONTROL ===\n"
    )
    out = common + allnames + tail
    _LOCAL_CHEATSHEET_CACHE[0] = out
    return out


def _call_local_llm(system: str, messages: list, max_tokens: int = 500) -> str | None:
    """POST to Ollama /api/chat. Returns the assistant text or None on any
    failure (no Ollama running, no model pulled, HTTP error, timeout)."""
    if not LOCAL_LLM_FALLBACK:
        return None
    if not _ollama_alive():
        _ollama_selfheal_async()   # mid-session death: restart in background
        _ollama_install_async()    # (no-op when the binary is present+installed)
        return None
    model = _get_local_llm_model()
    if not _ollama_has_model(model):
        _ollama_pull_async(model)
        return None
    # Anti-hallucination guard: if the recent conversation shows a web_search
    # was fired but no subsequent see_screen read the results, the local LLM
    # tends to fabricate source attributions ("from census data…"). Scan the
    # last few assistant messages narrowly to avoid false positives from
    # trimmed history.
    # Swap the ~18k-token PC_CONTROL_PROMPT for the compact local cheatsheet —
    # the single biggest lever on local quality + speed (see _local_cheatsheet).
    # Everything else (persona, memory, per-turn tone hint) is preserved.
    sys_prompt = system
    try:
        if PC_CONTROL_PROMPT and PC_CONTROL_PROMPT in sys_prompt:
            sys_prompt = sys_prompt.replace(PC_CONTROL_PROMPT, _local_cheatsheet())
    except Exception:
        pass
    try:
        recent = messages[-6:] if isinstance(messages, list) else []
        last_search_idx = -1
        last_see_idx = -1
        for i, m in enumerate(recent):
            if not isinstance(m, dict) or m.get("role") != "assistant":
                continue
            content = m.get("content") or ""
            if not isinstance(content, str):
                continue
            if "[ACTION: web_search" in content:
                last_search_idx = i
            if "[ACTION: see_screen" in content:
                last_see_idx = i
        if last_search_idx >= 0 and last_see_idx <= last_search_idx:
            _search_guard = (
                "IMPORTANT: a web search was just fired but the results have "
                "not been read. Do NOT fabricate or claim source attributions. "
                "Acknowledge the search was opened in the browser and offer to "
                "read the results via see_screen.\n\n"
            )
            if _STABLE_LOCAL_PREFIX:
                # Under the cache-stable layout this must NOT go on the front
                # of the system prompt: a per-turn prepend moves the divergence
                # point to token 0 and costs a full ~2.9 s re-evaluation of the
                # whole prompt (see _STABLE_LOCAL_PREFIX). The tail of the user
                # message is both free and MORE salient, which is what the
                # "IMPORTANT" was reaching for anyway.
                messages = _with_turn_context(messages, _search_guard)
            else:
                sys_prompt = _search_guard + sys_prompt
    except Exception:
        pass
    # Reinforce the local-mode behaviour rules at the most-salient (final)
    # position — addresses the hallucinated-execution / verbose / moralising
    # replies the giant Claude prompt produced on a 14B model.
    sys_prompt = sys_prompt + _LOCAL_MODE_DIRECTIVE
    def _generate(model_tag: str) -> tuple[str | None, str]:
        """One /api/chat round-trip. Returns (text, kind):
          'ok'    → text is the non-empty reply
          'empty' → HTTP 200 but the model emitted an EMPTY string. This is the
                    broken-quant fingerprint — the model RAN (tokens generated)
                    yet produced no content (exactly what gemma4:26b-a4b-it-qat's
                    Q4_0 build did, muting the local brain on 2026-07-09).
          'fail'  → HTTP error, read timeout, or exception (treat as down)."""
        payload = {
            "model": model_tag,
            "messages": [{"role": "system", "content": sys_prompt}] + messages,
            "stream": False,
            "options": {
                "num_predict": max_tokens,
                # Cap context (was the model-default 32k). With the compact
                # prompt the real prompt is ~8k, so even 12k leaves ample room
                # for history + generation while keeping the KV cache small
                # enough that the model fits 100% on the GPU (no CPU spill →
                # much faster). Model-aware because the 32B needs the tighter
                # window: MEASURED on the 3090, 32B@12k = 100% GPU / ~49 tok/s,
                # but 32B@16k spills ~5% to CPU / ~28 tok/s. 14B/8B keep 16k.
                "num_ctx": _local_num_ctx(model_tag),
                # Lower than Ollama's 0.8 default → more focused, less rambly,
                # better at emitting the exact action-token grammar.
                "temperature": 0.4,
                "top_p": 0.9,
                # Light, deliberately conservative tuning: a small repeat
                # penalty curbs the local model's tendency to loop a phrase,
                # and top_k=40 trims the long tail without hurting the
                # action-grammar. Kept gentle so behaviour stays close to the
                # tuning the cheatsheet/persona were validated against.
                "repeat_penalty": 1.05,
                "top_k": 40,
            },
            # Keep the model resident between turns so a voice burst doesn't pay
            # the ~3-5s reload each time (it competes with whisper on reload).
            "keep_alive": "20m",
        }
        # Thinking models MUST have thinking disabled/minimised for voice —
        # computed per model_tag because the empty-response failover can land
        # on a different family than the primary. None = omit (pure instruct).
        _think = _local_think_param(model_tag)
        if _think is not None:
            payload["think"] = _think
        _prof("llm_post", f"sys={len(sys_prompt)}")
        try:
            r = requests.post(f"{LOCAL_LLM_BASE_URL}/api/chat", json=payload,
                              timeout=_LOCAL_GENERATE_TIMEOUT)
            _prof("llm_resp", _prof_ollama(r))
            if not r.ok:
                print(f"  [local-llm] HTTP {r.status_code}: {r.text[:200]}")
                return (None, "fail")
            text = ((r.json().get("message") or {}).get("content") or "").strip()
            if not text:
                return (None, "empty")
            _text_wedge_note_ok()
            return (text, "ok")
        except _RequestsTimeout as _e:
            # The runner accepted the POST but never produced a reply within the
            # read budget — almost always a blocked/wedged runner (e.g. SAC).
            # (Uses the import-time class, not requests.Timeout, so a mocked-out
            # `requests` global can't turn this except into a TypeError.)
            print(f"  [local-llm] generate timed out ({_e}) — runner up but not "
                  f"responding (blocked/wedged?); treating local as unavailable")
            # A TEXT-path wedge is as invisible to _ollama_alive() as the vision
            # one was: /api/tags keeps answering in ms while every generate
            # hangs, so _ensure_ollama_running() no-ops and nothing ever reaps
            # it — the brain stays "not responding" until a human kills
            # ollama.exe. The vision path got a detector in v2.0.58; the chat
            # path (the one that answers EVERY turn) had none. 2026-07-14 audit.
            _text_wedge_note_timeout()
            return (None, "fail")
        except Exception as _e:
            print(f"  [local-llm] call failed: {_e}")
            return (None, "fail")

    text, kind = _generate(model)
    if kind == "ok":
        print(f"  [local-llm] served via {model}")
        return text
    if kind == "empty":
        # 200-OK-but-EMPTY = the model ran but a broken quant / template
        # mismatch produced nothing. Do NOT report "down" (which muted JARVIS
        # for a full outage on 2026-07-09) — fail over ONCE to the best
        # DIFFERENT installed model so one bad quant can't take out the local
        # brain. Only the empty case retries; a timeout ('fail') already spent
        # the read budget, so retrying a wedged runner would just double the
        # wait for nothing.
        alt = _next_local_llm_fallback(exclude=model)
        print(f"  [local-llm] `{model}` returned EMPTY (likely a broken quant)"
              + (f" — failing over to `{alt}`" if alt
                 else " — no alternate model to fail over to"))
        if alt:
            text2, kind2 = _generate(alt)
            if kind2 == "ok":
                # Sticky: pin the working model for the rest of the session so
                # every later turn skips the broken one (no repeated empty+retry).
                _RESOLVED_LOCAL_LLM_MODEL[0] = alt
                print(f"  [local-llm] served via {alt} (failed over from {model})")
                return text2
            print(f"  [local-llm] failover model `{alt}` returned {kind2} too "
                  f"— treating local as unavailable")
    return None


def _local_fallback_or(sys_prompt: str, default_reply: str) -> str:
    """Try the local LLM; on success prepend `[local] `, else return the
    cloud-side error message untouched."""
    text = _call_local_llm(sys_prompt, conversation_history)
    if not text:
        return default_reply
    # Deliberately NO "[local]" prefix on the reply — it was being spoken
    # aloud ("local, sir…") every turn during the API cap and the user asked
    # for it to stop (2026-05-30). The per-call `[local-llm] served via …`
    # console line already records that the local model answered, so the
    # debug signal is preserved without polluting the voiced/displayed text.
    # Strip a stale leading tag too, in case one is already present.
    t = text.lstrip()
    if t.startswith("[local]"):
        t = t[len("[local]"):].lstrip()
    return t


# ── Local-brain resilience: honest fallback when the local model is down ──
#
# The contract (see TASKS §4): NEVER fabricate or fail silently when the local
# brain is actually down. When local can't answer this turn, fall back to
# Claude if it's reachable; if NEITHER works, say so honestly. A wrinkle this
# guards against: Smart App Control can block Ollama's runner (ggml.dll / the
# runner .exe) while /api/tags still answers 200 — so _ollama_alive() reports
# healthy but generation hangs. We detect that via the read-timeout in
# _call_local_llm (which returns None) AND, best-effort, via the Windows event
# log (_sac_blocked_local_recently) so the user gets a specific explanation.

# Cache for the SAC event-log probe: (monotonic_expiry, bool_result). The probe
# forks PowerShell, so it's rate-limited to once per ~60 s and only run right
# after a local generate has actually failed.
_SAC_CHECK_CACHE: list = [0.0, False]
_SAC_CHECK_TTL_S = 60.0


def _sac_blocked_local_recently() -> bool:
    """Best-effort: did Windows Smart App Control block Ollama's runner in the
    last ~15 min? Returns True if a CodeIntegrity 3077 (blocked-image) event
    naming 'ollama' or 'ggml' is found. Windows-only, never fatal, rate-limited
    to one real probe per ~60 s. Any error / non-Windows / timeout → False."""
    now = time.monotonic()
    expiry, cached = _SAC_CHECK_CACHE
    if now < expiry:
        return cached

    result = False
    try:
        import platform
        if platform.system() == "Windows":
            # CodeIntegrity/Operational Id 3077 = "image could not load because
            # it did not meet the SAC/WDAC policy". Filter to the last 15 min,
            # render the messages, and look for our runner / ggml in the text.
            ps = (
                "$ErrorActionPreference='SilentlyContinue';"
                "$evs = Get-WinEvent -FilterHashtable @{"
                "LogName='Microsoft-Windows-CodeIntegrity/Operational';"
                "Id=3077;StartTime=(Get-Date).AddMinutes(-15)};"
                "if ($evs) { $evs | ForEach-Object { $_.Message } }"
            )
            out = subprocess.run(
                ["powershell", "-NoProfile", "-NonInteractive", "-Command", ps],
                capture_output=True, text=True, timeout=4,
                creationflags=(subprocess.CREATE_NO_WINDOW if sys.platform == "win32" else 0),
            )
            blob = ((out.stdout or "") + (out.stderr or "")).lower()
            if "ollama" in blob or "ggml" in blob:
                result = True
    except Exception:
        # Non-Windows, no such log, PowerShell missing, timeout, permission —
        # all non-fatal. We simply don't have SAC evidence.
        result = False

    _SAC_CHECK_CACHE[0] = now + _SAC_CHECK_TTL_S
    _SAC_CHECK_CACHE[1] = result
    return result


def _claude_reachable() -> bool:
    """Is the Claude cloud path usable right now? True only when the backend is
    Claude AND a key is present. (We deliberately do NOT fire a network ping
    here — this gates whether to ATTEMPT Claude as a fallback; the attempt's own
    try/except handles an actually-down cloud.) Ollama-backend installs and
    keyless installs return False, so the honest 'both down' message fires."""
    try:
        if AI_BACKEND != "claude":
            return False
        return bool((os.environ.get("ANTHROPIC_API_KEY") or "").strip())
    except Exception:
        return False


def _claude_oneshot(system: str, messages: list, max_tokens: int = 500) -> str | None:
    """Single Claude completion used as the cloud fallback when the LOCAL model
    fails on a 'local'-routed turn. Returns the text, or None if the cloud is
    unreachable / errors (caller then emits the honest both-down message).
    Mirrors the timeout + client-reuse the main _call_llm Claude path uses."""
    if not _claude_reachable():
        return None
    try:
        # Prefer the shared, instrumented client wrapper (same path _call_llm
        # uses); fall back to a direct anthropic client otherwise. Either way
        # the call is bounded by _ANTHROPIC_TIMEOUT_S so a hung cloud socket
        # can't freeze the voice thread.
        if _llm_client is not None:
            return _llm_client.complete(
                model=CLAUDE_MODEL, max_tokens=max_tokens,
                system=system, messages=messages,
                timeout=_ANTHROPIC_TIMEOUT_S,
            )
        msg = _anthropic_client().messages.create(
            model=CLAUDE_MODEL, max_tokens=max_tokens,
            system=system, messages=messages,
        )
        return msg.content[0].text
    except Exception as _e:
        print(f"  [local-llm] cloud fallback also failed ({type(_e).__name__}: {_e})")
        return None


def _local_unavailable_message() -> str:
    """The honest, user-facing sentence to speak when the local brain couldn't
    answer AND the cloud isn't an option either. Specific when we have evidence
    Smart App Control blocked the runner this boot; generic otherwise. Never
    fabricates an answer to the user's actual question."""
    if _sac_blocked_local_recently():
        return ("Windows Smart App Control blocked my local model this boot, "
                "sir — and I can't reach the cloud either, so I'm unable to "
                "answer that right now.")
    return ("My local model isn't responding and I can't reach the cloud "
            "either, sir.")


def _local_then_cloud_or_honest(sys_prompt: str, messages: list,
                                max_tokens: int = 500) -> str:
    """LOCAL-routed turn with honest resilience. Try the local model; if it
    can't answer this turn, fall back to Claude when reachable; if neither
    works, return an honest sentence (never a fabricated answer).

    This is the 'local' route's counterpart to _call_llm's Claude-first path:
    there, Claude is tried first and local is the safety net; here local is
    primary and Claude is the safety net.

    The whole body is wrapped so an unexpected raise (from a helper's pre-try
    guard, the SAC probe, etc.) degrades to the honest unavailability line
    rather than propagating — giving the LOCAL route the same no-propagate
    guarantee the Claude and Ollama branches of _call_llm already have."""
    try:
        text = _call_local_llm(sys_prompt, messages, max_tokens=max_tokens)
        if text:
            t = text.lstrip()
            if t.startswith("[local]"):
                t = t[len("[local]"):].lstrip()
            return t
        # Local didn't answer. Prefer the cloud if we can reach it.
        cloud = _claude_oneshot(sys_prompt, messages, max_tokens=max_tokens)
        if cloud:
            if _sac_blocked_local_recently():
                print("  [local-llm] SAC blocked the local runner this boot — "
                      "served this turn from the cloud instead")
            else:
                print("  [local-llm] local model unavailable — served this turn "
                      "from the cloud instead")
            return cloud
    except Exception as _e:
        print(f"  [local-llm] local route raised ({type(_e).__name__}: {_e}) — "
              "returning honest unavailability message (no fabrication)")
        return _local_unavailable_message()
    # Neither local nor cloud. Be honest; never fabricate.
    print("  [local-llm] BOTH local and cloud unavailable — returning honest "
          "unavailability message (no fabrication)")
    return _local_unavailable_message()


# Guard so the boot warm-up fires at most once per process.
_LOCAL_WARMUP_TRIGGERED = [False]


def _warm_up_local_llm_async() -> None:
    """Non-blocking boot warm-up: confirm the local model actually GENERATES
    (not merely that /api/tags answers 200 — the SAC-blocked-runner case passes
    that check but can't generate). Runs a tiny 1-token generate on a daemon
    thread so it NEVER delays boot, logs which model answered + that it's now
    resident, and is otherwise best-effort. Pays the one-time model-load cost
    up front so the first real user turn (and the 50 s generate read budget)
    isn't competing with a cold 19 GB VRAM load.

    Gated OFF in staging / test (JARVIS_STAGING / JARVIS_TEST_MODE / the
    singleton sentinel) so the import-harness and the blue/green staging
    instance don't spin a real Ollama generate."""
    if _LOCAL_WARMUP_TRIGGERED[0]:
        return
    _LOCAL_WARMUP_TRIGGERED[0] = True
    # Match the codebase's staging/test sentinel pattern: never warm up under
    # the test harness or the staging instance.
    if (os.environ.get("JARVIS_STAGING", "").strip() == "1"
            or os.environ.get("JARVIS_TEST_MODE", "").strip() == "1"
            or "--staging" in sys.argv
            or _is_staging()):
        return
    if not LOCAL_LLM_FALLBACK:
        return

    def _do() -> None:
        try:
            if not _ollama_alive():
                # Ollama not up yet — the normal lazy path (_call_local_llm)
                # will install/pull on first real use; nothing to warm.
                print("  [local-llm] warm-up skipped — Ollama not reachable yet")
                return
            model = _get_local_llm_model()
            if not _ollama_has_model(model):
                # Not pulled yet; _call_local_llm kicks the background pull on
                # first real use. Don't duplicate that here.
                print(f"  [local-llm] warm-up skipped — `{model}` not pulled yet")
                return
            t0 = time.monotonic()
            # Confirm it GENERATES. 1 token, keep_alive so it stays resident.
            payload = {
                "model": model,
                "messages": [{"role": "user", "content": "ok"}],
                "stream": False,
                "options": {"num_predict": 1, "num_ctx": _local_num_ctx(model)},
                "keep_alive": "20m",
            }
            r = requests.post(f"{LOCAL_LLM_BASE_URL}/api/chat", json=payload,
                              timeout=_LOCAL_GENERATE_TIMEOUT)
            dt = time.monotonic() - t0
            if r.ok:
                print(f"  [local-llm] warm-up OK — `{model}` generated in "
                      f"{dt:.1f}s and is now resident (num_ctx="
                      f"{_local_num_ctx(model)})")
            else:
                print(f"  [local-llm] warm-up FAILED — `{model}` HTTP "
                      f"{r.status_code}: {r.text[:160]}")
        except requests.Timeout:
            # Up on /api/tags but couldn't generate within the budget — the
            # exact blocked/wedged-runner signature. Surface SAC if we can.
            if _sac_blocked_local_recently():
                print("  [local-llm] warm-up FAILED — runner up but did not "
                      "generate; Smart App Control appears to have blocked it "
                      "this boot. Foreground turns will fall back to the cloud.")
            else:
                print("  [local-llm] warm-up FAILED — runner up on /api/tags "
                      "but did not generate within the budget (blocked/wedged "
                      "runner?). Foreground turns will fall back to the cloud.")
        except Exception as _e:
            print(f"  [local-llm] warm-up error (non-fatal): "
                  f"{type(_e).__name__}: {_e}")

    threading.Thread(target=_do, daemon=True, name="local-llm-warmup").start()


# ── Local VLM (vision) over the same Ollama instance ─────────────────────
_LOCAL_VISION_PULL_TRIGGERED = [False]


def _ollama_pull_vision_async(model: str) -> None:
    """Background-pull a vision model. Separate trigger flag so the text
    fallback's pull and the vision fallback's pull don't block each other."""
    if _LOCAL_VISION_PULL_TRIGGERED[0]:
        return
    _LOCAL_VISION_PULL_TRIGGERED[0] = True

    def _do() -> None:
        print(f"  [local-vision] pulling VLM `{model}` in background…")
        try:
            with requests.post(
                f"{LOCAL_LLM_BASE_URL}/api/pull",
                json={"name": model}, timeout=3600, stream=True,
            ) as r:
                for _ in r.iter_lines():
                    pass
            print(f"  [local-vision] VLM `{model}` ready.")
        except requests.RequestException as _e:
            # Reset the trigger so a transient network failure doesn't
            # permanently block local vision until the process restarts.
            _LOCAL_VISION_PULL_TRIGGERED[0] = False
            print(f"  [local-vision] VLM pull failed: {_e}")

    threading.Thread(target=_do, daemon=True).start()


# Tag used in console output for the env-ensure step.
_OLLAMA_MAX_LOADED_ENV = "OLLAMA_MAX_LOADED_MODELS"


def _persist_user_env(name: str, value: str) -> str:
    """Idempotently persist NAME=VALUE to the User-scope environment (HKCU\\
    Environment) so a process the User launches LATER inherits it. Returns one
    of: 'already' (already set to VALUE — no write), 'set' (written), 'noop'
    (non-Windows / winreg unavailable), or 'error' (write failed). Never raises.

    Why the registry and not just os.environ: the Ollama SERVER reads
    OLLAMA_MAX_LOADED_MODELS at ITS OWN startup, and JARVIS does NOT spawn the
    server (it's auto-started by Windows / the Ollama tray app). Setting it only
    in JARVIS's process env would never reach that server. Persisting it at User
    scope makes the server pick it up the next time it launches. (We do NOT
    broadcast WM_SETTINGCHANGE — already-running processes, including the live
    Ollama server, keep their old env until they restart; that one-time restart
    is surfaced to the user by the boot caller.)"""
    try:
        import winreg
    except Exception:
        return "noop"
    try:
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, "Environment", 0,
                            winreg.KEY_READ | winreg.KEY_SET_VALUE) as k:
            try:
                cur, _ = winreg.QueryValueEx(k, name)
            except FileNotFoundError:
                cur = None
            if isinstance(cur, str) and cur.strip() == value:
                return "already"
            winreg.SetValueEx(k, name, 0, winreg.REG_SZ, value)
            return "set"
    except Exception as _e:
        print(f"  [ollama-env] could not persist {name}={value}: {_e}")
        return "error"


def _ensure_ollama_single_model_env() -> None:
    """Cap Ollama at ONE resident model so a 2nd-model load EVICTS the first
    instead of co-loading it — the canonical fix for the 24 GB VRAM brick
    (REVIEW_FINDINGS_2 P0-2). Sets OLLAMA_MAX_LOADED_MODELS=1.

    Two-pronged, because the Ollama server reads this env at ITS OWN startup and
    JARVIS doesn't spawn the server:
      1. os.environ — set it for THIS process (and anything JARVIS itself might
         spawn), harmless and future-proof.
      2. HKCU\\Environment — persist it so the NEXT Ollama server launch reads
         the cap even though the currently-running server can't.
    If the persistent value was newly written AND a server is already up holding
    multiple models, the user must restart Ollama ONCE for the cap to bind on
    the live server; we log exactly that. Best-effort and silent on non-Windows.
    Gated OFF in staging/test so the import-harness never writes to the registry."""
    if (os.environ.get("JARVIS_STAGING", "").strip() == "1"
            or os.environ.get("JARVIS_TEST_MODE", "").strip() == "1"):
        return
    # 1) Current process. setdefault: never clobber an explicit operator override
    #    (e.g. someone who deliberately set it to 2 for a multi-GPU box).
    os.environ.setdefault(_OLLAMA_MAX_LOADED_ENV, "1")
    # 2) Persist for the next server launch.
    status = _persist_user_env(_OLLAMA_MAX_LOADED_ENV, "1")
    if status == "already":
        print(f"  [ollama-env] {_OLLAMA_MAX_LOADED_ENV}=1 already persisted "
              f"(User env) — Ollama will evict, not co-load. Good.")
    elif status == "set":
        print(f"  [ollama-env] persisted {_OLLAMA_MAX_LOADED_ENV}=1 to User env "
              f"so Ollama evicts instead of co-loading a 2nd model (VRAM-brick "
              f"guard).")
        # Only nag about a restart if a server is actually up AND already holding
        # more than one model — otherwise nothing is at risk right now.
        try:
            loaded = _ollama_loaded_models()
        except Exception:
            loaded = []
        if len(loaded) > 1:
            names = ", ".join(
                (m.get("name") or m.get("model") or "?")
                for m in loaded if isinstance(m, dict))
            print(f"  [ollama-env] NOTE: the RUNNING Ollama server still holds "
                  f"{len(loaded)} models ({names}) and won't read the new cap "
                  f"until restarted. Restart Ollama ONCE (quit the tray icon / "
                  f"`Restart-Service ollama` / kill ollama.exe) to bind the cap "
                  f"on the live server. JARVIS's runtime guard protects the GPU "
                  f"until then.")
    # status in ('noop','error'): nothing persisted — the runtime co-load guard
    # in _call_local_vision is the sole protection; that's fine.


def _local_vision_usable() -> bool:
    """True when the local VLM may serve a vision request.

    ONE predicate, used by BOTH the caller's capability gate and the callee's
    guard — they used to DISAGREE (2026-07-14 audit). _call_local_vision
    early-returned unless LOCAL_VISION_FALLBACK was on, but
    _vision_click_backend_available() (the gate) also accepts
    `model_route("vision") == "local"`. So an owner who set MODEL_ROUTING
    vision:"local" and left the FALLBACK knob at its default False got a
    capability gate that said YES and a vision call that silently returned
    None — every screen question answered "I couldn't see the screen", with
    nothing in the log. A route that explicitly SELECTS local vision is at
    least as strong a consent signal as the fallback flag."""
    if not LOCAL_VISION_MODEL or str(LOCAL_VISION_MODEL).strip().lower() == "off":
        return False
    if LOCAL_VISION_FALLBACK:
        return True
    try:
        import core.config as _cfg
        return _cfg.model_route("vision") == "local"
    except Exception:
        return False


def _call_local_vision(question: str, png_images: list[bytes],
                       max_tokens: int = 600) -> str | None:
    """POST a vision request to Ollama's /api/chat with one or more PNGs.

    Returns the assistant text on success, or None if local vision is
    disabled, Ollama isn't reachable, the VLM isn't pulled (a background
    pull is kicked off in that case), or the HTTP call fails. The caller
    is responsible for prepending the `[local-vision]` tag on success."""
    if not _local_vision_usable():
        return None
    if not png_images:
        return None
    if not _ollama_alive():
        _ollama_selfheal_async()   # mid-session death: restart in background
        _ollama_install_async()
        return None
    if not _ollama_has_model(LOCAL_VISION_MODEL):
        _ollama_pull_vision_async(LOCAL_VISION_MODEL)
        return None
    # VRAM brick guard (REVIEW_FINDINGS_2 P0-2/P0-3): if the big 30B-class brain
    # is already pinned in VRAM, loading the VLM on top co-loads a 2nd model and
    # over-commits the 24 GB card (CUDA-OOM bricks the GPU). The canonical fix is
    # OLLAMA_MAX_LOADED_MODELS=1 on the SERVER (Ollama then EVICTS the brain
    # instead of co-loading) — but that env is read by the server at ITS startup,
    # so on a server JARVIS didn't spawn it may not be applied yet. This runtime
    # guard protects regardless: refuse the local-vision load while the brain is
    # resident and let the caller speak its honest 'couldn't see' message. The
    # VLM tag itself is excluded, so a box where the VLM is ALREADY resident
    # (steady-state local-vision use) is never blocked. Power users with the
    # headroom to hold both can set JARVIS_ALLOW_VLM_COLOAD=1 to opt out.
    _allow_coload = (os.environ.get("JARVIS_ALLOW_VLM_COLOAD", "").strip().lower()
                     in ("1", "true", "yes", "on"))
    # ALREADY-RESIDENT EXEMPTION (2026-07-14 audit). Both gates below exist to
    # stop a SECOND model being co-loaded on top of the brain. But since the
    # v2.0.33 overhaul the shipped default is chat == vision == gemma4:12b — ONE
    # multimodal model serving both — so a vision call needs ZERO new VRAM: the
    # weights are already on the card. The free-VRAM gate does not know that; it
    # just sees a nearly-full 24GB card (whisper + chatterbox + the brain) and
    # refuses, so JARVIS says "I couldn't see the screen" while the very model it
    # needs is sitting loaded in front of it. Observed live in the 660-action
    # sweep: "REFUSING co-load: only 3976 MB free … for gemma4:12b" — with
    # gemma4:12b resident. If the VLM tag is already loaded, there is nothing to
    # co-load and nothing to guard against.
    _resident = _local_vision_model_already_resident()
    if not _allow_coload and _resident:
        _allow_coload = True
        print(f"  [local-vision] {LOCAL_VISION_MODEL} is ALREADY resident — no "
              f"co-load needed, VRAM gates skipped")
    if not _allow_coload:
        _resident_big = _ollama_big_model_resident(exclude_model=LOCAL_VISION_MODEL)
        if _resident_big:
            print(f"  [local-vision] REFUSING co-load: big model "
                  f"`{_resident_big}` is resident in VRAM — loading "
                  f"{LOCAL_VISION_MODEL} on top would over-commit the GPU "
                  f"(set OLLAMA_MAX_LOADED_MODELS=1 so Ollama evicts instead of "
                  f"co-loading, or JARVIS_ALLOW_VLM_COLOAD=1 to override).")
            return None
        # True-free-VRAM gate (2026-07-08): the Ollama residency check above is
        # blind to the ~6 GB of whisper + chatterbox pinned on cuda:0 by OTHER
        # frameworks, so on a 24 GB card it can green-light a VLM co-load that
        # over-commits. Read the DRIVER's real free counter and refuse whenever
        # it can't fit the VLM + headroom — regardless of which framework holds
        # the memory. None (probe unavailable) leaves the Ollama check as the
        # sole guard, preserving prior behaviour on non-NVIDIA / no-torch boxes.
        _free_mb = _cuda0_free_vram_mb()
        _need_mb = _VLM_COLOAD_NEEDED_MB + _VLM_COLOAD_HEADROOM_MB
        if _free_mb is not None and _free_mb < _need_mb:
            print(f"  [local-vision] REFUSING co-load: only {_free_mb} MB free "
                  f"on cuda:0 < {_need_mb} MB needed for {LOCAL_VISION_MODEL} "
                  f"(+headroom) — whisper/chatterbox/other frameworks hold the "
                  f"rest. Set JARVIS_ALLOW_VLM_COLOAD=1 to override.")
            return None
    _log_gpu_state(LOCAL_VISION_MODEL)
    try:
        b64_images = [base64.standard_b64encode(p).decode("utf-8") for p in png_images]
        payload = {
            "model": LOCAL_VISION_MODEL,
            "messages": [{
                "role": "user",
                "content": question,
                "images": b64_images,
            }],
            "stream": False,
            # num_ctx MUST be pinned here, and MUST match the value the chat
            # path sends (_local_num_ctx) — Ollama keys a loaded runner by
            # (model, options), so an options set that differs by so much as
            # the context length is a DIFFERENT runner: it EVICTS the warm one
            # and reloads the weights. Since the v2.0.33 overhaul chat and
            # vision are the SAME multimodal tag, so omitting num_ctx here made
            # every vision call silently reload the brain at the model's own
            # default context — 262144 for gemma4:26b-a4b. PROVEN live
            # 2026-07-21 (ollama server.log): `llama_context: n_ctx = 262144`,
            # `ollama ps` → `16 GB  6%/94% CPU/GPU  CONTEXT 262144`, the 3090
            # pinned at 24147/24576 MiB, and the next chat turn died on the 50 s
            # read timeout → "My local model isn't responding and I can't reach
            # the cloud either, sir." The ambient-extract daemon fires a vision
            # call every 300 s, so this bricked the local brain on a 5-minute
            # cycle. It also silently falsified the ALREADY-RESIDENT EXEMPTION
            # above, whose whole premise is that a vision call needs ZERO new
            # VRAM because the weights are already on the card — true only when
            # the runner is actually REUSED, which requires matching options.
            "options": {"num_predict": max_tokens,
                        "num_ctx": _local_num_ctx(LOCAL_VISION_MODEL)},
        }
        # Thinking-capable multimodal models (qwen3.x / gemma4) must not spend
        # seconds reasoning before describing a screen; pure VLMs (qwen2.5vl)
        # get no think param at all (400 otherwise).
        _think = _local_think_param(LOCAL_VISION_MODEL)
        if _think is not None:
            payload["think"] = _think
        # RESIDENCY-ADAPTIVE TIMEOUT (2026-07-14 audit). This was a flat
        # timeout=180 — and ask_vision runs on the MAIN VOICE THREAD for every
        # caller but _glance (which wraps it in its own 12 s bounded join). So a
        # wedged runner could mute JARVIS for three solid minutes: he'd stop
        # answering, stop hearing, and look dead. The 180 s only ever existed to
        # cover a COLD weight load (Ollama pulls the weights off disk on first
        # hit). Now that we can ask /api/ps whether the model is already loaded,
        # a warm call — the steady-state case — gets a bound sized to what a warm
        # 12B VLM actually costs (2-11 s measured on the 3090), with 5x headroom.
        # A cold load still gets the long rope, because there is nothing to do
        # but wait for the disk.
        _vis_timeout = (_LOCAL_VISION_TIMEOUT_WARM_S if _resident
                        else _LOCAL_VISION_TIMEOUT_COLD_S)
        r = requests.post(f"{LOCAL_LLM_BASE_URL}/api/chat", json=payload,
                          timeout=_vis_timeout)
        if not r.ok:
            print(f"  [local-vision] HTTP {r.status_code}: {r.text[:200]}")
            return None
        try:
            body = r.json()
        except ValueError as _je:
            print(f"  [local-vision] non-JSON response: {_je}; body={r.text[:200]!r}")
            return None
        msg = body.get("message")
        if not isinstance(msg, dict):
            print(f"  [local-vision] unexpected response shape (no message dict): keys={list(body.keys())}")
            return None
        text = (msg.get("content") or "").strip()
        if not text:
            print(f"  [local-vision] empty content; done_reason={body.get('done_reason')!r}")
            return None
        print(f"  [local-vision] served via {LOCAL_VISION_MODEL}")
        _vision_wedge_note_ok()
        return text
    except requests.RequestException as _e:
        print(f"  [local-vision] HTTP call failed: {_e}")
        # A TIMEOUT here (not a connection refusal) is the signature of a
        # VISION-WEDGED runner: the server still answers /api/tags and text
        # chat in ~1s while the multimodal path never returns. _ollama_alive()
        # therefore reads HEALTHY, so _ollama_selfheal_async's
        # _ensure_ollama_running() no-ops and nothing ever reaps the wedge —
        # it survived until a human killed ollama.exe by hand, TWICE
        # (2026-07-12 and 2026-07-13). Count consecutive timeouts and escalate
        # to a full reap+restart once the pattern is unmistakable.
        if isinstance(_e, requests.Timeout):
            _vision_wedge_note_timeout()
        return None


# ── ollama wedge detector (2026-07-14) ──────────────────────────────────────
# A wedged runner is INVISIBLE to _ollama_alive(): the server keeps answering
# /api/tags in milliseconds while every generate on the wedged path hangs, so
# _ensure_ollama_running() is a no-op and nothing ever reaps it — the failure
# survived until a human killed ollama.exe by hand, twice. Count consecutive
# timeouts PER PATH ("vision" | "text"); at the threshold, reap the whole stack
# (server + llama-server children) and let the self-heal bring it back — the
# manual fix that worked both times.
#
# ONE implementation, two paths (the text path had NO detector at all, and the
# chat route answers EVERY turn — the higher-impact of the two).
_WEDGE_STATE: dict[str, dict] = {
    "vision": {"timeouts": 0, "last_reap": 0.0},
    "text":   {"timeouts": 0, "last_reap": 0.0},
}
_WEDGE_THRESHOLD = 2                 # two consecutive timeouts = wedged
_WEDGE_REAP_COOLDOWN_S = 300.0


def _wedge_note_ok(path: str) -> None:
    """A successful call on `path` clears its wedge counter."""
    st = _WEDGE_STATE.get(path)
    if st is not None:
        st["timeouts"] = 0


def _wedge_note_timeout(path: str) -> None:
    """Count a timeout on `path`; reap the ollama stack at the threshold.

    Escalates to _reap_wedged_ollama() (kill ollama.exe + llama-server.exe)
    rather than _ensure_ollama_running(), which is a NO-OP while the server
    still answers /api/tags — exactly the state a wedge presents."""
    st = _WEDGE_STATE.get(path)
    if st is None:
        return
    st["timeouts"] += 1
    n = st["timeouts"]
    tag = "local-vision" if path == "vision" else "local-llm"
    if n < _WEDGE_THRESHOLD:
        print(f"  [{tag}] timeout {n}/{_WEDGE_THRESHOLD} — watching for a "
              f"wedged {path} runner")
        return
    now = time.time()
    if now - st["last_reap"] < _WEDGE_REAP_COOLDOWN_S:
        print(f"  [{tag}] wedge suspected but a reap ran recently — not "
              f"thrashing the server")
        return
    st["last_reap"] = now
    st["timeouts"] = 0

    def _do():
        try:
            print(f"  [{tag}] {path.upper()} WEDGE: {n} consecutive timeouts "
                  f"while the server answers /api/tags — reaping the ollama "
                  f"stack and restarting it")
            _reap_wedged_ollama()
            _ensure_ollama_running()
            # A reap kills BOTH runners, so neither path is still wedged.
            for other in _WEDGE_STATE.values():
                other["timeouts"] = 0
            print(f"  [{tag}] ollama stack restarted after the wedge")
        except Exception as _re:
            print(f"  [{tag}] wedge reap raised {type(_re).__name__}: {_re}")

    threading.Thread(target=_do, name=f"{path}-wedge-reap", daemon=True).start()


# Thin per-path aliases so call sites read clearly.
def _vision_wedge_note_ok() -> None:
    _wedge_note_ok("vision")


def _vision_wedge_note_timeout() -> None:
    _wedge_note_timeout("vision")


def _text_wedge_note_ok() -> None:
    _wedge_note_ok("text")


def _text_wedge_note_timeout() -> None:
    _wedge_note_timeout("text")


def _cached_system_param(full_prompt: str):
    """Split a per-turn system prompt into Anthropic content blocks so the big
    STABLE prefix is served from the prompt cache.

    Every conversation turn sends `_system_prompt` (the ~18-22k-token base +
    phrasebook + PC_CONTROL_PROMPT + memory build) plus a few hundred tokens of
    VOLATILE per-turn addenda (tone / voice-mood route / emotion / agent-mode).
    Without caching, Anthropic re-processes the whole thing at full input price
    and latency on EVERY turn. Splitting into

        [ {stable core,     cache_control: ephemeral},
          {memory section,  cache_control: ephemeral},
          {volatile tail} ]

    makes the prefix a cache hit on every turn after the first (~90% cheaper
    for those tokens, and a materially faster time-to-first-token). The cache
    is a strict prefix match, which is exactly why the volatile addenda MUST
    live in a separate trailing block — inside a single block they would
    invalidate the whole prefix whenever the tone/mode changed.

    TWO breakpoints (not one) because `_system_prompt` itself has two churn
    rates: the ambient-learning timer rebuilds it via
    build_system_prompt(load_memory()) after every learn, and with a single
    breakpoint a few hundred changed memory-fact tokens forced a full ~43k
    cache RE-WRITE. build_system_prompt records the stable-core/memory-section
    boundary in _system_prompt_stable_len; breaking there means fact-learning
    rebuilds re-cache only the small memory block while the big core (base
    prompt + standing rules + PC control + skill examples) stays a cache hit.
    Anthropic allows up to 4 breakpoints, so two here is safe.

    Defensive fallbacks: an unsane boundary (0, out of range, or a stable core
    below the worth-caching floor) degrades to the previous single-breakpoint
    split on the whole `_system_prompt`. Empty blocks are never emitted —
    Anthropic rejects empty text blocks — so an empty memory section yields two
    blocks and an empty tail is omitted, mirroring the old behavior.

    Returns the original string unchanged when it doesn't start with
    `_system_prompt` (defensive: a caller built something unusual) or when the
    prefix is too short to be worth a cache write (Anthropic silently ignores
    sub-minimum prefixes anyway, so the guard just avoids pointless structure).
    Callers on the OLLAMA/local path must keep using the plain string — this is
    Anthropic-API structure only.
    """
    base = _system_prompt
    if (isinstance(full_prompt, str) and isinstance(base, str)
            and len(base) >= 4000 and full_prompt.startswith(base)):
        stable_len = _system_prompt_stable_len[0]
        if isinstance(stable_len, int) and 4000 <= stable_len <= len(base):
            # Two-breakpoint split: stable core and memory section each get
            # their own cache entry so memory churn can't evict the core.
            blocks = [{"type": "text", "text": base[:stable_len],
                       "cache_control": {"type": "ephemeral"}}]
            mem_section = base[stable_len:]
            if mem_section:
                blocks.append({"type": "text", "text": mem_section,
                               "cache_control": {"type": "ephemeral"}})
        else:
            # Boundary unsane/stale (never recorded, or _system_prompt was
            # reassigned around build_system_prompt — shouldn't happen, but a
            # wrong slice would corrupt the prompt): fall back to the proven
            # single-breakpoint split over the whole stable prompt.
            blocks = [{"type": "text", "text": base,
                       "cache_control": {"type": "ephemeral"}}]
        tail = full_prompt[len(base):]
        if tail:
            blocks.append({"type": "text", "text": tail})
        return blocks
    return full_prompt


# ── Tiered long-term memory bridge (core/long_term_memory.py) ──────────────
# The LTM module (working / semantic / episodic tiers + reflector) was built
# and unit-tested in full but had ZERO production callers (2026-07-06 audit) —
# no turn was ever recorded and the tray's memory viewer read a file nothing
# wrote. This bridge wires it in with two rules:
#   * NEVER on the voice thread's critical path: recording goes through a
#     background queue worker; retrieval runs under a hard time budget and
#     simply contributes nothing when slow/cold.
#   * NEVER breaks prompt caching: retrieved facts are appended to the
#     VOLATILE system-prompt tail (see _cached_system_param), not the cached
#     stable prefix.
# Kill switch: LTM_ENABLED in core/config.py (user_settings.json overridable),
# plus the staging guard (test injects must not pollute real memory).
_ltm_queue: "queue.Queue[tuple[str, str]] | None" = None
_ltm_worker_started = [False]
_LTM_RETRIEVE_BUDGET_S = 0.6   # max wall-clock a turn will wait on recall
_LTM_RETRIEVE_K = 6


def _ltm_enabled() -> bool:
    try:
        from core.config import LTM_ENABLED as _flag
    except Exception:
        _flag = True
    if not _flag:
        return False
    return os.environ.get("JARVIS_STAGING", "").strip() != "1"


def _ltm_module():
    """Lazy import of core.long_term_memory. None when unavailable."""
    try:
        from core import long_term_memory as _ltm
        return _ltm
    except Exception:
        return None


def _ltm_boot_warm() -> None:
    """Warm the LTM store off the boot path: first-boot migration + index
    load can take seconds, so it runs on a daemon thread."""
    if not _ltm_enabled():
        return

    def _warm():
        ltm = _ltm_module()
        if ltm is None:
            return
        try:
            ltm.ensure_loaded()
            print("  [ltm] long-term memory loaded "
                  f"({len(ltm.list_facts() or [])} semantic fact(s))")
        except Exception as e:
            print(f"  [ltm] warm-up failed: {e}")
            return
        # Wire the reflector's contradiction adjudicator. reflect_and_
        # consolidate's contradiction pass was DEAD in production — its sole
        # caller (record_turn's every-50-turns trigger) passed llm_call=None,
        # so mid-band contradictions ('user's name is X' x7) were never
        # resolved (2026-07-21 audit #39). _llm_quick honours
        # AMBIENT_LEARNING_FORCE_LOCAL / model_route("ambient"), so
        # adjudication stays local-only/free, and returns "" on failure,
        # which the reflector treats as 'both facts stay'. Reflection runs
        # on the ltm-queue worker thread — never the voice thread.
        try:
            def _ltm_reflector_llm(prompt, ctx):
                return _llm_quick(
                    system=prompt,
                    user="\n".join(
                        f"{m.get('role', '')}: {m.get('text', '')}"
                        for m in (ctx or [])),
                    max_tokens=60,
                )
            ltm.set_reflector_llm(_ltm_reflector_llm)
        except Exception as e:
            print(f"  [ltm] reflector wiring failed: {e}")

    threading.Thread(target=_warm, name="ltm-warm", daemon=True).start()


def _ltm_worker_loop() -> None:
    while True:
        try:
            role, text = _ltm_queue.get()
        except Exception:
            return
        ltm = _ltm_module()
        if ltm is None:
            continue
        try:
            ltm.record_turn(role, text)
        except Exception as e:
            print(f"  [ltm] record_turn failed: {e}")


def _ltm_learn_facts(facts, projects=None) -> None:
    """Mirror newly-learned durable facts/projects into the SEMANTIC LTM store
    (chroma vectors + facts.json + BM25) via long_term_memory.add_fact, which
    embeds (bge-small) and upserts with its own exact-text dedupe. Fire-and-
    forget on a daemon thread; NEVER blocks merge_memory or raises into it.

    Closes the 2026-05-28 sync gap: merge_memory (store A, bobert_memory.json)
    and the semantic store were never wired together, so 97+ facts learned after
    migration day never became fuzzy-searchable. Gated on _ltm_enabled() (which
    also honours the JARVIS_STAGING guard) so blue/green test injects can't
    pollute the real store."""
    if not _ltm_enabled():
        return
    items = [(f, "learned") for f in (facts or [])] + \
            [(p, "project") for p in (projects or [])]
    items = [(t.strip(), tag) for (t, tag) in items
             if isinstance(t, str) and t.strip()]
    if not items:
        return
    ltm = _ltm_module()
    if ltm is None:
        return

    def _worker():
        for text, tag in items:
            try:
                ltm.add_fact(text, source="merge_memory", tags=[tag])
            except Exception as e:
                print(f"  [ltm] learn_fact failed: {e}")

    try:
        threading.Thread(target=_worker, name="ltm-learn", daemon=True).start()
    except Exception:
        pass


def _ltm_enqueue(role: str, text: str) -> None:
    """Queue one turn for background recording. Non-blocking, never raises."""
    global _ltm_queue
    if not _ltm_enabled() or not text or not text.strip():
        return
    try:
        if _ltm_queue is None:
            _ltm_queue = queue.Queue(maxsize=512)
        if not _ltm_worker_started[0]:
            _ltm_worker_started[0] = True
            threading.Thread(target=_ltm_worker_loop, name="ltm-writer",
                             daemon=True).start()
        _ltm_queue.put_nowait((role, text))
    except Exception:
        pass


def _ltm_context(user_text: str) -> str:
    """Top-k semantic facts relevant to this utterance, formatted as a
    system-prompt addendum — or '' when disabled, cold, or slow. The hard
    time budget means a cold embedder simply skips a turn or two while it
    loads in the background instead of stalling the voice loop."""
    if not _ltm_enabled() or not user_text or not user_text.strip():
        return ""
    ltm = _ltm_module()
    if ltm is None:
        return ""
    result: list = []
    done = threading.Event()

    def _fetch():
        try:
            result.extend(ltm.retrieve_facts(user_text, k=_LTM_RETRIEVE_K) or [])
        except Exception as e:
            print(f"  [ltm] retrieve failed: {e}")
        finally:
            done.set()

    threading.Thread(target=_fetch, name="ltm-recall", daemon=True).start()
    if not done.wait(timeout=_LTM_RETRIEVE_BUDGET_S):
        return ""
    lines = []
    for f in result[:_LTM_RETRIEVE_K]:
        t = (f.get("text") or "").strip() if isinstance(f, dict) else ""
        if t:
            lines.append(f"- {t[:300]}")
    if not lines:
        return ""
    return ("\n\n# RELEVANT LONG-TERM MEMORY (retrieved for this turn; use "
            "when helpful, ignore when not)\n" + "\n".join(lines))


# ── Sentence-flush streaming TTS ────────────────────────────────────────────
# Perceived-latency win: instead of sitting silent for the whole Claude
# completion, speak the FIRST complete, action-free sentence(s) as they
# stream (core/llm_client.stream_text was built with exactly this seam).
# Deliberately conservative rules, because early speech can't be un-said:
#   * only COMPLETE sentences flush ('.'/'!'/'?' followed by whitespace),
#     and a sentence must have ≥2 words — a bare "Sir." waits and rides
#     along with the next sentence instead of being voiced as a fragment;
#   * HARD STOP at the first '[': it may open an [ACTION:]/[intent:]/[wry]
#     marker, and only text STRICTLY BEFORE the first '[' is ever eligible
#     — the moment a '[' appears in the unflushed buffer, early speech is
#     over for this reply (the tail goes through the normal speak path,
#     which parses/strips those markers properly);
#   * at most 2 sentences flush early — the rest is one coherent utterance
#     via the normal path, so prosody isn't chopped into single lines.
# Kill switch: STREAMING_TTS_ENABLED in core/config.py (user_settings.json
# overridable). Everything in here is best-effort: a raise inside feed()
# is swallowed (stream_text also guards on_delta) so a TTS hiccup can
# never abort the stream.

# Exact text already sent to TTS by the flush buffer for the CURRENT reply.
# Reset at the top of every _call_llm; read by the downstream speaker
# (_strip_stream_spoken_prefix) so the already-voiced sentences aren't
# spoken twice. Single-element-list global, matching the _last_user_tone /
# _last_recording_peak idiom.
_stream_spoken_prefix = [""]

# Sentence boundary: terminal punctuation followed by whitespace. The
# trailing whitespace requirement means "3.5 GHz" or a mid-decimal '.'
# never splits, and an end-of-stream sentence with no trailing space
# simply doesn't flush early (the normal path speaks it — safe default).
_SENTENCE_BOUNDARY_RE = re.compile(r"[.!?](?:\s+)")


def _streaming_tts_enabled() -> bool:
    try:
        from core.config import STREAMING_TTS_ENABLED as _flag
    except Exception:
        _flag = True
    return bool(_flag)


class _SentenceFlushBuffer:
    """Accumulates streamed text chunks and speaks complete leading
    sentences early, per the rules in the section comment above.

    feed() is the stream_text on_delta callback — it must be cheap and must
    never raise, so the actual _speak() call is dispatched onto a daemon
    thread (chained: each flush thread joins its predecessor first, so two
    early sentences can never race each other out of order). join() lets
    _call_llm wait for the early speech to finish before the downstream
    path speaks the tail, keeping the whole reply in order."""

    MAX_EARLY_SENTENCES = 2   # flush cap — the tail rides the normal path

    def __init__(self, speak_fn=None):
        # None → resolve the monolith's _speak at dispatch time (it's
        # defined further down the file); tests inject a recorder.
        self._speak_fn = speak_fn
        self._buf = ""              # streamed text not yet flushed
        self._stopped = False       # latched on first '[' — never unlatched
        self._flushed = 0           # sentences flushed so far
        self._thread = None         # tail of the chained speak threads
        self.spoken_prefix = ""     # exact raw text ACTUALLY handed to TTS so far
        # Snapshot the accepted-barge counter at reply start. A later increment
        # means a wake-word barge-in was accepted DURING this reply, so the
        # chained flush threads skip their remaining early sentences (see
        # _dispatch). Snapshotted here rather than read live because the
        # _tts_interrupt Event is cleared before prev.join() returns. 2026-07-08.
        try:
            self._barge_seq0 = _tts_interrupt_seq[0]
        except Exception:
            self._barge_seq0 = 0

    def feed(self, chunk: str) -> None:
        """on_delta callback. Best-effort by contract — never raises."""
        try:
            if self._stopped or not chunk:
                return
            self._buf += chunk
            # Hard stop: a '[' anywhere in the unflushed buffer may be the
            # start of an action/prosody marker. Nothing at or after it is
            # eligible, and to keep the rule dead-simple nothing further
            # flushes at all once one is seen (already-flushed text stands).
            if "[" in self._buf:
                self._stopped = True
                return
            self._try_flush()
        except Exception:
            pass   # defensive belt on top of stream_text's own guard

    def _try_flush(self) -> None:
        while not self._stopped and self._flushed < self.MAX_EARLY_SENTENCES:
            end = None
            for m in _SENTENCE_BOUNDARY_RE.finditer(self._buf):
                # Require ≥2 words up to this boundary; a short fragment
                # ("Sir. ") waits and flushes together with the next
                # sentence as one piece.
                if len(self._buf[:m.end()].split()) >= 2:
                    end = m.end()
                    break
            if end is None:
                return
            piece = self._buf[:end]
            # Hallucinated-claim gate: parse_and_run_actions' preemptive
            # interceptor (_detect_preemptive_hallucination) runs AFTER the
            # stream completes — but by then an early-flushed sentence has
            # already been SPOKEN. A fabricated "running version 4.2.3" /
            # "it's 1:47 AM" in the opening sentence would be voiced before
            # the corrective [ACTION:] injection could replace it (live
            # near-miss 2026-07-07, saved only by a leading [intent:] tag).
            # So: any flush candidate matching a preemptive pattern latches
            # the same permanent stop as '[' — the whole reply rides the
            # normal path, where the interceptor speaks the TRUE value.
            try:
                if any(rx.search(piece) for rx, _a, _d
                       in _PREEMPTIVE_HALLUCINATION_PATTERNS):
                    self._stopped = True
                    return
            except Exception:
                self._stopped = True   # fail closed: don't early-speak
                return
            self._buf = self._buf[end:]
            self._flushed += 1
            # Pass the RAW piece (not .strip()) so spoken_prefix — accumulated in
            # _dispatch only for sentences actually voiced — stays an exact
            # leading substring of the reply for _strip_stream_spoken_prefix.
            self._dispatch(piece)

    def _dispatch(self, piece: str) -> None:
        """Speak one flushed sentence off-thread. Chained on the previous
        flush thread so playback order matches text order."""
        sentence = piece.strip()
        if not sentence:
            return
        prev = self._thread
        speak_fn = self._speak_fn
        seq0 = self._barge_seq0

        def _run():
            try:
                if prev is not None:
                    prev.join(timeout=60)
                # If the user BARGED IN (a wake-word hit cut the prior sentence
                # via the tts-reaper's stream.abort(), which unblocks
                # prev.join above), do NOT speak the
                # next chained early sentence — honour the interrupt instead of
                # blurting one more line the user talked over. Compare the
                # monotonic accepted-barge counter to the snapshot taken at reply
                # start: _tts_interrupt.is_set() was ALWAYS False here (the Event
                # is cleared by the cut sentence's _speak/play_with_lipsync finally
                # BEFORE prev.join() returns), which made the old guard dead code.
                # 2026-07-07 intent; 2026-07-08 made functional.
                try:
                    if _tts_interrupt_seq[0] != seq0:
                        return
                except Exception:
                    pass
                fn = speak_fn if speak_fn is not None else _speak
                _spoke = fn(sentence)
                # Record as spoken ONLY after actually dispatching to TTS: a
                # skipped (barged-in) or TTS-failed sentence must NOT be stripped
                # from the downstream tail (which would silently DROP it) — it
                # rides the normal speak path instead. 2026-07-08. _speak now
                # returns False when playback FAILED (2026-07-14 #18); `is not
                # False` so a custom speak_fn returning None still counts as
                # spoken (prior behaviour).
                if _spoke is not False:
                    self.spoken_prefix += piece
            except Exception:
                pass   # early speech is a bonus — never let it propagate

        t = threading.Thread(target=_run, name="stream-tts-flush", daemon=True)
        self._thread = t
        t.start()

    def join(self, timeout: float = 60.0) -> None:
        """Wait for the chained speak threads to drain (bounded), so the
        downstream tail speech can't start mid-early-sentence."""
        t = self._thread
        if t is not None:
            try:
                t.join(timeout=timeout)
            except Exception:
                pass


def _strip_stream_spoken_prefix(text: str) -> str:
    """Remove the early-spoken prefix (this reply's flush-buffer output)
    from the downstream spoken text, so those sentences aren't voiced twice.
    Also tries the rstrip'd prefix because parse_and_run_actions may have
    trimmed trailing whitespace. A non-matching prefix (e.g. the stream
    failed over to complete() and produced different text) leaves the text
    untouched — worst case is a rare repeat, never a dropped sentence."""
    try:
        prefix = _stream_spoken_prefix[0]
        if not prefix or not text:
            return text
        for p in (prefix, prefix.rstrip()):
            if p and text.startswith(p):
                return text[len(p):].lstrip()
        return text
    except Exception:
        return text


def _call_llm(user_text: str) -> str:
    # New reply, new early-speech ledger: whatever the flush buffer voiced
    # last turn was already consumed by the downstream speaker, and a stale
    # prefix must never strip text from THIS turn's reply.
    _stream_spoken_prefix[0] = ""
    conversation_history.append({"role": "user", "content": user_text})
    # Trim BEFORE the API request, not just after (line ~9750). A boot-time /
    # follow-up-loop assistant-only append can leave conversation_history
    # LEADING with an 'assistant' message; sending that to Claude 400s ('first
    # message must use the user role') and the whole first turn degrades to
    # local. _trim_conversation_history drops leading non-'user' messages, so
    # running it here guarantees the very first request is well-formed. 2026-07-08.
    _trim_conversation_history()
    _ltm_enqueue("user", user_text)

    # Classify mood from this utterance and (if non-default) extend the
    # system prompt for this single turn. Cache the label so the follow-up
    # call stays in the same register without re-running the detector.
    # Guarded to a neutral default on any raise — like the voice-mood /
    # emotion-tracker / mode-router adapters below — so a classifier glitch
    # degrades the register for this turn instead of crashing the LLM turn
    # (which the unguarded main loop would turn into a full crash).
    try:
        tone = detect_tone(user_text)
    except Exception as _tone_err:
        print(f"  [tone] classifier failed: {_tone_err}")
        tone = None
    _last_user_tone[0] = tone
    _last_user_text[0] = user_text
    if tone:
        print(f"  [tone] {tone}")

    # Voice emotion router: fuses text-tone with time-of-day into a single
    # mood label and emits a per-turn system-prompt addendum (reply length
    # + register). TTS prosody for the same mood is picked downstream by
    # synthesise() via _USER_TONE_TTS. Cached so the follow-up call stays
    # in the same register without re-classifying. Same neutral-default guard
    # as the tone classifier above.
    try:
        route = route_voice_emotion(user_text)
    except Exception as _route_err:
        print(f"  [voice-mood] router failed: {_route_err}")
        route = {"mood": "casual", "addendum": ""}
    _last_voice_route[0] = route
    if route["mood"] != "casual":
        print(f"  [voice-mood] {route['mood']}")

    # Voice-mood response: closes the loop on a 'stressed' label by
    # suppressing proactive nudges for 15 min, dimming Hue/Govee lights to
    # warm 2700K on a daemon thread, and returning an extra-deferential
    # addendum to stack onto sys_prompt_now. Returns '' for every other
    # mood so non-stressed turns are unchanged.
    voice_mood_addendum = ""
    if _voice_mood_response is not None:
        try:
            voice_mood_addendum = _voice_mood_response.apply_voice_mood_response(
                route,
                user_text,
                memory_lock=_memory_lock,
                load_memory=load_memory,
                save_memory=save_memory,
            )
        except Exception as _vm_err:
            print(f"  [voice-mood] response adapter failed: {_vm_err}")

    # Five-label emotion tracker (core/emotion_tracker). Adds a 'focused'
    # bucket the legacy detector lacks and maps each label to a TTS preset
    # (stressed→calm, excited→amused, focused→briefing, tired→concerned).
    # Its addendum stacks on top of detect_tone()'s — they overlap on the
    # shared labels but emphasise different facets of the response strategy.
    emotion_addendum = ""
    if _emotion_tracker is not None:
        try:
            er = _emotion_tracker.classify_emotion(user_text)
            _last_emotion[0] = er
            if er and er.label:
                print(f"  [emotion] {er.label} ({er.reason})")
                # Only stack the new addendum when its label differs from
                # what detect_tone already covered — avoids duplicating the
                # same directive twice in the system prompt.
                if er.label != tone:
                    emotion_addendum = er.addendum
        except Exception as _err:
            print(f"  [emotion-tracker] failed: {_err}")
            _last_emotion[0] = None
    else:
        _last_emotion[0] = None

    # Agent-mode addendum: when the user is in agent mode, extend the
    # system prompt with a PLAN→EXECUTE→CRITIQUE→REPORT directive so the
    # LLM iterates autonomously rather than stopping after one step.
    # Empty string in smart/controlled mode, so this is a no-op for the
    # default path.
    mode_addendum = ""
    try:
        from core.mode_router import system_prompt_addendum as _mode_addendum
        mode_addendum = _mode_addendum()
    except Exception:
        pass

    from core.config import model_route
    _chat_route = model_route("chat")

    # DYNAMIC LOCAL PROMPT: on the local path, swap the full PC_CONTROL block for
    # a per-turn slim version (only the sections this text implicates) so the
    # ~30k prompt fits the 12-16k local context UNCUT instead of being truncated.
    # Cloud/Claude keeps the full prompt (200k ctx, no truncation). One string
    # replace on the cached _system_prompt — the BASE identity, rules, phrasebook
    # and memory around it are untouched. 2026-07-15.
    _prof("prompt_start")
    _base_prompt = _system_prompt
    # Per-turn material that must NOT sit in the cached prefix on the local
    # route. Empty string = legacy behaviour (everything in the system prompt).
    _turn_ctx = ""
    _stable_split = False
    if (_chat_route == "local" and _DYNAMIC_LOCAL_PROMPT and _STABLE_LOCAL_PREFIX
            and PC_CONTROL_PROMPT and PC_CONTROL_PROMPT in _system_prompt):
        # CACHE-STABLE SPLIT — see _STABLE_LOCAL_PREFIX. The system prompt keeps
        # the guard + PC core preamble (action grammar + safety rules) + an
        # index of every capability, all byte-identical turn to turn; only the
        # section BODIES this turn implicates move to the user message.
        try:
            from core import prompt_router as _pr
            _stable_pc = (_LOCAL_NEVER_GUESS_GUARD + "\n"
                          + _pr.stable_pc_block(PC_CONTROL_PROMPT))
            _base_prompt = _system_prompt.replace(
                PC_CONTROL_PROMPT, _stable_pc, 1)
            _turn_ctx = _pr.turn_pc_block(user_text, PC_CONTROL_PROMPT)
            _stable_split = True
        except Exception as _pr_err:
            print(f"  [prompt-router] stable split failed ({_pr_err}); "
                  f"full prompt")
            _base_prompt = _system_prompt
            _turn_ctx = ""
            _stable_split = False
    elif (_chat_route == "local" and _DYNAMIC_LOCAL_PROMPT
            and PC_CONTROL_PROMPT and PC_CONTROL_PROMPT in _system_prompt):
        try:
            from core import prompt_router as _pr
            _slim_pc = _pr.slim_pc_control(user_text, PC_CONTROL_PROMPT)
            # slim_pc_control keeps PC_CONTROL's own preamble but NOT the local
            # anti-hallucination guard (the highest-value instruction on this
            # path). _local_cheatsheet has it; this path did not — restore it
            # from the single shared source so weather/version/whats_broken stop
            # getting hedged or fabricated on the default local route.
            _slim_pc = _LOCAL_NEVER_GUESS_GUARD + "\n" + _slim_pc
            _base_prompt = _system_prompt.replace(PC_CONTROL_PROMPT, _slim_pc, 1)
        except Exception as _pr_err:
            print(f"  [prompt-router] slim failed ({_pr_err}); full prompt")
            _base_prompt = _system_prompt

    _turn_addenda = (
        _tone_system_addendum(tone)
        + route["addendum"]
        + emotion_addendum
        + mode_addendum
        + voice_mood_addendum
        # Per-turn semantic recall from tiered long-term memory. Lives in the
        # VOLATILE tail so it never invalidates the cached stable prefix
        # (see _cached_system_param); '' when disabled / cold / slow.
        + _ltm_context(user_text)
    )

    if _stable_split:
        # Cache-stable layout: the system prompt is byte-identical every turn,
        # so EVERY per-turn addendum has to travel with the user message too —
        # a 300-char tone hint spliced onto the system prompt costs exactly as
        # much cache as a 6,800-token PC block does.
        sys_prompt_now = _base_prompt
        # Stash the BODIES alone (before the addenda are folded in, so the
        # follow-up doesn't get the tone hint twice — it recomputes its own).
        # See _last_turn_pc_block: without this the follow-up round loses the
        # action reference entirely.
        _last_turn_pc_block[0] = _turn_ctx
        _turn_ctx = _turn_ctx + _turn_addenda
    else:
        sys_prompt_now = _base_prompt + _turn_addenda
        _turn_ctx = ""
        _last_turn_pc_block[0] = ""
    # Remember the split so the follow-up round (get_followup_response) can
    # re-use the very same cached system prompt instead of rebuilding a
    # different one and paying a second full prompt evaluation. (It used to
    # build from the FULL _system_prompt, which _call_local_llm then swapped
    # for the 21k-char static cheatsheet — a completely different prefix, so
    # every action chain paid a second ~3 s prompt eval AND left the next
    # turn's prefix cold.)
    _last_stable_sys_prompt[0] = sys_prompt_now if _stable_split else ""

    _prof("prompt_end", f"sys={len(sys_prompt_now)} ctx={len(_turn_ctx)}")
    if _chat_route == "local":
        # LOCAL-routed turn: local model is primary. On local failure, fall
        # back to Claude if reachable, else speak an HONEST unavailability line
        # (SAC-specific when we have evidence) — never a fabricated answer and
        # never a silent freeze (the generate read-timeout trips the fallback).
        reply = _local_then_cloud_or_honest(
            sys_prompt_now, _with_turn_context(conversation_history, _turn_ctx))
    elif AI_BACKEND == "claude":
        import anthropic
        try:
            # Cache-split system param: stable prefix cached, per-turn addenda
            # in a trailing uncached block. See _cached_system_param.
            _sys_param = _cached_system_param(sys_prompt_now)
            if _llm_client is not None:
                if _streaming_tts_enabled():
                    # Sentence-flush streaming TTS: speak the first complete,
                    # action-free sentence(s) while the rest still streams
                    # (see _SentenceFlushBuffer). The downstream speaker
                    # strips _stream_spoken_prefix so nothing is said twice.
                    _flush_buf = _SentenceFlushBuffer()
                    try:
                        reply = _llm_client.stream_text(
                            model=CLAUDE_MODEL, max_tokens=500,
                            system=_sys_param, messages=conversation_history,
                            timeout=_ANTHROPIC_TIMEOUT_S,
                            on_delta=_flush_buf.feed,
                        )
                    except Exception as _stream_err:
                        # Stream failed mid-flight (network blip, SDK quirk).
                        # Fall back to the blocking call ONCE — its anthropic.*
                        # exceptions propagate to the handlers below with the
                        # exact same semantics as before this feature. Any
                        # sentences already voiced stay on the ledger so the
                        # prefix-strip can still dedupe if the retry happens
                        # to produce the same opening (a mismatch just means
                        # a rare repeat, never a dropped sentence).
                        print(f"  [stream-tts] stream failed, falling back "
                              f"to complete(): {_stream_err}")
                        _flush_buf.join()
                        _stream_spoken_prefix[0] = _flush_buf.spoken_prefix
                        reply = _llm_client.complete(
                            model=CLAUDE_MODEL, max_tokens=500,
                            system=_sys_param, messages=conversation_history,
                            timeout=_ANTHROPIC_TIMEOUT_S,
                        )
                    else:
                        # Let the early sentences finish before the caller
                        # speaks the tail — keeps the reply in order (the
                        # chained flush threads serialise among themselves;
                        # this serialises them against the downstream path).
                        _flush_buf.join()
                        _stream_spoken_prefix[0] = _flush_buf.spoken_prefix
                else:
                    reply = _llm_client.complete(
                        model=CLAUDE_MODEL, max_tokens=500,
                        system=_sys_param, messages=conversation_history,
                        timeout=_ANTHROPIC_TIMEOUT_S,
                    )
            else:
                msg = _anthropic_client().messages.create(
                    model=CLAUDE_MODEL, max_tokens=500,
                    system=_sys_param,
                    messages=conversation_history,
                )
                reply = msg.content[0].text
        except anthropic.BadRequestError as _e:
            _s = str(_e).lower()
            if "credit balance" in _s or "too low" in _s or "upgrade or purchase" in _s:
                reply = _local_fallback_or(
                    sys_prompt_now,
                    "I'm afraid my API credits have run out, sir. "
                    "Please top up the balance at console.anthropic.com "
                    "to bring me back online.",
                )
            elif ("usage limit" in _s or "regain access" in _s
                  or "monthly limit" in _s or "spend limit" in _s
                  or "quota" in _s or "exceeded" in _s
                  or "reached your" in _s or "rate limit" in _s):
                reply = _local_fallback_or(
                    sys_prompt_now,
                    "I've reached the monthly API usage limit, sir. "
                    "Access will be restored automatically once the limit resets.",
                )
            else:
                # Unrecognised 4xx — the cloud API is unavailable for this
                # request regardless of the reason, so fall back to the local
                # LLM and only surface the raw error if the fallback fails.
                reply = _local_fallback_or(
                    sys_prompt_now,
                    f"API request rejected (400): {_e}",
                )
        except anthropic.RateLimitError:
            reply = _local_fallback_or(
                sys_prompt_now,
                "I'm being rate-limited by the API, sir — "
                "please give it a moment and try again.",
            )
        except anthropic.APIStatusError as _e:
            reply = _local_fallback_or(
                sys_prompt_now,
                f"API error {_e.status_code}: {_e.message}",
            )
        except Exception as _e:
            reply = _local_fallback_or(
                sys_prompt_now,
                f"Unexpected LLM error: {_e}",
            )

    elif AI_BACKEND == "ollama":
        # Mirror the claude branch's guard: a dead/unreachable Ollama server
        # (or a missing model) must NOT propagate out of _call_llm. The outer
        # main loop only catches KeyboardInterrupt, so an unguarded raise here
        # would crash the whole conversation loop. 2026-05-30 audit.
        try:
            # Bounded (see _ollama_chat_bounded): a wedged runner raises rather
            # than blocking the voice thread forever; the except below degrades.
            # RESOLVE the model, never trust the raw OLLAMA_MODEL constant: its
            # shipped default is still the retired "llama3" tag, so an owner who
            # picks "Primary AI backend = ollama" got a 404 on EVERY turn while
            # every OTHER local call (_call_local_llm) correctly resolved
            # gemma4:12b. The local-only backend was dead on arrival
            # (2026-07-14 audit). _get_local_llm_model() is the single resolver.
            resp = _ollama_chat_bounded(
                _get_local_llm_model(),
                [{"role": "system", "content": sys_prompt_now}] + conversation_history,
            )
            reply = resp["message"]["content"]
        except Exception as _e:
            print(f"  [ollama] chat failed: {_e}")
            # Route through the instrumented local fallback like the claude
            # branch and the two sibling call sites, not a dead-end string.
            # _local_fallback_or → _call_local_llm, which carries the ollama
            # SELF-HEAL + wedge-reap machinery _ollama_chat_bounded alone does
            # not trigger — so a wedged/killed runner gets restarted and retried
            # instead of the user just hearing "Ollama may be down". If the
            # local model still can't answer, the honest default is spoken.
            # 2026-07-14 bug-hunt.
            reply = _local_fallback_or(
                sys_prompt_now,
                "I'm afraid my local model isn't responding, sir — "
                "Ollama may be down. Please check it and try again.",
            )

    else:
        reply = "AI backend not configured. Check AI_BACKEND in the script."

    _prof("reply_ready", reply[:40].replace("\t", " "))
    conversation_history.append({"role": "assistant", "content": reply})
    _ltm_enqueue("assistant", reply)

    # Update phrasebook rotation state — scan the reply for any canonical MCU
    # lines and record them in memory so the next turn's system prompt asks
    # the LLM to rotate to a different phrase in each matched intent bucket.
    try:
        hits = _mcu_phrases.detect_phrases_in_reply(reply)
        if hits:
            with _memory_lock:
                _mem = load_memory()
                _last = _mem.setdefault("last_used_phrase_by_intent", {})
                _last.update(hits)
                save_memory(_mem)
    except Exception as _phr_err:
        print(f"  [phrase-rotation] update failed: {_phr_err}")

    # Keep history bounded — see _trim_conversation_history (trims in pairs so
    # the first message stays 'user', as the Claude API requires).
    _trim_conversation_history()

    return reply


# ──────────────────────────────────────────────────────────────────────────
#  TEXT-TO-SPEECH  (edge-tts, falls back to pyttsx3 if offline)
# ──────────────────────────────────────────────────────────────────────────

# Emotion-aware TTS prosody presets (_TTS_EMOTION_PRESETS), the [intent:xxx]→
# preset map (_INTENT_PRESETS), the user-tone→preset map (_USER_TONE_TTS), the
# text-keyword classifier (detect_tts_emotion + _TTS_EMOTION_KEYWORDS), and the
# priority resolver now live in core/tts.py (consolidated so the edge-tts
# (rate, pitch, gain) triples sit in one module). They're re-exported at the
# top-of-file `from core.tts import (...)` so the references below still resolve
# off this namespace; _resolve_tts_preset() further down is a thin shim that
# feeds the live _last_* state into core.tts.resolve_tts_preset().

# _INTENT_PRESETS (the [intent:xxx]→preset-name map) moved to core/tts.py and
# is re-exported at the top of this file; _parse_intent_tag() below reads it.

# Slot for the most-recent parsed [intent:xxx] tag. Set by _parse_intent_tag()
# inside _speak() right before synthesise() is called, read by
# _resolve_tts_preset(), then cleared. Mirrors the _last_user_tone /
# _last_voice_route pattern so synthesise() can pick it up without changing
# the call signature.
_last_intent_override: list[str | None] = [None]

# Slot for the [wry] marker. When True, _resolve_tts_preset() returns the
# 'wry' preset (overrides intent/emotion/tone for this line) and synthesise()
# inserts a short beat before the punchline. Set in _speak() via
# core.tts.parse_wry_tag(), cleared in the same finally block.
_last_wry: list[bool] = [False]

# Slot for the voice_mood layer (core/voice_mood_selector). Carries a mood
# name (calm_efficient / urgent_clipped / dry_amused / concerned_soft) when
# the caller passed mood= to _speak(), or when [mood:xxx] was parsed off the
# leading tag. Read by _resolve_tts_preset() between the [intent:xxx]
# override and the emotion-tracker fallback so explicit intents still win.
_last_mood: list[str | None] = [None]

# Match a leading [mood:xxx] tag, same shape as [intent:xxx]. Skills that
# return text via the dispatcher (chappie recall, banter quips) can opt
# into a mood without holding a reference to _speak(); the tag is parsed in
# _speak() and forwarded into _last_mood for the synthesise() turn.
_MOOD_TAG_RE = re.compile(r"^\s*\[\s*mood\s*:\s*([a-z_][a-z0-9_]*)\s*\]\s*", re.IGNORECASE)

_VOICE_MOOD_NAMES: frozenset[str] = frozenset({
    "calm_efficient", "urgent_clipped", "dry_amused", "concerned_soft",
})


def _parse_mood_tag(text: str) -> tuple[str | None, str]:
    """If `text` starts with [mood:xxx], return (mood_name_if_known, stripped).
    Unknown mood names are still stripped from the spoken text but resolve
    to None so they fall through to the rest of the priority chain."""
    if not text:
        return None, text
    m = _MOOD_TAG_RE.match(text)
    if not m:
        return None, text
    raw = m.group(1).lower().strip()
    stripped = text[m.end():]
    if raw in _VOICE_MOOD_NAMES:
        return raw, stripped
    return None, stripped

# Match a leading [intent:xxx] tag (case-insensitive, allowing surrounding
# whitespace). Anchored to the start because the LLM is instructed to lead
# replies with it. The pattern is permissive on the intent name so unknown
# values still get stripped from the spoken text rather than read aloud.
_INTENT_TAG_RE = re.compile(r"^\s*\[\s*intent\s*:\s*([a-z_][a-z0-9_]*)\s*\]\s*", re.IGNORECASE)


def _parse_intent_tag(text: str) -> tuple[str | None, str]:
    """If `text` starts with [intent:xxx], return (intent_name, text_with_tag_stripped).
    Otherwise return (None, text). Unknown intents are still stripped from
    the text — we never want a literal '[intent:foo]' to be spoken aloud —
    but the returned intent will be None, falling back to the existing
    tone/keyword routing."""
    if not text:
        return None, text
    m = _INTENT_TAG_RE.match(text)
    if not m:
        return None, text
    raw = m.group(1).lower().strip()
    stripped = text[m.end():]
    if raw in _INTENT_PRESETS:
        return raw, stripped
    return None, stripped

# _USER_TONE_TTS (user-tone→preset map), the text-keyword classifier
# detect_tts_emotion() and its _TTS_EMOTION_KEYWORDS table all moved to
# core/tts.py and are re-exported at the top of this file.


def _resolve_tts_preset(text: str, user_tone: str | None) -> tuple[str, dict[str, object]]:
    """Thin state-supplying shim around core.tts.resolve_tts_preset().

    The pure preset-priority logic lives in core/tts.py; this reads the live
    runtime singletons it needs (_last_wry / _last_intent_override / _last_mood
    / _last_user_text / _last_emotion) plus the recent vocal RMS and forwards
    them as arguments. Kept at this 2-arg (text, user_tone) signature so the
    synthesise() call site AND the night_owl_mode monkeypatch (which wraps
    bobert_companion._resolve_tts_preset) keep working unchanged.
    """
    if _tts_layer is None:
        # core.tts failed to import — flat neutral prosody keeps JARVIS talking.
        return "neutral", {"rate": "+0%", "pitch": "+0Hz", "gain": 1.0}

    try:
        from core.audio_processor import recent_peak_rms as _recent_peak_rms
        peak_rms = float(_recent_peak_rms())
    except Exception:
        peak_rms = 0.0

    er = _last_emotion[0]
    emotion_preset = getattr(er, "tts_preset", None) if er is not None else None

    return _tts_layer.resolve_tts_preset(
        text,
        user_tone,
        wry=_last_wry[0],
        intent_override=_last_intent_override[0],
        mood=_last_mood[0],
        user_text=_last_user_text[0],
        peak_rms=peak_rms,
        emotion_preset=emotion_preset,
    )


def _rate_to_speed(rate: str) -> float:
    """Map an edge-tts style rate string ('-15%'…'+15%') to a Kokoro speed
    multiplier (0.85…1.15). Kokoro's create() takes a float speed instead of a
    percentage, so this is the bridge that lets the prosody presets drive the
    kokoro backend too (2026-07-21 audit: the preset rate was computed, logged,
    then thrown away on kokoro). Fail-closed: any malformed value maps to 1.0
    so a bad preset can never mute or distort speech; clamped to [0.5, 2.0]."""
    try:
        pct = float(str(rate).strip().rstrip("%"))
    except (TypeError, ValueError):
        return 1.0
    return max(0.5, min(2.0, 1.0 + pct / 100.0))


async def _tts_bytes(text: str, rate: str = "+0%", pitch: str = "+0Hz") -> bytes:
    import edge_tts
    buf = io.BytesIO()
    async for chunk in edge_tts.Communicate(text, TTS_VOICE, rate=rate, pitch=pitch).stream():
        if chunk["type"] == "audio":
            buf.write(chunk["data"])
    buf.seek(0)
    return buf.read()


# Persistent asyncio loop in a background thread so each TTS call doesn't
# spin up + tear down its own loop.
_tts_loop: asyncio.AbstractEventLoop | None = None
_tts_loop_thread: "threading.Thread | None" = None
_TTS_LOOP_LOCK = threading.Lock()


def _ensure_tts_loop():
    global _tts_loop, _tts_loop_thread
    # Lock the entire check-and-assign so two threads racing through here
    # cannot both observe None and both create a new loop (which would
    # leak the first loop's selector + aiohttp connectors).
    with _TTS_LOOP_LOCK:
        # Recreate unless the loop is running AND its background thread is
        # still alive. is_running() ALONE misses the case where the loop
        # thread died while the loop object still reports running — then every
        # run_coroutine_threadsafe() hangs at its 30s timeout forever and TTS
        # goes mute with no recovery. Track + check the thread. 2026-05-30 audit.
        if (_tts_loop is not None and _tts_loop.is_running()
                and _tts_loop_thread is not None and _tts_loop_thread.is_alive()):
            return
        # Best-effort: stop a half-dead old loop before replacing it so we
        # don't leak its selector/connectors.
        if _tts_loop is not None:
            try:
                _tts_loop.call_soon_threadsafe(_tts_loop.stop)
            except Exception:
                pass
        _tts_loop = asyncio.new_event_loop()
        _tts_loop_thread = threading.Thread(target=_tts_loop.run_forever, daemon=True)
        _tts_loop_thread.start()


def _render_edge_tts(text: str, rate: str, pitch: str) -> tuple[np.ndarray, int]:
    """Render `text` through edge-tts and decode to a mono float32 buffer.
    Separated from synthesise() so the wry path can call it twice (setup,
    punchline) with a silence gap spliced between.

    Transient Bing WebSocket errors (503, handshake, network blips) get up
    to 3 attempts with 0.5/1/2-second backoff before propagating. Non-
    transient failures (ImportError, bad text) raise immediately.

    Repeated short phrases are served from the core.tts render cache, skipping
    the network round-trip entirely. The cache key is the PRE-gain (voice,
    rate, pitch, text) tuple; synthesise() re-applies per-mood gain after."""
    if _tts_layer is not None:
        try:
            _cached = _tts_layer.tts_cache_get(text, TTS_VOICE, rate, pitch)
        except Exception:
            _cached = None
        if _cached is not None:
            return _cached
    _ensure_tts_loop()
    for attempt in range(3):
        try:
            fut = asyncio.run_coroutine_threadsafe(_tts_bytes(text, rate=rate, pitch=pitch), _tts_loop)
            raw = fut.result(timeout=30)
            audio, sr = sf.read(io.BytesIO(raw), dtype="float32")
            if audio.ndim > 1:
                audio = audio.mean(axis=1)
            if _tts_layer is not None:
                try:
                    _tts_layer.tts_cache_put(text, TTS_VOICE, rate, pitch, audio, sr)
                except Exception:
                    pass
            return audio, sr
        except Exception as e:
            err_str = str(e).lower()
            transient = any(s in err_str for s in (
                "503", "handshake", "timeout", "timed out", "connection",
                "websocket", "wsserver", "temporarily", "reset",
            ))
            if isinstance(e, ImportError) or not transient or attempt == 2:
                raise
            backoff = 0.5 * (2 ** attempt)  # 0.5s, 1.0s, 2.0s
            print(f"  [tts] edge-tts attempt {attempt + 1}/3 failed ({type(e).__name__}: {e}); retrying in {backoff:.1f}s")
            time.sleep(backoff)
    raise RuntimeError("unreachable")  # pragma: no cover  (loop always returns or raises)


def _silent_clip(sr: int = 24000, ms: int = 80) -> tuple[np.ndarray, int]:
    """Return a tiny silent buffer so callers that expect (audio, sr) can
    keep going when every TTS backend has failed. 24 kHz mirrors edge-tts'
    native output so the downstream sample-rate path doesn't change."""
    samples = max(1, int(sr * ms / 1000))
    return np.zeros(samples, dtype=np.float32), sr


def _render_xtts_or_raise(text: str, rate: str, pitch: str) -> tuple[np.ndarray, int]:
    """Render `text` via skills/custom_voice.py (Coqui XTTS-v2). Raises on
    any failure so the caller can fall back to edge-tts. Looked up via
    sys.modules so the skill is optional — if it isn't loaded yet we raise
    the same way as a normal render failure and the fallback path engages."""
    mod = sys.modules.get("skill_custom_voice")
    if mod is None:
        raise RuntimeError("custom_voice skill not loaded")
    return mod.render(text, rate, pitch)


# Hard wall-clock cap on a voice-clone render (see the clone block in synthesise).
# Generous enough for Chatterbox's first-run cold start (model download + CUDA
# load), then we abandon it and fall through to the edge-tts ladder so a hang can
# never leave JARVIS mute. 2026-07-07 review.
_VOICE_CLONE_TIMEOUT_S = 20.0
# SINGLE-FLIGHT GUARD (2026-07-08, MED). On a clone TIMEOUT we ABANDON the daemon
# worker but it keeps running its Chatterbox model load / generate. core.voice_clone
# has NO internal lock, so a second worker spawned by the next utterance would run a
# CONCURRENT ChatterboxTTS.from_pretrained (N× VRAM cold-loads during a multi-minute
# cold start) or a concurrent model.generate on the shared cached model (unsafe CUDA
# forward pass). True while ANY clone worker is in flight (incl. an abandoned one);
# the worker's finally clears it when it actually finishes, so a fresh worker can
# start once the previous one truly returns. While set, the clone is skipped and the
# utterance uses the normal edge-tts ladder (JARVIS still speaks).
_voice_clone_inflight = [False]
_voice_clone_inflight_lock = threading.Lock()


def synthesise(text: str) -> tuple[np.ndarray, int]:
    # Voice-mood router output wins over raw detect_tone() output here:
    # the router fuses tone with time-of-day, so its label is the one
    # that should drive prosody. Fall back to the fine-grained text tone
    # (rushed/tired/playful/frustrated) when the router said 'casual'.
    try:
        route = _last_voice_route[0]
        mood = route["mood"] if route else "casual"
        user_tone = mood if mood != "casual" else _last_user_tone[0]
        chosen, preset = _resolve_tts_preset(text, user_tone)
        rate  = str(preset.get("rate",  "+0%"))
        pitch = str(preset.get("pitch", "+0Hz"))
        gain  = float(preset.get("gain", 1.0))  # type: ignore[arg-type]
        if chosen != "neutral" or gain != 1.0:
            tone_tag = f" tone={user_tone}" if user_tone else ""
            mood_tag = f" mood={_last_mood[0]}" if _last_mood[0] else ""
            print(f"  [tts] preset={chosen}{tone_tag}{mood_tag} rate={rate} pitch={pitch} gain={gain:.2f}")

        # Wry deliveries get a brief beat spliced in before the final clause
        # so the punchline actually lands. core.tts.split_for_wry_pause()
        # returns (text, None) when no good split exists — single-pass render
        # in that case. Computed ONCE here, ABOVE the backend selection, so
        # both the kokoro and edge-tts renderers splice the same pause — the
        # split used to live inside the edge branch only, so kokoro replies
        # lost their comic beat (2026-07-21 audit).
        wry_split = None
        if chosen == "wry" and _tts_layer is not None:
            try:
                _wry_head, _wry_tail = _tts_layer.split_for_wry_pause(text)
                if _wry_tail:
                    wry_split = (_wry_head, _wry_tail,
                                 int(_tts_layer.WRY_PAUSE_MS))
            except Exception:
                wry_split = None

        # LOCAL VOICE-CLONE (Chatterbox) takes precedence over EVERY backend
        # below when the owner has opted in (VOICE_CLONE_ENABLED) and selected a
        # consented profile and core.voice_clone.is_available() agrees the
        # package + model + CUDA are all present. It returns a FULL waveform per
        # sentence (so streaming-TTS / barge-in, which call synthesise() once
        # per sentence, are unaffected). ANY None/exception falls straight
        # through to the existing edge-tts → pyttsx3 → SAPI5 ladder UNCHANGED —
        # a missing dep, a no-GPU box, or an unselected/unconsented profile must
        # never silence JARVIS. Read live each utterance so a 'switch to my
        # voice' toggle applies immediately. Gate is defensive: a broken import
        # of the wrapper itself is swallowed and we proceed to the ladder.
        try:
            if globals().get("VOICE_CLONE_ENABLED", False):
                from core import voice_clone as _voice_clone
                if _voice_clone.is_available():
                    # WALL-CLOCK CAP (2026-07-07 review, MED): run the clone on a
                    # DAEMON worker with a hard join timeout. Chatterbox pays a
                    # multi-second cold start (first-run model download + CUDA
                    # load) and can stall on the GPU — a HANG (not a raise/None)
                    # would otherwise freeze the whole voice turn indefinitely,
                    # unlike every other backend (edge-tts caps at 30s). On
                    # timeout/failure we abandon it and fall through to the ladder
                    # so JARVIS is NEVER left mute. Daemon → a hung worker can't
                    # block process exit and dies with it.
                    #
                    # SINGLE-FLIGHT: if a prior worker was abandoned on timeout and
                    # is STILL running (its model load/generate hasn't returned),
                    # do NOT spawn a second — that would pile up concurrent CUDA
                    # loads / an unsafe concurrent generate. Skip the clone this
                    # utterance and use the ladder.
                    with _voice_clone_inflight_lock:
                        _clone_busy = _voice_clone_inflight[0]
                        if not _clone_busy:
                            _voice_clone_inflight[0] = True
                    if _clone_busy:
                        print("  [tts] voice-clone worker still in flight from a "
                              "prior timeout — using the normal TTS ladder")
                    else:
                        _clone_box: dict = {}

                        def _clone_worker():
                            try:
                                _clone_box["v"] = _voice_clone.synthesize(text)
                            except Exception as _ce:      # noqa: BLE001
                                _clone_box["err"] = _ce
                            finally:
                                # Release the single-flight guard whenever this
                                # worker actually finishes — even long after we
                                # abandoned it on timeout — so the next utterance
                                # may try the clone again.
                                with _voice_clone_inflight_lock:
                                    _voice_clone_inflight[0] = False

                        _ct = threading.Thread(target=_clone_worker,
                                               name="voice-clone-synth", daemon=True)
                        _ct.start()
                        _ct.join(timeout=_VOICE_CLONE_TIMEOUT_S)
                        if _ct.is_alive():
                            print(f"  [tts] voice-clone timed out "
                                  f"(>{_VOICE_CLONE_TIMEOUT_S:.0f}s) — using the normal "
                                  f"TTS ladder")
                        elif "err" in _clone_box:
                            _e = _clone_box["err"]
                            print(f"  [tts] voice-clone failed "
                                  f"({type(_e).__name__}: {_e}); using the normal "
                                  f"TTS ladder")
                        else:
                            clone = _clone_box.get("v")
                            if clone is not None:
                                audio, sr = clone
                                if gain != 1.0:
                                    audio = np.clip(audio * gain, -1.0,
                                                    1.0).astype(np.float32)
                                return audio, sr
        except Exception as e:
            print(f"  [tts] voice-clone unavailable ({type(e).__name__}: {e}); "
                  f"using the normal TTS ladder")

        # Voice-clone backend takes precedence when the user has opted in
        # via TTS_BACKEND='xtts'. Any failure (deps missing, sample WAV
        # unreadable, render crash) falls straight through to edge-tts so
        # an over-eager toggle never silences JARVIS.
        backend = (globals().get("TTS_BACKEND", "edge") or "edge").lower()
        if backend == "xtts":
            try:
                audio, sr = _render_xtts_or_raise(text, rate, pitch)
                if gain != 1.0:
                    audio = np.clip(audio * gain, -1.0, 1.0).astype(np.float32)
                return audio, sr
            except Exception as e:
                print(f"  [tts] XTTS render failed ({e}); falling back to edge-tts")

        if backend == "pyttsx3":
            try:
                audio, sr = _pyttsx3_tts(text)
                if gain != 1.0:
                    audio = np.clip(audio * gain, -1.0, 1.0).astype(np.float32)
                return audio, sr
            except Exception as e:
                print(f"  [tts] pyttsx3 render failed ({e}); falling back to edge-tts")

        if backend == "kokoro":
            # CPU Kokoro (frees the 3090). Reached only when NO on-demand clone is
            # armed (the clone is Axis 1, handled above), so an explicit clone
            # request still wins. synthesize() is fail-closed (never raises,
            # returns None) so a missing/corrupt model or a wedged engine falls
            # straight through to the edge → pyttsx3 → SAPI5 → silence ladder and
            # never mutes JARVIS. See core/kokoro_tts.py. (2026-07-15, P2.)
            # The preset's rate drives Kokoro's speed (2026-07-21 audit — it
            # was resolved, logged, then silently dropped here); pitch has no
            # kokoro_onnx equivalent, so speed + the wry pause + gain are the
            # prosody this backend honours.
            try:
                from core import kokoro_tts as _kokoro
                res = None
                if _kokoro.is_available():
                    speed = _rate_to_speed(rate)
                    if wry_split is not None:
                        # Two-part wry render: BOTH clauses must succeed or the
                        # whole attempt falls through to the edge ladder (which
                        # does its own wry splice) — a half-rendered wry line
                        # must never ship head-only audio.
                        w_head, w_tail, pause_ms = wry_split
                        head_res = _kokoro.synthesize(w_head, speed=speed)
                        tail_res = _kokoro.synthesize(w_tail, speed=speed)
                        if head_res is not None and tail_res is not None:
                            head_audio, sr = head_res
                            tail_audio, _ = tail_res
                            pause_samples = max(0, int(sr * pause_ms / 1000))
                            silence = np.zeros(pause_samples, dtype=np.float32)
                            res = (np.concatenate(
                                [head_audio, silence, tail_audio]
                            ).astype(np.float32), sr)
                    else:
                        res = _kokoro.synthesize(text, speed=speed)
                if res is not None:
                    audio, sr = res
                    if gain != 1.0:
                        audio = np.clip(audio * gain, -1.0, 1.0).astype(np.float32)
                    return audio, sr
            except Exception as e:
                print(f"  [tts] kokoro render failed ({type(e).__name__}: {e}); "
                      f"falling back to edge-tts")

        try:
            # wry_split was computed once above the backend selection (shared
            # with the kokoro branch); (text, None) → single-pass render.
            if wry_split is not None:
                head, tail, pause_ms = wry_split
                head_audio, sr = _render_edge_tts(head, rate, pitch)
                tail_audio, _  = _render_edge_tts(tail, rate, pitch)
                pause_samples  = max(0, int(sr * pause_ms / 1000))
                silence        = np.zeros(pause_samples, dtype=np.float32)
                audio          = np.concatenate([head_audio, silence, tail_audio]).astype(np.float32)
            else:
                audio, sr = _render_edge_tts(text, rate, pitch)

            if gain != 1.0:
                audio = np.clip(audio * gain, -1.0, 1.0).astype(np.float32)
            return audio, sr
        except Exception as e:
            print(f"  edge-tts failed ({e}), using pyttsx3…")
            audio, sr = _pyttsx3_tts(text)
            if gain != 1.0:
                audio = np.clip(audio * gain, -1.0, 1.0).astype(np.float32)
            return audio, sr
    except Exception as e:
        # Both backends are dead (e.g. edge-tts 503 + pyttsx3 not installed).
        # Returning silence keeps main() alive — losing one line of speech
        # is strictly better than crashing the whole assistant.
        print(f"  [tts] total failure ({type(e).__name__}: {e}); returning silence so JARVIS stays online")
        return _silent_clip()


def _try_sapi5_then_silence(text: str, rate: str = "+0%", pitch: str = "+0Hz") -> tuple[np.ndarray, int]:
    """Final fallback chain: SAPI5 via PowerShell, then silence. Called from
    _pyttsx3_tts when pyttsx3 itself fails so the edge-tts → pyttsx3 →
    SAPI5 → silence ladder remains transparent to synthesise()."""
    try:
        from tts.render import render_sapi5
    except ImportError as e:
        print(f"  [tts] SAPI5 module unavailable ({e}); returning silence")
        return _silent_clip()
    try:
        audio, sr = render_sapi5(text, rate=rate, pitch=pitch)
        print(f"  [tts] SAPI5 fallback succeeded ({len(audio)} samples @ {sr} Hz)")
        return audio, sr
    except Exception as e:
        print(f"  [tts] SAPI5 fallback failed ({type(e).__name__}: {e}); returning silence")
        return _silent_clip()


# WALL-CLOCK CAP on the pyttsx3 rung of the TTS ladder (2026-08-20 audit).
# EVERY other backend in the ladder is already bounded — the voice clone joins
# at _VOICE_CLONE_TIMEOUT_S, edge-tts at fut.result(timeout=30), Kokoro at
# core/kokoro_tts._SYNTH_TIMEOUT_S, SAPI5 at tts/render._SUBPROCESS_TIMEOUT_S —
# because synthesise() runs on the VOICE THREAD underneath _SPEAK_LOCK, and the
# house rule is that NOTHING unbounded runs there: a hang, unlike a raise, is
# unrecoverable (the main loop never reaches the watchdog's reset consumer, so
# JARVIS goes permanently deaf AND mute while every other _speak() caller piles
# up on the untimed `with _SPEAK_LOCK`). engine.runAndWait() was the one rung
# with no bound of any kind: it drives a synchronous ISpeechVoice::Speak render
# into an SAPI.SPFileStream, which is native code we cannot interrupt.
_PYTTSX3_TIMEOUT_S = 15.0
# SINGLE-FLIGHT GUARD, same rationale as the voice clone's. On a timeout we
# ABANDON the daemon worker but it keeps holding the SAPI engine. pyttsx3.init()
# memoises its driver in a module-level registry, so a second call would hand a
# fresh caller the SAME wedged engine (and a second concurrent runAndWait on it).
# While a worker is in flight the fallback goes straight to the subprocess-bounded
# SAPI5 rung instead — JARVIS still speaks.
_pyttsx3_inflight = [False]
_pyttsx3_inflight_lock = threading.Lock()


def _pyttsx3_tts(text: str) -> tuple[np.ndarray, int]:
    try:
        import pyttsx3
    except ImportError as e:
        # Fallback engine not installed; surface to console but do NOT crash
        # the caller. Try SAPI5 next so a missing pyttsx3 doesn't silence us.
        print(f"  [tts] pyttsx3 unavailable ({e}); trying SAPI5")
        return _try_sapi5_then_silence(text)

    with _pyttsx3_inflight_lock:
        _busy = _pyttsx3_inflight[0]
        if not _busy:
            _pyttsx3_inflight[0] = True
    if _busy:
        print("  [tts] pyttsx3 worker still in flight from a prior timeout — "
              "trying SAPI5")
        return _try_sapi5_then_silence(text)

    # The worker owns the temp .wav for its whole lifetime: an ABANDONED worker
    # must not race the caller over unlink(), and the caller must not delete a
    # file the wedged SAPI stream is still writing.
    _box: dict = {}

    def _pyttsx3_worker():
        path = None
        try:
            engine = pyttsx3.init()
            with tempfile.NamedTemporaryFile(suffix=".wav", delete=False) as f:
                path = f.name
            _box["path"] = path
            try:
                engine.save_to_file(text, path)
                engine.runAndWait()
                engine.stop()   # release the file handle before we delete it
                audio, sr = sf.read(path, dtype="float32")
                if audio.ndim > 1:
                    audio = audio.mean(axis=1)
                _box["v"] = (audio, sr)
            finally:
                # Always remove the temp .wav — if save_to_file/runAndWait/
                # sf.read raised before we got here the file would otherwise
                # leak.
                try:
                    if path and os.path.exists(path):
                        os.unlink(path)
                except OSError:
                    pass   # Windows can hold the file briefly; not fatal
        except Exception as _re:   # noqa: BLE001 - reported to the caller below
            _box["err"] = _re
        finally:
            # Release the single-flight guard whenever this worker actually
            # finishes — even long after we abandoned it — so the next
            # utterance may try pyttsx3 again.
            with _pyttsx3_inflight_lock:
                _pyttsx3_inflight[0] = False

    _pt = threading.Thread(target=_pyttsx3_worker, name="pyttsx3-synth",
                           daemon=True)
    # The claim above was made on THIS thread but is released only inside the
    # worker's finally — so a start() that raises (RuntimeError: can't start
    # new thread, the thread exhaustion _pa_close_handoff's contract already
    # treats as real) would leave a claim with no worker to retire it. The
    # pyttsx3 rung would then be skipped for the rest of the session while the
    # console asserted "worker still in flight from a prior timeout", which is
    # a false statement about a worker that never existed. Same shape as
    # _pa_close_handoff's re-raising unwind. 2026-08-20.
    try:
        _pt.start()
    except BaseException as _se:
        with _pyttsx3_inflight_lock:
            _pyttsx3_inflight[0] = False
        if isinstance(_se, Exception):
            # Same destination as every other failure branch in this function:
            # the rung failed, so try SAPI5 rather than raising into the ladder
            # (site 2 of 2 would turn the raise into _silent_clip()). Loud,
            # and it names the REAL cause instead of the in-flight fiction.
            print(f"  [tts] pyttsx3 worker thread could not start "
                  f"({type(_se).__name__}: {_se}); trying SAPI5")
            return _try_sapi5_then_silence(text)
        raise            # KeyboardInterrupt / SystemExit stay unswallowed
    _pt.join(timeout=_PYTTSX3_TIMEOUT_S)
    if _pt.is_alive():
        # DEGRADED PATH — must be loud. The worker still holds the SAPI engine
        # and its temp .wav; we abandon both rather than block the voice thread.
        print(f"  [tts] pyttsx3 render timed out (>{_PYTTSX3_TIMEOUT_S:.0f}s) — "
              f"abandoning the worker (temp wav "
              f"{_box.get('path') or 'not yet created'} is left behind if it "
              f"never returns); trying SAPI5")
        return _try_sapi5_then_silence(text)
    if "err" in _box:
        # pyttsx3 itself blew up (init failed, save_to_file failed, etc.).
        # Try SAPI5 before giving up — this is the cascade the user kept
        # seeing as 'edge-tts failed → pyttsx3 render failed → silence'.
        e = _box["err"]
        print(f"  [tts] pyttsx3 render failed ({type(e).__name__}: {e}); trying SAPI5")
        return _try_sapi5_then_silence(text)
    out = _box.get("v")
    if out is None:
        # Worker finished without a result AND without an exception — should be
        # unreachable, but never report success we did not verify.
        print("  [tts] pyttsx3 render produced no audio and no error; trying SAPI5")
        return _try_sapi5_then_silence(text)
    return out


# ──────────────────────────────────────────────────────────────────────────
#  PLAYBACK + LIP-SYNC
# ──────────────────────────────────────────────────────────────────────────

def is_using_headset() -> bool:
    """True if the current output device name looks like a headset.
    Used to decide whether barge-in is safe (no mic feedback)."""
    try:
        idx = get_output_device()
        if idx is None:
            # None means "no explicit preference — use the SYSTEM DEFAULT
            # output" (the default config: SPEAKER_INDEX unset and
            # PREFERRED_OUTPUT_DEVICES empty), not "no device". Resolve the
            # real default and name-check IT — treating None as False
            # hard-wired this to False for the default install, which made
            # standby_audio_detect's auto-standby-on-music unreachable
            # (2026-07-21 audit). PortAudio reports "no default output"
            # as -1; an empty/None default tuple means the same.
            dflt = sd.default.device
            idx = dflt[1] if dflt else None
            if idx is None or (isinstance(idx, int) and idx < 0):
                return False
        name = sd.query_devices(idx)["name"].lower()
        return any(kw in name for kw in HEADSET_NAME_HINTS)
    except Exception:
        return False


# Barge-in shared state (legacy RMS/headset path — see BARGE_IN_ENABLED above)
_barge_in_interrupted = False

# ── Wake-word barge-in (v1.95.x, feat/barge-in) ───────────────────────────
# A wake-word ENGINE hit (openwakeword/porcupine via skills/wake_listener.py)
# that lands while play_with_lipsync is live can cut playback so the user
# never waits out a long reply. This path is deliberately separate from the
# legacy RMS listener above: it opens NO extra InputStream (the wake listener
# already owns its own mic), so the 0xc0000374 PortAudio use-after-free that
# killed the RMS path cannot recur here. ALL native calls on the play stream
# (active/abort/stop/close) happen on the single tts-reaper daemon
# (_reap_playback); sd.stop()/sd.wait() are NEVER called on this stream
# (sd.stop hides a second Pa_CloseStream that raced sd.wait's finally-close —
# the 0xc0000374 double-free, 2026-08 barge-in-stall fix). Never from a
# PortAudio callback, never from the wake listener's thread, never from the
# caller's thread.
#
# _tts_interrupt        — set by request_tts_interrupt(); polled every 50 ms
#                         by the tts-reaper daemon (_reap_playback — worst-case
#                         abort latency one 50 ms slice, well under the 300 ms
#                         budget).
# _tts_current_text     — single-element-list cell (the monolith's shared-
#                         mutable idiom) holding the LOWERCASED text currently
#                         in playback, published by _speak() right before
#                         play_with_lipsync and cleared in its finally. This
#                         is the airtight echo gate: the mic hears the
#                         speakers, so when JARVIS himself is saying "jarvis"
#                         a wake hit during that sentence is almost certainly
#                         his own voice — refuse the interrupt.
_tts_interrupt = threading.Event()
# Monotonic count of ACCEPTED barge-ins. Unlike the _tts_interrupt Event (which
# _speak's / play_with_lipsync's finally CLEARS before a chained flush thread's
# prev.join() returns — making an `_tts_interrupt.is_set()` check there dead
# code), this counter is never reset, so a flush thread can detect "a barge-in
# happened during this reply" by comparing it to a snapshot taken when the
# reply's flush buffer was created. 2026-07-08.
_tts_interrupt_seq: list[int] = [0]
_tts_current_text: list[str] = [""]


def _barge_in_wake_enabled() -> bool:
    """Live read of core.config.BARGE_IN_ENABLED (the NEW wake-word knob —
    NOT this module's legacy BARGE_IN_ENABLED constant, which stays False
    for the crashy RMS path). Fresh import per call mirrors the
    STREAMING_TTS_ENABLED pattern so a Settings-GUI / user_settings.json
    flip reaches the runtime without a restart. Any failure → False, i.e.
    zero behaviour change."""
    try:
        from core import config as _cfg
        return bool(getattr(_cfg, "BARGE_IN_ENABLED", False))
    except Exception:
        return False


# A non-acoustic barge-in (Kinect hand-swipe, web stop, tray) that cuts the
# BOOT greeting mid-synthesis races the still-initialising audio/CUDA stack.
# Observed 2026-07-15: a phantom hand-track swipe fired during a freshly
# restarted successor's session-resume greeting, the main loop stalled 100s, and
# the process VANISHED with no Python traceback — the signature of a native crash
# (same class as the 0xc0000374 that already forced BARGE_IN_ENABLED off). During
# this window the owner isn't intentionally gesturing; it's phantom motion. Ignore
# non-acoustic interrupts for the first N seconds so the greeting plays out. Lines
# up with the existing 30s boot-window speech throttle (see _speak); a touch
# longer because the greeting PLAYBACK can extend past 30s.
_BOOT_BARGE_IN_GRACE_S = 60.0

# Gesture (Kinect hand-swipe) barge-in is OFF by default. It cut TTS mid-playback
# and then the teardown wedged the main loop → the watchdog reaped the process:
# JARVIS went DOWN twice on 2026-07-15, BOTH times from a PHANTOM swipe (the owner
# wasn't deliberately gesturing). The depth sensor false-fires swipes, so a feature
# that lets a phantom gesture kill the assistant is a net negative — mirror the
# already-off-by-default acoustic BARGE_IN_ENABLED. Web-UI / tray STOP buttons are
# unaffected (they aren't gesture sources). Opt in with JARVIS_GESTURE_BARGE_IN=1.
_GESTURE_BARGE_IN_ENABLED = (os.environ.get("JARVIS_GESTURE_BARGE_IN", "")
                             .strip().lower() in ("1", "true", "yes", "on"))


def request_tts_interrupt(source: str = "wake-word",
                          acoustic: bool = True) -> bool:
    """Barge-in entry point, called from skills/wake_listener.py when the
    wake-word ENGINE fires while JARVIS is speaking. Returns True when the
    interrupt was ACCEPTED — the caller must then swallow its wake
    announcement (JARVIS just goes quiet and listens; no "yes sir?" spoken
    over the tail of the aborted reply). Returns False when:

      * the core.config.BARGE_IN_ENABLED knob is off (zero behaviour change),
      * TTS playback isn't actually live (nothing to interrupt — the normal
        wake path should proceed unchanged), or
      * the sentence currently being spoken contains "jarvis" — the
        echo-safety gate. The mic hears the speakers, so an engine hit
        during a self-referential sentence is treated as JARVIS's own voice
        and ignored. Cheap and airtight; deliberately conservative (a real
        user barging in during such a sentence loses this one race, and the
        wake path still handles them the moment playback ends).

    `acoustic=False` marks an interrupt that did NOT arrive through the
    microphone — a Kinect hand-swipe, a web-UI stop button, a tray click. Both
    guarded gates above exist purely because the mic hears the speakers:
    BARGE_IN_ENABLED is the *wake-word* knob, and the "jarvis" echo gate is
    there to stop JARVIS's own voice retriggering him. Neither can apply to a
    hand waved in front of a depth sensor, and applying them anyway just makes
    the gesture mysteriously dead whenever he happens to be saying his own
    name. Non-acoustic sources still require live playback — there must be
    something to actually stop. 2026-07-14 audit.

    Only sets the event — the actual cut (stream.abort()) runs on the
    tts-reaper daemon (_reap_playback), the ONE thread allowed to make
    native calls on the play stream. The caller thread parks on a pure
    Event wait and never enters PortAudio, so a wedged native teardown
    can no longer stall the main loop (2026-08 barge-in-stall fix)."""
    if acoustic and not _barge_in_wake_enabled():
        return False
    if not _tts_playback_active[0]:
        return False
    if (not acoustic
            and (time.time() - _session_start_time) < _BOOT_BARGE_IN_GRACE_S):
        print(f"  [barge-in] ignored during boot grace "
              f"(source={source}, non-acoustic) — greeting plays out")
        return False
    if (not acoustic and not _GESTURE_BARGE_IN_ENABLED
            and any(g in (source or "").lower() for g in ("swipe", "gesture", "kinect"))):
        # Phantom depth-sensor swipes cutting TTS wedged the main loop → JARVIS
        # went down twice 2026-07-15. OFF by default (JARVIS_GESTURE_BARGE_IN=1
        # to re-enable). Web/tray STOP buttons are NOT gesture sources, so they
        # still interrupt normally.
        print(f"  [barge-in] gesture barge-in disabled (source={source}); "
              f"ignoring — set JARVIS_GESTURE_BARGE_IN=1 to enable")
        return False
    if acoustic and "jarvis" in (_tts_current_text[0] or ""):
        print(f"  [barge-in] wake hit ignored (own TTS says 'jarvis'), "
              f"source={source}")
        return False
    print(f"  [barge-in] TTS interrupt accepted, source={source}"
          f"{'' if acoustic else ' (non-acoustic)'}")
    _tts_interrupt.set()
    # Bump the monotonic accepted-barge counter so a streaming-TTS flush thread
    # can see the barge-in even after _tts_interrupt is cleared by the finally
    # of the sentence it cut. 2026-07-08.
    _tts_interrupt_seq[0] += 1
    return True


def _start_barge_in_listener():
    """Open a mic InputStream that flags sustained speech during playback.
    The callback ONLY sets `_barge_in_interrupted = True`; calling sd.stop()
    from inside a PortAudio callback frees the stream while the callback
    that triggered the free is still on the stack (use-after-free → 0xc0000374).
    The watch thread inside play_with_lipsync routes the flag into
    _tts_interrupt so the tts-reaper daemon — the play stream's single
    toucher — performs the actual cut (2026-08 barge-in-stall fix).
    Returns the stream so we can close it when playback finishes, or None
    on failure."""
    global _barge_in_interrupted
    _barge_in_interrupted = False
    sustained = [0]

    def cb(indata, frames, time_info, status):
        global _barge_in_interrupted
        if _barge_in_interrupted:
            return
        data = indata[:, 0] if indata.ndim > 1 else indata
        rms = float(np.sqrt(np.mean(data ** 2)))
        if rms > BARGE_IN_THRESHOLD:
            sustained[0] += 1
            if sustained[0] >= BARGE_IN_SUSTAIN_CHUNKS:
                _barge_in_interrupted = True
        else:
            sustained[0] = 0

    if _mic_input_disabled():
        return None
    try:
        stream = sd.InputStream(
            samplerate=SAMPLE_RATE, channels=1, dtype="float32",
            blocksize=1024, device=get_input_device(), callback=cb,
        )
        stream.start()
        return stream
    except Exception as e:
        print(f"  [barge-in] could not start listener: {e}")
        return None


# ── Audio ducking (pycaw) ──────────────────────────────────────────────────
# Lazy WASAPI-session ducker. duck() runs the fade-down on a background
# thread so TTS playback can start immediately; restore() cancels any
# in-flight fade-down and fades back up synchronously so the next utterance
# sees a fully-restored mixer. No-op when pycaw isn't installed, when not on
# Windows, or when no matching session is currently playing.
class _AudioDucker:
    _AVAILABLE: bool | None = None
    _SELF_PID = os.getpid()

    def __init__(self):
        self._lock = threading.Lock()
        self._saved: list[tuple[object, float]] = []
        self._fade_cancel = threading.Event()
        self._fade_done = threading.Event()
        self._fade_done.set()
        self._worker_lock = threading.Lock()
        self._worker_thread: threading.Thread | None = None
        self._work_queue: queue.Queue = queue.Queue()

    @classmethod
    def _check_available(cls) -> bool:
        if cls._AVAILABLE is not None:
            return cls._AVAILABLE
        if sys.platform != "win32":
            cls._AVAILABLE = False
            return False
        try:
            import pycaw.pycaw  # noqa: F401
            import comtypes     # noqa: F401
            cls._AVAILABLE = True
        except Exception:
            cls._AVAILABLE = False
        return cls._AVAILABLE

    def _ensure_worker(self) -> None:
        # A single long-lived worker thread initializes COM once at startup
        # and reuses the same MTA apartment for every fade. Spawning a fresh
        # thread per TTS playback used to leak an apartment each call (the
        # CoInitialize had no paired CoUninitialize).
        with self._worker_lock:
            t = self._worker_thread
            if t is not None and t.is_alive():
                return
            new_t = threading.Thread(
                target=self._worker_loop,
                daemon=True,
                name="AudioDuckerFade",
            )
            new_t.start()
            self._worker_thread = new_t

    def _worker_loop(self) -> None:
        com_inited = False
        try:
            import comtypes
            comtypes.CoInitialize()
            com_inited = True
        except Exception:
            pass
        try:
            while True:
                job = self._work_queue.get()
                if job is None:
                    return
                plans, target_level, cancellable, done_event = job
                try:
                    self._fade_run(plans, target_level, cancellable)
                except Exception as e:
                    print(f"  [audio-duck] fade failed: {e}")
                finally:
                    if done_event is not None:
                        done_event.set()
        finally:
            if com_inited:
                try:
                    import comtypes
                    comtypes.CoUninitialize()
                except Exception:
                    pass

    def _enumerate_targets(self) -> list[tuple[object, float]]:
        from pycaw.pycaw import AudioUtilities
        com_inited = False
        try:
            import comtypes
            comtypes.CoInitialize()
            com_inited = True
        except Exception:
            pass
        try:
            try:
                sessions = AudioUtilities.GetAllSessions()
            except Exception as e:
                print(f"  [audio-duck] enumerate failed: {e}")
                return []
            targets = [t.lower() for t in AUDIO_DUCKING_TARGETS]
            matched: list[tuple[object, float]] = []
            for sess in sessions:
                try:
                    proc = sess.Process
                    if proc is None or proc.pid == self._SELF_PID:
                        continue
                    name = (proc.name() or "").lower()
                    if not any(t in name for t in targets):
                        continue
                    vol_iface = sess.SimpleAudioVolume
                    if vol_iface is None:
                        continue
                    cur = float(vol_iface.GetMasterVolume())
                    # Skip sessions already at/below the duck level so we don't
                    # later 'restore' them to a louder level than the user set.
                    if cur <= AUDIO_DUCKING_LEVEL + 0.01:
                        continue
                    matched.append((vol_iface, cur))
                except Exception:
                    continue
            return matched
        finally:
            if com_inited:
                try:
                    import comtypes
                    comtypes.CoUninitialize()
                except Exception:
                    pass

    def _fade_run(self, plans, target_level, cancellable: bool) -> None:
        # Called only from the worker thread, which has COM already initialized
        # for its lifetime. Do not CoInitialize here — that's what was leaking.
        if not plans:
            return
        steps = 10
        step_dur = (AUDIO_DUCKING_FADE_MS / 1000.0) / steps
        started = []
        for iface, original in plans:
            try:
                start = float(iface.GetMasterVolume())
            except Exception:
                continue
            end = original if target_level is None else target_level
            started.append((iface, start, end))
        for i in range(1, steps + 1):
            if cancellable and self._fade_cancel.is_set():
                return
            frac = i / steps
            for iface, start, end in started:
                lvl = max(0.0, min(1.0, start + (end - start) * frac))
                try:
                    iface.SetMasterVolume(lvl, None)
                except Exception:
                    pass
            time.sleep(step_dur)

    def duck(self) -> None:
        if not AUDIO_DUCKING_ENABLED or not self._check_available():
            return
        with self._lock:
            if self._saved:
                return
            try:
                matched = self._enumerate_targets()
            except Exception as e:
                print(f"  [audio-duck] duck failed: {e}")
                return
            if not matched:
                return
            self._saved = matched
            self._fade_cancel.clear()
            self._fade_done.clear()
            self._ensure_worker()
            self._work_queue.put(
                (list(matched), AUDIO_DUCKING_LEVEL, True, self._fade_done)
            )

    def restore(self) -> None:
        with self._lock:
            if not self._saved:
                return
            saved = list(self._saved)
            self._fade_cancel.set()
            self._saved = []
            fade_done = self._fade_done
        # Wait for any in-flight duck fade to observe the cancel and exit.
        try:
            fade_done.wait(timeout=AUDIO_DUCKING_FADE_MS / 1000.0 + 0.3)
        except Exception:
            pass
        # Enqueue the fade-up on the worker so it runs in the COM-initialized
        # apartment, then wait for completion synchronously.
        self._ensure_worker()
        restore_done = threading.Event()
        self._work_queue.put((saved, None, False, restore_done))
        try:
            restore_done.wait(timeout=AUDIO_DUCKING_FADE_MS / 1000.0 + 1.0)
        except Exception:
            pass


_audio_ducker = _AudioDucker()


def _reap_playback(stream, done_evt: threading.Event, audio_secs: float) -> None:
    """Single-toucher playback reaper — the body of the "tts-reaper" daemon.

    THE THREADING CONTRACT (2026-08 barge-in-stall fix): ALL native calls on
    the play stream (active/abort/stop/close) happen on this ONE thread;
    sd.stop()/sd.wait() are NEVER called on this stream. The old shape — a
    caller-side sd.stop() cutting playback while a _safe_wait daemon sat in
    sd.wait() — hid a second Pa_CloseStream inside sd.stop() that raced
    sd.wait()'s finally-close: both threads read the live _ptr (Stream.close
    has no lock and nulls _ptr only AFTER Pa_CloseStream returns) and both
    closed it. Concurrent Pa_CloseStream on one WASAPI stream corrupts the
    heap (0xc0000374 — the process VANISHES with no Python traceback) or
    wedges WASAPI natively under the caller, which held _SPEAK_LOCK on the
    main voice loop → the 100-181 s heartbeat stalls the watchdog kept
    reaping. Do not reintroduce sd.wait()/sd.stop() here.

    Polls every 50 ms:
      * _tts_interrupt set → stream.abort() (Pa_AbortStream — no buffer
        drain, snappier than stop()); abort latency ≤ one slice, well
        inside the 300 ms barge-in budget.
      * stream inactive (natural end, or post-abort) → break.
      * past deadline (audio length + 2 s grace, floor 5 s) → abort, break.
    Then the ONLY Pa_CloseStream for this stream: stop() before close()
    (sounddevice issue #87), both ignore_errors. The caller parks on a pure
    done_evt.wait() and never enters PortAudio — a wedged native teardown
    strands this daemon (it dies with the process), not the main loop.

    Interaction with the NEXT utterance: none, since H-7 (2026-08-20). The
    caller runs _pa_detach_play_stream the instant it hands this stream over,
    so the stream is no longer in sounddevice's module-global `_last_callback`
    and the next sd.play()'s IMPLICIT module-level stop() cannot reach it.
    That interaction used to be described here as benign — "its _ptr is NULL by
    then, so Pa_StopStream/Pa_CloseStream(NULL) return paBadStreamPtr" — which
    held only on the HEALTHY path. On the ABANDON path (caller's bounded wait
    expired while this thread is still inside Pa_CloseStream) the _ptr is still
    live, and that implicit stop() was a genuine second Pa_CloseStream from a
    second thread: the 0xc0000374 this contract exists to prevent."""
    try:
        deadline = time.monotonic() + max(audio_secs + 2.0, 5.0)
        cut = False
        while True:
            try:
                if not stream.active:   # False once closed/aborted/finished
                    break
            except Exception:
                break
            if not cut and _tts_interrupt.is_set():
                print("  [barge-in] cutting TTS playback (wake word)")
                t0 = time.monotonic()
                try:
                    stream.abort(ignore_errors=True)
                except Exception:
                    pass
                cut = True
                print("  [barge-in] cut complete (%d ms)"
                      % int((time.monotonic() - t0) * 1000))
            if time.monotonic() >= deadline:
                try:
                    stream.abort(ignore_errors=True)
                except Exception:
                    pass
                break
            time.sleep(0.05)
        try:
            stream.stop(ignore_errors=True)
        except Exception:
            pass
        try:
            stream.close(ignore_errors=True)
        except Exception:
            pass
    finally:
        # H-6: retire the in-flight-close registration made by
        # _pa_close_handoff in play_with_lipsync, BEFORE signalling the caller
        # — so a caller whose bounded wait succeeds never leaves a phantom
        # count deferring hotplug. If this thread never gets here (wedged in
        # the Pa_CloseStream above) the count stays up, which is exactly what
        # keeps sd._terminate() away from the live native call.
        _pa_close_done()
        done_evt.set()


def play_with_lipsync(audio: np.ndarray, sr: int):
    """Play TTS audio through speakers. If a robot is connected, also stream
    mouth-open values at ~30 fps so it lip-syncs. If barge-in is enabled and
    the user is on a headset, listen for interruptions during playback.

    Always publishes a per-chunk TTS amplitude to the HUD state (separate
    field from mic_level) so the arc-reactor HUD can brighten the ring
    during speech — see hud/jarvis_hud.py (arc_reactor_hud upgrade)."""
    # Claim TTS playback for the whole function (via the _pa_gate teardown
    # gate, 2026-08-14) so _refresh_devices cannot start its destructive
    # sd._terminate()/_initialize() reinit while the barge-in InputStream /
    # tts-reaper teardown are in play. Mirrors the _record_speech_active claim
    # — a device refresh firing here otherwise frees PortAudio state under the
    # live barge-in stream (0xc0000374). Released in the finally below, AFTER
    # the barge-in stream's close. A claim timeout means a reinit's native
    # call has hung >1s: losing this one utterance beats opening streams into
    # a heap-corrupting teardown, so raise into _speak's existing
    # device-hiccup handler (it logs the line and returns _speak_ok=False to
    # the streaming flush ledger).
    if not _pa_claim_owner(_tts_playback_active):
        raise RuntimeError("PortAudio reinit hung >1s — skipping playback")
    # A stale interrupt from a previous utterance (e.g. one that raced the
    # end of playback and set the event after that utterance's wait loop
    # exited) must not kill THIS utterance at its first chunk — start every
    # playback with a clean slate.
    _prof("play_enter")
    _tts_interrupt.clear()
    out_dev = get_output_device()

    def _play_audio_safe():
        """sd.play(audio, sr, device=out_dev) with a one-shot fallback to the
        system default. The autoswitch thread (audio/audio_switch.py) flips the
        default render endpoint for all roles on a 3 s poll; when that swap lands
        between get_output_device() resolving out_dev and PortAudio opening the
        stream, the open fails with DirectSound -9999 and the utterance is
        silently dropped. Mirror record_speech's input-side retry: invalidate the
        cached index and re-open on device=None (the now-current default) so a
        mid-playback endpoint change finishes the speech on the new endpoint
        instead of swallowing it. If the fallback also fails, re-raise so the
        outer handler logs it loudly rather than failing silent."""
        _prof("sdplay_call")
        try:
            sd.play(audio, sr, device=out_dev)
            _prof("sdplay_return")
        except sd.PortAudioError as e:
            # -9999 / endpoint vanished mid-open: drop to the live system default.
            print(f"  [speak] playback open failed on device {out_dev} ({e}); "
                  f"retrying on system default")
            _device_cache["out"] = None
            _device_cache["checked_at"] = 0.0
            sd.play(audio, sr, device=None)

    # Start barge-in listener if conditions met
    barge_stream = None
    if BARGE_IN_ENABLED and is_using_headset():
        barge_stream = _start_barge_in_listener()

    # Barge-in watch: the InputStream callback flags `_barge_in_interrupted`
    # but cannot touch the play stream itself (native calls from a PortAudio
    # callback → use-after-free). A daemon thread polls the flag and routes
    # it into _tts_interrupt so the tts-reaper — the ONLY thread allowed to
    # make native calls on the play stream (_reap_playback) — performs the
    # actual cut. Started only when the listener is actually live.
    barge_watch_stop = threading.Event()
    barge_watch_thread: threading.Thread | None = None
    if barge_stream is not None:
        def _barge_watch():
            while not barge_watch_stop.wait(0.02):
                if _barge_in_interrupted:
                    print("  [barge-in] user interrupted")
                    _tts_interrupt.set()
                    return
        barge_watch_thread = threading.Thread(target=_barge_watch, daemon=True)
        barge_watch_thread.start()

    # Duck Chrome / Spotify / Apple Music / Edge so JARVIS sits cleanly
    # over whatever's already playing. Fades down in the background so
    # playback starts immediately; restored in the finally block.
    _audio_ducker.duck()

    CHUNK_SECS = 0.033
    chunk_n    = int(sr * CHUNK_SECS)
    amp_stop   = threading.Event()

    def _amp_pump():
        """Stream RMS amplitude to the HUD state file at ~30 fps. Decoupled
        from the robot lip-sync loop so it runs even when ROBOT_ENABLED=False."""
        pos = 0
        try:
            while pos < len(audio) and not amp_stop.is_set():
                chunk = audio[pos : pos + chunk_n]
                if len(chunk):
                    amp = float(np.clip(
                        np.sqrt(np.mean(chunk.astype(np.float32) ** 2)),
                        0.0, 1.0,
                    ))
                    _write_hud_state(tts_amplitude=amp)
                pos += chunk_n
                time.sleep(CHUNK_SECS)
        finally:
            _write_hud_state(tts_amplitude=0.0)

    amp_thread = threading.Thread(target=_amp_pump, daemon=True)
    amp_thread.start()

    # Hand the outgoing waveform to the noise-cancel-1 processor before
    # playback starts so its AEC layer has a far-end reference for the
    # duration of speech.
    _feed_playback_reference(audio, sr)

    # MUTE_TTS support — synthesise() already ran, so the prosody pipeline
    # has been exercised. Skip the actual sd.play() call and just sleep for
    # the audio duration so the HUD amplitude pump + lip-sync helpers stay
    # in sync with what would have been audible. core/tts.is_muted() is
    # checked fresh per call so an operator can toggle MUTE_TTS mid-session.
    _muted = False
    try:
        if _tts_layer is not None and _tts_layer.is_muted():
            _muted = True
    except Exception:
        _muted = False
    audio_secs = (len(audio) / float(sr)) if sr else 0.0

    try:
        if _muted:
            # Replace the device write with a sleep — keeps the surrounding
            # amp_thread + barge-in watchdog logic identical. Waiting on
            # _tts_interrupt (instead of time.sleep) keeps the muted path
            # barge-in-responsive too: an accepted interrupt ends the
            # simulated playback immediately, same as the reaper's abort would.
            _tts_interrupt.wait(timeout=min(audio_secs, 30.0))
        elif not ROBOT_ENABLED:
            # 2026-05-29 silent-crash fix, rebuilt 2026-08 (barge-in-stall):
            # hand the played stream to the single-toucher tts-reaper daemon
            # (_reap_playback) — it owns EVERY native call on the stream
            # (active/abort/stop/close) while this caller parks on a pure
            # Event wait. No sd.wait() (its finally-close raced sd.stop()'s
            # hidden second close — the 0xc0000374 double-free) and no
            # caller-side sd.stop() (the old timeout "recovery" WAS the
            # crash vector, and unbounded native calls on this thread are
            # what stalled the main loop 100-181 s until the watchdog reaped
            # the process).
            _play_audio_safe()
            try:
                _stream = sd.get_stream()
            except Exception:
                logging.exception(
                    "[audio] sd.get_stream() failed — skipping playback reaper")
                _stream = None
            if _stream is not None:
                _done_evt = threading.Event()
                _t = threading.Thread(target=_reap_playback,
                                      args=(_stream, _done_evt, audio_secs),
                                      daemon=True, name="tts-reaper")
                # H-6: register the reaper's native close BEFORE starting it —
                # the wait below is abandonable, and the finally further down
                # clears _tts_playback_active unconditionally (it must: the
                # barge-in gate, ambient listen and the face tracker read that
                # flag and would stall forever on a lie). _pa_close_pending is
                # what keeps the destructive reinit away from the abandoned
                # close.
                _pa_close_handoff(_t)
                # H-7 (2026-08-20): the stream now belongs to the reaper, so
                # take it OUT of sounddevice's shared `_last_callback` slot.
                # The wait below is abandonable, and an abandoned reaper is
                # still inside Pa_CloseStream — the next utterance's sd.play()
                # would then run its IMPLICIT module-level stop() (a second
                # Pa_StopStream + Pa_CloseStream) against that same handle:
                # 0xc0000374. Ordered AFTER the handoff on purpose — if the
                # daemon could not be started, _pa_close_handoff re-raises and
                # the stream stays reachable so the next sd.play() still reaps
                # it. See _pa_detach_play_stream.
                _pa_detach_play_stream(_stream)
                # Bounded pure-Python wait: the reaper's own deadline plus
                # 1 s grace for its native teardown. On timeout, ABANDON the
                # daemon (precedent: _safe_close_stream) — never touch the
                # stream from this thread.
                if not _done_evt.wait(
                        timeout=max(audio_secs + 2.0, 5.0) + 1.0):
                    print("  [audio] tts-reaper wedged in native code — "
                          "abandoning (daemon dies with process)")
        else:
            pos = 0

            def _sync():
                nonlocal pos
                while pos < len(audio):
                    try:
                        chunk = audio[pos : pos + chunk_n]
                        if len(chunk):
                            mouth = float(np.clip(np.sqrt(np.mean(chunk ** 2)) * MOUTH_SCALE, 0.0, 1.0))
                            send(mouth=mouth)
                        pos += chunk_n
                        time.sleep(CHUNK_SECS)
                    except Exception:
                        logging.exception("[_sync] lip-sync iteration failed")
                        pos += chunk_n
                        time.sleep(CHUNK_SECS)
                try:
                    send(mouth=0.0)
                except Exception:
                    logging.exception("[_sync] failed to send mouth=0.0 on exit")

            t = threading.Thread(target=_sync, daemon=True)
            t.start()
            _play_audio_safe()
            # Same single-toucher tts-reaper as the no-robot branch — barge-in
            # works with the robot connected too. Shared _reap_playback body,
            # deliberately NOT a divergent copy (the old _safe_wait_robot twin
            # was exactly the stale-duplicate shape this codebase keeps paying
            # for).
            try:
                _stream = sd.get_stream()
            except Exception:
                logging.exception(
                    "[audio] sd.get_stream() failed — skipping playback reaper (robot)")
                _stream = None
            if _stream is not None:
                _done_evt = threading.Event()
                _t = threading.Thread(target=_reap_playback,
                                      args=(_stream, _done_evt, audio_secs),
                                      daemon=True, name="tts-reaper")
                # H-6 — same registration as the no-robot branch above.
                # Deliberately NOT a divergent copy of the rule: both branches
                # call the one _pa_close_handoff.
                _pa_close_handoff(_t)
                # H-7 — same fence as the no-robot branch, same one helper.
                # A stale duplicate here would leave the robot path with the
                # abandoned-reaper double-close the no-robot path just closed.
                _pa_detach_play_stream(_stream)
                if not _done_evt.wait(
                        timeout=max(audio_secs + 2.0, 5.0) + 1.0):
                    print("  [audio] tts-reaper wedged in native code — "
                          "abandoning (daemon dies with process)")
            t.join(timeout=0.5)
    finally:
        amp_stop.set()
        try:
            amp_thread.join(timeout=0.2)
        except Exception:
            pass
        # Stop the barge-in watch thread before tearing down the InputStream
        # so it can't observe the flag after `barge_stream` is closed.
        barge_watch_stop.set()
        if barge_watch_thread is not None:
            try:
                barge_watch_thread.join(timeout=0.2)
            except Exception:
                pass
        # Wake-word barge-in cleanup: clear the interrupt so the flag can't
        # leak into the next utterance (belt AND the clear-at-start braces
        # above). Runs whether playback finished naturally or was cut short —
        # after this point the system is in exactly the state a completed
        # reply would leave it in.
        _tts_interrupt.clear()
        # Ensure HUD doesn't show stale amplitude after playback
        _write_hud_state(tts_amplitude=0.0)
        if barge_stream is not None:
            _safe_close_stream(barge_stream)
        # Release the TTS-playback claim only NOW — after the barge-in
        # stream's native close — so the flag covers its whole native lifetime
        # and a queued device refresh can never latch its reinit while that
        # close is still executing (2026-08-14; an older comment promised this
        # ordering but the code cleared the flag at the top of this finally).
        # _speak's belt-and-braces force-clear still backstops a setup-time
        # raise. Plain write: releases need no lock, only claims do.
        #
        # H-6 (2026-08-20): "its whole native lifetime" is exact only up to an
        # ABANDON — both the barge_stream close above and the tts-reaper wait
        # further up give up after a bounded time while PortAudio may still be
        # inside the close. That remainder is covered by _pa_close_pending
        # (registered by _pa_close_handoff, retired by the daemon), NOT by
        # pinning this flag up: it MUST keep telling the truth here.
        _tts_playback_active[0] = False
        # Fade Chrome/Spotify/Apple Music/Edge back to their original volumes
        try:
            _audio_ducker.restore()
        except Exception:
            pass


# ──────────────────────────────────────────────────────────────────────────
#  SCREEN VISION  — Bobert sees what's on screen via Claude's vision API
# ──────────────────────────────────────────────────────────────────────────

import base64

# Spoken refusal returned by the vision/screenshot actions when the focused
# window matches SCREENSHOT_PRIVACY_BLOCKLIST — kept as a single constant so
# every entry point says the same thing.
SCREENSHOT_PRIVACY_REFUSAL = (
    "I'm not capturing the screen — a private window is in focus, sir."
)


def screenshot_privacy_block_reason() -> str | None:
    """Return the SCREENSHOT_PRIVACY_BLOCKLIST entry matching the focused
    window's title (case-insensitive substring), or None when capture is
    allowed.

    Empty/missing blocklist → always None (no behaviour change). Any failure
    reading the focused window is treated as 'allowed' so a transient Win32
    hiccup never silently blinds vision — the blocklist is an opt-in privacy
    guard, not a hard gate."""
    try:
        from core import config as _cfg
        blocklist = getattr(_cfg, "SCREENSHOT_PRIVACY_BLOCKLIST", ()) or ()
    except Exception:
        return None
    if not blocklist:
        return None
    try:
        _, title, _ = _read_focused_window()
    except Exception:
        return None
    if not title:
        return None
    low = title.lower()
    for entry in blocklist:
        try:
            needle = str(entry).strip().lower()
        except Exception:
            continue
        if needle and needle in low:
            return str(entry)
    return None


def take_screenshot(monitor: str | None = None, max_dim: int = 1568) -> bytes | None:
    """Return PNG bytes of the requested monitor (defaults to primary),
    downscaled so the longest edge is at most max_dim. Claude vision
    requires the image to be under ~5MB and ≤ 1568px on the long side.

    Uses mss (preferred — DPI-safe, handles all multi-monitor configs on
    Windows without crashing) with a PIL.ImageGrab fallback.

    Hard privacy gate: if the focused window matches
    SCREENSHOT_PRIVACY_BLOCKLIST, returns None without capturing — so every
    caller (vision, saved screenshots, the loopback grabbers) is covered even
    if a higher-level entry point forgot to check."""
    blocked = screenshot_privacy_block_reason()
    if blocked:
        print(f"  [vision] screenshot refused — private window in focus "
              f"(matched {blocked!r})")
        return None
    try:
        from PIL import Image
    except ImportError:
        print("  [vision] Pillow not installed — pip install pillow")
        return None

    # ── mss path (preferred) ──────────────────────────────────────────────
    try:
        import mss
        _MSSClass = getattr(mss, "MSS", mss.mss)   # MSS in ≥9, mss in older
        with _MSSClass() as sct:
            if monitor and monitor in MONITORS:
                x, y, w, h = MONITORS[monitor]
                region = {"left": x, "top": y, "width": w, "height": h}
            else:
                # sct.monitors[0] is the virtual screen spanning all displays
                region = sct.monitors[0]
            raw = sct.grab(region)
            # mss returns BGRA; convert to PIL RGB
            img = Image.frombytes("RGB", raw.size, raw.bgra, "raw", "BGRX")
    except Exception as e_mss:
        # ── PIL fallback ──────────────────────────────────────────────────
        try:
            from PIL import ImageGrab
            if monitor and monitor in MONITORS:
                x, y, w, h = MONITORS[monitor]
                img = ImageGrab.grab(bbox=(x, y, x + w, y + h), all_screens=True)
            else:
                # monitor=None must capture the WHOLE virtual desktop to match
                # the mss path (and what find_click_target's translate assumes).
                # Bare ImageGrab.grab() returns ONLY the primary monitor, so a
                # target on a secondary/negative-origin display would be cropped
                # out and the coords mistranslated. Grab the full virtual bounds.
                vx, vy, vw, vh = _virtual_screen_bounds()
                img = ImageGrab.grab(bbox=(vx, vy, vx + vw, vy + vh),
                                     all_screens=True)
        except Exception as e_pil:
            print(f"  [vision] screenshot failed (mss: {e_mss}, pil: {e_pil})")
            return None

    try:
        # Downscale so the longest edge ≤ max_dim — Claude rejects larger images
        if max(img.size) > max_dim:
            ratio = max_dim / max(img.size)
            new_size = (int(img.size[0] * ratio), int(img.size[1] * ratio))
            img = img.resize(new_size, Image.LANCZOS)
        buf = io.BytesIO()
        img.save(buf, format="PNG", optimize=True)
        return buf.getvalue()
    except Exception as e:
        print(f"  [vision] screenshot encode failed: {e}")
        return None


def ask_vision(question: str, png_bytes: bytes | None = None) -> str:
    """Send a screenshot to Claude with a question, return its answer.

    If the Claude vision call fails (rate-limit, credit exhausted, network,
    5xx) or the Claude backend is disabled outright, falls through to a
    local VLM via Ollama (controlled by LOCAL_VISION_FALLBACK /
    LOCAL_VISION_MODEL). Local-vision answers are prefixed with
    `[local-vision] ` so the user knows the offline eye answered."""
    if not SCREEN_VISION_ENABLED:
        return "(screen vision is disabled — set SCREEN_VISION_ENABLED = True)"
    # Privacy gate first — when a blocklisted window is focused, refuse with a
    # spoken line instead of the generic capture-failure text. Skip the check
    # when the caller already supplied png_bytes (it captured before whatever
    # is now focused; the gate ran at that capture).
    if png_bytes is None:
        if screenshot_privacy_block_reason():
            return SCREENSHOT_PRIVACY_REFUSAL
        png_bytes = take_screenshot()
    if png_bytes is None:
        return "(could not capture screen)"

    # Per-function routing: force the local VLM when vision is routed "local".
    from core.config import model_route
    if model_route("vision") == "local":
        local = _call_local_vision(question, [png_bytes])
        return f"[local-vision] {local}" if local else "(local vision unavailable — Ollama not reachable)"

    # Cloud-disabled path: jump straight to the local VLM.
    if AI_BACKEND != "claude":
        local = _call_local_vision(question, [png_bytes])
        if local:
            return f"[local-vision] {local}"
        return "(screen vision requires Claude backend or a local VLM via Ollama)"

    # Import the SDK OUTSIDE the try below. If `import anthropic` fails there,
    # Python still has to EVALUATE the `except anthropic.APIStatusError` header to
    # decide whether it matches — and `anthropic` is unbound, so that evaluation
    # raises NameError, which propagates straight out of the try/except and
    # crashes the vision action, bypassing the whole local-VLM fallback. (The old
    # catch-all's comment claimed it handled a failed import; it never could —
    # an exception raised while matching an EARLIER except clause never reaches a
    # LATER one.) A missing SDK is exactly the local-fallback case. 2026-07-14.
    try:
        import anthropic
    except Exception:
        local = _call_local_vision(question, [png_bytes])
        if local:
            return f"[local-vision] {local}"
        return "(screen vision requires the anthropic SDK or a local VLM via Ollama)"

    try:
        b64 = base64.standard_b64encode(png_bytes).decode("utf-8")
        msg = _anthropic_client().messages.create(
            model=SCREEN_VISION_MODEL, max_tokens=500,
            messages=[{
                "role": "user",
                "content": [
                    {"type": "image", "source": {
                        "type": "base64", "media_type": "image/png", "data": b64
                    }},
                    {"type": "text", "text": question},
                ],
            }],
        )
        return msg.content[0].text.strip()
    except anthropic.APIStatusError as e:
        # 4xx/5xx from Claude (rate limit, credit exhausted, server error,
        # auth) — exactly the case the local VLM fallback was built for.
        print(f"  [vision] Claude API {e.status_code} → local VLM fallback")
        local = _call_local_vision(question, [png_bytes])
        if local:
            return f"[local-vision] {local}"
        return f"(vision failed: HTTP {e.status_code})"
    except (anthropic.APIConnectionError, anthropic.APITimeoutError) as e:
        print(f"  [vision] Claude API unreachable ({type(e).__name__}) → local VLM fallback")
        local = _call_local_vision(question, [png_bytes])
        if local:
            return f"[local-vision] {local}"
        return f"(vision failed: {e})"
    except Exception as e:
        # Catch-all: an empty content list → IndexError on content[0], or
        # `import anthropic` failing → ImportError. Neither is an anthropic.*
        # subclass, so without this they'd escape uncaught and crash the
        # vision action — bypassing the local-VLM fallback this whole
        # function is built around. Route to local like the API-error
        # paths do. 2026-05-30 audit.
        print(f"  [vision] Claude vision failed "
              f"({type(e).__name__}: {e}) → local VLM fallback")
        local = _call_local_vision(question, [png_bytes])
        if local:
            return f"[local-vision] {local}"
        return f"(vision failed: {type(e).__name__})"


def take_all_monitor_screenshots(max_dim: int = 1024) -> dict[str, bytes]:
    """Capture every monitor in MONITORS and return {name: png_bytes}.
    Monitors that fail to capture are skipped silently. Each image is
    downscaled to max_dim on its longest edge — smaller than the
    single-monitor default (1568) because we're going to send 4 of them at
    once and Claude has total-payload limits to respect."""
    out: dict[str, bytes] = {}
    for name in MONITORS:
        png = take_screenshot(monitor=name, max_dim=max_dim)
        if png is not None:
            out[name] = png
    return out


def ask_vision_multi(question: str, images: dict[str, bytes]) -> str:
    """Send several labelled screenshots to Claude in a single message and
    return its answer. Each image is preceded by a text block naming the
    monitor it came from, so the model can refer to them in its answer.
    Used by see_screen when no specific monitor is requested — gives JARVIS
    full situational awareness across all 4 displays in one call.

    Falls back to a local VLM via Ollama on Claude failure (or when the
    Claude backend is disabled). The local prompt embeds each monitor's
    name inline since Ollama's chat API doesn't support per-image labels
    the way Claude's interleaved content blocks do."""
    if not SCREEN_VISION_ENABLED:
        return "(screen vision is disabled — set SCREEN_VISION_ENABLED = True)"
    if not images:
        return "(no screens to look at)"

    def _local_multi_fallback() -> str | None:
        # Build an interleaved-style prompt that names each monitor in the
        # text, then pass all PNGs in order. VLMs like qwen2.5vl handle
        # multi-image with positional ordering preserved.
        names = list(images.keys())
        pngs  = [images[n] for n in names]
        labels = "\n".join(
            f"Image #{i+1} = {n.upper()} monitor" for i, n in enumerate(names)
        )
        prompt = (
            f"You are looking at {len(images)} monitors at once. They are "
            f"provided in this order:\n{labels}\n\n"
            f"When answering, name which monitor(s) the relevant content is on. "
            f"If the question doesn't apply to a given monitor, you can skip it.\n\n"
            f"Question: {question}"
        )
        text = _call_local_vision(prompt, pngs, max_tokens=900)
        return f"[local-vision] {text}" if text else None

    from core.config import model_route
    if model_route("vision") == "local":
        local = _local_multi_fallback()
        return local if local else "(local vision unavailable — Ollama not reachable)"

    if AI_BACKEND != "claude":
        local = _local_multi_fallback()
        if local:
            return local
        return "(screen vision requires Claude backend or a local VLM via Ollama)"

    # Hoisted for the same reason as ask_vision: a failed `import anthropic`
    # inside the try would crash while EVALUATING the `except anthropic.*`
    # headers (unbound name → NameError), bypassing the local fallback. A
    # missing SDK is the local-fallback case. 2026-07-14 audit.
    try:
        import anthropic
    except Exception:
        local = _local_multi_fallback()
        return local if local else (
            "(screen vision requires the anthropic SDK or a local VLM via Ollama)")

    try:
        intro = (
            f"You are looking at {len(images)} monitors at once. Each image "
            f"below is labelled with which monitor it is. When answering, "
            f"mention which monitor(s) the relevant content is on. If "
            f"something is on only one monitor, name that monitor. If the "
            f"question doesn't apply to a given monitor, you can skip it."
        )

        content: list = [{"type": "text", "text": intro}]
        for name, png in images.items():
            b64 = base64.standard_b64encode(png).decode("utf-8")
            content.append({"type": "text", "text": f"--- {name.upper()} monitor ---"})
            content.append({
                "type": "image",
                "source": {"type": "base64", "media_type": "image/png", "data": b64},
            })
        content.append({"type": "text", "text": question})

        msg = _anthropic_client().messages.create(
            model=SCREEN_VISION_MODEL, max_tokens=800,
            messages=[{"role": "user", "content": content}],
        )
        return msg.content[0].text.strip()
    except anthropic.APIStatusError as e:
        # 4xx/5xx from Claude (rate limit, credit exhausted, server error,
        # auth) — exactly the case the local VLM fallback was built for.
        print(f"  [vision] Claude API {e.status_code} → local VLM fallback")
        local = _local_multi_fallback()
        if local:
            return local
        return f"(vision failed: HTTP {e.status_code})"
    except (anthropic.APIConnectionError, anthropic.APITimeoutError) as e:
        print(f"  [vision] Claude API unreachable ({type(e).__name__}) → local VLM fallback")
        local = _local_multi_fallback()
        if local:
            return local
        return f"(vision failed: {e})"
    except Exception as e:
        # Catch-all (empty content → IndexError, import failure, unexpected
        # SDK error). Without this they'd crash the multi-monitor vision
        # action instead of degrading to the local VLM. 2026-05-30 audit.
        print(f"  [vision] Claude multi-vision failed "
              f"({type(e).__name__}: {e}) → local VLM fallback")
        local = _local_multi_fallback()
        if local:
            return local
        return f"(vision failed: {type(e).__name__})"


def _query_vision_for_coords(description: str, png_bytes: bytes, w: int, h: int) -> tuple[int, int] | None:
    """One-shot ask: find a UI element in a screenshot. Returns pixel coords
    in the SAME coordinate space as the input image, or None."""
    prompt = (
        f"You are helping a UI automation agent click PRECISELY on a target.\n"
        f"The image is {w}x{h} pixels. Origin (0,0) is the TOP-LEFT.\n"
        f"Target: {description}\n\n"
        f"Reply with ONLY the pixel coordinates of the EXACT VISUAL CENTRE of the "
        f"clickable element (not the centre of its label, the centre of the "
        f"clickable area itself).\n"
        f"Format: X,Y    (e.g. 432,718)\n"
        f"If the element isn't visible, reply: NOT_FOUND"
    )
    answer = ask_vision(prompt, png_bytes).strip()
    if "NOT_FOUND" in answer.upper():
        return None
    ans = answer.strip()
    # The model is told to reply with ONLY the coordinates, so do NOT mine an
    # arbitrary "\d+,\d+" out of prose — a reply like "I see 2 buttons, 3 tabs"
    # was yielding a confident click at (2,3) (esp. on the chattier local VLM).
    # Accept a clean coordinate reply, or a coordinate at the very END of a
    # SHORT answer; otherwise refuse — safer not to click than to click
    # garbage on the user's live screen. 2026-05-30 deep audit.
    m = re.fullmatch(r"\(?\s*(\d+)\s*,\s*(\d+)\s*\)?\.?", ans)
    if not m and len(ans) <= 32:
        m = re.search(r"(\d+)\s*,\s*(\d+)\s*\)?\.?\s*$", ans)
    if not m:
        return None
    x, y = int(m.group(1)), int(m.group(2))
    if 0 <= x <= w and 0 <= y <= h:
        return x, y
    return None


def _captured_region(monitor: str | None) -> dict | None:
    """Geometry of the region take_screenshot(monitor) actually grabs, as the
    SAME mss dict take_screenshot uses: {left, top, width, height} in the
    capture's NATIVE pixel space.

    This is the single source of truth that ties the capture origin to the
    click translation in find_click_target. For monitor=None it returns the
    LIVE mss virtual-screen rect (mss.monitors[0]) — whose left/top is the true
    bounding-box origin of all displays and is NEGATIVE on this owner's rig
    (a monitor sits left of/above the primary). Reading it live (instead of
    recomputing from the static MONITORS config) means the absolute-click origin
    can never silently disagree with what was photographed — the failure mode
    that lands clicks on the wrong monitor when the config and the real desktop
    diverge (e.g. a display was rearranged, or per-monitor DPI makes the
    DPI-aware mss origin differ from the logical config). For a named monitor it
    returns that monitor's configured rect. Returns None if mss is unavailable
    and no usable config entry exists."""
    if monitor and monitor in MONITORS:
        m = MONITORS[monitor]
        if len(m) >= 4 and m[2] and m[3]:
            return {"left": int(m[0]), "top": int(m[1]),
                    "width": int(m[2]), "height": int(m[3])}
    try:
        import mss
        _MSSClass = getattr(mss, "MSS", mss.mss)
        with _MSSClass() as sct:
            vs = sct.monitors[0]   # virtual screen — the monitor=None default
            return {"left": int(vs["left"]), "top": int(vs["top"]),
                    "width": int(vs["width"]), "height": int(vs["height"])}
    except Exception:
        return None


def _native_capture_size(monitor: str | None) -> tuple[int, int]:
    """Native pixel (width, height) of the region take_screenshot(monitor)
    captures. Used to rescale Pass-1 coords back to native when the full-res
    Pass-2 capture fails. Returns (0, 0) if it can't be determined.

    Prefers the LIVE mss size (true native pixels) for both the virtual screen
    and a named monitor, falling back to the configured MONITORS size only when
    mss can't be queried. The config holds LOGICAL dims, so on a DPI-scaled
    display the live mss size is the correct 'native' value here."""
    reg = _captured_region(monitor)
    if reg and reg["width"] and reg["height"]:
        return int(reg["width"]), int(reg["height"])
    if monitor and monitor in MONITORS:
        m = MONITORS[monitor]
        if len(m) >= 4 and m[2] and m[3]:
            return int(m[2]), int(m[3])
    return 0, 0


def find_click_target(description: str, monitor: str | None = None) -> tuple[int, int] | None:
    """Two-pass vision: locate a UI element with sub-pixel-ish precision.

    Pass 1: downscaled full screenshot → rough estimate.
    Pass 2: crop a small native-resolution region around the estimate and
            ask vision to refine the coords inside that crop.

    Returns absolute screen coordinates the click action can use directly,
    or None if the element isn't found.
    """
    try:
        from PIL import Image
    except ImportError:
        return None

    # Pass 1: low-res
    png = take_screenshot(monitor=monitor, max_dim=1568)
    if png is None:
        return None
    img1 = Image.open(io.BytesIO(png))
    w1, h1 = img1.size

    pass1 = _query_vision_for_coords(description, png, w1, h1)
    if pass1 is None:
        return None
    rx1, ry1 = pass1

    # Capture the geometry of the region we actually photographed ONCE, from the
    # same source take_screenshot used (live mss for monitor=None, the config
    # rect for a named monitor). This single rect drives BOTH the native size we
    # un-downscale to AND the absolute origin we add in the translate below — so
    # the click origin can never silently disagree with what was captured.
    cap = _captured_region(monitor)

    # Pass 2: grab the full-res monitor and crop a small region around the estimate
    full_png = take_screenshot(monitor=monitor, max_dim=10000)   # 10k = effectively no downscale
    if full_png is None:
        # Pass-2 capture failed — we have no full-res image to refine on.
        # CRITICAL: img1 is the DOWNSCALED Pass-1 image (max_dim=1568), so its
        # coords are NOT native screen pixels. Use the TRUE native size of the
        # captured region so the Pass-1 coords scale to native below. The old
        # code set full_w,full_h = w1,h1, treating downscaled coords as
        # full-res → an off-by-hundreds / wrong-monitor click on any >1568px
        # display (or the virtual desktop, where it could land a NEGATIVE X on
        # the wrong monitor). 2026-05-30 deep audit.
        full_img = None
        nw, nh = _native_capture_size(monitor)
        full_w = nw or w1
        full_h = nh or h1
    else:
        full_img = Image.open(io.BytesIO(full_png))
        full_w, full_h = full_img.size

    # Scale pass-1 coords from low-res image space → full-res image space
    scale_to_full_x = full_w / w1
    scale_to_full_y = full_h / h1
    cx_full = int(rx1 * scale_to_full_x)
    cy_full = int(ry1 * scale_to_full_y)

    refined_x = cx_full
    refined_y = cy_full

    # Only do pass 2 if we actually have a higher-res image to refine on
    # (full_img is None when the Pass-2 capture failed — see fallback above).
    if full_img is not None and (full_w > w1 or full_h > h1):
        CROP = 500   # 500x500 region around the estimate
        left   = max(0, cx_full - CROP // 2)
        top    = max(0, cy_full - CROP // 2)
        right  = min(full_w, cx_full + CROP // 2)
        bottom = min(full_h, cy_full + CROP // 2)
        crop = full_img.crop((left, top, right, bottom))
        cw, ch = crop.size
        crop_buf = io.BytesIO()
        crop.save(crop_buf, format="PNG")
        crop_png = crop_buf.getvalue()

        print(f"  [vision] 🔍 Refining position in {cw}x{ch} crop…", flush=True)
        pass2 = _query_vision_for_coords(description, crop_png, cw, ch)
        if pass2 is not None:
            refined_x = left + pass2[0]
            refined_y = top  + pass2[1]
            print(f"  [vision] ✓ Refined offset: {pass2[0]-cw//2:+},{pass2[1]-ch//2:+} px", flush=True)
        # If pass 2 fails, keep pass-1 estimate

    # Translate full-res image coords → absolute screen coordinates.
    #
    # refined_x/refined_y are an offset (in the captured image's NATIVE pixels)
    # from the TOP-LEFT of the region we photographed. To produce a coordinate
    # pyautogui can click we map that offset proportionally onto the region's
    # LOGICAL (DIP) extent and add the region's LOGICAL origin:
    #
    #     abs = logical_origin + refined * (logical_extent / native_extent)
    #
    # Two independent things this gets right on the owner's negative-origin,
    # multi-monitor rig (virtual desktop 7680x2880 @ -2560,-1440):
    #   • ORIGIN. We add the region's real top-left, which is NEGATIVE here. For
    #     monitor=None that origin is taken from the SAME capture (live mss
    #     monitors[0]) rather than recomputed from a possibly-stale config, so
    #     the add can't disagree with the photo. A target on the top-left
    #     monitor therefore lands at a negative absolute coordinate instead of
    #     being clamped onto the primary.
    #   • DPI. native_extent comes from the actual captured image (or the live
    #     mss size when Pass-2 failed), logical_extent from the config, so a
    #     display scaled >100% — where the native grab is LARGER than its logical
    #     size — is scaled back down before the offset is applied. At 100% the
    #     ratio is exactly 1.0, so a single-monitor / un-scaled rig is unchanged.
    if monitor and monitor in MONITORS:
        mx, my, lw, lh = MONITORS[monitor]
        sx = (lw / full_w) if full_w else 1.0
        sy = (lh / full_h) if full_h else 1.0
        if abs(sx - 1.0) > 0.01 or abs(sy - 1.0) > 0.01:
            print(f"  [vision] DPI scale: monitor={monitor} "
                  f"native={full_w}x{full_h} logical={lw}x{lh} "
                  f"→ click x({sx:.3f},{sy:.3f})", flush=True)
        return int(mx + refined_x * sx), int(my + refined_y * sy)
    # No monitor specified — Pass-2 captured the whole virtual screen (mss
    # monitors[0]). Use the LOGICAL origin (config-derived virtual bounds, which
    # is what pyautogui clicks in) but scale by the LIVE captured native size so
    # the origin and the scale come from one coherent picture of the desktop.
    vx, vy, vw, vh = _virtual_screen_bounds()
    # Prefer the live captured origin when it is available AND matches the
    # logical virtual origin (uniform-DPI / correctly-configured case). When the
    # config is stale the two diverge; we keep the logical origin because that is
    # the space pyautogui clicks in, but emit a one-line warning so a genuinely
    # wrong layout is visible in the log rather than silently mis-clicking.
    if cap is not None and (cap["left"] != vx or cap["top"] != vy):
        print(f"  [vision] ⚠ captured virtual origin ({cap['left']},{cap['top']}) "
              f"≠ configured ({vx},{vy}); using configured (pyautogui-logical) "
              f"origin. If clicks miss, re-run --list-monitors.", flush=True)
    sx = (vw / full_w) if full_w else 1.0
    sy = (vh / full_h) if full_h else 1.0
    if abs(sx - 1.0) > 0.01 or abs(sy - 1.0) > 0.01:
        print(f"  [vision] DPI scale: virtual native={full_w}x{full_h} "
              f"logical={vw}x{vh} → click x({sx:.3f},{sy:.3f})", flush=True)
    return int(vx + refined_x * sx), int(vy + refined_y * sy)


# ──────────────────────────────────────────────────────────────────────────
#  UI AUTOMATION  — click, type, key-press via pyautogui
# ──────────────────────────────────────────────────────────────────────────

_pyautogui = None


class UIFailsafeError(Exception):
    """Raised when pyautogui's fail-safe trips and a mouse-nudge retry
    also failed. Callers should catch this and surface the friendly
    message instead of the raw pyautogui traceback."""


_FAILSAFE_MSG = (
    # Must contain a FAILURE_MARKERS substring ("failed") so that when _act_click
    # / _act_type catch UIFailsafeError and `return str(e)`, the returned string is
    # classified as a failure (core/failure_markers.py) and routed through the
    # failure follow-up — otherwise a corner-triggered click/type abort is spoken
    # as a bogus success.
    "Click failed — your mouse was in a corner, sir; "
    "try again with the cursor elsewhere"
)


def _get_pyautogui():
    global _pyautogui
    if _pyautogui is None:
        try:
            import pyautogui as pag
            pag.FAILSAFE = True   # slam mouse into top-left corner to abort
            pag.PAUSE    = 0.15   # small pause between actions
            _pyautogui = pag
        except ImportError:
            print("  [ui] pyautogui not installed — run: pip install pyautogui")
    return _pyautogui


def _nudge_from_corner(pag) -> bool:
    """If the cursor is sitting on (or within 5 px of) a pyautogui FAILSAFE
    point, move it ~50 px toward screen center so the next call can run.
    Returns True if a nudge was performed."""
    try:
        cx, cy = pag.position()
        sw, sh = pag.size()
        corners = getattr(pag, "FAILSAFE_POINTS", [(0, 0)])
        for fx, fy in corners:
            if abs(cx - fx) <= 5 and abs(cy - fy) <= 5:
                new_x = 50 if fx < sw / 2 else sw - 50
                new_y = 50 if fy < sh / 2 else sh - 50
                # Disable FAILSAFE for the nudge itself so the move doesn't trip it.
                prev = pag.FAILSAFE
                pag.FAILSAFE = False
                try:
                    pag.moveTo(new_x, new_y, duration=0.05)
                finally:
                    pag.FAILSAFE = prev
                return True
    except Exception:
        pass
    return False


def _ui_safe(pag, op, *args, **kwargs):
    """Run a pyautogui operation. On FailSafeException, nudge the mouse off
    the corner and retry once; if it still trips, raise UIFailsafeError."""
    try:
        return op(*args, **kwargs)
    except Exception as e:
        # Match by class name so we don't have to import the exception type
        # at module load (pyautogui may be unavailable).
        if type(e).__name__ != "FailSafeException":
            raise
        if _nudge_from_corner(pag):
            try:
                return op(*args, **kwargs)
            except Exception as e2:
                if type(e2).__name__ == "FailSafeException":
                    raise UIFailsafeError(_FAILSAFE_MSG) from e2
                raise
        raise UIFailsafeError(_FAILSAFE_MSG) from e


def ui_click(x: int, y: int, button: str = "left"):
    pag = _get_pyautogui()
    if not pag:
        return
    # Clamp into the virtual-desktop bounds so a bad coordinate — a negative X
    # from a failed two-pass refine, or an out-of-range LLM-emitted
    # [ACTION: click, x,y] — can't fire pyautogui at the wrong monitor or off
    # screen. pyautogui's FAILSAFE only trips at the (0,0) corner, not on
    # arbitrary bad coords. 2026-05-30 deep audit.
    try:
        vx, vy, vw, vh = _virtual_screen_bounds()
        x = max(vx, min(int(x), vx + vw - 1))
        y = max(vy, min(int(y), vy + vh - 1))
    except Exception:
        pass
    # Flash the reticle BEFORE the click so the user sees where JARVIS aimed
    # even if the click itself raises (FailSafe, etc.). The overlay auto-fades
    # in ~2s — failed actions still leave a visible reticle for debugging.
    label = "click" if button == "left" else f"{button}-click"
    _publish_reticle(x, y, label)
    _ui_safe(pag, pag.click, x, y, button=button)


def ui_double_click(x: int, y: int):
    pag = _get_pyautogui()
    if not pag:
        return
    _publish_reticle(x, y, "dblclick")
    _ui_safe(pag, pag.doubleClick, x, y)

def ui_type(text: str):
    pag = _get_pyautogui()
    if not pag:
        return
    center = _active_window_center()
    if center is not None:
        _publish_reticle(center[0], center[1], "type")
    _ui_safe(pag, pag.write, text, interval=0.04)

def ui_press(key: str):
    pag = _get_pyautogui()
    if not pag:
        return
    center = _active_window_center()
    if center is not None:
        _publish_reticle(center[0], center[1], f"key:{key}"[:24])
    _ui_safe(pag, pag.press, key)

def ui_hotkey(*keys: str):
    pag = _get_pyautogui()
    if not pag:
        return
    center = _active_window_center()
    if center is not None:
        _publish_reticle(center[0], center[1], "+".join(keys)[:24])
    _ui_safe(pag, pag.hotkey, *keys)

def ui_scroll(amount: int):
    pag = _get_pyautogui()
    if not pag:
        return
    try:
        pos = pag.position()
        _publish_reticle(int(pos[0]), int(pos[1]), f"scroll {amount}")
    except Exception:
        pass
    _ui_safe(pag, pag.scroll, amount)


# ──────────────────────────────────────────────────────────────────────────
#  PC CONTROL  — Bobert can do things on the computer.
#
#  The LLM emits action tokens in its reply, e.g.:
#     [ACTION: open_url, https://news.ycombinator.com]
#     [ACTION: launch_app, notepad]
#     [ACTION: web_search, claude code documentation]
#     [ACTION: youtube, lofi hip hop]
#     [ACTION: screenshot]
#     [ACTION: get_time]
#
#  The token is stripped from what gets spoken aloud, then executed.
# ──────────────────────────────────────────────────────────────────────────

import shutil
import subprocess
import urllib.parse
import webbrowser

# Action-name class includes digits: `[a-z_]+` truncated names like
# `switch_to_gpt4` at the first digit, so any digit-bearing action name (or a
# future MCP-catalog name) silently failed to dispatch. 2026-05-30 deep audit.
_ACTION_RE = re.compile(r"\[ACTION:\s*([a-z0-9_]+)\s*(?:,\s*(.+?))?\s*\]", re.IGNORECASE)


# Phase 4A refactor (2026-05-29): _act_open_url moved to core/actions.py.
# Imported via `from core.actions import *` higher up in this file.
# The ACTIONS dispatch dict still resolves it by name.


# Common Chrome install locations. First existing path wins. Used by
# _open_url_new_window when we need a SEPARATE Chrome window rather than
# a tab in the user's current window.
_CHROME_PATHS = [
    r"C:\Program Files\Google\Chrome\Application\chrome.exe",
    r"C:\Program Files (x86)\Google\Chrome\Application\chrome.exe",
    os.path.expandvars(r"%LOCALAPPDATA%\Google\Chrome\Application\chrome.exe"),
]

# Common Edge install locations — the fallback browser when Chrome is absent.
# Edge ships with Windows, so this almost always resolves on this fleet.
_EDGE_PATHS = [
    r"C:\Program Files (x86)\Microsoft\Edge\Application\msedge.exe",
    r"C:\Program Files\Microsoft\Edge\Application\msedge.exe",
    os.path.expandvars(r"%LOCALAPPDATA%\Microsoft\Edge\Application\msedge.exe"),
]


def _exe_from_app_paths(exe_name: str) -> str | None:
    """Resolve a browser executable from the Windows 'App Paths' registry key
    (HKCU first, then HKLM). This is the most reliable locator — it's what the
    shell itself uses to resolve `start chrome` — and it survives non-default
    install dirs. Returns the path if it exists on disk, else None. Never
    raises (winreg missing on non-Windows, key absent, etc.)."""
    try:
        import winreg
    except Exception:
        return None
    subkey = (
        r"SOFTWARE\Microsoft\Windows\CurrentVersion\App Paths\\" + exe_name
    )
    for hive in (winreg.HKEY_CURRENT_USER, winreg.HKEY_LOCAL_MACHINE):
        try:
            with winreg.OpenKey(hive, subkey) as k:
                # The default (unnamed) value holds the full exe path.
                val, _ = winreg.QueryValueEx(k, None)
                if val and os.path.exists(val):
                    return val
        except Exception:
            continue
    return None


def _find_browser_exe(exe_name: str, fallback_paths: list[str]) -> str | None:
    """Locate a browser executable by name. Order: App Paths registry → the
    known fallback install dirs → PATH (shutil.which). Returns the first
    existing path, or None. Total (never raises)."""
    found = _exe_from_app_paths(exe_name)
    if found:
        return found
    for p in fallback_paths:
        if p and os.path.exists(p):
            return p
    try:
        which = shutil.which(exe_name)
    except Exception:
        which = None
    return which


def _find_chrome() -> str | None:
    """Locate chrome.exe via the App Paths registry, the common install
    dirs, then PATH. Returns the path or None."""
    return _find_browser_exe("chrome.exe", _CHROME_PATHS)


def _find_edge() -> str | None:
    """Locate msedge.exe via the App Paths registry, the common install
    dirs, then PATH. Returns the path or None."""
    return _find_browser_exe("msedge.exe", _EDGE_PATHS)


def _close_browser_windows_matching(terms, only_hwnd=None) -> int:
    """Close the dedicated media browser window JARVIS opened so a repeat media
    request reuses ONE window instead of piling up tabs. Returns count closed.

    SAFE mode (only_hwnd set): close ONLY the window whose native handle equals
    only_hwnd — the exact window JARVIS opened last time — never a window merely
    matching a title substring. This is what stops JARVIS from destroying the
    user's own main browser window whose ACTIVE-TAB title happens to contain a
    `terms` fragment (a Spotify "Web Player" tab, an article titled "…Apple
    Music…", etc.). LEGACY mode (only_hwnd is None): the old title-substring
    match, kept for callers with no recorded handle (e.g. the first-ever open)."""
    if only_hwnd is None and not terms:
        return 0
    try:
        import pygetwindow as gw
        wins = gw.getAllWindows()
    except Exception:
        return 0
    closed = 0
    for w in wins:
        if only_hwnd is not None:
            if getattr(w, "_hWnd", None) != only_hwnd:
                continue
            try:
                w.close()
                closed += 1
            except Exception:
                pass
            continue
        t = _strip_bidi_and_nbsp((getattr(w, "title", "") or "")).lower()
        if not t or not any(m in t for m in _MUSIC_BROWSER_MARKERS):
            continue
        if any(term in t for term in terms):
            try:
                w.close()
                closed += 1
            except Exception:
                pass
    return closed


def _find_browser_window_matching(terms):
    """Return the first BROWSER window whose normalized title contains any of
    `terms` (and a browser marker), or None. Used to locate a streaming
    service's just-opened window so vision-capture can be pinned to its
    monitor. Mirrors _close_browser_windows_matching's matching."""
    if not terms:
        return None
    try:
        import pygetwindow as gw
        wins = gw.getAllWindows()
    except Exception:
        return None
    for w in wins:
        t = _strip_bidi_and_nbsp((getattr(w, "title", "") or "")).lower()
        if t and any(m in t for m in _MUSIC_BROWSER_MARKERS) and any(term in t for term in terms):
            return w
    return None


def _open_url_in_browser(url: str, close_matching=None, close_hwnd=None) -> str:
    """Open `url` in a REAL web browser, deliberately bypassing the default
    URL handler.

    `close_matching` (a list of title substrings) puts this in MEDIA MODE:
    first close any existing dedicated browser window for the same service so
    repeats REUSE one window instead of stacking tabs, then open in a fresh
    dedicated window (the webbrowser controller is skipped in this mode because
    it may add a tab to the user's MAIN window, whose title we then can't match
    to close next time).

    WHY: the user installed the UWP Apple Music *app*, which registered itself
    as the protocol handler for music.apple.com. A bare `webbrowser.open(url)`
    therefore launches the APP (not a browser), and JARVIS then tries to drive
    the wrong, policy-restricted target. Opening the same URL in Chrome loads
    the real WEB PLAYER, which the keyboard-SPACE + tab-title pipeline can
    actually control.

    Resolution order:
      1. webbrowser.get("chrome") — uses Python's registered Chrome launcher.
      2. chrome.exe located via registry / known paths → subprocess.Popen.
      3. msedge.exe the same way (Edge ships with Windows).
      4. last resort: webbrowser.open(url) (may be intercepted by the app —
         we log a warning so the failure is explained, not silent).

    Returns a short string naming which path opened it ("chrome",
    "chrome:webbrowser", "edge", or "default") for logging/tests. NEVER raises.
    """
    if not url.startswith(("http://", "https://")):
        url = "https://" + url

    media_mode = bool(close_matching) or close_hwnd is not None
    if media_mode:
        try:
            n = _close_browser_windows_matching(close_matching, only_hwnd=close_hwnd)
            if n:
                print(f"  [open-url] closed {n} prior media window(s) — reusing one tab",
                      flush=True)
                time.sleep(0.35)
        except Exception:
            pass

    # 1) Python's own registered Chrome controller. Fast and dependency-free
    #    when Chrome is registered; KeyError when it isn't. Skipped in media
    #    mode so we get a dedicated, matchable --new-window (not a tab in the
    #    user's main window).
    if not media_mode:
        try:
            browser = webbrowser.get("chrome")
            if browser.open(url):
                return "chrome:webbrowser"
        except Exception:
            pass

    # 2) chrome.exe directly. --new-window keeps it off whatever Chrome window
    #    the user already has, matching _open_url_new_window's behaviour.
    chrome = _find_chrome()
    if chrome:
        try:
            subprocess.Popen([chrome, "--new-window", url], close_fds=True)
            return "chrome"
        except Exception as e:
            print(f"  [open-url] chrome.exe launch failed: {e}", flush=True)

    # 3) Edge fallback — also a real browser that loads the web player.
    edge = _find_edge()
    if edge:
        try:
            subprocess.Popen([edge, "--new-window", url], close_fds=True)
            return "edge"
        except Exception as e:
            print(f"  [open-url] msedge.exe launch failed: {e}", flush=True)

    # 4) Last resort: the default handler. On this box that may be the UWP
    #    Apple Music app rather than a browser, so warn — this explains why
    #    auto-play might then act on the wrong target.
    print(
        "  [open-url] WARNING: no Chrome/Edge found; falling back to the "
        "default URL handler — if the UWP Apple Music app is registered for "
        "this link it may open the APP instead of the web player.",
        flush=True,
    )
    try:
        webbrowser.open(url)
    except Exception as e:
        print(f"  [open-url] default handler also failed: {e}", flush=True)
    return "default"


def _open_url_new_window(url: str) -> bool:
    """Spawn a NEW Chrome window for `url`, leaving any existing Chrome
    windows untouched. Returns True if a new window was spawned, False if
    Chrome wasn't found (caller should fall back to webbrowser.open)."""
    if not url.startswith(("http://", "https://")):
        url = "https://" + url
    chrome = _find_chrome()
    if not chrome:
        return False
    try:
        # --new-window forces a separate top-level window even when Chrome
        # is already running. Without it, Chrome reuses the most recent
        # window and just adds a tab — which would steal focus from
        # whatever the user was watching there.
        subprocess.Popen([chrome, "--new-window", url], close_fds=True)
        return True
    except Exception:
        return False


# Coordinates well outside the virtual screen bounding box for this rig.
# MONITORS spans (-2560,-1440)..(5120,1440); placing a window at (10000,-30000)
# guarantees no part of it lands on any real monitor.
_OFFSCREEN_X, _OFFSCREEN_Y = 10000, -30000
_OFFSCREEN_W, _OFFSCREEN_H = 1600, 1200


def _open_url_offscreen_capture(url: str, page_load_wait: float = 6.0) -> tuple[bytes | None, str]:
    """Open `url` in a NEW Chrome window that is immediately parked off the
    virtual screen, wait for the page to render, capture the window's pixel
    content directly with win32 PrintWindow (PW_RENDERFULLCONTENT), then
    close the window. Used for headless-style screenshotting that reuses the
    user's logged-in Chrome session without ever showing the window on any
    monitor.

    Returns (png_bytes, "ok") on success or (None, error_reason) on failure.
    """
    if not url.startswith(("http://", "https://")):
        url = "https://" + url

    try:
        import win32gui
        import win32ui
        import win32con
        from ctypes import windll
        from PIL import Image
    except ImportError as e:
        return None, f"missing dep for offscreen capture: {e}"

    chrome = _find_chrome()
    if not chrome:
        return None, "chrome_not_found"

    chrome_class = "Chrome_WidgetWin_1"

    def _enum_chrome_hwnds() -> set:
        found: set = set()
        def _cb(hwnd, _):
            try:
                if (win32gui.GetClassName(hwnd) == chrome_class
                        and win32gui.IsWindowVisible(hwnd)):
                    rect = win32gui.GetWindowRect(hwnd)
                    w, h = rect[2] - rect[0], rect[3] - rect[1]
                    if w > 200 and h > 200:
                        found.add(hwnd)
            except Exception:
                pass
            return True
        try:
            win32gui.EnumWindows(_cb, None)
        except Exception:
            pass
        return found

    pre = _enum_chrome_hwnds()

    try:
        # Pass the offscreen position as Chrome launch flags so the window
        # starts at (10000, -30000) from frame 0 — no visible flash, no race
        # between spawn and SetWindowPos. --new-window keeps it separate from
        # any existing Chrome windows. --no-first-run / --no-default-browser-check
        # suppress startup dialogs that would create extra visible windows.
        subprocess.Popen([
            chrome,
            "--new-window",
            f"--window-position={_OFFSCREEN_X},{_OFFSCREEN_Y}",
            f"--window-size={_OFFSCREEN_W},{_OFFSCREEN_H}",
            "--no-first-run",
            "--no-default-browser-check",
            url,
        ], close_fds=True)
    except Exception as e:
        return None, f"chrome_spawn_failed: {e}"

    # Tight poll for the new top-level Chrome window so we can move it off
    # screen with minimal on-screen flash (~50ms in practice).
    target_hwnd = None
    deadline = time.time() + 5.0
    while time.time() < deadline:
        time.sleep(0.02)
        delta = _enum_chrome_hwnds() - pre
        if delta:
            target_hwnd = next(iter(delta))
            break

    if not target_hwnd:
        return None, "chrome_window_not_found"

    # Park the window off the virtual screen so it isn't visible anywhere.
    # SWP_NOZORDER (0x0004) | SWP_NOACTIVATE (0x0010) — don't steal focus.
    try:
        win32gui.SetWindowPos(
            target_hwnd, 0,
            _OFFSCREEN_X, _OFFSCREEN_Y, _OFFSCREEN_W, _OFFSCREEN_H,
            0x0004 | 0x0010,
        )
    except Exception:
        pass

    time.sleep(page_load_wait)

    png_bytes: bytes | None = None
    try:
        left, top, right, bot = win32gui.GetWindowRect(target_hwnd)
        w, h = right - left, bot - top
        if w > 0 and h > 0:  # pragma: no cover - live Win32 GDI PrintWindow capture of a real offscreen window handle
            hwndDC = None
            mfcDC = None
            saveDC = None
            saveBitMap = None
            try:
                hwndDC = win32gui.GetWindowDC(target_hwnd)
                mfcDC = win32ui.CreateDCFromHandle(hwndDC)
                saveDC = mfcDC.CreateCompatibleDC()
                saveBitMap = win32ui.CreateBitmap()
                saveBitMap.CreateCompatibleBitmap(mfcDC, w, h)
                saveDC.SelectObject(saveBitMap)
                # PW_RENDERFULLCONTENT (0x00000002) forces a full re-render via
                # the GDI DC — required for hardware-accelerated apps like
                # Chrome where the front buffer isn't otherwise GDI-readable.
                ok = windll.user32.PrintWindow(
                    target_hwnd, saveDC.GetSafeHdc(), 0x00000002
                )
                if ok:
                    bmpinfo = saveBitMap.GetInfo()
                    bmpstr  = saveBitMap.GetBitmapBits(True)
                    img = Image.frombuffer(
                        "RGB",
                        (bmpinfo["bmWidth"], bmpinfo["bmHeight"]),
                        bmpstr, "raw", "BGRX", 0, 1,
                    )
                    if max(img.size) > 1568:
                        ratio = 1568 / max(img.size)
                        img = img.resize(
                            (int(img.size[0] * ratio), int(img.size[1] * ratio)),
                            Image.LANCZOS,
                        )
                    buf = io.BytesIO()
                    img.save(buf, format="PNG", optimize=True)
                    png_bytes = buf.getvalue()
            finally:
                # Release every GDI handle we actually acquired, in reverse
                # order of acquisition. Each cleanup is independently guarded
                # so one failure doesn't strand the rest.
                if saveBitMap is not None:
                    try:
                        win32gui.DeleteObject(saveBitMap.GetHandle())
                    except Exception:
                        pass
                if saveDC is not None:
                    try:
                        saveDC.DeleteDC()
                    except Exception:
                        pass
                if mfcDC is not None:
                    try:
                        mfcDC.DeleteDC()
                    except Exception:
                        pass
                if hwndDC is not None:
                    try:
                        win32gui.ReleaseDC(target_hwnd, hwndDC)
                    except Exception:
                        pass
    except Exception as e:
        # Continue to close even if capture failed
        print(f"  [offscreen] PrintWindow capture error: {e}")

    # Close the window by posting WM_CLOSE (0x0010) directly to the HWND.
    # Safer than matching by title — guaranteed to hit the right window.
    try:
        win32gui.PostMessage(target_hwnd, 0x0010, 0, 0)
    except Exception:  # pragma: no cover - defensive: WM_CLOSE PostMessage to a live HWND rarely raises
        pass

    if png_bytes is None:
        return None, "printwindow_failed"
    return png_bytes, "ok"  # pragma: no cover - live Win32 GDI PrintWindow grab succeeded; needs a real on-screen window


# Known apps that aren't on PATH and don't have a Start-menu shortcut name
# that os.startfile() can resolve. Add new entries here when JARVIS fails to
# launch something the user asks for. Keys are normalised lower-case;
# aliases all point at the same canonical entry.
#
# Each value is a list of candidate absolute paths, tried in order — the
# first one that exists wins. Use lists so a single alias works across
# install locations (Program Files vs Program Files (x86) vs LocalAppData).
_KNOWN_APP_PATHS: dict[str, list[str]] = {
    "bambu studio": [
        r"C:\Program Files\Bambu Studio\bambu-studio.exe",
        r"C:\Program Files (x86)\Bambu Studio\bambu-studio.exe",
        os.path.expandvars(r"%LOCALAPPDATA%\Programs\Bambu Studio\bambu-studio.exe"),
    ],
}

# Aliases → canonical key in _KNOWN_APP_PATHS. Whisper transcripts can be
# inconsistent ("bambustudio", "bamboo studio") so we cast a wide net.
_KNOWN_APP_ALIASES: dict[str, str] = {
    "bambu":         "bambu studio",
    "bambustudio":   "bambu studio",
    "bambu_studio":  "bambu studio",
    "bambu-studio":  "bambu studio",
    "bamboo":        "bambu studio",
    "bamboo studio": "bambu studio",
    "bambu slicer":  "bambu studio",
}


def _resolve_known_app(name: str) -> str | None:
    """Return an existing executable path for `name` if it matches a known
    alias, otherwise None. Case-insensitive, tolerant of extra whitespace."""
    key = re.sub(r"\s+", " ", name.strip().lower())
    key = _KNOWN_APP_ALIASES.get(key, key)
    for candidate in _KNOWN_APP_PATHS.get(key, []):
        if candidate and os.path.exists(candidate):
            return candidate
    return None


