TODO_FILE             = os.path.join(os.path.dirname(os.path.abspath(__file__)), "jarvis_todo.md")
UPGRADE_SUMMARY_FILE  = os.path.join(os.path.dirname(os.path.abspath(__file__)), ".last_upgrade_summary.json")
